// === KV STORE (Postgres) — persistência permanente entre deploys ===
let _pgPool = null;
let _kvCache = {};
let _kvLoaded = false;
async function pgInit() {
  if (_pgPool) return _pgPool;
  if (!process.env.DATABASE_URL) { console.warn('[pg] DATABASE_URL ausente'); return null; }
  try {
    const { Pool } = require('pg');
    _pgPool = new Pool({
      connectionString: process.env.DATABASE_URL,
      // Sem SSL para o Postgres interno da Railway E para banco local. Antes só
      // `railway.internal` era isento, então qualquer Postgres local era forçado a
      // SSL e a conexão morria com "The server does not support SSL connections" —
      // o que tornava IMPOSSÍVEL rodar o portal na máquina de alguém. Foi o que
      // bloqueou a verificação manual do PDV no navegador (19/08/2026).
      ssl: /railway\.internal|localhost|127\.0\.0\.1|::1/.test(process.env.DATABASE_URL)
        ? false
        : { rejectUnauthorized: false },
      max: 5,
    });
    await _pgPool.query(`CREATE TABLE IF NOT EXISTS kv_store (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
    try {
      const dealOverrides = require('./lib/deal-overrides');
      await dealOverrides.ensureTable(_pgPool);
    } catch(e) { console.warn('[pg] deal_overrides ensureTable:', e.message); }
    console.log('[pg] conectado, tabelas kv_store e deal_overrides prontas');
    return _pgPool;
  } catch(e) { console.error('[pg init]', e.message); return null; }
}
async function kvLoadAll() {
  if (_kvLoaded) return _kvCache;
  const pool = await pgInit();
  if (!pool) { _kvLoaded = true; return _kvCache; }
  try {
    const r = await pool.query('SELECT key, value FROM kv_store');
    for (const row of r.rows) _kvCache[row.key] = row.value;
    _kvLoaded = true;
    console.log(`[kv] carregado ${r.rows.length} chaves do Postgres`);
    // Migração one-shot: se PG vazio E há JSONs em disco, copia tudo pra PG
    if (r.rows.length === 0) {
      console.log('[kv] PG vazio — migrando JSONs em disco...');
      const fs = require('fs');
      const migrar = [
        ['wati-inbox',          path.join(__dirname, 'data/wati-inbox.json')],
        ['manut-meta',          path.join(__dirname, 'data/manut-meta.json')],
        ['closer-perfis',       path.join(__dirname, 'data/closer-perfis.json')],
        ['propostas-closy',     path.join(__dirname, 'data/propostas-closy.json')],
        ['funis-closy',         path.join(__dirname, 'data/funis-closy.json')],
        ['inbox-kanban-etapas', path.join(__dirname, 'data/inbox-kanban-etapas.json')],
        ['respostas-rapidas',   path.join(__dirname, 'data/respostas-rapidas.json')],
        ['meta-closy',          path.join(__dirname, 'data/meta-closy.json')],
        ['regras-manutencao',   path.join(__dirname, 'data/regras-manutencao.json')],
      ];
      let migradas = 0;
      for (const [key, file] of migrar) {
        try {
          if (fs.existsSync(file)) {
            const data = JSON.parse(fs.readFileSync(file, 'utf8'));
            await kvSet(key, data);
            console.log(`[kv migração] ${key}: OK (${typeof data==='object'?Object.keys(data).length+' chaves':typeof data})`);
            migradas++;
          }
        } catch(e) { console.warn(`[kv migração ${key}]`, e.message); }
      }
      console.log(`[kv] migração one-shot completa: ${migradas} storages migrados`);
    }
  } catch(e) { console.error('[kv load]', e.message); _kvLoaded = true; }
  return _kvCache;
}
async function kvSet(key, value) {
  _kvCache[key] = value;
  const pool = await pgInit();
  if (!pool) return false;
  try {
    await pool.query(
      `INSERT INTO kv_store (key, value, updated_at) VALUES ($1, $2, NOW()) ON CONFLICT (key) DO UPDATE SET value = $2, updated_at = NOW()`,
      [key, JSON.stringify(value)]
    );
    return true;
  } catch(e) { console.error('[kv set]', key, e.message); return false; }
}
function kvOrFile(key, file, defaultVal) {
  if (_kvCache[key] !== undefined) return _kvCache[key];
  try { return JSON.parse(require('fs').readFileSync(file, 'utf8')); }
  catch { return defaultVal !== undefined ? defaultVal : {}; }
}
function kvAndFile(key, file, value) {
  kvSet(key, value).catch(e => console.warn('[kv save]', key, e.message));
  try {
    require('fs').mkdirSync(path.dirname(file), { recursive: true });
    require('fs').writeFileSync(file, JSON.stringify(value, null, 2));
  } catch(_){}
}
pgInit().then(() => kvLoadAll()).catch(() => {});

// === CACHE COMPARTILHADO: deals "won" últimos 36 meses ===
// Antes: cada endpoint refazia query Zoho (60 queries × 200 deals + enrichment) = 5-10s
// Agora: 1 fetch por hora, cache em memória + snapshot no Postgres (sobrevive deploy)
let _wonCache = null;
let _wonCacheAt = 0;
const WON_FIELDS = 'Deal_Name,Amount,Owner,Closing_Date,Pipeline,Layout,Telefone_contato,Cidade,Tipo_de_Agua,Produto_Vendido,Lead_Source,Email,ultima_manuten_o,Data_da_Instala_o,Tier_Lead';
const WON_TTL = 30 * 60 * 1000; // 30 min
let _wonRefreshing = null;

async function getWonDealsCached(force = false) {
  if (!force && _wonCache && (Date.now() - _wonCacheAt) < WON_TTL) return _wonCache;
  // Já tem refresh em curso? aguarda o mesmo
  if (_wonRefreshing) return _wonRefreshing;
  _wonRefreshing = (async () => {
    const t0 = Date.now();
    try {
      console.log('[won-cache] refresh em andamento...');
      const previousIds = new Set((_wonCache || []).map(d => d.id));
      const won = await buscarTodosFechadosGanho(36, WON_FIELDS);
      const semProduto = won.filter(d => !d.Produto_Vendido || !d.Produto_Vendido.trim());
      await enrichDealsWithProducts(semProduto, { limit: 400, parallel: 12 });
      // Detecta vendas NOVAS (não estavam no cache anterior) e broadcasta
      // Só faz isso se já tinha cache antes (evita disparar 6000 sons no boot inicial)
      if (previousIds.size > 0) {
        const today = todayBR();
        const novos = won.filter(d => !previousIds.has(d.id) && d.Closing_Date === today);
        for (const d of novos) {
          try {
            sseBroadcast('venda-fechada', {
              id: d.id,
              nome: d.Deal_Name || '',
              amount: parseFloat(d.Amount) || 0,
              owner: d.Owner?.name || '',
              produto: d.Produto_Vendido || '',
              data: d.Closing_Date,
              ts: Date.now(),
            });
            console.log(`[won-cache] 🎉 NOVA VENDA detectada: ${d.Deal_Name} · R$${d.Amount} · ${d.Owner?.name}`);
          } catch(_){}
        }
      }
      _wonCache = won;
      _wonCacheAt = Date.now();
      // Snapshot no PG (resiliente a deploy)
      kvSet('won-deals-snapshot', { count: won.length, at: _wonCacheAt, deals: won }).catch(()=>{});
      console.log(`[won-cache] refresh OK: ${won.length} deals em ${Date.now()-t0}ms`);
      return won;
    } finally {
      _wonRefreshing = null;
    }
  })();
  return _wonRefreshing;
}

// Boot: tenta carregar snapshot do PG pra ter dados imediatos
async function bootLoadWonCache() {
  await kvLoadAll(); // garante KV carregado
  const snap = _kvCache['won-deals-snapshot'];
  if (snap?.deals && Array.isArray(snap.deals) && (Date.now() - (snap.at||0)) < 4 * 3600000) {
    _wonCache = snap.deals;
    _wonCacheAt = snap.at;
    console.log(`[won-cache] boot do PG: ${snap.deals.length} deals (idade ${Math.round((Date.now()-snap.at)/60000)}min)`);
  } else {
    console.log('[won-cache] sem snapshot válido — vai buscar do Zoho no 1º request');
  }
}
bootLoadWonCache();

// Pre-warm: refresh em background a cada 30min (mantém cache sempre quente)
setTimeout(() => getWonDealsCached(true).catch(e => console.warn('[pre-warm]', e.message)), 60000);
setInterval(() => getWonDealsCached(true).catch(()=>{}), WON_TTL);

