// === SQUADS — equipes de venda configuráveis ===
// Cada user pode estar em N squads (campo teams[]). Mantemos `team` (string)
// como squad PRIMÁRIA pra compat com código legado que filtra por u.team.
// Empresa total = soma das squads.
const SQUADS = [
  { key: 'filtro_tratada', label: 'Filtro Água Tratada',     icon: '💧' },
  { key: 'filtro_poco',    label: 'Filtro Água Não Tratada', icon: '🪣' },
  { key: 'bebedouro',      label: 'Time Bebedouro',          icon: '🚰' },
  { key: 'refil',          label: 'Reflow',                  icon: '🔄' },
  { key: 'loja',           label: 'Loja Física',             icon: '🏬' },
];
const SQUAD_KEYS = SQUADS.map(s => s.key);
// Mapeia chaves legadas (campo team string) pras novas keys de squad
const LEGACY_TEAM_MAP = { filtro: 'filtro_tratada', poco: 'filtro_poco' };
function getUserTeams(u) {
  if (Array.isArray(u?.teams) && u.teams.length) return u.teams;
  if (!u?.team) return [];
  return [LEGACY_TEAM_MAP[u.team] || u.team];
}
function userInSquad(u, squadKey) {
  return getUserTeams(u).includes(squadKey);
}
// Backfill: garante que todo user tem teams[] (idempotente)
for (const u of Object.values(USERS)) {
  if (!Array.isArray(u.teams)) u.teams = getUserTeams(u);
}

