// Simple cache (5 min TTL)
const _cache = {};
function cacheGet(key) {
  const c = _cache[key];
  if (c && Date.now() < c.exp) return c.data;
  return null;
}
function cacheSet(key, data, ttl = 300000) {
  _cache[key] = { data, exp: Date.now() + ttl };
}

// Clear all cache
app.get('/cache-clear', requireAuth, (req, res) => {
  Object.keys(_cache).forEach(k => delete _cache[k]);
  res.json({ cleared: true });
});

// Helper: data de hoje no fuso de São Paulo (Brasília UTC-3, sem DST desde 2019)
// Bug crítico antes: todayBR() retornava UTC, então depois das 21h
// BRT a data já estava no dia seguinte e comparações com Closing_Date (BRT) zeravam.
function todayBR() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(new Date());
}
function nowBR() {
  // Retorna objeto Date "alinhado" ao horário de Brasília — útil pra getHours, etc.
  // Truque: pega componentes em São Paulo e cria Date local
  const f = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Sao_Paulo', year:'numeric', month:'2-digit', day:'2-digit',
    hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false
  }).formatToParts(new Date());
  const o = {};
  for (const p of f) o[p.type] = p.value;
  return new Date(`${o.year}-${o.month}-${o.day}T${o.hour==='24'?'00':o.hour}:${o.minute}:${o.second}`);
}

async function zohoSearch(criteria, fields, perPage = 200, maxPages = 10) {
  const token = await getZohoToken();
  if (!token) return [];
  const all = [];
  for (let page = 1; page <= maxPages; page++) {
    const url = `https://www.zohoapis.com/crm/v5/Deals/search?criteria=${encodeURIComponent(criteria)}&fields=${fields}&per_page=${perPage}&page=${page}`;
    const res = await fetch(url, { headers: { Authorization: `Zoho-oauthtoken ${token}` } });
    if (res.status === 204) break;
    if (!res.ok) break;
    const data = await res.json();
    const records = data.data || [];
    if (!records.length) break;
    all.push(...records);
    // Para se não há mais páginas (Zoho v5 retorna info.more_records)
    if (data.info && data.info.more_records === false) break;
    if (records.length < perPage) break;
  }
  return all;
}

// === Detalhe de um canal: produtos cotados + vendas convertidas ===
app.get('/gestao/canal-detalhe', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });

  const canalReq = (req.query.canal || '').toString();
  if (!canalReq) return res.status(400).json({ error: 'canal obrigatório' });

  // Mapeia label do front pro regex de Lead_Source
  const canalRegex = {
    'Google':     /google/i,
    'Facebook':   /facebook|meta(?!s)/i,
    'Instagram':  /instagram/i,
    'WhatsApp':   /ctwa|whatsapp/i,
    'Indicação':  /indica/i,
    'Loja':       /loja/i,
    'Orgânico':   /org[aâ]nic/i,
    'Outros':     /.*/, // fallback
  }[canalReq] || new RegExp(canalReq, 'i');

  try {
    const nowBr = nowBR();
    const today = todayBR();
    const monthStart = `${nowBr.getFullYear()}-${String(nowBr.getMonth()+1).padStart(2,'0')}-01`;

    const cacheKey = `canal-detalhe:${canalReq}:${today}:${nowBr.getHours()}`;
    const cached = cacheGet(cacheKey);
    if (cached) return res.json(cached);

    // Busca em paralelo: propostas ativas + vendas do mês + perdas do mês
    const [propostasAtivas, vendasMes, perdasMes] = await Promise.all([
      zohoSearch(
        '(Stage:in:Proposta,Proposta Quente,Proposta Fria,Em Atendimento)',
        'Deal_Name,Stage,Amount,Lead_Source,Owner,Telefone_contato,Last_Activity_Time,Created_Time,Tier_Lead', 200
      ),
      zohoSearch(
        `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Amount,Owner,Closing_Date,Lead_Source,Created_Time,Tier_Lead', 200
      ),
      zohoSearch(
        `((Stage:equals:Fechado perdido)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Amount,Owner,Lead_Source,Closing_Date', 200
      ),
    ]);

    // Função pra checar se o deal pertence ao canal solicitado
    // Pra "Outros": tudo que NÃO bate com nenhum dos canais conhecidos
    const matchCanal = (d) => {
      const src = d.Lead_Source || '';
      if (canalReq === 'Outros') {
        const conhecidos = [/google/i, /facebook|meta(?!s)/i, /instagram/i, /ctwa|whatsapp/i, /indica/i, /loja/i, /org[aâ]nic/i];
        return !conhecidos.some(rx => rx.test(src));
      }
      return canalRegex.test(src);
    };

    const propsCanal = propostasAtivas.filter(matchCanal);
    const vendasCanal = vendasMes.filter(matchCanal);
    const perdasCanal = perdasMes.filter(matchCanal);

    // Enriquece com Quoted_Items pra ter produtos reais
    await enrichDealsWithProducts(propsCanal, { limit: 50 });
    await enrichDealsWithProducts(vendasCanal, { limit: 80 });

    // Identifica produto principal de um deal (o item de maior valor) ou string concat
    const produtoPrincipal = (d) => {
      if (Array.isArray(d.produtosArr) && d.produtosArr.length) {
        const top = [...d.produtosArr].sort((a,b) => (b.valor||0) - (a.valor||0))[0];
        return top.nome;
      }
      return d.produtosReais || d.Produto_Vendido || '— sem produto cadastrado —';
    };

    // Agrega por produto
    const agg = {}; // {produto: { propostas:N, valorProp:R$, vendas:N, valorVendas:R$, dealsVendas:[], dealsPropostas:[] }}
    for (const d of propsCanal) {
      const p = produtoPrincipal(d);
      if (!agg[p]) agg[p] = { produto:p, propostas:0, valorProp:0, vendas:0, valorVendas:0, dealsVendas:[], dealsPropostas:[] };
      agg[p].propostas++;
      agg[p].valorProp += parseFloat(d.Amount) || 0;
      agg[p].dealsPropostas.push({
        id: d.id, name: d.Deal_Name, amount: parseFloat(d.Amount)||0,
        owner: d.Owner?.name || '?', stage: d.Stage,
        crmLink: d.id ? `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}` : '',
        phone: d.Telefone_contato,
      });
    }
    for (const d of vendasCanal) {
      const p = produtoPrincipal(d);
      if (!agg[p]) agg[p] = { produto:p, propostas:0, valorProp:0, vendas:0, valorVendas:0, dealsVendas:[], dealsPropostas:[] };
      agg[p].vendas++;
      agg[p].valorVendas += parseFloat(d.Amount) || 0;
      agg[p].dealsVendas.push({
        id: d.id, name: d.Deal_Name, amount: parseFloat(d.Amount)||0,
        owner: d.Owner?.name || '?', dataFechamento: d.Closing_Date,
        crmLink: d.id ? `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}` : '',
      });
    }

    // Ordena por valor potencial (proposta + venda) decrescente
    const produtos = Object.values(agg).sort((a,b) => (b.valorProp + b.valorVendas) - (a.valorProp + a.valorVendas));

    // Totais do canal
    const totalPropostas = propsCanal.length;
    const valorPropostas = propsCanal.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const totalVendas = vendasCanal.length;
    const valorVendas = vendasCanal.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const totalPerdas = perdasCanal.length;
    const conversao = (totalVendas + totalPerdas) > 0 ? Math.round(totalVendas / (totalVendas + totalPerdas) * 100) : 0;

    const out = {
      canal: canalReq,
      stats: {
        totalPropostas, valorPropostas,
        totalVendas, valorVendas,
        totalPerdas,
        conversao,
        ticketMedioVendas: totalVendas > 0 ? Math.round(valorVendas / totalVendas) : 0,
      },
      produtos,
      generatedAt: new Date().toISOString(),
    };
    cacheSet(cacheKey, out, 600000); // 10 min
    res.json(out);
  } catch (err) {
    console.error('canal-detalhe:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// === Helper: produtos REAIS de 1 deal via Quotes/Quoted_Items ===
async function getQuoteItemsForDeal(dealId) {
  if (!dealId) return [];
  const cacheKey = `quote-items:${dealId}`;
  const cached = cacheGet(cacheKey);
  if (cached) return cached;
  try {
    const token = await getZohoToken();
    if (!token) return [];
    // 1. Quotes relacionados ao deal
    const relUrl = `https://www.zohoapis.com/crm/v6/Deals/${dealId}/Quotes?fields=id`;
    const r1 = await fetch(relUrl, { headers: { Authorization: `Zoho-oauthtoken ${token}` } });
    if (!r1.ok || r1.status === 204) { cacheSet(cacheKey, [], 3600000); return []; }
    const j1 = await r1.json();
    const quotes = j1.data || [];
    if (!quotes.length) { cacheSet(cacheKey, [], 3600000); return []; }
    // 2. Carrega cada Quote completo + extrai Quoted_Items
    const items = [];
    for (const q of quotes) {
      try {
        const r2 = await fetch(`https://www.zohoapis.com/crm/v6/Quotes/${q.id}`, {
          headers: { Authorization: `Zoho-oauthtoken ${token}` }
        });
        if (!r2.ok) continue;
        const j2 = await r2.json();
        const qd = j2.data?.[0];
        if (!qd?.Quoted_Items) continue;
        for (const it of qd.Quoted_Items) {
          // Description = nome customizado pro cliente; Product_Name.name = catálogo
          const nome = it.Description || it.Product_Name?.name || '';
          if (nome) items.push({
            nome,
            qtd: it.Quantity || 1,
            valor: parseFloat(it.Total) || 0,
          });
        }
      } catch(_){}
    }
    cacheSet(cacheKey, items, 3600000); // 1 hora
    return items;
  } catch (e) {
    console.error('getQuoteItemsForDeal:', e.message);
    return [];
  }
}

// Helper: enriquece array de deals injetando produtosReais (string concat dos
// itens cotados) + produtosArr (array). Usar SEMPRE em regex de match de
// produto em vez de d.Produto_Vendido (que vem null em maioria das vendas).
async function enrichDealsWithProducts(deals, opts = {}) {
  const { limit = 50, parallel = 8 } = opts;
  if (!Array.isArray(deals) || !deals.length) return deals;
  const targets = deals.slice(0, limit);
  for (let i = 0; i < targets.length; i += parallel) {
    const ch = targets.slice(i, i + parallel);
    await Promise.all(ch.map(async d => {
      if (!d.id) return;
      try {
        const items = await getQuoteItemsForDeal(d.id);
        d.produtosArr = items;
        d.produtosReais = items.map(it => it.nome).join(' | ') ||
                          d.Produto_Vendido || '';
      } catch(_) {
        d.produtosArr = [];
        d.produtosReais = d.Produto_Vendido || '';
      }
    }));
  }
  // Pros que ficaram fora do limite, copia Produto_Vendido como fallback
  for (let i = limit; i < deals.length; i++) {
    deals[i].produtosArr = [];
    deals[i].produtosReais = deals[i].Produto_Vendido || '';
  }
  return deals;
}

// Endpoint batch — pra modal da meta-bar carregar produtos sob demanda
app.post('/gestao/deal-products', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { dealIds } = req.body || {};
  if (!Array.isArray(dealIds) || !dealIds.length) return res.status(400).json({ error: 'dealIds obrigatório' });
  const limit = dealIds.slice(0, 100);
  const results = {};
  // Chunks de 8 paralelos pra não estourar Zoho rate limit
  for (let i = 0; i < limit.length; i += 8) {
    const ch = limit.slice(i, i+8);
    await Promise.all(ch.map(async id => { results[id] = await getQuoteItemsForDeal(id); }));
  }
  res.json({ products: results });
});

// Helper: categoria comercial baseada em Pipeline + Layout (verdade do Zoho)
// 5 canais: filtro (concessionária+poço) | bebedouro | loja (balcão) | refil (online) | outros
function canalDeal(d) {
  const layoutName = (d.Layout?.name || d.Layout?.display_label || '').toString();
  const pipe = (d.Pipeline || '').toString();
  if (layoutName === 'Loja') return 'loja';                                    // balcão
  if (/^Fúnil Base$|^Funil Base$/i.test(pipe)) return 'refil';                 // refil/elemento filtrante online
  if (pipe === 'Geral') return 'bebedouro';                                     // bebedouro novo
  if (/estação de tratamento/i.test(pipe)) return 'filtro';                     // concessionária
  if (/água não tratada|agua nao tratada/i.test(pipe)) return 'filtro';         // poço
  return 'outros';
}

