// === TRAVA GLOBAL DO REVENDEDOR ===
// Roda ANTES de qualquer rota, para todo request. É global de propósito: nem toda
// rota do portal passa por requireAuth (lib/auditoria-crm, por exemplo, monta as
// próprias rotas com auth próprio). Allowlist só é confiável quando está no caminho
// de TODO request, não em cada rota lembrando de se proteger.
// Arquivos estáticos (public/) são servidos antes deste ponto e não são afetados.
app.use((req, res, next) => {
  if (!req.session?.user) return next();
  const role = USERS[req.session.user.username]?.role;
  if (role !== 'revendedor') return next();
  // originalUrl, não req.path: em rota montada com app.use('/x', ...) o Express
  // corta o prefixo e req.path viraria '/', bloqueando tudo.
  const p = String(req.originalUrl || req.url || '').split('?')[0];
  if (revendedorPodeAcessar(p)) return next();
  const accept = req.headers.accept || '';
  if (/^text\/html\b|,\s*text\/html\b/i.test(accept)) return res.redirect('/revendedor');
  return res.status(403).json({ error: 'acesso restrito aos treinamentos' });
});

// --- Helpers de nível de autorização ---
function nivelDe(u) {
  if (!u) return 'usuario';
  if (u.nivel) return u.nivel;
  if (u.role === 'admin') return 'ceo';
  return 'usuario';
}
function isGestor(u) { const n = nivelDe(u); return n === 'gestor' || n === 'ceo'; }
function isCEO(u)    { return nivelDe(u) === 'ceo'; }

// === REVENDEDOR: catálogo do que ele enxerga ===
// Esta é a ÚNICA lista que decide o acesso do revendedor. Para liberar ou tirar
// um conteúdo, mexa só aqui — a trava de rotas, o menu e a página inicial dele
// leem todos desta constante.
const ACADEMIAS_REVENDEDOR = [
  { base: '/treinamento/filtro-entrada', titulo: 'Filtro de Entrada',            ico: '🏠', desc: 'O carro-chefe da casa: onde instala, o que trata e como dimensionar.' },
  { base: '/treinamento/poco',           titulo: 'Tratamento de Água de Poço',   ico: '💧', desc: 'Ferro, manganês, pH, coliformes — o que cada problema exige de equipamento.' },
  { base: '/treinamento/bebedouros',     titulo: 'Bebedouros Industriais',       ico: '🚰', desc: 'Linha corporativa: modelos, capacidade, instalação e o ciclo de troca de refil.' },
  { base: '/treinamento/scale-stop',     titulo: 'Scale Stop',                   ico: '💎', desc: 'Anti-incrustante: água dura, incrustação e proteção de equipamento.' },
  { base: '/treinamento/tecnicas-vendas',titulo: 'Técnicas Avançadas de Vendas', ico: '🎯', desc: 'Venda consultiva: sondagem, implicação, ancoragem e fechamento.' },
  { base: '/treinamento/scripts-rav',    titulo: 'Scripts de Atendimento',       ico: '📚', desc: 'Primeira mensagem, qualificação, oferta e as respostas para as objeções mais comuns.' },
];

// Sufixos SEMPRE bloqueados dentro do que foi liberado.
// /gestor mostra a matriz do time inteiro (nome de closer, % e nota) — nunca para revendedor.
const REVENDEDOR_SUFIXOS_BLOQUEADOS = ['/gestor'];

// Telas de serviço que o revendedor precisa.
const REVENDEDOR_ROTAS_EXTRAS = ['/revendedor', '/revendedor/como-usar', '/logout'];

function revendedorPodeAcessar(p) {
  p = p || '';
  if (REVENDEDOR_ROTAS_EXTRAS.includes(p)) return true;
  if (p.startsWith('/uploads/')) return true;
  for (const a of ACADEMIAS_REVENDEDOR) {
    if (p !== a.base && !p.startsWith(a.base + '/')) continue;
    const resto = p.slice(a.base.length);
    if (REVENDEDOR_SUFIXOS_BLOQUEADOS.some(s => resto === s || resto.startsWith(s + '/'))) return false;
    return true;
  }
  return false;
}

// --- Auth middleware ---
function requireAuth(req, res, next) {
  if (req.session && req.session.user) {
    // Isolamento do role 'financeiro': só pode navegar em rotas autorizadas.
    // Tudo o mais é redirecionado pro BI Financeiro (UI já omite os links,
    // mas isto fecha o loop pra acesso direto por URL).
    const role = USERS[req.session.user.username]?.role;
    if (role === 'financeiro') {
      const p = req.path || '';
      const allowedExact = ['/bi-financeiro', '/meu-perfil', '/perfil-completar', '/logout', '/home', '/contatos', '/inbox', '/auvo', '/operacional'];
      // CRM/Manutenção, Inbox, Operacional, Auvo, BI Financeiro — todas as subrotas
      const allowedPrefix = [
        '/uploads/', '/api/perfil', '/bi-financeiro/api',
        '/manutencao', '/inbox', '/auvo', '/operacional', '/contatos',
        '/api/manutencao', '/api/auvo', '/api/contatos', '/api/inbox',
        '/webhooks/wati', '/webhooks/zapi', // pra não atrapalhar mensagens chegando
      ];
      const ok = allowedExact.includes(p) || allowedPrefix.some(pre => p.startsWith(pre));
      if (!ok) {
        const accept = req.headers.accept || '';
        if (/^text\/html\b|,\s*text\/html\b/i.test(accept)) return res.redirect('/bi-financeiro');
        return res.status(403).json({ error: 'acesso restrito ao BI Financeiro' });
      }
    }
    return next();
  }
  // Detecta navegação HTML vs AJAX. Browser nav envia 'Accept: text/html,...'.
  // Fetch padrão sem custom header envia 'Accept: */*'.
  const accept = req.headers.accept || '';
  const wantsHTML = /^text\/html\b|,\s*text\/html\b/i.test(accept);
  if (!wantsHTML) {
    return res.status(401).json({ error: 'Sessão expirada — recarregue a página e faça login novamente.', code: 'session_expired', loginUrl: '/' });
  }
  return res.redirect('/');
}

// === PERFIL OBRIGATÓRIO PARA CLOSERS ===
// Closer precisa preencher cadastro completo (foto rosto + foto momento +
// CEP, estado, telefone, email, aniversário) antes de acessar o portal.
// Admin não precisa.
const PERFIS_FILE = path.join(__dirname, 'data/closer-perfis.json');
const UPLOADS_DIR = path.join(__dirname, 'data/uploads/closers');
function loadPerfis() { return kvOrFile('closer-perfis', PERFIS_FILE, {}); }
function savePerfis(d) { kvAndFile('closer-perfis', PERFIS_FILE, d); }
function perfilCompleto(p) {
  if (!p) return false;
  if (!p.lgpd?.aceito) return false; // LGPD obrigatório
  const obrig = ['email', 'telefone', 'cep', 'estado', 'aniversario', 'fotoRosto', 'fotoMomento'];
  return obrig.every(f => p[f] && String(p[f]).trim().length >= 2);
}

// Middleware: redireciona closer com perfil incompleto pra /perfil-completar
function requireProfile(req, res, next) {
  const u = USERS[req.session.user.username];
  if (!u || u.role === 'admin') return next();
  const perfis = loadPerfis();
  if (perfilCompleto(perfis[req.session.user.username])) return next();
  // Já está numa rota de perfil ou logout? deixa passar
  if (req.path.startsWith('/perfil') || req.path === '/logout' || req.path === '/uploads') return next();
  // Browser nav → redirect; AJAX → JSON 403
  const isAjax = req.xhr || /\bapplication\/json\b/i.test(req.headers.accept || '') || ['POST','PUT','DELETE','PATCH'].includes(req.method);
  if (isAjax) return res.status(403).json({ error: 'Complete seu cadastro primeiro', code:'profile_incomplete', redirect:'/perfil-completar' });
  return res.redirect('/perfil-completar');
}

