app.post('/perfil', requireAuth, (req, res) => {
  const { email, telefone, cep, estado, cidade, endereco, aniversario, instagram, aceitouLgpd } = req.body || {};
  const perfis = loadPerfis();
  const username = req.session.user.username;
  if (!perfis[username]) perfis[username] = {};
  const p = perfis[username];
  if (email !== undefined) p.email = String(email||'').trim().toLowerCase();
  if (telefone !== undefined) p.telefone = String(telefone||'').replace(/\D/g,'');
  if (cep !== undefined) p.cep = String(cep||'').replace(/\D/g,'');
  if (estado !== undefined) p.estado = String(estado||'').toUpperCase().slice(0, 2);
  if (cidade !== undefined) p.cidade = String(cidade||'').trim();
  if (endereco !== undefined) p.endereco = String(endereco||'').trim();
  if (aniversario !== undefined) p.aniversario = aniversario; // YYYY-MM-DD
  if (instagram !== undefined) p.instagram = String(instagram||'').trim();
  // LGPD: registra aceite com timestamp + IP + UserAgent (Lei Geral Proteção Dados)
  if (aceitouLgpd === true && !p.lgpd?.aceito) {
    p.lgpd = {
      aceito: true,
      at: new Date().toISOString(),
      ip: (req.headers['x-forwarded-for']||'').split(',')[0].trim() || req.socket?.remoteAddress || '',
      userAgent: (req.headers['user-agent']||'').slice(0, 200),
      versao: '1.0',
    };
  }
  p.updatedAt = new Date().toISOString();
  savePerfis(perfis);
  res.json({ ok:true, perfil: perfis[username], completo: perfilCompleto(perfis[username]) });
});

// POST /perfil/foto { tipo: 'rosto'|'momento', dataUrl: 'data:image/jpeg;base64,...' }
// Armazena foto reduzida (base64) DENTRO do JSON pra sobreviver a deploy
// sem volume Railway. Frontend faz resize antes de enviar (max ~120kb).
app.post('/perfil/foto', requireAuth, (req, res) => {
  const { tipo, dataUrl } = req.body || {};
  if (!['rosto', 'momento'].includes(tipo)) return res.status(400).json({ error: 'tipo deve ser rosto ou momento' });
  if (!dataUrl || !dataUrl.startsWith('data:image/')) return res.status(400).json({ error: 'dataUrl inválido' });
  const m = dataUrl.match(/^data:image\/(jpeg|jpg|png|webp);base64,(.+)$/);
  if (!m) return res.status(400).json({ error: 'formato não suportado (use jpeg/png/webp)' });
  const buffer = Buffer.from(m[2], 'base64');
  // Limite generoso, mas frontend já reduz pra ~50-150kb
  if (buffer.length > 1.5 * 1024 * 1024) return res.status(400).json({ error: 'foto ainda muito grande (max 1.5MB) — recarregue a página' });
  const username = req.session.user.username;
  const perfis = loadPerfis();
  if (!perfis[username]) perfis[username] = {};
  const key = tipo === 'rosto' ? 'fotoRosto' : 'fotoMomento';
  const tsKey = tipo === 'rosto' ? 'fotoRostoAt' : 'fotoMomentoAt';
  perfis[username][key] = dataUrl; // armazena dataUrl completa no JSON
  perfis[username][tsKey] = Date.now();
  perfis[username].updatedAt = new Date().toISOString();
  savePerfis(perfis);
  // Também salva em disco se tiver volume (best-effort, não obrigatório)
  try {
    const dir = path.join(UPLOADS_DIR, username);
    require('fs').mkdirSync(dir, { recursive: true });
    require('fs').writeFileSync(path.join(dir, `${tipo}.jpg`), buffer);
  } catch(_){}
  res.json({
    ok: true,
    url: `/uploads/closers/${username}/${tipo}.jpg?v=${Date.now()}`,
    completo: perfilCompleto(perfis[username]),
    bytes: buffer.length,
  });
});

// Servir uploads — preferência: arquivo em disco; fallback: base64 do JSON
app.get('/uploads/closers/:username/:filename', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin';
  if (!isAdmin && req.params.username !== req.session.user.username) return res.status(403).end();
  const username = req.params.username.replace(/[^A-Za-z0-9._-]/g, '');
  const safe = req.params.filename.replace(/[^A-Za-z0-9._-]/g, '');
  const file = path.join(UPLOADS_DIR, username, safe);
  // 1. tenta arquivo em disco (se Railway tiver volume montado)
  if (file.startsWith(UPLOADS_DIR) && require('fs').existsSync(file)) {
    return res.sendFile(file);
  }
  // 2. fallback: base64 no JSON
  const tipo = safe.startsWith('rosto') ? 'fotoRosto' : (safe.startsWith('momento') ? 'fotoMomento' : null);
  if (!tipo) return res.status(404).end();
  const perfis = loadPerfis();
  const dataUrl = perfis[username]?.[tipo];
  if (!dataUrl || !dataUrl.startsWith('data:image/')) return res.status(404).end();
  const m = dataUrl.match(/^data:image\/(jpeg|jpg|png|webp);base64,(.+)$/);
  if (!m) return res.status(404).end();
  res.set('Content-Type', `image/${m[1] === 'jpg' ? 'jpeg' : m[1]}`);
  res.set('Cache-Control', 'private, max-age=300');
  res.send(Buffer.from(m[2], 'base64'));
});

