app.post('/login', (req, res) => {
  const { username, password } = req.body;
  const user = USERS[username];
  if (user && user.password === password) {
    req.session.user = { username, name: user.name, role: user.role };
    // Loga login
    try {
      if (typeof _accessLogAdd === 'function') {
        _accessLogAdd({
          type: 'login', username, name: user.name, role: user.role,
          ip: (req.headers['x-forwarded-for']||req.ip||'').split(',')[0].trim(),
          ua: (req.headers['user-agent']||'').slice(0, 200),
        });
      }
    } catch(_){}
    // Financeiro vai direto pro BI; outros roles vão pro Home
    if (user.role === 'financeiro') return res.redirect('/bi-financeiro');
    if (user.role === 'revendedor') return res.redirect('/revendedor');
    return res.redirect('/home');
  }
  return res.redirect('/?error=1');
});

