// === PRAZO DE TREINAMENTO (countdown 168h) — só para closers-alvo ===
// deadlineISO = ~168h a partir de 03/jul/2026. Ajuste aqui se precisar reprogramar.
const PRAZO_TREINO = {
  deadlineISO: '2026-07-10T18:00:00-03:00',
  totalHoras: 168,
  // casa por username, email ou primeiro nome (robusto a como o login foi criado)
  alvos: ['catia', 'larissa', 'gabrielly', 'gabrielly.s', 'gabrielly.s@tudodefiltro.com.br'],
  academia: { nome: 'Bebedouros Industriais', url: '/treinamento/bebedouros', totalModulos: 21 },
};
function ehAlvoPrazo(uname) {
  const u = USERS[uname] || {};
  const campos = [String(uname || ''), String(u.email || ''), String(u.name || '')].map(s => s.toLowerCase());
  return PRAZO_TREINO.alvos.some(a => {
    a = a.toLowerCase();
    return campos[0] === a || campos[1] === a || campos[2].split(/\s+/).includes(a) || campos[2].includes(a);
  });
}

app.get('/home', requireAuth, (req, res) => {
  // Financeiro não tem o que fazer no Home — vai direto pro BI
  const role = USERS[req.session.user.username]?.role;
  if (role === 'financeiro') return res.redirect('/bi-financeiro');
  // countdown de treinamento (só para os alvos)
  let prazoTreino = null;
  const uname = req.session.user.username;
  if (ehAlvoPrazo(uname)) {
    const prog = _kvCache['treinbeb:progress:' + uname] || {};
    const concluidos = Object.values(prog.modulos || {}).filter(m => m && m.concluido).length;
    const certificado = !!prog.certificado;
    const pct = Math.round((concluidos / PRAZO_TREINO.academia.totalModulos) * 100);
    prazoTreino = {
      deadlineISO: PRAZO_TREINO.deadlineISO, totalHoras: PRAZO_TREINO.totalHoras,
      academia: PRAZO_TREINO.academia, nome: (USERS[uname] && USERS[uname].name) || uname,
      concluidos, total: PRAZO_TREINO.academia.totalModulos, pct, certificado,
      atrasado: !certificado, // ainda não certificou = precisa acelerar
    };
  }
  res.render('home', { user: req.session.user, prazoTreino });
});

// Propostas por categoria (Filtro Entrada / Bebedouro / Outros) — hoje + mês
app.get('/home/propostas-categoria', requireAuth, async (req, res) => {
  try {
    const today = todayBR();
    const nowBr = nowBR();
    const monthStart = `${nowBr.getFullYear()}-${String(nowBr.getMonth()+1).padStart(2,'0')}-01`;
    const cacheKey = `home-propostas:${today}:${nowBr.getHours()}:${Math.floor(nowBr.getMinutes()/10)}`;
    if (req.query.nocache !== '1') {
      const cached = cacheGet(cacheKey);
      if (cached) return res.json(cached);
    }
    // Busca deals em Stage de Proposta criados/movidos no mês
    // Modified_Time funciona como aproximação de "quando virou proposta"
    const propostas = await zohoSearch(
      `((Stage:in:Proposta,Proposta Quente,Proposta Fria)and(Modified_Time:between:${monthStart}T00:00:00-03:00,${today}T23:59:59-03:00))`,
      'Deal_Name,Stage,Amount,Owner,Pipeline,Layout,Produto_Vendido,Modified_Time,Telefone_contato',
      200, 5
    );
    await enrichDealsWithProducts(propostas, { limit: 200, parallel: 8 });
    // Carrega overrides (só admin pode ter setado, mas todo mundo enxerga o resultado)
    const dealOverrides = require('./lib/deal-overrides');
    const ovMap = await dealOverrides.getOverridesMap(_pgPool).catch(() => ({}));
    // Detecta purificador (não industrial). Usa nome do deal + Pipeline + produto.
    const isPurificador = (d) => {
      const blob = `${d.produtosReais||''} ${d.Deal_Name||''} ${d.Pipeline||''} ${d.Produto_Vendido||''}`.toLowerCase();
      if (/industrial/.test(blob)) return false; // industrial vai pra bebedouro
      return /\bpurificador\b|\baf.?15\b|\baf.?25\b|\bbliss\b|\bsoft\b|\bpremium\b/.test(blob);
    };
    const buildCategoria = (deals) => {
      const out = { filtro_entrada: [], bebedouro: [], purificador: [], outros: [] };
      for (const d of deals) {
        // 1) Override manual tem prioridade absoluta
        const ov = ovMap[d.id];
        let bucket;
        if (ov && ov.category_override) {
          const oc = ov.category_override;
          bucket = (oc === 'filtro_entrada' || oc === 'iron_free' || oc === 'scale_stop' || oc === 'elemento_filtrante') ? 'filtro_entrada'
                 : (oc === 'bebedouro' || oc === 'refil') ? 'bebedouro'
                 : (oc === 'purificador') ? 'purificador'
                 : 'outros';
        } else {
          // 2) Detecção automática
          if (isPurificador(d)) {
            bucket = 'purificador';
          } else {
            const cat = categoriaManutInteligente(d);
            bucket = (cat === 'elemento' || cat === 'iron_free' || cat === 'scale_stop') ? 'filtro_entrada'
                   : cat === 'bebedouro_refil' ? 'bebedouro'
                   : 'outros';
          }
        }
        const ownerName = ov?.vendedor_override_name || d.Owner?.name || '?';
        out[bucket].push({
          id: d.id,
          nome: d.Deal_Name || '?',
          stage: d.Stage,
          owner: ownerName,
          owner_overridden: !!ov?.vendedor_override_name,
          category_overridden: !!ov?.category_override,
          amount: parseFloat(d.Amount) || 0,
          produto: d.produtosReais || d.Produto_Vendido || '',
          modificadoEm: d.Modified_Time,
          phone: d.Telefone_contato || '',
        });
      }
      return out;
    };
    // Hoje vs Mês — split pela data de modificação
    const todayPropostas = propostas.filter(d => (d.Modified_Time||'').slice(0,10) === today);
    const dataHoje = buildCategoria(todayPropostas);
    const dataMes = buildCategoria(propostas);
    const stats = {
      hoje: {
        filtro_entrada: { count: dataHoje.filtro_entrada.length, valor: dataHoje.filtro_entrada.reduce((s,d) => s+d.amount, 0) },
        bebedouro:      { count: dataHoje.bebedouro.length,      valor: dataHoje.bebedouro.reduce((s,d) => s+d.amount, 0) },
        purificador:    { count: dataHoje.purificador.length,    valor: dataHoje.purificador.reduce((s,d) => s+d.amount, 0) },
        outros:         { count: dataHoje.outros.length,         valor: dataHoje.outros.reduce((s,d) => s+d.amount, 0) },
      },
      mes: {
        filtro_entrada: { count: dataMes.filtro_entrada.length, valor: dataMes.filtro_entrada.reduce((s,d) => s+d.amount, 0) },
        bebedouro:      { count: dataMes.bebedouro.length,      valor: dataMes.bebedouro.reduce((s,d) => s+d.amount, 0) },
        purificador:    { count: dataMes.purificador.length,    valor: dataMes.purificador.reduce((s,d) => s+d.amount, 0) },
        outros:         { count: dataMes.outros.length,         valor: dataMes.outros.reduce((s,d) => s+d.amount, 0) },
      },
    };
    const out = { stats, leadsHoje: dataHoje, leadsMes: dataMes, generatedAt: new Date().toISOString() };
    cacheSet(cacheKey, out, 600000);
    res.json(out);
  } catch (e) {
    console.error('[home propostas]', e.message);
    res.status(500).json({ error: e.message });
  }
});

