app.post('/admin/deals/:id/override', requireAuth, requireAdmin, async (req, res) => {
  try {
    const { category, vendedorUsername, vendedorName, vendedorId, reason } = req.body || {};
    // Se passou username, resolve nome via USERS
    let resolvedName = vendedorName;
    let resolvedId = vendedorId;
    if (vendedorUsername && USERS[vendedorUsername]) {
      resolvedName = USERS[vendedorUsername].crmOwner || USERS[vendedorUsername].name;
      // ID Zoho não temos no USERS local — fica null e UI mostra só o nome
    }
    if (!category && !resolvedName && !resolvedId) {
      return res.status(400).json({ error: 'precisa de category ou vendedor' });
    }
    await dealOverridesLib.setOverride(_pgPool, req.params.id, {
      category, vendedorId: resolvedId, vendedorName: resolvedName,
      changedBy: req.session.user.username, reason,
    });
    dealOverridesLib.invalidateCache();
    res.json({ ok: true });
  } catch (e) { res.status(400).json({ error: e.message }); }
});

