const biZapiAprov   = require('./lib/bi-zapi-aprovacao');
// bi-zapi-aprovacao recebe DOIS senders:
//   - zapiSendByInstance(cfg, phone, msg) → manda usando uma cfg específica (config da empresa)
//   - zapiSendDefault(phone, msg)         → fallback (resolve config global, sem empresa)
// Lazy-bind: as funções são resolvidas na chamada (à prova de ordem de declaração).
