const biZapiConfig = require('./lib/bi-zapi-config');

// Cache leve por módulo (TTL 90s) pra evitar chamar Zoho a cada filtro do front
const _biZohoCache = { Deals: null, Quotes: null, Sales_Orders: null };
const _biZohoCacheAt = { Deals: 0, Quotes: 0, Sales_Orders: 0 };
const BI_TTL = 90 * 1000;

async function _fetchVendasZoho(module, opts = {}) {
  const force = !!opts.force;
  if (!force && _biZohoCache[module] && (Date.now() - _biZohoCacheAt[module] < BI_TTL)) {
    return _biZohoCache[module];
  }
  let data = [];
  try {
    if (module === 'Deals') {
      // Reusa cache existente de Won deals (já enriquecido com produtos)
      if (typeof getWonDealsCached === 'function') {
        data = await getWonDealsCached();
      } else {
        data = await zoho.search('(Stage:equals:Closed Won)', WON_FIELDS || 'Deal_Name,Amount,Owner,Closing_Date');
      }
    } else if (module === 'Quotes') {
      // Quotes recentes: últimos 90 dias por Modified_Time
      const ninety = new Date(); ninety.setDate(ninety.getDate() - 90);
      const iso = ninety.toISOString();
      // Campos validados via MCP no Zoho real (org TDF):
      //  - Empresa_da_venda (custom, picklist) — pra match automático com empresa BI
      //  - Frete + Valor_de_Frete — pré-preenche ficha
      //  - Forma_de_pagamento, Condi_es_do_pagamento — pré-preenche
      //  - Cidade/Estado/Bairro/Rua — endereço
      //  - Deal_Name (lookup) — link cruzado pro Deal de origem
      //  - ID_do_or_amento — número ERP do orçamento
      //  - Tipo_de_Venda, Categoria_do_Produto — segmentação
      //  - Quoted_Items — itens (com Product_Name, Quantity, Total, Unit_Price)
      const fields = [
        'Subject','Grand_Total','Sub_Total','Discount','Owner','Account_Name','Contact_Name',
        'Quote_Date','Valid_Till','Created_Time','Modified_Time','Quoted_Items',
        'Empresa_da_venda','Frete','Valor_de_Frete','Forma_de_pagamento','Condi_es_do_pagamento',
        'Cidade','Estado','Bairro','Deal_Name','ID_do_or_amento','Tipo_de_Venda','Categoria_do_Produto',
        'Vendedor','Tipo_de_Agua','Agua_de_Po_o','Telefone_do_contato','E_mail_do_contato'
      ].join(',');
      data = await zoho.searchModule('Quotes', `(Modified_Time:greater_equal:${iso})`, fields, { perPage: 200, maxPages: 5 });
    } else if (module === 'Sales_Orders') {
      const ninety = new Date(); ninety.setDate(ninety.getDate() - 90);
      const iso = ninety.toISOString();
      // Sales_Orders TDF: Status ("Recebido", "Aprovado"), Valor_do_Frete (não Frete), Sales_Commission,
      //   Condi_es_de_pagamento, Quote_Name + Deal_Name (lookups), ID_do_Pedido (ERP)
      const fields = [
        'Subject','Status','Grand_Total','Sub_Total','Discount','Owner','Account_Name','Contact_Name',
        'Created_Time','Modified_Time','Ordered_Items',
        'Empresa_da_venda','Valor_do_Frete','Sales_Commission','Condi_es_de_pagamento',
        'Cidade','Estado','Bairro','Quote_Name','Deal_Name','ID_do_Pedido','Tipo_de_Venda',
        'Categoria_do_Produto','Due_Date','Valor_recebido','Pending','Vaz_o','Agua_de_Po_o'
      ].join(',');
      data = await zoho.searchModule('Sales_Orders', `(Modified_Time:greater_equal:${iso})`, fields, { perPage: 200, maxPages: 5 });
    }
  } catch(e) {
    console.warn('[bi] _fetchVendasZoho '+module+':', e.message);
    data = _biZohoCache[module] || []; // fallback pro cache anterior
  }
  _biZohoCache[module] = data;
  _biZohoCacheAt[module] = Date.now();
  return data;
}

// Normaliza records de qualquer módulo num shape único pro frontend.
// Schema validado via MCP Zoho na org TDF (mai/2026):
//   - Deals usa Closing_Date, Amount, Pipeline, Layout, Cidade, Tipo_de_Agua, Lead_Source
//   - Quotes usa Quoted_Items (com Product_Name lookup), Frete, Valor_de_Frete, Forma_de_pagamento
//   - Sales_Orders usa Ordered_Items, Valor_do_Frete, Sales_Commission, Condi_es_de_pagamento
//   - Empresa_da_venda existe nos 3 módulos (custom field) — usado pro match com empresa BI
function _normalizeRecord(module, rec) {
  if (!rec) return null;
  const owner = rec.Owner?.name || rec.Owner_Name || rec.Owner?.full_name || '';
  const ownerId = rec.Owner?.id || '';
  const empresaZoho = rec.Empresa_da_venda || '';

  if (module === 'Deals') {
    const produtosReais = Array.isArray(rec.produtosReais) ? rec.produtosReais : [];
    return {
      module, zohoId: rec.id,
      titulo: rec.Deal_Name || '',
      cliente: rec.Account_Name?.name || rec.Contact_Name?.name || rec.Telefone_contato || '',
      valor: Number(rec.Amount || 0),
      data: rec.Closing_Date || (rec.Created_Time||'').slice(0,10),
      vendedor: owner, vendedorId: ownerId,
      stage: rec.Stage || '',
      origem: rec.Lead_Source || '',
      pipeline: rec.Pipeline || '',
      layout: rec.Layout?.name || '',
      cidade: rec.Cidade || '',
      tipoAgua: rec.Tipo_de_Agua || '',
      empresaZoho,
      produtos: produtosReais.map(p => p.name || p.Product_Name || '').filter(Boolean),
      itens: produtosReais.map(p => ({
        nome: p.name || p.Product_Name || '',
        qtd: Number(p.quantity || 1),
        valor: Number(p.total || p.list_price || 0),
        custo: 0,
      })),
      // Pré-preenchimento sugerido pra ficha (frete/comissão Zoho não vem em Deals)
      prefill: {},
      raw: { Stage: rec.Stage, Closing_Date: rec.Closing_Date, Telefone_contato: rec.Telefone_contato },
    };
  }

  if (module === 'Quotes') {
    const items = Array.isArray(rec.Quoted_Items) ? rec.Quoted_Items : [];
    const grandTotal = Number(rec.Grand_Total || rec.Sub_Total || 0);
    const freteZoho = Number(rec.Valor_de_Frete || rec.Frete || 0);
    const formaPagZoho = rec.Forma_de_pagamento || rec.Condi_es_do_pagamento || '';
    return {
      module, zohoId: rec.id,
      titulo: rec.Subject || '',
      cliente: rec.Account_Name?.name || rec.Contact_Name?.name || rec.Deal_Name?.name || '',
      valor: grandTotal,
      data: (rec.Quote_Date || rec.Created_Time || '').slice(0,10),
      vendedor: owner, vendedorId: ownerId,
      stage: rec.$approval_state || rec.Record_Status__s || '',
      origem: '',
      cidade: rec.Cidade || '',
      estado: rec.Estado || '',
      bairro: rec.Bairro || '',
      tipoAgua: rec.Tipo_de_Agua || '',
      tipoVenda: rec.Tipo_de_Venda || '',
      categoriaProduto: rec.Categoria_do_Produto || '',
      dealLink: rec.Deal_Name ? { id: rec.Deal_Name.id, nome: rec.Deal_Name.name } : null,
      idERP: rec.ID_do_or_amento || '',
      empresaZoho,
      itens: items.map(it => ({
        nome: it.Product_Name?.name || it.product_name || it.Description || '',
        codigo: it.Product_Name?.Product_Code || '',
        qtd: Number(it.Quantity || it.quantity || 1),
        valor: Number(it.Total || it.total || 0),
        unitario: Number(it.Product_Name?.Unit_Price || it.List_Price || 0),
        descricao: it.Description || '',
        custo: 0,
      })),
      produtos: items.map(it => it.Product_Name?.name || it.product_name || '').filter(Boolean),
      desconto: Number(rec.Discount || 0),
      // Pré-preenchimento: o que o Zoho já sabe — pra ficha não nascer zerada
      prefill: {
        frete: freteZoho,
        formaPagamento: formaPagZoho,
        desconto: Number(rec.Discount || 0),
      },
      raw: {},
    };
  }

  if (module === 'Sales_Orders') {
    const items = Array.isArray(rec.Ordered_Items) ? rec.Ordered_Items : [];
    const grandTotal = Number(rec.Grand_Total || rec.Sub_Total || 0);
    const freteZoho = Number(rec.Valor_do_Frete || 0);
    const comissaoZoho = Number(rec.Sales_Commission || 0);
    const formaPagZoho = rec.Condi_es_de_pagamento || '';
    return {
      module, zohoId: rec.id,
      titulo: rec.Subject || '',
      cliente: rec.Account_Name?.name || rec.Contact_Name?.name || rec.Deal_Name?.name || '',
      valor: grandTotal,
      data: (rec.Due_Date || rec.Created_Time || '').slice(0,10),
      vendedor: owner, vendedorId: ownerId,
      stage: rec.Status || rec.$approval_state || '',
      origem: '',
      cidade: rec.Cidade || '',
      estado: rec.Estado || '',
      bairro: rec.Bairro || '',
      tipoVenda: rec.Tipo_de_Venda || '',
      categoriaProduto: rec.Categoria_do_Produto || '',
      dealLink: rec.Deal_Name ? { id: rec.Deal_Name.id, nome: rec.Deal_Name.name } : null,
      quoteLink: rec.Quote_Name ? { id: rec.Quote_Name.id, nome: rec.Quote_Name.name } : null,
      idERP: rec.ID_do_Pedido || '',
      valorRecebido: Number(rec.Valor_recebido || 0),
      valorPendente: Number(rec.Pending || 0),
      vencimento: rec.Due_Date || '',
      empresaZoho,
      itens: items.map(it => ({
        nome: it.Product_Name?.name || it.product_name || '',
        codigo: it.Product_Name?.Product_Code || '',
        qtd: Number(it.Quantity || it.quantity || 1),
        valor: Number(it.Total || it.total || 0),
        unitario: Number(it.Product_Name?.Unit_Price || it.List_Price || 0),
        descricao: it.Description || '',
        custo: 0,
      })),
      produtos: items.map(it => it.Product_Name?.name || it.product_name || '').filter(Boolean),
      desconto: Number(rec.Discount || 0),
      prefill: {
        frete: freteZoho,
        comissao: comissaoZoho,
        formaPagamento: formaPagZoho,
        desconto: Number(rec.Discount || 0),
      },
      raw: {},
    };
  }
  return null;
}

// Tenta achar a empresa BI cadastrada que case com Empresa_da_venda do Zoho (texto).
// Se não houver, retorna ''. Não persiste nada — só sugere pro frontend.
function _matchEmpresaBI(empresaZohoStr, companies) {
  if (!empresaZohoStr || !Array.isArray(companies) || companies.length === 0) return '';
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'');
  const target = norm(empresaZohoStr);
  if (!target) return '';
  // 1) match exato no nome
  let m = companies.find(c => norm(c.nome) === target);
  if (m) return m.id;
  // 2) substring (Zoho contém ou é contido)
  m = companies.find(c => norm(c.nome).includes(target) || target.includes(norm(c.nome)));
  return m ? m.id : '';
}

function _withinDateRange(dateStr, from, to) {
  if (!dateStr) return false;
  const d = String(dateStr).slice(0,10);
  if (from && d < from) return false;
  if (to && d > to) return false;
  return true;
}

// Lista vendas Zoho (Deals + Quotes + Sales_Orders) com filtros
app.get('/bi-financeiro/api/vendas-zoho', requireAuth, requireBIRole, async (req, res) => {
  try {
    const from = req.query.from || ''; // YYYY-MM-DD
    const to   = req.query.to   || '';
    const modulesParam = (req.query.modules || 'Deals').split(',').map(s => s.trim()).filter(Boolean);
    const owner = (req.query.owner || '').toLowerCase();
    const search = (req.query.search || '').toLowerCase();

    const out = [];
    for (const m of modulesParam) {
      if (!['Deals','Quotes','Sales_Orders'].includes(m)) continue;
      const raw = await _fetchVendasZoho(m);
      for (const rec of raw) {
        const norm = _normalizeRecord(m, rec);
        if (!norm) continue;
        if (!_withinDateRange(norm.data, from, to)) continue;
        if (owner && !(norm.vendedor||'').toLowerCase().includes(owner)) continue;
        if (search) {
          const hay = (norm.titulo+' '+norm.cliente+' '+(norm.produtos||[]).join(' ')+' '+norm.vendedor).toLowerCase();
          if (!hay.includes(search)) continue;
        }
        out.push(norm);
      }
    }
    // Anexa ficha + cálculo. Quando a ficha ainda não existe (nunca salva),
    // sugere pré-preenchimento dos custos com dados que o próprio Zoho já tem
    // (frete, comissão, forma_pag, desconto) — financeiro só revisa e salva.
    const fichas = biFichas.indexAll();
    // Busca custo logístico + materiais em batch (1 query cada pra todas as vendas)
    let custosLog = {}, custosMat = {};
    const zohoIdsDeals = out.filter(v => v.module === 'Deals' && v.zohoId).map(v => v.zohoId);
    try {
      if (zohoIdsDeals.length) custosLog = await biRotasCusto.custoPorZohoDealIdsBatch(zohoIdsDeals);
    } catch(e) { console.warn('[vendas-zoho] custo logístico batch:', e.message); }
    try {
      if (zohoIdsDeals.length) custosMat = await biOsMateriais.custoPorZohoDealIdsBatch(zohoIdsDeals);
    } catch(e) { console.warn('[vendas-zoho] custo materiais batch:', e.message); }
    out.forEach(v => {
      const k = `${v.module}_${v.zohoId}`;
      let ficha = fichas[k];
      let isNova = false;
      if (!ficha) {
        ficha = biFichas.defaultFicha(v.module, v.zohoId);
        isNova = true;
        // pré-preenche custos com sugestões do Zoho
        if (v.prefill) {
          if (v.prefill.frete)            ficha.custos.frete = +v.prefill.frete;
          if (v.prefill.comissao)         ficha.custos.comissao = +v.prefill.comissao;
          if (v.prefill.desconto)         ficha.custos.desconto = +v.prefill.desconto;
          if (v.prefill.formaPagamento)   ficha.formaPagamento = String(v.prefill.formaPagamento);
        }
        // Empresa BI: o frontend faz o match com `v.empresaZoho` contra
        // state.companies (localStorage). Backend só expõe a string.
      }
      // Injeta custo logístico automático (sobrescreve qualquer valor manual nesse campo)
      const cl = custosLog[v.zohoId];
      if (cl) {
        ficha.custos.custoLogistico = cl.valor;
        v.custoLogisticoDetalhe = cl; // pra UI mostrar info da rota
      }
      // Custo de materiais (F4) — saída de estoque feita em OSs baixadas
      const cm = custosMat[v.zohoId];
      if (cm) {
        ficha.custos.custoMateriais = cm.valor;
        v.custoMateriaisDetalhe = cm;
      }
      v.ficha = ficha;
      v.fichaNova = isNova; // frontend usa pra mostrar selo "sugerido"
      v.calc = biFichas.calcLucro(v, ficha);
    });
    out.sort((a,b) => (b.data||'').localeCompare(a.data||''));
    res.json({ ok:true, total: out.length, vendas: out });
  } catch(e) {
    console.error('[bi vendas-zoho]', e);
    res.status(500).json({ error: e.message });
  }
});

// Detalhe de UMA venda + ficha
app.get('/bi-financeiro/api/venda/:module/:id', requireAuth, requireBIRole, async (req, res) => {
  try {
    const { module, id } = req.params;
    if (!['Deals','Quotes','Sales_Orders'].includes(module)) return res.status(400).json({ error:'módulo inválido' });
    let rec = null;
    if (module === 'Deals') {
      // tenta cache primeiro
      const cached = (await _fetchVendasZoho('Deals')).find(d => d.id === id);
      rec = cached || await zoho.getRecord('Deals', id, 'Deal_Name,Amount,Owner,Closing_Date,Stage,Lead_Source,Account_Name,Contact_Name,Pipeline,Layout,Telefone_contato,Cidade,Tipo_de_Agua,Produto_Vendido');
    } else {
      rec = await zoho.getRecord(module, id);
    }
    if (!rec) return res.status(404).json({ error:'venda não encontrada' });
    const norm = _normalizeRecord(module, rec);
    let ficha = biFichas.get(module, id);
    let isNova = false;
    if (!ficha) {
      ficha = biFichas.defaultFicha(module, id);
      isNova = true;
      if (norm.prefill) {
        if (norm.prefill.frete)          ficha.custos.frete = +norm.prefill.frete;
        if (norm.prefill.comissao)       ficha.custos.comissao = +norm.prefill.comissao;
        if (norm.prefill.desconto)       ficha.custos.desconto = +norm.prefill.desconto;
        if (norm.prefill.formaPagamento) ficha.formaPagamento = String(norm.prefill.formaPagamento);
      }
    }
    // Custo logístico (se for Deal)
    if (module === 'Deals' && id) {
      try {
        const batch = await biRotasCusto.custoPorZohoDealIdsBatch([id]);
        const cl = batch[id];
        if (cl) {
          ficha.custos.custoLogistico = cl.valor;
          norm.custoLogisticoDetalhe = cl;
        }
      } catch(e) { console.warn('[bi venda] custo logístico:', e.message); }
      try {
        const batchM = await biOsMateriais.custoPorZohoDealIdsBatch([id]);
        const cm = batchM[id];
        if (cm) {
          ficha.custos.custoMateriais = cm.valor;
          norm.custoMateriaisDetalhe = cm;
        }
      } catch(e) { console.warn('[bi venda] custo materiais:', e.message); }
    }
    norm.ficha = ficha;
    norm.fichaNova = isNova;
    norm.calc = biFichas.calcLucro(norm, ficha);
    res.json({ ok:true, venda: norm });
  } catch(e) {
    console.error('[bi venda]', e);
    res.status(500).json({ error: e.message });
  }
});

// Salva ficha (custos editáveis) de uma venda
app.put('/bi-financeiro/api/ficha/:module/:id', requireAuth, requireBIRole, async (req, res) => {
  try {
    const { module, id } = req.params;
    if (!['Deals','Quotes','Sales_Orders'].includes(module)) return res.status(400).json({ error:'módulo inválido' });
    const who = req.session.user?.username || 'desconhecido';
    const body = req.body || {};
    const ficha = biFichas.upsert(module, id, body, who);
    res.json({ ok:true, ficha });
  } catch(e) {
    console.error('[bi ficha PUT]', e);
    res.status(500).json({ error: e.message });
  }
});

// Sync forçado: limpa cache Zoho do BI e re-busca
app.post('/bi-financeiro/api/sync', requireAuth, requireBIRole, async (req, res) => {
  try {
    const modulos = ['Deals','Quotes','Sales_Orders'];
    const counts = {};
    for (const m of modulos) {
      const data = await _fetchVendasZoho(m, { force: true });
      counts[m] = data.length;
    }
    res.json({ ok:true, counts, syncedAt: new Date().toISOString() });
  } catch(e) {
    console.error('[bi sync]', e);
    res.status(500).json({ error: e.message });
  }
});

// Lista vendedores únicos vistos no cache
app.get('/bi-financeiro/api/owners', requireAuth, requireBIRole, async (req, res) => {
  try {
    const set = new Map();
    for (const m of ['Deals','Quotes','Sales_Orders']) {
      const data = await _fetchVendasZoho(m);
      for (const rec of data) {
        const id = rec.Owner?.id || '';
        const name = rec.Owner?.name || '';
        if (name) set.set(id || name, name);
      }
    }
    res.json({ ok:true, owners: Array.from(set.values()).sort() });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

