const biEstoqueDb = require('./lib/bi-estoque-db');
const biEstoque = require('./lib/bi-estoque');

// Inicialização: hooka pool do pgInit existente, cria tabelas
const biFornecedores = require('./lib/bi-fornecedores');
const biVeiculos = require('./lib/bi-veiculos');
const biRotasCusto = require('./lib/bi-rotas-custo');
const biNfEntrada = require('./lib/bi-nf-entrada');
const biNfImap = require('./lib/bi-nf-imap');
const biCompras = require('./lib/bi-compras');
const biZapiCompras = require('./lib/bi-zapi-compras');
const biComprasPdf = require('./lib/bi-compras-pdf');
const biOsMateriais = require('./lib/bi-os-materiais');
(async () => {
  try {
    const pool = await pgInit();
    if (!pool) { console.warn('[bi-estoque] sem Postgres — módulo estoque desativado'); return; }
    biEstoqueDb.setPool(pool);
    await biEstoqueDb.ensureTables();
    await biFornecedores.ensureTable();
    await biVeiculos.ensureTable();
    await biRotasCusto.ensureTable();
    await biNfEntrada.ensureTable();
    await biCompras.ensureTable();
    await biOsMateriais.ensureTable();
    // Liga o monitor IMAP (no-op se NF_IMAP_ENABLED != true)
    biNfImap.start();
  } catch(e) { console.error('[bi-estoque init]', e.message); }
})();

