// Dashboard estoque
// === CONSULTA CNPJ (Receita Federal) ===
// Tenta BrasilAPI primeiro → fallback publica.cnpj.ws (ambas gratuitas e públicas).
// User-Agent é obrigatório nas duas, sem ele dá 403.
// Cache em memória 24h pra evitar bater toda hora.
const _cnpjCache = new Map(); // cnpj → { data, ts }
const _CNPJ_TTL = 24 * 3600 * 1000;
const _CNPJ_UA = 'tdf-portal/1.0 (+https://tudodefiltro.com.br)';

function _normCnpjBrasilApi(data) {
  return {
    cnpj: data.cnpj,
    razaoSocial: data.razao_social || '',
    nomeFantasia: data.nome_fantasia || '',
    situacao: data.descricao_situacao_cadastral || '',
    dataAbertura: data.data_inicio_atividade || '',
    capitalSocial: data.capital_social || 0,
    naturezaJuridica: data.natureza_juridica || '',
    cnaePrincipal: data.cnae_fiscal_descricao || '',
    cnaeCodigo: data.cnae_fiscal || '',
    endereco: {
      logradouro: (data.descricao_tipo_de_logradouro ? data.descricao_tipo_de_logradouro + ' ' : '') + (data.logradouro || ''),
      numero: data.numero || '',
      complemento: data.complemento || '',
      bairro: data.bairro || '',
      cep: (data.cep||'').replace(/(\d{5})(\d{3})/,'$1-$2'),
      cidade: data.municipio || '',
      uf: data.uf || '',
    },
    telefone: data.ddd_telefone_1 || '',
    email: data.email || '',
    porte: data.porte || '',
    socios: (data.qsa||[]).map(s => ({ nome: s.nome_socio, qual: s.qualificacao_socio })),
    fonte: 'brasilapi',
    raw: data,
  };
}

function _normCnpjPublicaWs(data) {
  // https://publica.cnpj.ws — formato diferente, mais aninhado
  const est = data.estabelecimento || {};
  const end = est;
  return {
    cnpj: (est.cnpj || data.cnpj_raiz || '').replace(/\D/g,''),
    razaoSocial: data.razao_social || '',
    nomeFantasia: est.nome_fantasia || '',
    situacao: est.situacao_cadastral || '',
    dataAbertura: est.data_inicio_atividade || data.data_inicio_atividade || '',
    capitalSocial: data.capital_social ? Number(data.capital_social) : 0,
    naturezaJuridica: data.natureza_juridica?.descricao || '',
    cnaePrincipal: est.atividade_principal?.descricao || '',
    cnaeCodigo: est.atividade_principal?.id || '',
    endereco: {
      logradouro: (end.tipo_logradouro ? end.tipo_logradouro + ' ' : '') + (end.logradouro || ''),
      numero: end.numero || '',
      complemento: end.complemento || '',
      bairro: end.bairro || '',
      cep: (end.cep||'').replace(/(\d{5})(\d{3})/,'$1-$2'),
      cidade: end.cidade?.nome || '',
      uf: end.estado?.sigla || '',
    },
    telefone: (est.ddd1 && est.telefone1) ? `${est.ddd1}${est.telefone1}` : '',
    email: est.email || '',
    porte: data.porte?.descricao || '',
    socios: (data.socios||[]).map(s => ({ nome: s.nome, qual: s.qualificacao_socio?.descricao || '' })),
    fonte: 'publica.cnpj.ws',
    raw: data,
  };
}

async function _fetchCnpjBrasilApi(cnpj) {
  const r = await fetch(`https://brasilapi.com.br/api/cnpj/v1/${cnpj}`, {
    headers: { 'User-Agent': _CNPJ_UA, 'Accept': 'application/json' },
    signal: AbortSignal.timeout(8000),
  });
  if (r.status === 404) { const e = new Error('CNPJ não encontrado'); e.status = 404; throw e; }
  if (r.status === 429) { const e = new Error('rate limit'); e.status = 429; throw e; }
  if (!r.ok) { const e = new Error('BrasilAPI '+r.status); e.status = r.status; throw e; }
  return _normCnpjBrasilApi(await r.json());
}
async function _fetchCnpjPublicaWs(cnpj) {
  const r = await fetch(`https://publica.cnpj.ws/cnpj/${cnpj}`, {
    headers: { 'User-Agent': _CNPJ_UA, 'Accept': 'application/json' },
    signal: AbortSignal.timeout(8000),
  });
  if (r.status === 404) { const e = new Error('CNPJ não encontrado'); e.status = 404; throw e; }
  if (r.status === 429) { const e = new Error('rate limit'); e.status = 429; throw e; }
  if (!r.ok) { const e = new Error('publica.cnpj.ws '+r.status); e.status = r.status; throw e; }
  return _normCnpjPublicaWs(await r.json());
}

// Núcleo da consulta (cache + BrasilAPI + fallback publica.cnpj.ws), extraído
// da rota pra poder ser REUSADO pelo PDV (/pdv/api/cnpj/:cnpj, ver bloco do
// PDV acima) sem duplicar fetch nem normalização. `cnpj` já chega só-dígitos
// e validado (14 dígitos) — quem chama garante isso antes. Nunca rejeita:
// toda falha de rede/status vira um {status, json} de erro, nunca um throw
// — assim quem consome (a rota do BI e a decisão em lib/pdv-web.js) nunca
// precisa se preocupar com exceção não tratada travando a resposta.
async function _resolveCnpj(cnpj) {
  const cached = _cnpjCache.get(cnpj);
  if (cached && (Date.now() - cached.ts) < _CNPJ_TTL) {
    return { status: 200, json: { ok:true, cnpj, cached:true, ...cached.data } };
  }
  // Tenta BrasilAPI primeiro
  let norm = null; let err1 = null;
  try { norm = await _fetchCnpjBrasilApi(cnpj); }
  catch(e) {
    err1 = e;
    if (e.status === 404) return { status: 404, json: { ok:false, error:'CNPJ não encontrado na Receita' } };
    console.warn('[cnpj] BrasilAPI falhou, tentando publica.cnpj.ws:', e.message);
  }
  if (!norm) {
    try { norm = await _fetchCnpjPublicaWs(cnpj); }
    catch(e2) {
      console.error('[cnpj] ambas APIs falharam:', err1?.message, '|', e2.message);
      if (e2.status === 404) return { status: 404, json: { ok:false, error:'CNPJ não encontrado' } };
      if (e2.status === 429 || err1?.status === 429) return { status: 429, json: { ok:false, error:'Limite das APIs atingido — tente em 1 minuto' } };
      return { status: 502, json: { ok:false, error:'Falha nas APIs públicas: ' + (e2.message || err1?.message) } };
    }
  }
  _cnpjCache.set(cnpj, { data: norm, ts: Date.now() });
  return { status: 200, json: { ok:true, cnpj, cached:false, ...norm } };
}

app.get('/bi-financeiro/api/cnpj/:cnpj', requireAuth, requireBIRole, async (req, res) => {
  const cnpj = String(req.params.cnpj||'').replace(/\D/g,'');
  if (cnpj.length !== 14) return res.status(400).json({ ok:false, error:'CNPJ inválido (precisa 14 dígitos)' });
  const { status, json } = await _resolveCnpj(cnpj);
  res.status(status).json(json);
});

// PDV de balcão (Tarefa: autopreenchimento de cliente novo pelo CNPJ, pedido
// do dono depois de usar o PDV) — MESMA consulta acima (_resolveCnpj), só
// que atrás de requirePDVRole (loja/closer/admin) em vez de requireBIRole.
// O gate do /bi-financeiro/ acima NÃO muda; esta é uma rota própria. Toda a
// decisão (papel, formato do CNPJ, shape da resposta, aviso de situação
// cadastral irregular) mora em lib/pdv-web.js#tratarConsultaCnpj — testável
// sem servidor, mesmo padrão de tratarFinalizarVenda logo acima.
app.get('/pdv/api/cnpj/:cnpj', requireAuth, requirePDVRole, async (req, res) => {
  const { status, json } = await pdvWeb.tratarConsultaCnpj({
    cnpj: req.params.cnpj,
    username: req.session.user?.username,
    users: USERS,
    consultarCnpj: _resolveCnpj,
  });
  res.status(status).json(json);
});

