// === DASHBOARD CEO CONSOLIDADO ===
// Aceita dateFrom/dateTo (YYYY-MM-DD). Calcula período + período anterior pra comparativo.
app.get('/bi-financeiro/api/ceo-dashboard', requireAuth, requireBIRole, async (req, res) => {
  try {
    const empresaBI = req.query.empresaBI || '';
    const today = new Date();
    const dateTo   = req.query.dateTo   || today.toISOString().slice(0,10);
    const dateFrom = req.query.dateFrom || new Date(today.getFullYear(), today.getMonth(), today.getDate() - 29).toISOString().slice(0,10);
    const compararPeriodoAnterior = req.query.comparePrev !== 'false';

    // Período anterior = mesma duração, deslocado pra trás
    let prevFrom = '', prevTo = '';
    if (compararPeriodoAnterior) {
      const dF = new Date(dateFrom + 'T00:00:00Z');
      const dT = new Date(dateTo   + 'T00:00:00Z');
      const ms = dT - dF + 86400000;
      const pT = new Date(dF.getTime() - 86400000);
      const pF = new Date(pT.getTime() - ms + 86400000);
      prevFrom = pF.toISOString().slice(0,10);
      prevTo   = pT.toISOString().slice(0,10);
    }

    // Bancos (saldo absoluto, não depende de período)
    const todosBancos = biBancos.listAll().filter(b => !empresaBI || b.empresaBI === empresaBI);
    const bancosAtivos = todosBancos.filter(b => b.ativo);
    const saldoTotal  = bancosAtivos.reduce((s,b) => s + Number(b.saldoAtual||0), 0);
    const limiteTotal = bancosAtivos.reduce((s,b) => s + Number(b.limite||0), 0);

    const pgDash = biPagamentos.dashboardSummary(empresaBI);
    const rcDash = biRecebimentos.dashboardSummary(empresaBI);
    const aPagarAberto   = pgDash.valores.aguardando + pgDash.valores.aprovado;
    const aReceberAberto = rcDash.valores.totalAberto;

    // Helper: agrega vendas Zoho de um intervalo
    const agregarZoho = (cached, fichas, custosLog, custosMat, from, to) => {
      const lista = []; let receita = 0, lucro = 0, prejuizos = 0, semFicha = 0;
      for (const rec of cached) {
        const norm = _normalizeRecord('Deals', rec);
        if (!norm || !norm.data) continue;
        if (norm.data < from || norm.data > to) continue;
        if (empresaBI) {
          const f = fichas[`Deals_${norm.zohoId}`];
          if (!f || f.empresaBI !== empresaBI) continue;
        }
        const k = `Deals_${norm.zohoId}`;
        const ficha = fichas[k] || biFichas.defaultFicha('Deals', norm.zohoId);
        const cl = custosLog?.[norm.zohoId];
        if (cl) ficha.custos.custoLogistico = cl.valor;
        const cm = custosMat?.[norm.zohoId];
        if (cm) ficha.custos.custoMateriais = cm.valor;
        const calc = biFichas.calcLucro(norm, ficha);
        receita += calc.valorBruto;
        lucro += calc.lucro;
        if (calc.status === 'prejuizo') prejuizos++;
        if (calc.status === 'sem-dados') semFicha++;
        lista.push({
          module: 'Deals', zohoId: norm.zohoId, cliente: norm.cliente, vendedor: norm.vendedor,
          titulo: norm.titulo,
          valor: calc.valorBruto, custoTotal: calc.custoTotal, lucro: calc.lucro,
          margemLiquida: calc.margemLiquida, status: calc.status, data: norm.data,
          produtos: norm.produtos || [],
        });
      }
      return { lista, receita, lucro, prejuizos, semFicha, count: lista.length };
    };

    let zohoCurr = { lista:[], receita:0, lucro:0, prejuizos:0, semFicha:0, count:0 };
    let zohoPrev = { lista:[], receita:0, lucro:0, prejuizos:0, semFicha:0, count:0 };
    try {
      const cached = (await _fetchVendasZoho('Deals')) || [];
      const fichas = biFichas.indexAll();
      // Custo logístico + materiais em batch
      let custosLog = {}, custosMat = {};
      try {
        const ids = cached.map(rec => rec.id).filter(Boolean);
        if (ids.length) {
          custosLog = await biRotasCusto.custoPorZohoDealIdsBatch(ids);
          custosMat = await biOsMateriais.custoPorZohoDealIdsBatch(ids);
        }
      } catch(e) { console.warn('[ceo-dashboard] custo batch:', e.message); }
      zohoCurr = agregarZoho(cached, fichas, custosLog, custosMat, dateFrom, dateTo);
      if (compararPeriodoAnterior) zohoPrev = agregarZoho(cached, fichas, custosLog, custosMat, prevFrom, prevTo);
    } catch(e) { console.warn('[ceo-dashboard zoho]', e.message); }

    const fmt = (v) => 'R$ ' + Number(v||0).toLocaleString('pt-BR', { minimumFractionDigits:2 });
    const caixaProj = saldoTotal - aPagarAberto + aReceberAberto;
    const alertas = [];
    if (caixaProj < 0) alertas.push({ kind:'bad', txt:`Caixa projetado NEGATIVO: ${fmt(caixaProj)} (saldo ${fmt(saldoTotal)} − a pagar ${fmt(aPagarAberto)} + a receber ${fmt(aReceberAberto)})` });
    if (pgDash.valores.vencidos > 0) alertas.push({ kind:'bad', txt:`${pgDash.listas.vencidos.length} pagamento(s) VENCIDO(S) totalizando ${fmt(pgDash.valores.vencidos)}` });
    if (rcDash.valores.vencidos > 0) alertas.push({ kind:'warn', txt:`${rcDash.listas.vencidos.length} recebimento(s) atrasado(s) totalizando ${fmt(rcDash.valores.vencidos)}` });
    if (zohoCurr.prejuizos > 0) alertas.push({ kind:'bad', txt:`${zohoCurr.prejuizos} venda(s) com PREJUÍZO no período` });
    if (pgDash.counts.aguardando > 0) alertas.push({ kind:'info', txt:`${pgDash.counts.aguardando} pagamento(s) aguardando aprovação (${fmt(pgDash.valores.aguardando)})` });
    if (zohoCurr.semFicha > 0) alertas.push({ kind:'info', txt:`${zohoCurr.semFicha} venda(s) Zoho sem ficha financeira — lucro real subestimado` });

    zohoCurr.lista.sort((a,b) => b.lucro - a.lucro);
    const top5Lucro = zohoCurr.lista.slice(0,5);
    const piores = zohoCurr.lista.slice().sort((a,b) => a.lucro - b.lucro).slice(0,5);

    res.json({ ok:true, ts: new Date().toISOString(), empresaBI: empresaBI || 'consolidado',
      periodo: { from: dateFrom, to: dateTo, prevFrom, prevTo, compararPeriodoAnterior },
      bancos: { total: bancosAtivos.length, saldoTotal, limiteTotal, lista: bancosAtivos.map(b => ({ id:b.id, apelido:b.apelido||b.banco, saldo:b.saldoAtual })) },
      pagamentos: { aguardando: pgDash.counts.aguardando, aprovado: pgDash.counts.aprovado, valorAguardando: pgDash.valores.aguardando, valorAprovado: pgDash.valores.aprovado, vencidos: pgDash.valores.vencidos, vencendoHoje: pgDash.valores.vencendoHoje, proxSemana: pgDash.valores.proxSemana, noMes: pgDash.valores.noMes },
      recebimentos: { aberto: rcDash.counts.aberto, valorAberto: rcDash.valores.totalAberto, vencidos: rcDash.valores.vencidos, recebidoNoMes: rcDash.valores.recebidoNoMes },
      zoho: {
        atual: { count: zohoCurr.count, receita: zohoCurr.receita, lucro: zohoCurr.lucro, prejuizos: zohoCurr.prejuizos, semFicha: zohoCurr.semFicha },
        anterior: compararPeriodoAnterior ? { count: zohoPrev.count, receita: zohoPrev.receita, lucro: zohoPrev.lucro, prejuizos: zohoPrev.prejuizos, semFicha: zohoPrev.semFicha } : null,
        top5Lucro,
        piores,
        listaCompleta: zohoCurr.lista,
      },
      caixaProjetado: caixaProj,
      alertas,
    });
  } catch(e) {
    console.error('[ceo-dashboard]', e);
    res.status(500).json({ error: e.message });
  }
});

// === CONCILIAÇÃO BANCÁRIA OFX/CSV ===
const biConciliacao = require('./lib/bi-conciliacao');

app.post('/bi-financeiro/api/conciliacao/preview', requireAuth, requireAdmin, express.json({ limit:'10mb' }), (req, res) => {
  const { contaId, formato, conteudo } = req.body || {};
  if (!contaId)  return res.status(400).json({ error:'contaId obrigatório' });
  if (!conteudo) return res.status(400).json({ error:'conteudo do arquivo obrigatório' });
  let parsed;
  if (formato === 'ofx')      parsed = { formato:'ofx', txs: biConciliacao.parseOFX(conteudo) };
  else if (formato === 'csv') parsed = { formato:'csv', txs: biConciliacao.parseCSV(conteudo) };
  else                        parsed = biConciliacao.parseAuto(conteudo);
  if (!parsed.txs.length) return res.status(400).json({ error:'arquivo não tem transações reconhecíveis (formato detectado: '+parsed.formato+')' });
  const matchResult = biConciliacao.match(parsed.txs, contaId);
  res.json({ ok:true, formato: parsed.formato, ...matchResult });
});
app.post('/bi-financeiro/api/conciliacao/confirmar', requireAuth, requireAdmin, (req, res) => {
  const { extratoEntryId, ofxTxId } = req.body || {};
  if (!extratoEntryId || !ofxTxId) return res.status(400).json({ error:'extratoEntryId e ofxTxId obrigatórios' });
  res.json(biConciliacao.confirmarMatch(extratoEntryId, ofxTxId, req.session.user?.username));
});
app.post('/bi-financeiro/api/conciliacao/quebrar', requireAuth, requireAdmin, (req, res) => {
  const r = biConciliacao.quebrarMatch(req.body?.extratoEntryId, req.session.user?.username);
  if (!r.ok) return res.status(400).json(r);
  res.json(r);
});
app.post('/bi-financeiro/api/conciliacao/importar', requireAuth, requireAdmin, (req, res) => {
  const { contaId, tx } = req.body || {};
  if (!contaId || !tx) return res.status(400).json({ error:'contaId e tx obrigatórios' });
  const r = biConciliacao.importarComoMovimento(tx, contaId, req.session.user?.username);
  if (!r.ok) return res.status(400).json(r);
  res.json(r);
});

// === BULK DELETE (admin only — exclusão em massa server-side) ===
// Body: { kind: 'pagamentos'|'recebimentos'|'bancos'|'aprovadores'|'estoque-empresas'|'estoque-locais'|'estoque-produtos', ids: [string] }
app.post('/bi-financeiro/api/bulk-delete', requireAuth, requireAdmin, express.json({ limit:'2mb' }), async (req, res) => {
  const { kind, ids } = req.body || {};
  if (!kind || !Array.isArray(ids) || ids.length === 0) return res.status(400).json({ error:'kind e ids[] obrigatórios' });
  let removidos = 0;
  const erros = [];
  try {
    for (const id of ids) {
      try {
        if (kind === 'pagamentos') {
          const r = biPagamentos.remover(id, req.session.user?.username);
          if (r.ok) removidos++; else erros.push({ id, erro: r.error });
        } else if (kind === 'recebimentos') {
          const r = biRecebimentos.remover(id, req.session.user?.username);
          if (r.ok) removidos++; else erros.push({ id, erro: r.error });
        } else if (kind === 'bancos') {
          const ok = biBancos.remove(id);
          if (ok) removidos++; else erros.push({ id, erro:'não encontrado' });
        } else if (kind === 'aprovadores') {
          const ok = biAprovadores.remove(id);
          if (ok) removidos++; else erros.push({ id, erro:'não encontrado' });
        } else if (kind === 'estoque-empresas') {
          if (await biEstoque.removeEmpresa(id)) removidos++;
        } else if (kind === 'estoque-locais') {
          if (await biEstoque.removeEstoque(id)) removidos++;
        } else if (kind === 'estoque-produtos') {
          if (await biEstoque.removeProduto(id)) removidos++;
        } else if (kind === 'fornecedores') {
          if (await biFornecedores.remove(id)) removidos++;
        } else {
          return res.status(400).json({ error:'kind inválido: '+kind });
        }
      } catch(e) { erros.push({ id, erro: e.message }); }
    }
    res.json({ ok:true, removidos, erros, total: ids.length });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// === SYNC do state do BI Financeiro (localStorage compartilhado via kv_store) ===
// O BI Financeiro multi-empresa salva tudo em state local (state.companies,
// state.produtos, state.contasPagar, state.contasReceber, state.custosFixos,
// state.receitas, state.config). Esse state precisa ser COMPARTILHADO entre
// admin, financeiro, e qualquer browser (não-localStorage). Solução: salvar
// no kv_store sob a chave 'bi-financeiro-state' (last-write-wins).
//
// Concorrência: last-write-wins simples. Pra v1 OK; pra produção pesada com
// múltiplas edições simultâneas, evoluir pra timestamp/versão.
const BI_STATE_KEY = 'bi-financeiro-state';

app.get('/bi-financeiro/api/state', requireAuth, requireBIRole, async (req, res) => {
  try {
    const value = _kvCache[BI_STATE_KEY] || null;
    res.json({ ok:true, state: value, updatedAt: value ? (value._meta?.savedAt || null) : null });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

app.put('/bi-financeiro/api/state', requireAuth, requireBIRole, express.json({ limit:'10mb' }), async (req, res) => {
  try {
    const body = req.body || {};
    if (!body || typeof body !== 'object') return res.status(400).json({ error:'state inválido' });
    // Adiciona metadata de auditoria
    body._meta = {
      savedAt: new Date().toISOString(),
      savedBy: req.session.user?.username || 'desconhecido',
      version: (body._meta?.version || 0) + 1,
    };
    await kvSet(BI_STATE_KEY, body);
    res.json({ ok:true, savedAt: body._meta.savedAt, version: body._meta.version });
  } catch(e) {
    console.error('[bi state PUT]', e);
    res.status(500).json({ error: e.message });
  }
});

