const biRecorrencia = require('./lib/bi-recorrencia');

// Cron diário — 60s após boot (não pesa startup) + a cada 24h.
// Anti-dup já está no lib (par modeloId+competencia único). Rodar 2x no mesmo dia é safe.
function _cronRecorrenciaTick() {
  try {
    const r = biRecorrencia.rodarRecorrencia({ usuario: 'cron-diario' });
    if (r.criados > 0) console.log('[cron-recorrencia] gerou', r.criados, 'pagamentos · competência', r.competencia);
  } catch(e) { console.warn('[cron-recorrencia]', e.message); }
}
setTimeout(_cronRecorrenciaTick, 60 * 1000);
setInterval(_cronRecorrenciaTick, 24 * 3600 * 1000);

