// Importação CSV de contas a pagar (body: { csv:text, dryRun:bool })
// As empresas BI vivem em localStorage do navegador, então o frontend passa
// um mapa nome→id pra resolução. Bancos vêm do servidor (Postgres + JSON).
app.post('/bi-financeiro/api/pagamentos/import-csv', requireAuth, requireBIRole, express.json({ limit:'5mb' }), (req, res) => {
  const { csv, dryRun = true, empresasMap = {}, bancosMap = {} } = req.body || {};
  if (!csv) return res.status(400).json({ error:'csv obrigatório' });
  const norm = s => String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'');
  const empNomeIndex = Object.fromEntries(Object.entries(empresasMap).map(([nome, id]) => [norm(nome), id]));
  const bancoApIndex = Object.fromEntries(Object.entries(bancosMap).map(([apelido, id]) => [norm(apelido), id]));
  try {
    const r = biPagamentos.importCsv(csv, {
      dryRun: !!dryRun,
      who: req.session.user?.username || 'import-csv',
      resolveEmpresaPorNome: (nome) => empNomeIndex[norm(nome)] || null,
      resolveBancoPorApelido: (ap)  => bancoApIndex[norm(ap)]  || null,
    });
    res.json({ ok:true, ...r });
  } catch(e) {
    res.status(400).json({ ok:false, error: e.message });
  }
});

