app.get('/bi-financeiro/api/status', requireAuth, requireBIRole, (req, res) => {
  const tokenStats = zoho.stats();
  const cacheStats = {
    Deals: { count: _biZohoCache.Deals?.length || 0, ageMs: _biZohoCache.Deals ? (Date.now() - _biZohoCacheAt.Deals) : null },
    Quotes: { count: _biZohoCache.Quotes?.length || 0, ageMs: _biZohoCache.Quotes ? (Date.now() - _biZohoCacheAt.Quotes) : null },
    Sales_Orders: { count: _biZohoCache.Sales_Orders?.length || 0, ageMs: _biZohoCache.Sales_Orders ? (Date.now() - _biZohoCacheAt.Sales_Orders) : null },
  };
  res.json({
    ok: true,
    zohoConfigured: !!process.env.ZOHO_REFRESH_TOKEN,
    token: tokenStats,
    cache: cacheStats,
  });
});

