// === MODO LIGAÇÃO (aberto pelo botão "Script" no Zoho, com contexto do deal) ===
app.get('/script-ligacao', requireAuth, (req, res) => {
  const fs = require('fs');
  const ctx = {
    nome: String(req.query.nome || '').split(' ')[0].replace(/[^\p{L}\p{N} '.-]/gu, '') || '[Nome]',
    cidade: String(req.query.cidade || '').replace(/[^\p{L}\p{N} '.-]/gu, '') || '[Cidade]',
    produto: String(req.query.produto || '').toLowerCase(),
    pipeline: String(req.query.pipeline || '').toLowerCase(),
    dealId: String(req.query.deal || '').replace(/\D/g, ''),
  };
  // qual seção âncora abrir, por produto/pipeline do deal
  const chave = ctx.produto + ' ' + ctx.pipeline;
  let ancora = 'filtro';
  if (/esta[cç][aã]o/.test(chave)) ancora = 'estação';
  else if (/po[cç]o|iron|n[aã]o tratada/.test(chave)) ancora = 'iron free';
  else if (/bebedouro/.test(chave)) ancora = 'bebedouro';
  else if (/purificador/.test(chave)) ancora = 'purificador';
  else if (/refil|elemento|manuten/.test(chave)) ancora = 'troca';
  const papel = String(req.query.papel || '').toLowerCase() ||
    ((req.session.user.role === 'closer' && req.session.user.team !== 'bebedouro') ? 'closer' : 'sdr');
  const ordem = papel === 'closer'
    ? ['oferta', 'objecoes', 'qualificacao', 'respostas-rapidas']
    : ['qualificacao', 'objecoes', 'oferta', 'respostas-rapidas'];
  const abas = ordem.map(slug => {
    const m = SCRIPTS_RAV_MAP.find(x => x.slug === slug);
    let md = '';
    try { md = fs.readFileSync(path.join(SCRIPTS_RAV_DIR, m.file), 'utf8'); } catch (_) {}
    md = md.replace(/\[Nome\]/g, ctx.nome).replace(/\[Cidade\]/g, ctx.cidade)
           .replace(/\[Closer\]/g, req.session.user.name || '[Closer]');
    return { slug, titulo: m.titulo, icon: m.icon, md };
  });
  res.render('script-ligacao', { user: req.session.user, ctx, abas, ancora, papel });
});

app.get('/treinamento/scripts-rav/raw/:slug', requireAuth, (req, res) => {
  const m = SCRIPTS_RAV_MAP.find(x => x.slug === req.params.slug);
  if (!m) return res.status(404).json({ error: 'módulo não encontrado' });
  try {
    const content = require('fs').readFileSync(path.join(SCRIPTS_RAV_DIR, m.file), 'utf8');
    res.json({ slug: m.slug, titulo: m.titulo, markdown: content });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

