// Upload protegido por chave (subir arquivos via curl, streaming direto pro volume)
app.post('/admin/biblioteca/upload/:filename', (req, res) => {
  if (!process.env.BIBLIOTECA_UPLOAD_KEY || req.headers['x-upload-key'] !== process.env.BIBLIOTECA_UPLOAD_KEY) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const fs = require('fs');
  const fname = path.basename(req.params.filename); // anti path-traversal
  const dest = path.join(BIBLIOTECA_DIR, fname);
  const ws = fs.createWriteStream(dest);
  req.pipe(ws);
  ws.on('finish', () => { try { res.json({ ok: true, file: fname, bytes: fs.statSync(dest).size }); } catch(e){ res.json({ ok:true, file:fname }); } });
  ws.on('error', e => res.status(500).json({ error: e.message }));
});

// Manifesto do volume (verificação) — protegido por chave
app.get('/admin/biblioteca/manifest', (req, res) => {
  if (!process.env.BIBLIOTECA_UPLOAD_KEY || req.headers['x-upload-key'] !== process.env.BIBLIOTECA_UPLOAD_KEY) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const fs = require('fs');
  try {
    const files = fs.readdirSync(BIBLIOTECA_DIR).map(f => ({ f, bytes: fs.statSync(path.join(BIBLIOTECA_DIR, f)).size }));
    res.json({ dir: BIBLIOTECA_DIR, count: files.length, files });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// === CENTRAL DE RESULTADOS (record diário: raio-x, planos, PDFs e vídeos) ===
const RESULTADOS_DIR = path.join(__dirname, 'media', 'resultados');
try { require('fs').mkdirSync(RESULTADOS_DIR, { recursive: true }); } catch(_) {}
const RESULTADOS_POSTS = path.join(RESULTADOS_DIR, 'posts.json');

function lerResultadosPosts() {
  try { return JSON.parse(require('fs').readFileSync(RESULTADOS_POSTS, 'utf8')); } catch(_) { return []; }
}
function salvarResultadosPosts(posts) {
  require('fs').writeFileSync(RESULTADOS_POSTS, JSON.stringify(posts, null, 2));
}

// Arquivos (vídeo seekável) — só logado
app.use('/resultados-files', requireAuth, require('express').static(RESULTADOS_DIR, { acceptRanges: true, maxAge: '1d' }));

// Página da Central de Resultados
app.get('/resultados', requireAuth, (req, res) => {
  const fs = require('fs');
  const posts = lerResultadosPosts().map(p => ({
    ...p,
    arquivos: (p.arquivos || []).map(a => ({ ...a, existe: fs.existsSync(path.join(RESULTADOS_DIR, a.arq)) }))
  }));
  res.render('resultados', { user: req.session.user, posts });
});

// Upload de arquivo (curl, chave) — mesmo esquema da biblioteca
app.post('/admin/resultados/upload/:filename', (req, res) => {
  if (!process.env.BIBLIOTECA_UPLOAD_KEY || req.headers['x-upload-key'] !== process.env.BIBLIOTECA_UPLOAD_KEY) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const fs = require('fs');
  const fname = path.basename(req.params.filename);
  const dest = path.join(RESULTADOS_DIR, fname);
  const ws = fs.createWriteStream(dest);
  req.pipe(ws);
  ws.on('finish', () => { try { res.json({ ok: true, file: fname, bytes: fs.statSync(dest).size }); } catch(e){ res.json({ ok:true, file:fname }); } });
  ws.on('error', e => res.status(500).json({ error: e.message }));
});

// Criar post (JSON: {titulo, resumo, data?, tag?, arquivos:[{arq,tipo,titulo}]}) — chave
app.post('/admin/resultados/post', express.json({ limit: '1mb' }), (req, res) => {
  if (!process.env.BIBLIOTECA_UPLOAD_KEY || req.headers['x-upload-key'] !== process.env.BIBLIOTECA_UPLOAD_KEY) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const b = req.body || {};
  if (!b.titulo) return res.status(400).json({ error: 'titulo obrigatorio' });
  const posts = lerResultadosPosts();
  posts.unshift({
    id: Date.now().toString(36),
    data: b.data || new Date().toISOString().slice(0, 10),
    tag: b.tag || 'Raio-X',
    titulo: b.titulo,
    resumo: b.resumo || '',
    arquivos: Array.isArray(b.arquivos) ? b.arquivos.map(a => ({ arq: path.basename(a.arq || ''), tipo: a.tipo || 'pdf', titulo: a.titulo || a.arq })) : []
  });
  salvarResultadosPosts(posts.slice(0, 200));
  res.json({ ok: true, total: posts.length });
});

