// Remover foto do manifesto (JSON: {id}) — chave
app.post('/admin/instalacoes/remover', express.json({ limit: '64kb' }), (req, res) => {
  if (!process.env.BIBLIOTECA_UPLOAD_KEY || req.headers['x-upload-key'] !== process.env.BIBLIOTECA_UPLOAD_KEY) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const fotos = lerInstalacoes();
  const restantes = fotos.filter(f => f.id !== (req.body || {}).id);
  salvarInstalacoes(restantes);
  res.json({ ok: true, total: restantes.length });
});

// Manifesto (verificação) — chave
app.get('/admin/instalacoes/manifest', (req, res) => {
  if (!process.env.BIBLIOTECA_UPLOAD_KEY || req.headers['x-upload-key'] !== process.env.BIBLIOTECA_UPLOAD_KEY) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const fs = require('fs');
  try {
    const files = fs.readdirSync(INSTALACOES_DIR).map(f => ({ f, bytes: fs.statSync(path.join(INSTALACOES_DIR, f)).size }));
    res.json({ dir: INSTALACOES_DIR, manifest: lerInstalacoes().length, count: files.length, files });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

