app.get('/treinamento/trilha', requireAuth, (req, res) => {
  const fs = require('fs');
  const username = req.session.user.username;
  const prog = _kvCache[`trilha-progress:${username}`] || { sdr: {}, closer: {} };
  const trilhas = {};
  for (const [k, t] of Object.entries(TRILHAS)) {
    trilhas[k] = { ...t, passos: t.passos.map(p => ({
      ...p,
      existe: fs.existsSync(path.join(BIBLIOTECA_DIR, p.arq)),
      feito: !!(prog[k] && prog[k][p.arq]),
    })) };
  }
  res.render('treinamento/trilha', { user: req.session.user, trilhas });
});

app.post('/api/trilha/check', requireAuth, express.json(), async (req, res) => {
  const { trilha, arq, done } = req.body || {};
  if (!TRILHAS[trilha] || !TRILHAS[trilha].passos.some(p => p.arq === arq)) {
    return res.status(400).json({ error: 'trilha/arquivo inválido' });
  }
  const username = req.session.user.username;
  const key = `trilha-progress:${username}`;
  const prog = _kvCache[key] || { sdr: {}, closer: {} };
  if (!prog[trilha]) prog[trilha] = {};
  if (done) prog[trilha][arq] = Date.now(); else delete prog[trilha][arq];
  await kvSet(key, prog);
  const total = TRILHAS[trilha].passos.length;
  const feitos = Object.keys(prog[trilha]).length;
  res.json({ ok: true, feitos, total });
});

