// === PÁGINA INICIAL DO REVENDEDOR ===
// Única tela fora do conteúdo liberado que o role 'revendedor' enxerga.
const _REV_FONTES = {
  '/treinamento/bebedouros':     { prefix: 'treinbeb:progress:',  modulos: () => require('./data/treinamento-bebedouros/modulos.js') },
  '/treinamento/poco':           { prefix: 'treinpoco:progress:', modulos: () => require('./data/treinamento-poco/modulos.js') },
  '/treinamento/filtro-entrada': { prefix: 'treinfe:progress:',   modulos: () => require('./data/treinamento-filtro-entrada/modulos.js') },
  '/treinamento/scale-stop':     { prefix: 'treinss:progress:',   modulos: () => require('./data/treinamento-scale-stop/modulos.js') },
  '/treinamento/tecnicas-vendas':{ prefix: 'treintv:progress:',   modulos: () => require('./data/treinamento-tecnicas-vendas/modulos.js') },
  // scripts-rav é biblioteca de leitura, não academia: sem módulo, prova ou progresso.
  '/treinamento/scripts-rav':    null,
};

function revendedorProgresso(username) {
  return ACADEMIAS_REVENDEDOR.map(a => {
    const f = _REV_FONTES[a.base];
    if (!f) return Object.assign({}, a, { total: 0, concluidos: 0, pct: 0, aprovado: false, certificado: false, semProgresso: true });
    let total = 0, concluidos = 0, aprovado = false, certificado = false;
    try {
      const mod = f.modulos();
      const lista = (mod && (mod.MODULOS || mod)) || [];
      total = lista.length || 0;
      const prog = _kvCache[f.prefix + username] || null;
      if (prog) {
        const mods = prog.modulos || {};
        concluidos = lista.filter(m => mods[m.slug] && mods[m.slug].concluido).length;
        aprovado = !!(prog.prova && prog.prova.aprovado);
        certificado = !!prog.certificadoEm || !!prog.certificado;
      }
    } catch (_) { /* sem data dir — mostra zerado, não quebra a página */ }
    const pct = total ? Math.round((concluidos / total) * 100) : 0;
    return Object.assign({}, a, { total, concluidos, pct, aprovado, certificado });
  });
}

