// Faixas de premiação
const FAIXAS_PREMIO = [
  { faturamento: 75000, premio: 2000, bonus: 0 },
  { faturamento: 90000, premio: 3800, bonus: 20 },
  { faturamento: 110000, premio: 4900, bonus: 30 },
  { faturamento: 130000, premio: 6000, bonus: 40 },
  { faturamento: 150000, premio: 7200, bonus: 50 },
  { faturamento: 170000, premio: 8400, bonus: 50 },
  { faturamento: 190000, premio: 9800, bonus: 50 },
  { faturamento: 210000, premio: 11200, bonus: 50 },
];

function calcPremiacao(fat) {
  let faixaAtual = null;
  let faixaProxima = null;
  for (let i = FAIXAS_PREMIO.length - 1; i >= 0; i--) {
    if (fat >= FAIXAS_PREMIO[i].faturamento) { faixaAtual = FAIXAS_PREMIO[i]; faixaProxima = FAIXAS_PREMIO[i + 1] || null; break; }
  }
  if (!faixaAtual && FAIXAS_PREMIO.length > 0) faixaProxima = FAIXAS_PREMIO[0];
  return {
    faixaAtual: faixaAtual ? { ...faixaAtual } : null,
    faixaProxima: faixaProxima ? { ...faixaProxima, falta: faixaProxima.faturamento - fat } : null,
    premioAtual: faixaAtual?.premio || 0,
    bonusAtual: faixaAtual?.bonus || 0,
  };
}

