// Dados brutos do dossiê de UM closer (dia anterior + semana + mês)
app.get('/gestao/reuniao-matinal/dados', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const closerKey = req.query.closer;
  if (!closerKey || !USERS[closerKey]) return res.status(400).json({ error: 'closer obrigatório' });
  const target = USERS[closerKey];
  const ownerName = target.crmOwner;

  try {
    const today = todayBR();
    const todayMs = new Date(today + 'T12:00:00-03:00').getTime();
    const ontem = new Date(todayMs - 86400000).toISOString().slice(0,10);
    const seteDias = new Date(todayMs - 7 * 86400000).toISOString().slice(0,10);
    const trintaDias = new Date(todayMs - 30 * 86400000).toISOString().slice(0,10);
    const mesStart = `${today.slice(0,7)}-01`;
    const mesAnt = (() => {
      const d = new Date(todayMs); d.setMonth(d.getMonth()-1); d.setDate(1);
      return d.toISOString().slice(0,10);
    })();
    const mesAntFim = (() => {
      const d = new Date(today + 'T12:00:00-03:00'); d.setDate(0);
      return d.toISOString().slice(0,10);
    })();

    // 1. GoTo stats: ontem
    const gotoOntem = await getGotoCallStatsForDate(ontem).catch(() => ({}));
    const callsOntem = gotoOntem[ownerName] || { total:0, outbound:0, inbound:0, answered:0, missed:0, avgDurMin:0 };

    // 2. GoTo stats: últimos 7 dias (agregado)
    const gotosSemana = await Promise.all(Array.from({length: 7}, (_,i) => {
      const d = new Date(todayMs - i*86400000).toISOString().slice(0,10);
      return getGotoCallStatsForDate(d).catch(() => ({}));
    }));
    const callsSemana = gotosSemana.reduce((acc, day) => {
      const c = day[ownerName] || {};
      acc.total += c.total||0; acc.outbound += c.outbound||0; acc.inbound += c.inbound||0;
      acc.answered += c.answered||0; acc.missed += c.missed||0;
      return acc;
    }, { total:0, outbound:0, inbound:0, answered:0, missed:0 });

    // 3. Vendas/Propostas/Atividade Zoho (ontem, 7d, 30d, mês)
    const stagesAbertas = 'Primeiro Contato,Em Qualificação,Qualificado,Proposta,Proposta Quente,Proposta Fria,Em Atendimento';
    const propStages = 'Proposta,Proposta Quente,Proposta Fria,Em Atendimento';

    const [wonOntem, wonSemana, wonMes, wonMesAnt, perdidosSemana, propostas7d, ativos, novos7d] = await Promise.all([
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${ontem},${ontem}))`, 'Deal_Name,Amount', 50).catch(()=>[]),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${seteDias},${today}))`, 'Deal_Name,Amount,Closing_Date,Lead_Source', 100).catch(()=>[]),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${mesStart},${today}))`, 'Deal_Name,Amount,Closing_Date', 200).catch(()=>[]),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${mesAnt},${mesAntFim}))`, 'Deal_Name,Amount', 200).catch(()=>[]),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:equals:Fechado perdido)and(Closing_Date:between:${seteDias},${today}))`, 'Deal_Name,Amount,Description', 100).catch(()=>[]),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:in:${propStages})and(Modified_Time:between:${seteDias}T00:00:00-03:00,${today}T23:59:59-03:00))`, 'Deal_Name,Stage,Amount', 100).catch(()=>[]),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:in:${stagesAbertas}))`, 'Deal_Name,Stage,Tier_Lead,Last_Activity_Time,Created_Time,Amount,Telefone_contato', 200).catch(()=>[]),
      zohoSearch(`((Owner:equals:${ownerName})and(Created_Time:between:${seteDias}T00:00:00-03:00,${today}T23:59:59-03:00))`, 'Deal_Name,Stage,Tier_Lead,Created_Time,Amount,Telefone_contato', 200).catch(()=>[]),
    ]);

    const fatOntem = wonOntem.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const fatSemana = wonSemana.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const fatMes = wonMes.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const fatMesAnt = wonMesAnt.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);

    // 4. Análise pipeline atual: Diamante/Ouro parados >2h, deals em proposta sem follow-up, etc
    const nowMs = Date.now();
    const dOuro = ativos.filter(d => d.Tier_Lead === 'Diamante' || d.Tier_Lead === 'Ouro');
    const dOuroParados = dOuro.filter(d => {
      const h = (nowMs - new Date(d.Last_Activity_Time||d.Created_Time||'2020-01-01').getTime())/3600000;
      return h > 2;
    });
    const propostasSemFu = ativos.filter(d => /Proposta/i.test(d.Stage)).filter(d => {
      const h = (nowMs - new Date(d.Last_Activity_Time||d.Created_Time||'2020-01-01').getTime())/3600000;
      return h > 24;
    });
    const novosSemContato = novos7d.filter(d => {
      const created = new Date(d.Created_Time).getTime();
      const lastAct = d.Last_Activity_Time ? new Date(d.Last_Activity_Time).getTime() : null;
      return !lastAct || (lastAct - created) > 24 * 3600000;
    });

    // 5. Conversão funil simples
    const totalAtivos = ativos.length;
    const totalPropostas = ativos.filter(d => /Proposta/i.test(d.Stage)).length;
    const taxaPropAtual = totalAtivos > 0 ? (totalPropostas / totalAtivos) * 100 : 0;
    const taxaConversaoSemana = (novos7d.length + ativos.length) > 0 ? (wonSemana.length / Math.max(novos7d.length, 1)) * 100 : 0;

    res.json({
      closer: target.name,
      crmOwner: ownerName,
      datas: { ontem, hoje: today, sete_dias: seteDias, trinta_dias: trintaDias, mes_start: mesStart, mes_anterior: { start: mesAnt, end: mesAntFim } },
      ontem: {
        calls: callsOntem,
        vendas: wonOntem.length,
        receita: fatOntem,
      },
      semana: {
        calls: callsSemana,
        answer_rate: callsSemana.outbound > 0 ? (callsSemana.answered / callsSemana.outbound) * 100 : null,
        vendas: wonSemana.length,
        receita: fatSemana,
        propostas_movidas: propostas7d.length,
        perdidos: perdidosSemana.length,
        novos_leads: novos7d.length,
        novos_sem_contato: novosSemContato.length,
        taxa_conversao_pct: taxaConversaoSemana,
      },
      mes: {
        vendas: wonMes.length,
        receita: fatMes,
        receita_mes_anterior: fatMesAnt,
        delta_pct: fatMesAnt > 0 ? Math.round(((fatMes - fatMesAnt) / fatMesAnt) * 100) : null,
      },
      pipeline: {
        ativos: totalAtivos,
        propostas: totalPropostas,
        taxa_proposta_pct: taxaPropAtual,
        diamante_ouro: dOuro.length,
        diamante_ouro_parados: dOuroParados.length,
        propostas_sem_fu_24h: propostasSemFu.length,
      },
      gaps: [
        ...(callsSemana.outbound < 100 ? [{ tipo: 'volume', msg: `Apenas ${callsSemana.outbound} ligações outbound em 7d (mín 175 = 25/dia)` }] : []),
        ...(dOuroParados.length > 0 ? [{ tipo: 'tier', msg: `${dOuroParados.length} Diamante/Ouro sem contato >2h` }] : []),
        ...(propostasSemFu.length > 0 ? [{ tipo: 'followup', msg: `${propostasSemFu.length} propostas sem follow-up >24h` }] : []),
        ...(novosSemContato.length > 0 ? [{ tipo: 'speed', msg: `${novosSemContato.length} leads novos (7d) sem contato em <24h` }] : []),
        ...(callsSemana.outbound > 0 && (callsSemana.answered/callsSemana.outbound) < 0.4 ? [{ tipo: 'answer', msg: `Taxa de atendimento ${Math.round(callsSemana.answered/callsSemana.outbound*100)}% (ideal ≥50%)` }] : []),
      ],
      // Top 3 deals em risco (parados >7d, alto valor + tier alto)
      top3_risco: ativos
        .filter(d => d.Telefone_contato)
        .map(d => ({
          ...d,
          horas_parado: (nowMs - new Date(d.Last_Activity_Time||d.Created_Time||'2020-01-01').getTime())/3600000,
        }))
        .filter(d => d.horas_parado > 48)
        .sort((a,b) => {
          const tierRank = { Diamante:0, Ouro:1, Prata:2, Bronze:3, '':4 };
          const ta = tierRank[a.Tier_Lead||''] ?? 4;
          const tb = tierRank[b.Tier_Lead||''] ?? 4;
          if (ta !== tb) return ta - tb;
          return (parseFloat(b.Amount)||0) - (parseFloat(a.Amount)||0);
        })
        .slice(0, 3)
        .map(d => ({
          dealId: d.id, nome: d.Deal_Name, tier: d.Tier_Lead, valor: parseFloat(d.Amount)||0,
          stage: d.Stage, horas_parado: Math.round(d.horas_parado),
        })),
      perdidos_amostra: perdidosSemana.slice(0, 5).map(d => ({
        nome: d.Deal_Name, valor: parseFloat(d.Amount)||0, motivo: d.Description?.slice(0,100) || '?',
      })),
    });
  } catch(e) {
    console.error('[reuniao-matinal/dados]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// Síntese IA do dossiê (live agent — Diretor Comercial Matinal)
app.post('/gestao/reuniao-matinal/sintese-ia', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não setada' });
  const { dados } = req.body || {};
  if (!dados) return res.status(400).json({ error: 'dados (do endpoint /reuniao-matinal/dados) obrigatório' });

  const SYSTEM = `Você é o **Diretor Comercial Matinal da Tudo de Filtro** — gestor sênior. NÃO É AMIGO DO CLOSER. É um diretor que vai cobrar resultado em reunião matinal de 7h.

POSTURA:
- DIRETO. Sem rodeio, sem suavizar, sem "talvez", sem "considere".
- DURO quando os números merecem. Closer com 8 calls/dia tomando 35k de salário não é "atenção" — é PROBLEMA.
- USE NÚMEROS reais do snapshot. "Você teve 7 ligações ontem, meta é 25" — não "volume baixo".
- NOMEIE responsabilidade: "VOCÊ não ligou pros Diamante", "VOCÊ deixou 4 propostas mofarem".
- Quando cair, CAIA EM CIMA. Quando subir, RECONHEÇA SEM PUXAR SACO.
- Frases curtas, no imperativo: "Ligue", "Pause", "Mexa-se", "Pare de".
- Sem emojis dentro dos textos das listas. Apenas no veredito_curto.

CONTEXTO TDF:
- Closers atendem 4 produtos: Filtro de Entrada, Bebedouro AF, Purificador, Refil
- Meta diária ligações outbound: 25 mín / 35-45 ideal / <15 = INACEITÁVEL
- Speed-to-lead Diamante/Ouro: <30min é OBRIGATÓRIO — >2h é descaso
- Proposta sem follow-up >24h: ESQUECEU o cliente
- Answer rate <40%: closer não sabe abordar, ou liga em horário ruim
- Conversão típica do time: 8-15% lead→venda. <5% é incompetência.
- Closer SEM venda na semana: revisar treinamento OU desligar.

REGRAS DA ANÁLISE:
1. Compare com baseline (mês anterior + time). NÃO suavize delta negativo.
2. Distinga ESFORÇO (calls, follow-ups) de RESULTADO (vendas, receita).
   Closer pode estar trabalhando MUITO e errando MUITO — diga.
   Closer pode estar trabalhando POUCO e ainda assim vendendo — não relaxe.
3. CADA ação recomendada tem que ser MENSURÁVEL e com PRAZO.
   ERRADO: "Melhore follow-up"
   CERTO: "Hoje até 11h: ligue nas 4 propostas paradas há +24h. Reporte ao gestor"
4. Comparação_time: se está abaixo, NOMEIE a métrica. Se acima, dê crédito.
5. Veredito: 🔴 Crítico se vendas semana = 0 OU calls semana < 100 OU 3+ Diamante/Ouro parados.

FORMATO JSON OBRIGATÓRIO:
{
  "veredito_curto": "1-2 frases até 280 chars. Comece com 🟢/🟡/🔴 e seja direto. Ex: '🔴 Crítico — 0 vendas em 7 dias com 9 leads novos. Volume de calls em queda livre. Reunião com gestor URGENTE hoje.'",
  "classificacao": "saudavel | atencao | critico",
  "pontos_criticos": ["até 3 problemas que merecem ação HOJE — nominais, com número"],
  "pontos_atencao": ["até 3 sinais de alerta — riscos que viram crítico semana que vem"],
  "gaps_identificados": ["até 3 gaps comportamentais (ex: 'Não trabalha após 17h — dados últimos 30 dias')"],
  "acoes_recomendadas": [
    {
      "acao": "frase imperativa curta com PRAZO. Ex: 'Hoje até 11h: ligar pros 3 Diamante listados'",
      "tipo": "ligar | pausar_campanha | treinar | enviar_proposta | reunir | reabrir_lead | revisar_pipeline | follow_up | outro",
      "leads_referenciados": ["nome do lead 1", "nome do lead 2"],
      "tooltip": "explicação curta (até 200 chars) do PORQUÊ fazer + resultado esperado. Aparece em hover.",
      "prazo": "ex: 'até 11h hoje', 'amanhã 9h', 'esta semana'"
    }
  ],
  "destaques_positivos": ["até 2 — só se realmente houver. Sem inventar elogio."],
  "topico_coaching": "1 tópico ESPECÍFICO de coaching com diagnóstico e plano. Ex: 'Abertura na ligação fria. 38% answer rate. Hoje: gravar 5 calls + escutar com supervisor amanhã 9h'",
  "comparacao_time": "1 frase. Onde este closer está vs média. Sem palavras vazias."
}

REGRA CRÍTICA: NÃO suavize. NÃO encoraje sem dado. NÃO invente. Diga só o que os números mostram.`;

  try {
    const Anthropic = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
    const anthropic = new Anthropic({ apiKey });
    const r = await anthropic.messages.create({
      model: 'claude-sonnet-4-5-20250929', // usa Opus pra análise profunda
      max_tokens: 2500,
      system: SYSTEM,
      messages: [{ role: 'user', content: 'Snapshot do closer:\n```json\n' + JSON.stringify(dados, null, 2) + '\n```\n\nGere o dossiê em JSON estrito.' }],
    });
    const txt = r.content?.[0]?.text || '';
    let parsed = null;
    try { const m = txt.match(/\{[\s\S]*\}/); if (m) parsed = JSON.parse(m[0]); } catch(_){}
    if (!parsed) return res.json({ raw: txt, error: 'IA não retornou JSON válido' });
    res.json({ ...parsed, modelo: 'claude-sonnet-4-5', generated_at: new Date().toISOString() });
  } catch(e) {
    console.error('[reuniao-matinal/sintese-ia]', e.message);
    res.status(500).json({ error: e.message });
  }
});

