// === SISTEMA DE TAREFAS ===
// Storage Postgres KV (sobrevive deploy) — Code Review P2
// Carrega lista persistida no boot; cada save reescreve até 500 últimas tasks
let _TASKS = [];
const PORTAL_BASE = process.env.PORTAL_URL || 'https://tdf-portal-production.up.railway.app';

// Carrega tasks do KV no boot (uma vez quando KV inicializar)
setTimeout(() => {
  try {
    const persisted = kvOrFile('director-tasks-mem', null, []);
    if (Array.isArray(persisted) && persisted.length) {
      _TASKS = persisted.slice(-500); // mantém só últimas 500
      console.log(`[tasks] ${_TASKS.length} tarefas restauradas do Postgres`);
    }
  } catch(e) { console.warn('[tasks] restore:', e.message); }
}, 7000);

function _persistTasks() {
  try { kvAndFile('director-tasks-mem', null, _TASKS); } catch(_){}
}

function registerTask({ closerCRM, closerName, type, title, body, source, dealIds = [], priority = 'normal' }) {
  const id = `t_${Date.now()}_${Math.floor(Math.random()*1e6)}`;
  const task = {
    id, closerCRM, closerName, type, title, body, source, dealIds, priority,
    createdAt: Date.now(), status: 'pendente', concluidoEm: null, concluidoBy: null,
  };
  _TASKS.push(task);
  while (_TASKS.length > 500) _TASKS.shift();
  _persistTasks(); // sobrevive deploy agora!
  return task;
}

function getTasksForCloser(crmOwner, days = 1) {
  const cutoff = Date.now() - days * 86400000;
  return _TASKS.filter(t => t.closerCRM === crmOwner && t.createdAt >= cutoff)
    .sort((a, b) => b.createdAt - a.createdAt);
}

function getAllTasks(days = 1) {
  const cutoff = Date.now() - days * 86400000;
  return _TASKS.filter(t => t.createdAt >= cutoff).sort((a, b) => b.createdAt - a.createdAt);
}
function getTaskById(id) {
  return _TASKS.find(t => t.id === id) || null;
}

