app.get('/cobranca/:taskId/data', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const task = getTaskById(req.params.taskId);
  if (!task) return res.status(404).json({ error: 'cobrança não encontrada (pode ter expirado — limit 500 últimas)' });
  // Closer só pode ver a própria cobrança (ou admin/gestor vê qualquer uma)
  const isAdmin = u?.role === 'admin' || isGestor(u);
  const ehMinha = u?.crmOwner === task.closerCRM;
  if (!isAdmin && !ehMinha) return res.status(403).json({ error: 'cobrança não é sua' });
  // Busca dados de cada deal
  const deals = [];
  if (Array.isArray(task.dealIds) && task.dealIds.length) {
    const tk = await getZohoToken();
    if (tk) {
      const fields = 'Deal_Name,Telefone_contato,Cidade,Stage,Pipeline,Tier_Lead,Amount,Lead_Source,Owner,Last_Activity_Time,Created_Time,Produto_Vendido,Email';
      // Busca em chunks de 5 paralelos
      for (let i = 0; i < task.dealIds.length; i += 5) {
        const chunk = task.dealIds.slice(i, i+5);
        const results = await Promise.all(chunk.map(async id => {
          if (id.startsWith?.('erp:') || id.startsWith?.('wati:')) return { id, source: 'local' };
          try {
            const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${id}?fields=${fields}`, {
              headers: { Authorization: `Zoho-oauthtoken ${tk}` },
            });
            const j = await r.json().catch(() => ({}));
            return j.data?.[0] || { id, error: 'não encontrado' };
          } catch(e) { return { id, error: e.message }; }
        }));
        deals.push(...results);
      }
    }
  }
  const meta = loadManutMeta();
  // Status local do deal (visto/marcado pelo closer?)
  const tratados = task.tratados || {};
  res.json({
    task: {
      id: task.id,
      type: task.type, title: task.title, body: task.body,
      priority: task.priority, source: task.source,
      closerName: task.closerName, closerCRM: task.closerCRM,
      createdAt: task.createdAt,
      dealIds: task.dealIds || [],
      status: task.status,
      tratados,
    },
    deals: deals.map(d => ({
      id: d.id,
      nome: d.Deal_Name || '?',
      telefone: d.Telefone_contato || '',
      cidade: d.Cidade || '',
      stage: d.Stage || '',
      pipeline: d.Pipeline || '',
      tier: d.Tier_Lead || '',
      amount: parseFloat(d.Amount) || 0,
      leadSource: d.Lead_Source || '',
      owner: d.Owner?.name || '',
      lastActivity: d.Last_Activity_Time || '',
      createdAt: d.Created_Time || '',
      produto: d.Produto_Vendido || '',
      email: d.Email || '',
      iaAtendendo: !!meta[d.id]?.iaAtende,
      tratado: !!tratados[d.id],
      crmLink: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}`,
      error: d.error || null,
    })),
  });
});

// Marca um deal como tratado dentro de uma cobrança
app.post('/cobranca/:taskId/tratar/:dealId', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  const task = getTaskById(req.params.taskId);
  if (!task) return res.status(404).json({ error: 'task não encontrada' });
  const isAdmin = u?.role === 'admin' || isGestor(u);
  const ehMinha = u?.crmOwner === task.closerCRM;
  if (!isAdmin && !ehMinha) return res.status(403).json({ error: 'cobrança não é sua' });
  task.tratados = task.tratados || {};
  task.tratados[req.params.dealId] = {
    em: Date.now(),
    por: u.name || u.username,
    nota: req.body?.nota || '',
  };
  // Se todos tratados, marca task como concluída
  const todosOk = (task.dealIds || []).every(id => task.tratados[id]);
  if (todosOk) {
    task.status = 'concluida';
    task.concluidoEm = Date.now();
    task.concluidoBy = u.username;
  }
  _persistTasks();
  res.json({ ok: true, status: task.status, todosOk });
});

