function buildAlertMessage(preset, firstName, data, taskId) {
  const tpl = ALERT_TEMPLATES[preset] ? ALERT_TEMPLATES[preset](firstName, data || {}) : null;
  // Link direto pra cobrança específica (se temos taskId)
  const deepLink = taskId
    ? `${PORTAL_BASE}/cobranca/${taskId}`
    : `${PORTAL_BASE}/cockpit#tarefas`;
  if (!tpl) {
    return {
      title: 'AÇÃO NECESSÁRIA',
      icon: '⚡',
      priority: 'media',
      msg: `${firstName.toUpperCase()}, ação necessária. Abre direto nos leads:\n${deepLink}`,
    };
  }
  if (preset === 'elogio') {
    return {
      title: tpl.title, icon: tpl.icon, priority: tpl.priority,
      msg: `${tpl.icon} ${firstName.toUpperCase()} — ${tpl.title}\n\n${tpl.body}`,
    };
  }
  const cta = taskId
    ? `🎯 ABRA OS LEADS DESTA COBRANÇA (já filtrados):\n${deepLink}\n\nLá você pode ligar, chamar a Núbia, ver no Zoho — tudo direto sem perder tempo.`
    : `📋 ABRA SEU PAINEL DE TAREFAS:\n${deepLink}`;
  const msg =
`${tpl.icon} ${firstName.toUpperCase()} — ${tpl.title}

${tpl.body}

${cta}`;
  return { title: tpl.title, icon: tpl.icon, priority: tpl.priority, msg };
}

app.post('/gestao/alert-preset', requireAuth, async (req, res) => {
  const isAdmin = USERS[req.session.user.username]?.role === 'admin';
  if (!isAdmin) return res.status(403).json({ error: 'admin only' });

  const { preset, closerName, data } = req.body;
  const phone = CLOSER_PHONES[closerName];
  if (!phone) return res.json({ error: 'phone not found', closer: closerName });

  const firstName = closerName.split(' ')[0];

  // Registra TASK PRIMEIRO (pra ter ID antes da mensagem)
  let task = null;
  if (preset !== 'elogio') {
    task = registerTask({
      closerCRM: closerName, closerName: firstName,
      type: preset, title: '', body: '',
      source: `admin:${USERS[req.session.user.username]?.name||'?'}`,
      dealIds: data?.dealIds || [],
      priority: 'normal',
    });
  }
  // Constrói mensagem COM o link da task (deep link direto pros leads)
  const built = buildAlertMessage(preset, firstName, data, task?.id);
  // Atualiza task com title/body/priority finais
  if (task) {
    task.title = built.title;
    task.body = built.msg;
    task.priority = built.priority;
    _persistTasks();
  }

  // Envia Z-API ao closer
  const result = await zapiSend(phone, built.msg);

  // Notifica Paulo com confirmação detalhada
  if (preset !== 'elogio') {
    const conf = `[ALERTA DISPARADO] ${closerName}\n${built.icon} ${built.title}\nWhatsApp: ${result.ok?'✅ entregue':'❌ falhou ('+(result.status||'?')+')'}\nTask criada: ${task?.id||'-'}`;
    await zapiSend(PAULO_PHONE, conf);
  }

  res.json({
    sent: result.ok,
    zapiStatus: result.status || null,
    zapiError: result.error || null,
    closer: closerName,
    phone,
    title: built.title,
    message: built.msg,
    taskId: task?.id || null,
  });
});

