function loadNovidadesState() {
  try { return JSON.parse(require('fs').readFileSync(NOVIDADES_FILE, 'utf8')); }
  catch { return { agendadoPara: null, ultimoEnvio: null, sentTo: [] }; }
}
function saveNovidadesState(s) {
  try {
    require('fs').mkdirSync(path.dirname(NOVIDADES_FILE), { recursive: true });
    require('fs').writeFileSync(NOVIDADES_FILE, JSON.stringify(s, null, 2));
  } catch(_){}
}

// === PRÓXIMA AÇÃO (Sales Coach Win 3) — uma única coisa mais importante AGORA ===
// Lógica de prioridade em camadas. Retorna a primeira que matchar.
app.get('/cockpit/proxima-acao', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'sem CRM owner' });
  const isAdmin = u.role === 'admin' || isGestor(u);
  let target = u;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) target = USERS[req.query.closer];
  const ownerName = target.crmOwner;
  try {
    const nowMs = Date.now();
    // Camada 1: Tarefa vencendo nos próximos 30min
    const tarefas = loadTarefas();
    const minhasTarefas = Object.values(tarefas).filter(t =>
      t.status === 'aberta' && (
        t.atribuidoA === target.username
        || t.criadoPor === target.username
        || (Array.isArray(t.atribuidos) && t.atribuidos.includes(target.username))
      )
    );
    const proxTarefa = minhasTarefas
      .map(t => ({ ...t, dist: new Date(t.dataHora).getTime() - nowMs }))
      .filter(t => t.dist <= 30 * 60 * 1000) // <30min OU já vencida
      .sort((a,b) => a.dist - b.dist)[0];
    if (proxTarefa) {
      const venceMin = Math.round(proxTarefa.dist / 60000);
      const status = venceMin < 0 ? `⚠️ atrasada ${Math.abs(venceMin)}min` : `vence em ${venceMin}min`;
      return res.json({
        prioridade: 'CRITICA',
        tipo: 'tarefa',
        titulo: '⏰ ' + (proxTarefa.titulo||'?'),
        descricao: status + (proxTarefa.dealNome ? ' · cliente: '+proxTarefa.dealNome : ''),
        dealId: proxTarefa.dealId,
        link: proxTarefa.dealId ? `/manutencao#${proxTarefa.dealId}` : '/cockpit#tarefas',
        action_label: '✓ Concluir / 📋 Ver',
      });
    }
    // Camada 2: Decay Score >= 80 (1 deal mais crítico)
    const stagesAbertas = 'Primeiro Contato,Em Qualificação,Qualificado,Proposta,Proposta Quente,Proposta Fria,Em Atendimento';
    const criteria = `((Owner:equals:${ownerName})and(Stage:in:${stagesAbertas}))`;
    const deals = await zohoSearch(criteria, 'Deal_Name,Stage,Amount,Telefone_contato,Last_Activity_Time,Modified_Time,Created_Time,Tier_Lead', 100).catch(() => []);
    const meta = loadManutMeta();
    const inbox = loadWatiInbox();
    const tarefasFuturasByDeal = {};
    for (const t of Object.values(tarefas)) {
      if (!t.dealId || t.status !== 'aberta') continue;
      const ts = new Date(t.dataHora).getTime();
      if (ts > nowMs) tarefasFuturasByDeal[t.dealId] = true;
    }
    let topDecay = null, topDecayScore = 0;
    for (const d of deals) {
      const m = meta[d.id] || {};
      const wi = inbox[d.id];
      const score = calcDecayScore(d, m, wi, !!tarefasFuturasByDeal[d.id]);
      if (score > topDecayScore) { topDecayScore = score; topDecay = { deal: d, score }; }
    }
    if (topDecay && topDecayScore >= 80) {
      const d = topDecay.deal;
      return res.json({
        prioridade: 'CRITICA',
        tipo: 'decay',
        titulo: '🚨 ' + (d.Deal_Name || '?'),
        descricao: 'Decay Score ' + topDecay.score + ' — ' + d.Stage + (d.Tier_Lead?' · '+d.Tier_Lead:'') + (d.Amount ? ' · R$ '+Math.round(d.Amount).toLocaleString('pt-BR') : ''),
        dealId: d.id,
        link: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}`,
        action_label: '🤖 Disparar Núbia / 📞 Ligar',
      });
    }
    // Camada 3: Lead Diamante/Ouro respondeu nas últimas 2h SEM nossa resposta
    const cutoff2h = nowMs - 2 * 3600 * 1000;
    const dealsDimantesQuentes = deals.filter(d => {
      if (!['Diamante','Ouro'].includes(d.Tier_Lead)) return false;
      const wi = inbox[d.id];
      if (!wi || !wi.ultimaClienteTs) return false;
      if (wi.ultimaClienteTs < cutoff2h) return false;
      // Cliente respondeu, nós não respondemos depois
      if (wi.ultimaNossaTs && wi.ultimaNossaTs > wi.ultimaClienteTs) return false;
      return true;
    });
    if (dealsDimantesQuentes.length > 0) {
      const d = dealsDimantesQuentes.sort((a,b) => (inbox[b.id]?.ultimaClienteTs||0) - (inbox[a.id]?.ultimaClienteTs||0))[0];
      const min = Math.round((nowMs - inbox[d.id].ultimaClienteTs) / 60000);
      const ico = d.Tier_Lead === 'Diamante' ? '💎' : '🥇';
      return res.json({
        prioridade: 'ALTA',
        tipo: 'lead_quente',
        titulo: ico + ' ' + d.Deal_Name + ' (' + d.Tier_Lead + ')',
        descricao: `Cliente respondeu há ${min}min e ainda não voltou contato. ${d.Stage}.`,
        dealId: d.id,
        phone: d.Telefone_contato,
        link: `/inbox#phone=${(d.Telefone_contato||'').replace(/\D/g,'')}`,
        action_label: '💬 Responder agora',
      });
    }
    // Camada 4: Proposta Quente sem follow up há >3 dias
    const cutoff3d = nowMs - 3 * 86400000;
    const propostasFrias = deals.filter(d => {
      if (!/Proposta/.test(d.Stage)) return false;
      const lastAct = d.Last_Activity_Time ? new Date(d.Last_Activity_Time).getTime() : 0;
      return lastAct > 0 && lastAct < cutoff3d;
    });
    if (propostasFrias.length > 0) {
      const d = propostasFrias.sort((a,b) => (parseFloat(b.Amount)||0) - (parseFloat(a.Amount)||0))[0];
      const dias = Math.round((nowMs - new Date(d.Last_Activity_Time).getTime()) / 86400000);
      return res.json({
        prioridade: 'ALTA',
        tipo: 'proposta_fria',
        titulo: '📨 ' + d.Deal_Name,
        descricao: `Proposta sem retorno há ${dias} dias · ${d.Amount?'R$ '+Math.round(d.Amount).toLocaleString('pt-BR'):''}`,
        dealId: d.id,
        phone: d.Telefone_contato,
        link: `/inbox#phone=${(d.Telefone_contato||'').replace(/\D/g,'')}`,
        action_label: '📞 Reativar agora',
      });
    }
    // Camada 5: Lead novo (criado hoje) ainda em base_sem_contato
    const today = todayBR();
    const novosSemContato = deals.filter(d => {
      const created = (d.Created_Time||'').slice(0,10);
      if (created !== today) return false;
      const m = meta[d.id] || {};
      return (m.etapa || 'base_sem_contato') === 'base_sem_contato';
    });
    if (novosSemContato.length > 0) {
      const d = novosSemContato[0];
      return res.json({
        prioridade: 'MEDIA',
        tipo: 'lead_novo',
        titulo: '🆕 ' + d.Deal_Name,
        descricao: `Lead novo hoje sem contato ainda · ${d.Tier_Lead||'sem tier'}`,
        dealId: d.id,
        phone: d.Telefone_contato,
        link: `/inbox#phone=${(d.Telefone_contato||'').replace(/\D/g,'')}`,
        action_label: '👋 Primeiro contato',
      });
    }
    // Tudo OK
    res.json({
      prioridade: 'OK',
      tipo: 'tudo_ok',
      titulo: '✅ Tudo em dia!',
      descricao: 'Nenhum lead urgente, sem tarefas pra agora. Prospecte ou continue ligações da carteira.',
      action_label: 'Ver carteira',
      link: '/manutencao',
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === CONVERSÃO POR ESTÁGIO COM ALERTA DE DROP ===
// Para o closer (ou admin vendo um closer): pega deals criados nos últimos N dias
// e calcula funil cumulativo (% que chegaram em cada estágio). Compara com janela
// anterior do mesmo tamanho. Sinaliza drops >=15pp.
//
// Por que sem snapshot diário: bastam Created_Time + Stage atual no Zoho. Limitação:
// se um deal entrou e saiu de Proposta, ele aparece no estágio atual. OK pro use case
// principal (auto-coaching: "entrei como Qualificado e parou aí — onde travei?").
app.get('/cockpit/conversao-stages', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'sem CRM owner' });
  const isAdmin = u.role === 'admin' || isGestor(u);
  let target = u;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) target = USERS[req.query.closer];
  const ownerName = target.crmOwner;
  const days = Math.max(7, Math.min(180, parseInt(req.query.days, 10) || 30));
  try {
    const nowMs = Date.now();
    const curStart = new Date(nowMs - days * 86400000).toISOString().slice(0,10);
    const curEnd = new Date(nowMs).toISOString().slice(0,10);
    const prevStart = new Date(nowMs - 2 * days * 86400000).toISOString().slice(0,10);
    const prevEnd = curStart;

    const fields = 'Deal_Name,Stage,Amount,Created_Time,Closing_Date,Tier_Lead';
    const [dCur, dPrev] = await Promise.all([
      zohoSearch(
        `((Owner:equals:${ownerName})and(Created_Time:between:${curStart}T00:00:00-03:00,${curEnd}T23:59:59-03:00))`,
        fields, 300,
      ).catch(() => []),
      zohoSearch(
        `((Owner:equals:${ownerName})and(Created_Time:between:${prevStart}T00:00:00-03:00,${prevEnd}T23:59:59-03:00))`,
        fields, 300,
      ).catch(() => []),
    ]);

    // Etapas em ordem cumulativa (deals em Stage=Qualificado também passaram por Primeiro Contato, etc)
    const STAGES_ORDER = [
      { key: 'criados',     label: 'Criados',         icon: '📥', stages: [] }, // sempre 100%
      { key: 'contato',     label: 'Primeiro Contato',icon: '☎️', stages: ['Primeiro Contato','Em Qualificação','Qualificado','Proposta','Proposta Quente','Proposta Fria','Em Atendimento','Fechado Ganho','Fechado Perdido'] },
      { key: 'qualificado', label: 'Qualificado',     icon: '✅', stages: ['Qualificado','Proposta','Proposta Quente','Proposta Fria','Em Atendimento','Fechado Ganho','Fechado Perdido'] },
      { key: 'proposta',    label: 'Em Proposta',     icon: '📨', stages: ['Proposta','Proposta Quente','Proposta Fria','Em Atendimento','Fechado Ganho','Fechado Perdido'] },
      { key: 'ganho',       label: 'Fechado Ganho',   icon: '🏆', stages: ['Fechado Ganho'] },
    ];
    function calcFunil(deals) {
      const total = deals.length;
      const result = STAGES_ORDER.map(s => {
        const count = s.stages.length === 0 ? total : deals.filter(d => s.stages.includes(d.Stage)).length;
        return {
          key: s.key, label: s.label, icon: s.icon,
          count,
          pct: total > 0 ? (count / total) * 100 : 0,
        };
      });
      // taxas de transição (dropoff entre etapas consecutivas)
      for (let i = 1; i < result.length; i++) {
        const prev = result[i-1].count;
        result[i].conv_from_prev = prev > 0 ? (result[i].count / prev) * 100 : 0;
      }
      return { total, etapas: result };
    }
    const cur = calcFunil(dCur);
    const prev = calcFunil(dPrev);

    // Detecta drops em conv_from_prev (transição) >=15pp piora vs período anterior
    const ALERT_THRESHOLD = 15;
    const alertas = [];
    for (let i = 1; i < cur.etapas.length; i++) {
      const c = cur.etapas[i].conv_from_prev || 0;
      const p = prev.etapas[i].conv_from_prev || 0;
      const delta = c - p;
      cur.etapas[i].delta_pp = delta;
      cur.etapas[i].prev_conv = p;
      if (prev.etapas[i-1].count >= 5 && cur.etapas[i-1].count >= 5 && delta <= -ALERT_THRESHOLD) {
        alertas.push({
          de: cur.etapas[i-1].label,
          para: cur.etapas[i].label,
          conv_atual: c,
          conv_anterior: p,
          delta_pp: delta,
          mensagem: `Conversão ${cur.etapas[i-1].label}→${cur.etapas[i].label} caiu ${Math.abs(delta).toFixed(0)}pp (de ${p.toFixed(0)}% pra ${c.toFixed(0)}%)`,
        });
      }
    }

    res.json({
      owner: ownerName,
      periodo_atual: { start: curStart, end: curEnd, dias: days },
      periodo_anterior: { start: prevStart, end: prevEnd },
      atual: cur,
      anterior: prev,
      alertas,
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

