// === HISTÓRICO PERSONALIZADO DO CLOSER (período custom) ===
// Permite vendedor ver suas vendas em qualquer período, comparar com período
// anterior equivalente, e ver ranking (posição) no time naquele período.
app.get('/cockpit/historico', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'sem CRM owner' });
  const isAdmin = u.role === 'admin' || isGestor(u);
  // Admin pode ver outro closer via ?closer=username
  let target = u;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) target = USERS[req.query.closer];
  const ownerName = target.crmOwner;
  try {
    // Período: ?start&end OU presets ?periodo=hoje|ontem|7d|30d|esta_semana|este_mes|mes_passado
    let start, end;
    const today = todayBR();
    const nowBr = nowBR();
    if (req.query.start && req.query.end) {
      start = req.query.start;
      end = req.query.end;
    } else {
      const periodo = req.query.periodo || '7d';
      if (periodo === 'hoje') { start = today; end = today; }
      else if (periodo === 'ontem') {
        const y = new Date(nowBr.getTime() - 86400000);
        const ystr = y.toISOString().slice(0,10);
        start = ystr; end = ystr;
      } else if (periodo === 'esta_semana') {
        const dia = nowBr.getDay() || 7; // segunda = 1
        const seg = new Date(nowBr.getTime() - (dia - 1) * 86400000);
        start = seg.toISOString().slice(0,10);
        end = today;
      } else if (periodo === 'este_mes') {
        start = `${nowBr.getFullYear()}-${String(nowBr.getMonth()+1).padStart(2,'0')}-01`;
        end = today;
      } else if (periodo === 'mes_passado') {
        const lm = new Date(nowBr.getFullYear(), nowBr.getMonth() - 1, 1);
        start = `${lm.getFullYear()}-${String(lm.getMonth()+1).padStart(2,'0')}-01`;
        end = new Date(nowBr.getFullYear(), nowBr.getMonth(), 0).toISOString().slice(0,10);
      } else {
        // 7d, 30d, 90d
        const m = String(periodo).match(/^(\d+)d$/);
        const n = m ? parseInt(m[1], 10) : 7;
        const startDate = new Date(nowBr.getTime() - (n - 1) * 86400000);
        start = startDate.toISOString().slice(0,10);
        end = today;
      }
    }
    // Período anterior equivalente (pra comparativo)
    const startMs = new Date(start + 'T00:00:00-03:00').getTime();
    const endMs = new Date(end + 'T00:00:00-03:00').getTime();
    const duracaoDias = Math.round((endMs - startMs) / 86400000) + 1;
    const prevEnd = new Date(startMs - 86400000).toISOString().slice(0, 10);
    const prevStart = new Date(startMs - duracaoDias * 86400000).toISOString().slice(0, 10);

    // Busca em paralelo: meu período, período anterior, time inteiro (pra ranking)
    const myWonCrit = `((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${start},${end}))`;
    const myPrevCrit = `((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${prevStart},${prevEnd}))`;
    const teamWonCrit = `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${start},${end}))`;

    const [myWon, myPrev, teamWon] = await Promise.all([
      zohoSearch(myWonCrit, 'Deal_Name,Amount,Closing_Date,Produto_Vendido,Pipeline,Layout', 200),
      zohoSearch(myPrevCrit, 'Deal_Name,Amount,Closing_Date', 200),
      isAdmin || req.query.includeRanking ? zohoSearch(teamWonCrit, 'Deal_Name,Amount,Owner', 500) : Promise.resolve([]),
    ]);

    // Métricas atuais
    const vendas = myWon.length;
    const faturamento = myWon.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const ticketMedio = vendas > 0 ? faturamento / vendas : 0;
    // Período anterior
    const vendasPrev = myPrev.length;
    const fatPrev = myPrev.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    // Delta
    const deltaVendas = vendasPrev > 0 ? Math.round(((vendas - vendasPrev) / vendasPrev) * 100) : (vendas > 0 ? 100 : 0);
    const deltaFat = fatPrev > 0 ? Math.round(((faturamento - fatPrev) / fatPrev) * 100) : (faturamento > 0 ? 100 : 0);

    // Vendas por dia (pra gráfico)
    const porDia = {};
    for (const d of myWon) {
      const dia = (d.Closing_Date || '').slice(0,10);
      if (!dia) continue;
      if (!porDia[dia]) porDia[dia] = { vendas: 0, faturamento: 0 };
      porDia[dia].vendas++;
      porDia[dia].faturamento += parseFloat(d.Amount) || 0;
    }
    // Preenche dias sem venda com zero
    const series = [];
    for (let i = 0; i < duracaoDias; i++) {
      const d = new Date(startMs + i * 86400000).toISOString().slice(0,10);
      series.push({ data: d, vendas: porDia[d]?.vendas || 0, faturamento: porDia[d]?.faturamento || 0 });
    }

    // Por categoria (Pipeline/Layout)
    const porCategoria = {};
    for (const d of myWon) {
      const cat = categoriaManutInteligente(d);
      const cfg = VIDA_UTIL[cat]; if (!cfg) continue;
      if (!porCategoria[cat]) porCategoria[cat] = { count: 0, faturamento: 0, label: cfg.label };
      porCategoria[cat].count++;
      porCategoria[cat].faturamento += parseFloat(d.Amount) || 0;
    }

    // Ranking no time (sem mostrar nomes dos outros — só posição)
    let ranking = null;
    if (teamWon.length > 0) {
      const porOwner = {};
      for (const d of teamWon) {
        const o = d.Owner?.name || '?';
        if (!porOwner[o]) porOwner[o] = { vendas: 0, faturamento: 0 };
        porOwner[o].vendas++;
        porOwner[o].faturamento += parseFloat(d.Amount) || 0;
      }
      const lista = Object.entries(porOwner)
        .map(([nome, m]) => ({ nome, ...m }))
        .sort((a,b) => b.faturamento - a.faturamento);
      const minhaPos = lista.findIndex(l => l.nome === ownerName) + 1;
      ranking = {
        posicao: minhaPos || null,
        total: lista.length,
        top1_faturamento: lista[0]?.faturamento || 0,
        media_time: lista.reduce((s,l) => s + l.faturamento, 0) / lista.length,
        meu_faturamento: faturamento,
        // Não expõe nomes dos outros — só anonimizado
        distribuicao: lista.map(l => ({ vendas: l.vendas, faturamento: l.faturamento, eu: l.nome === ownerName })),
      };
    }

    res.json({
      ownerName: target.name,
      periodo: { start, end, duracaoDias, label: req.query.periodo || 'custom' },
      periodo_anterior: { start: prevStart, end: prevEnd },
      atual: { vendas, faturamento, ticket_medio: ticketMedio },
      anterior: { vendas: vendasPrev, faturamento: fatPrev },
      delta: { vendas: deltaVendas, faturamento: deltaFat },
      series,
      por_categoria: porCategoria,
      ranking,
      ultimas_vendas: myWon.slice(0, 20).map(d => ({
        nome: d.Deal_Name, amount: parseFloat(d.Amount)||0, data: d.Closing_Date,
        produto: d.Produto_Vendido || '',
      })),
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

