function buildNovidadesMsg(firstName) {
  return `🚀 Bom dia, ${firstName}!

Saiu uma penca de novidade no Portal:

📋 QUADRO DE TAREFAS — botão flutuante no canto inferior direito de toda página. Pulsa vermelho quando o gestor te cobra. Marca ✓ Concluída quando fizer.

🎙️ LIVE DIRECTOR — IA te diz qual cliente atacar primeiro com link direto pro CRM e WATI.

📈 META-BAR FORECAST — vendas hoje + mês + meta + projeção em tempo real. Vê em qualquer página.

🎯 SCORE 80/20 — agora usa ligações reais do GoTo. Meta: 25 ligações/dia.

🔊 YABADABADOOO! Toca o som do Fred quando chega tarefa nova.

Abre o Portal e dá uma olhada:
https://tdf-portal-production.up.railway.app/cockpit

Bora vender!`;
}

async function dispararNovidadesAgora() {
  const state = loadNovidadesState();
  const closers = Object.entries(USERS).filter(([_, u]) => u.role === 'closer');
  const results = { sent: 0, failed: [], total: closers.length, sentTo: [] };
  for (const [username, u] of closers) {
    const phone = CLOSER_PHONES[u.crmOwner];
    if (!phone) { results.failed.push({ username, reason: 'sem telefone' }); continue; }
    const firstName = u.name.split(' ')[0];
    try {
      const r = await zapiSend(phone, buildNovidadesMsg(firstName));
      if (r.ok) { results.sent++; results.sentTo.push(username); }
      else results.failed.push({ username, reason: 'zapi '+ (r.status||'?') });
    } catch (e) {
      results.failed.push({ username, reason: e.message });
    }
    await new Promise(r => setTimeout(r, 12000)); // rate limit 10s+
  }
  state.ultimoEnvio = new Date().toISOString();
  state.sentTo = results.sentTo;
  state.agendadoPara = null;
  saveNovidadesState(state);
  try { await zapiSend(PAULO_PHONE, `[Avisos Novidades] Disparado pra ${results.sent}/${results.total} closers. Falhas: ${results.failed.length}`); } catch(_){}
  return results;
}

app.post('/gestao/novidades/agendar', requireAuth, (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  // Amanhã 7h BRT em UTC: BRT = UTC-3, logo 7h BRT = 10h UTC
  const nowBr = nowBR();
  const amanhaY = nowBr.getFullYear();
  const amanhaM = nowBr.getMonth();
  const amanhaD = nowBr.getDate() + 1;
  // 7h BRT = 10h UTC
  const targetUtc = new Date(Date.UTC(amanhaY, amanhaM, amanhaD, 10, 0, 0));
  const state = loadNovidadesState();
  state.agendadoPara = targetUtc.toISOString();
  state.scheduledBy = USERS[req.session.user.username].name;
  saveNovidadesState(state);
  res.json({ ok: true, agendadoPara: state.agendadoPara, brtView: 'amanhã 07:00 BRT' });
});

app.post('/gestao/novidades/cancelar-agendamento', requireAuth, (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const state = loadNovidadesState();
  state.agendadoPara = null;
  saveNovidadesState(state);
  res.json({ ok: true });
});

app.post('/gestao/novidades/disparar', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  // Async fire-and-respond
  res.json({ ok: true, message: 'disparando em background — resultado em alguns minutos' });
  dispararNovidadesAgora().catch(e => console.error('disparar novidades:', e));
});

// Cron interno: checa a cada 5min se chegou hora do agendamento
setInterval(async () => {
  try {
    const state = loadNovidadesState();
    if (!state.agendadoPara) return;
    if (Date.now() >= new Date(state.agendadoPara).getTime()) {
      console.log('[novidades] disparando avisos agendados...');
      await dispararNovidadesAgora();
    }
  } catch(e) { console.error('[novidades] cron error:', e.message); }
}, 5 * 60 * 1000);

// ====================================================================
// === MÓDULO MANUTENÇÃO E RECOMPRA ===================================
// ====================================================================
const MANUT_FILE = path.join(__dirname, 'data/manutencao.json');

// Vida útil padrão por categoria (em meses)
const VIDA_UTIL = {
  refil:           { meses: 6,  ticket: 350,  label: 'Refil de Purificador' },
  // 14/Mai/2026 fix: elemento filtrante TDF tem ciclo de 3 ANOS (36 meses), não 12.
  // Confirmado no catálogo American Filter 1000-5000 (todos meses:36) e descrição
  // oficial "Troca técnica do elemento filtrante. Ciclo de 3 anos."
  // Bug anterior marcava 82 clientes (compraram 2025-2026) como vencidos por engano.
  elemento:        { meses: 36, ticket: 890,  label: 'Elemento Filtrante (filtro entrada)' },
  bebedouro_refil: { meses: 6,  ticket: 280,  label: 'Refil de Bebedouro' },
  iron_free:       { meses: 24, ticket: 2200, label: 'Manutenção Iron Free' },
  scale_stop:      { meses: 36, ticket: 1500, label: 'Manutenção Scale Stop' },
  outros:          { meses: 12, ticket: 500,  label: 'Outros' },
};

// Mapeamento da categoria do ERP (planilha) → categoria do VIDA_UTIL do portal
const ERP_TO_VIDA = {
  purificador:    'refil',           // purificador = troca de refil
  bebedouro:      'bebedouro_refil',
  filtro_entrada: 'elemento',
  iron_free:      'iron_free',
  refil:          'refil',
  outros:         'outros',
};

// Detecta vida útil ESPECÍFICA por modelo do produto (filtro de entrada).
// 14/Mai/2026 — Paulo informou que modelos variam:
//   2 ANOS: Filtrali V1-V8, FE600, FE1000, FE3000
//   3 ANOS: American Filter 1000, modelos de fibra (em geral), Inox 2500-5000
//   Default (sem modelo claro) = 36 meses (conservador — melhor errar pra mais que pra menos)
function detectarVidaUtilElemento(produtoStr) {
  const p = (produtoStr || '').toLowerCase();
  // 2 ANOS — Filtrali V1-V8 e FE600/1000/3000
  if (/filtrali\s*v?\s*[1-8]\b/i.test(p)) return 24;
  if (/\bfe\s*(600|1000|3000)\b/i.test(p)) return 24;
  // 3 ANOS — American Filter 1000 + modelos de fibra (geral) + Inox grandes
  if (/american\s*filter|af\s*(1000|2000|2500|3500|5000)/i.test(p)) return 36;
  if (/fibra/i.test(p)) return 36;
  if (/inox\s*(2500|3500|5000)/i.test(p)) return 36;
  // Default conservador
  return 36;
}

// Detecta categoria de manutenção pelo nome do produto vendido
function categoriaManut(produtoStr) {
  const p = (produtoStr || '').toLowerCase();
  if (/iron\s*free|ironfree/.test(p)) return 'iron_free';
  if (/scale\s*stop|scalestop|abrandador/.test(p)) return 'scale_stop';
  if (/american\s*filter|filtro\s*de\s*entrada|inox|fibra|tanque/.test(p)) return 'elemento';
  if (/bebedouro|af\s*\d+|purificador.*industrial|resfriador/.test(p)) return 'bebedouro_refil';
  if (/refil|cartucho|carbon\s*block|elemento\s*filtrante/.test(p)) return 'refil';
  return 'outros';
}

// Categorização que prioriza Layout/Pipeline antes do produto.
// Bebedouro vende muito via Telemarketing/Fúnil Base, e produtos muitas vezes
// vêm como nomes que NÃO batem com regex (ex: 'EUROPA FOR PET'), por isso
// o Layout dá um sinal mais confiável.
function categoriaManutInteligente(deal) {
  const layoutName = (deal.Layout?.name || deal.Layout?.display_label || '').toString();
  const pipeName = (deal.Pipeline || '').toString();
  const produto = deal.produtosReais || deal.Produto_Vendido || '';
  const blob = produto + ' ' + (deal.Deal_Name || '');

  // 1. Iron Free / Scale Stop: o produto/nome quase sempre identifica
  if (/iron\s*free|ironfree/i.test(blob)) return 'iron_free';
  if (/scale\s*stop|scalestop|abrandador/i.test(blob)) return 'scale_stop';

  // 2. Sinais fortes do Telemarketing/Fúnil Base = bebedouro ou refil de bebedouro
  if (/telemarketing|fúnil\s*base|funil\s*base|bebedouro/i.test(layoutName + ' ' + pipeName)) {
    if (/refil/i.test(blob)) return 'bebedouro_refil'; // refil de bebedouro
    return 'bebedouro_refil';
  }

  // 3. Produto contém indicadores diretos
  if (/american\s*filter|filtro\s*de\s*entrada|\bfe\b\s*\d+|inox\s*\d+|fibra\s*\d+|tanque/i.test(blob)) return 'elemento';
  if (/bebedouro|resfriador|af\s*\d+|purificador.*industrial|europa\s*industrial/i.test(blob)) return 'bebedouro_refil';
  if (/refil|cartucho|carbon\s*block|elemento\s*filtrante|noblesse|da\s*vinci|europa\s*(fluir|for\s*pet|bliss|hf)/i.test(blob)) return 'refil';

  // 4. Pipeline 'água não tratada' geralmente é filtro de entrada
  if (/[aá]gua\s*n[aã]o\s*tratada|po[çc]o/i.test(pipeName)) return 'elemento';

  return 'outros';
}

// === ÍNDICE ERP DE MANUTENÇÃO (planilha do ERP) ===
const ERP_FILE = path.join(__dirname, 'data/erp-manutencao.json');
let _ERP_INDEX = null;     // chave → idErp
let _ERP_LISTA = null;     // [{idErp, ...}]
let _ERP_BY_ID = null;     // idErp → registro
function loadErpRaw() {
  if (_ERP_INDEX) return { index: _ERP_INDEX, lista: _ERP_LISTA, byId: _ERP_BY_ID };
  try {
    const raw = JSON.parse(require('fs').readFileSync(ERP_FILE, 'utf8'));
    _ERP_INDEX = raw.index || {};
    _ERP_LISTA = raw.lista || [];
    _ERP_BY_ID = {};
    for (const r of _ERP_LISTA) _ERP_BY_ID[r.idErp] = r;
    console.log(`[erp] carregado: ${Object.keys(_ERP_INDEX).length} chaves · ${_ERP_LISTA.length} clientes (gerado ${raw.generatedAt})`);
  } catch { _ERP_INDEX = {}; _ERP_LISTA = []; _ERP_BY_ID = {}; console.log('[erp] erp-manutencao.json não encontrado'); }
  return { index: _ERP_INDEX, lista: _ERP_LISTA, byId: _ERP_BY_ID };
}
function loadErpManutencao() { return loadErpRaw().index; }
function loadErpLista() { return loadErpRaw().lista; }

// Busca registro do ERP por telefone — gera múltiplas variações pra casar
function erpLookup(telefone) {
  if (!telefone) return null;
  const { index, byId } = loadErpRaw();
  const limpo = String(telefone).replace(/\D/g, '');
  if (limpo.length < 7) return null;
  const variations = [];
  if (limpo.length >= 8) variations.push(limpo.slice(-8));
  if (limpo.length >= 9) variations.push(limpo.slice(-9));
  if (limpo.length >= 10) variations.push(limpo.slice(-10));
  if (limpo.length >= 11) variations.push(limpo.slice(-11));
  if (limpo.length === 13 && limpo.startsWith('55')) {
    const semDdi = limpo.slice(2);
    variations.push(semDdi, semDdi.slice(-9), semDdi.slice(-8));
  }
  if (limpo.length >= 9) {
    const last9 = limpo.slice(-9);
    if (last9[0] === '9') variations.push(last9.slice(1));
  }
  if (limpo.length === 8 && /^[6789]/.test(limpo)) variations.push('9' + limpo);
  for (const v of variations) {
    const id = index[v];
    if (id && byId[id]) return byId[id];
  }
  return null;
}

