// === REGRA DE DESLOCAMENTO (admin) ===
// cepBase = TDF (12243-260, São José dos Campos)
// kmGratis: distância sem cobrar deslocamento
// bloco: tamanho do bloco em km (cobra precoBloco a cada bloco completo após kmGratis)
// linear: { ativo: true, precoPorKm: N } — alternativa: cobra R$/km direto
const REGRA_DESLOC_DEFAULT = {
  cepBase: '12243260',
  kmGratis: 50,
  bloco: 50,
  precoBloco: 100,
  linear: { ativo: false, precoPorKm: 2 },
};
function loadRegraDesloc() {
  const r = kvOrFile('manut-regra-desloc', null, null);
  return r || REGRA_DESLOC_DEFAULT;
}
function saveRegraDesloc(regra) { kvAndFile('manut-regra-desloc', null, regra); }

// === GEOCODING CEP → coordenadas (cache + AwesomeAPI + BrasilAPI fallback) ===
function loadGeoCache() { return kvOrFile('geo-cache', null, {}); }
function saveGeoCache(cache) { kvAndFile('geo-cache', null, cache); }

async function geocodeCep(cepRaw) {
  const cep = String(cepRaw || '').replace(/\D/g, '');
  if (cep.length !== 8) return null;
  const cache = loadGeoCache();
  const hit = cache[cep];
  if (hit && hit.lat && hit.lng) return hit;
  // 1ª tentativa: AwesomeAPI (retorna lat/lng direto)
  try {
    const r = await fetch(`https://cep.awesomeapi.com.br/json/${cep}`, { signal: AbortSignal.timeout(5000) });
    if (r.ok) {
      const j = await r.json();
      if (j.lat && j.lng) {
        const out = {
          cep, lat: parseFloat(j.lat), lng: parseFloat(j.lng),
          city: j.city || '', state: j.state || '', district: j.district || '',
          source: 'awesomeapi', fetchedAt: Date.now(),
        };
        cache[cep] = out;
        saveGeoCache(cache);
        return out;
      }
    }
  } catch(e) { console.warn('[geocode awesomeapi]', cep, e.message); }
  // 2ª tentativa: BrasilAPI v2 (alguns providers retornam coords)
  try {
    const r = await fetch(`https://brasilapi.com.br/api/cep/v2/${cep}`, { signal: AbortSignal.timeout(5000) });
    if (r.ok) {
      const j = await r.json();
      const lat = j.location?.coordinates?.latitude;
      const lng = j.location?.coordinates?.longitude;
      if (lat && lng) {
        const out = {
          cep, lat: parseFloat(lat), lng: parseFloat(lng),
          city: j.city || '', state: j.state || '', district: j.neighborhood || '',
          source: 'brasilapi', fetchedAt: Date.now(),
        };
        cache[cep] = out;
        saveGeoCache(cache);
        return out;
      }
      // Sem coords — guarda só city/state pra debug
      console.warn(`[geocode] CEP ${cep} sem coords (city: ${j.city})`);
    }
  } catch(e) { console.warn('[geocode brasilapi]', cep, e.message); }
  return null;
}

function haversineKm(lat1, lng1, lat2, lng2) {
  const R = 6371; // raio da Terra em km
  const toRad = x => x * Math.PI / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

// Aplica regra de deslocamento → retorna { valor, detalhe }
function calcDeslocamento(distKm, regra) {
  if (!regra) regra = REGRA_DESLOC_DEFAULT;
  const km = Math.max(0, distKm);
  if (km <= regra.kmGratis) return { valor: 0, detalhe: `Dentro de ${regra.kmGratis}km — sem cobrança` };
  const excesso = km - regra.kmGratis;
  if (regra.linear?.ativo) {
    const valor = Math.round(excesso * (regra.linear.precoPorKm || 0));
    return { valor, detalhe: `${excesso.toFixed(1)}km extra × R$ ${regra.linear.precoPorKm}/km = R$ ${valor}` };
  }
  // Por bloco: arredonda PRA CIMA o nº de blocos
  const nBlocos = Math.ceil(excesso / regra.bloco);
  const valor = nBlocos * regra.precoBloco;
  return { valor, detalhe: `${nBlocos} bloco(s) de ${regra.bloco}km × R$ ${regra.precoBloco} = R$ ${valor}` };
}

// Resolve preço de manutenção pra um deal: override por cliente > preço da categoria > default VIDA_UTIL
function precoManutDe(metaCli, categoria, precosGlobais) {
  if (metaCli?.precoManutencao && metaCli.precoManutencao > 0) return Number(metaCli.precoManutencao);
  if (precosGlobais?.[categoria] && precosGlobais[categoria] > 0) return Number(precosGlobais[categoria]);
  return Number(VIDA_UTIL[categoria]?.ticket || 0);
}

// Layouts ativos do Zoho (Deals) — preencher novos aqui se aparecerem
const ZOHO_LAYOUTS = [
  { id: '6311862000000091023', nome: 'Inside Sales' },
  { id: '6311862000216245031', nome: 'Layout Teste Bebedouro' },
  { id: '6311862000101582231', nome: 'Loja' },
  { id: '6311862000037730183', nome: 'Telemarketing' },
  { id: '6311862000222675473', nome: 'Tudo de Filtro' },
];

// Busca TODOS os deals Fechado Ganho dos últimos N meses, dividindo
// por Layout × trimestres pra furar o cap de 2000 do search API.
// Layouts ATIVOS (têm deals) — pula os vazios pra não desperdiçar query
const ZOHO_LAYOUTS_ATIVOS = ['6311862000000091023','6311862000101582231','6311862000037730183'];
async function buscarTodosFechadosGanho(meses, fields) {
  const today = todayBR();
  const dStart = new Date(); dStart.setMonth(dStart.getMonth() - meses);
  // Buckets de 6 meses (em vez de 3) — metade das queries, ainda fura cap de 2000 do Zoho
  const buckets = [];
  let cursor = new Date(dStart);
  while (cursor < new Date(today)) {
    const ini = cursor.toISOString().slice(0, 10);
    const next = new Date(cursor); next.setMonth(next.getMonth() + 6);
    const fim = (next > new Date(today) ? new Date(today) : next).toISOString().slice(0, 10);
    buckets.push({ ini, fim });
    cursor = next;
  }
  const allMap = {};
  const tarefas = [];
  // Só layouts ATIVOS (descobertos pelo diag — Layout Teste Bebedouro e Tudo de Filtro retornam 0)
  for (const Lid of ZOHO_LAYOUTS_ATIVOS) {
    const L = ZOHO_LAYOUTS.find(l => l.id === Lid) || { id:Lid, nome:Lid };
    for (const b of buckets) {
      const criteria = `((Layout:equals:${L.id})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${b.ini},${b.fim}))`;
      tarefas.push({ criteria, layout: L.nome });
    }
  }
  // 8 paralelos (era 4) — 18 queries × ~1s = ~3s no total
  for (let i = 0; i < tarefas.length; i += 8) {
    const chunk = tarefas.slice(i, i + 8);
    await Promise.all(chunk.map(async tk => {
      try {
        const deals = await zohoSearch(tk.criteria, fields, 200, 10);
        for (const d of deals) {
          if (!allMap[d.id]) allMap[d.id] = d;
        }
      } catch (e) {
        console.warn(`[buscarTodos ${tk.layout}]`, e.message);
      }
    }));
  }
  return Object.values(allMap);
}

// Calcula status de vencimento baseado em diasParaVencer
function statusVencimento(diasParaVencer) {
  if (diasParaVencer < -90) return 'vencido_90';
  if (diasParaVencer < -60) return 'vencido_60';
  if (diasParaVencer < -30) return 'vencido_30';
  if (diasParaVencer < 0)   return 'vencido';
  if (diasParaVencer <= 30) return 'vence_30';
  if (diasParaVencer <= 60) return 'vence_60';
  if (diasParaVencer <= 90) return 'vence_90';
  return 'futuro';
}

// ===================================================================
// CRM NOVO (Fase 0) — pipeline de deals ABERTOS, shell estilo Twenty
// Rota isolada /crm — NÃO afeta nenhuma tela existente.
// ===================================================================
const CRM_STAGE_ORDER = ['Primeiro Contato','Em Qualificação','Qualificado','Proposta','Proposta Fria','Proposta Quente','Em Atendimento','Negociação'];

async function buscarDealsAbertosCrm() {
  const fields = 'Deal_Name,Amount,Stage,Owner,Cidade,Produto_Vendido,Tier_Lead,Telefone_contato,Last_Activity_Time,Lead_Source';
  const since = new Date(); since.setDate(since.getDate() - 120);
  const sinceStr = since.toISOString().slice(0, 19) + '-03:00';
  const allMap = {};
  for (const Lid of ZOHO_LAYOUTS_ATIVOS) {
    const criteria = `((Layout:equals:${Lid})and(Modified_Time:greater_equal:${sinceStr}))`;
    try {
      const deals = await zohoSearch(criteria, fields, 200, 10);
      for (const d of deals) {
        const st = (d.Stage || '').toLowerCase();
        if (st.includes('fechado') || st.includes('closed') || st.includes('perdido') || st.includes('ganho')) continue;
        if (!allMap[d.id]) allMap[d.id] = d;
      }
    } catch (e) { console.warn('[crm-abertos]', e.message); }
  }
  return Object.values(allMap);
}

app.get('/crm', requireAuth, async (req, res) => {
  try {
    const u = USERS[req.session.user.username] || {};
    const isAdmin = u.role === 'admin';
    let deals = await buscarDealsAbertosCrm();
    if (!isAdmin && u.crmOwner) {
      deals = deals.filter(d => (d.Owner && d.Owner.name) === u.crmOwner);
    }
    let _inbox = {}; try { _inbox = loadWatiInbox() || {}; } catch (_) {}
    const _nowMs = Date.now();
    for (const d of deals) {
      const wi = _inbox[d.id];
      if (wi && wi.ultimaClienteTs && (!wi.ultimaNossaTs || wi.ultimaNossaTs < wi.ultimaClienteTs)) {
        d._msgNova = true;
        d._ultimaClienteTs = wi.ultimaClienteTs;
        d._msgEsperaMin = Math.round((_nowMs - wi.ultimaClienteTs) / 60000);
      }
    }
    const byStage = {};
    for (const d of deals) {
      const s = d.Stage || '—';
      (byStage[s] = byStage[s] || []).push(d);
    }
    // Kanban conversacional: cards com mensagem nova sobem pro topo (mais recente primeiro)
    for (const s in byStage) {
      byStage[s].sort((a, b) => {
        if (!!a._msgNova !== !!b._msgNova) return a._msgNova ? -1 : 1;
        if (a._msgNova && b._msgNova) return (b._ultimaClienteTs || 0) - (a._ultimaClienteTs || 0);
        return 0;
      });
    }
    const stages = Object.keys(byStage).sort((a, b) => {
      const ia = CRM_STAGE_ORDER.indexOf(a), ib = CRM_STAGE_ORDER.indexOf(b);
      return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
    });
    res.render('crm', {
      user: req.session.user, isAdmin, activePage: 'crm',
      byStage, stages, totalDeals: deals.length,
    });
  } catch (e) {
    console.error('[/crm]', e);
    res.status(500).send('Erro ao carregar CRM: ' + (e.message || e));
  }
});

// Ficha do Negócio (CRM novo) — dados do deal + timeline (notas do Zoho)
app.get('/crm/deal/:id', requireAuth, async (req, res) => {
  try {
    const id = req.params.id;
    const fields = 'Deal_Name,Amount,Stage,Owner,Pipeline,Closing_Date,Lead_Source,Contact_Name,Account_Name,Telefone_contato,Email,Cidade,Tipo_de_Agua,Produto_Vendido,Tier_Lead,Probability,Description,ultima_manuten_o,Data_da_Instala_o,Tag,Created_Time,Modified_Time,Last_Activity_Time';
    const deal = await zoho.getRecord('Deals', id, fields);
    if (!deal) return res.status(404).send('Negócio não encontrado');
    // Timeline: notas do Zoho deste deal
    let notes = [];
    try {
      const tk = await getZohoToken();
      const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${id}/Notes?fields=Note_Title,Note_Content,Created_Time,Created_By&per_page=100`, { headers: { Authorization: `Zoho-oauthtoken ${tk}` } });
      if (r.ok) { const j = await r.json(); notes = (j.data || []); }
    } catch (e) { console.warn('[/crm/deal notes]', e.message); }
    notes.sort((a, b) => new Date(b.Created_Time || 0) - new Date(a.Created_Time || 0));
    const qk = 'crm:qualif:' + id;
    const qualif = (_kvCache[qk] && typeof _kvCache[qk] === 'object') ? _kvCache[qk] : {};
    const tkey = 'crm:tasks:' + id;
    const tasks = (_kvCache[tkey] && Array.isArray(_kvCache[tkey])) ? _kvCache[tkey] : [];
    let proposta = null; try { proposta = (loadPropostas() || {})[id] || null; } catch (_) {}
    const ligkey = 'crm:ligacoes:' + id;
    const ligacoes = (_kvCache[ligkey] && Array.isArray(_kvCache[ligkey])) ? _kvCache[ligkey] : [];
    res.render('crm-ficha', { user: req.session.user, deal, notes, qualif, tasks, proposta, cadencias: getCadencias(), ligacoes, activePage: 'crm' });
  } catch (e) {
    console.error('[/crm/deal]', e);
    res.status(500).send('Erro ao carregar negócio: ' + (e.message || e));
  }
});

// Salva campo de qualificação (água/SDR) do CRM novo — armazenado no portal (KV/Postgres)
app.post('/crm/deal/:id/campo', requireAuth, async (req, res) => {
  try {
    const id = req.params.id;
    const k = (req.body && req.body.k || '').toString().trim();
    const v = (req.body && req.body.v != null) ? req.body.v.toString() : '';
    const ALLOWED = ['vazao','caixa','gravidade','voltagem','aplicacao','queixa','dor','urgencia','decisor','orcamento','compromisso','proximo_passo'];
    if (!ALLOWED.includes(k)) return res.status(400).json({ error: 'campo inválido' });
    const qk = 'crm:qualif:' + id;
    const cur = (_kvCache[qk] && typeof _kvCache[qk] === 'object') ? _kvCache[qk] : {};
    cur[k] = v;
    cur._by = req.session.user.name;
    cur._at = Date.now();
    await kvSet(qk, cur);
    res.json({ ok: true });
  } catch (e) {
    console.error('[/crm campo]', e);
    res.status(500).json({ error: e.message || String(e) });
  }
});

