app.post('/crm/cadencias', requireAuth, async (req, res) => {
  try {
    const b = req.body || {};
    const nome = (b.nome || '').toString().trim();
    if (!nome) return res.status(400).json({ error: 'nome obrigatório' });
    const passos = (Array.isArray(b.passos) ? b.passos : []).slice(0, 12)
      .map(p => ({ dia: parseInt(p.dia) || 0, tipo: (p.tipo || 'followup').toString(), titulo: (p.titulo || '').toString().slice(0, 200) }))
      .filter(p => p.titulo);
    if (!passos.length) return res.status(400).json({ error: 'adicione ao menos 1 passo' });
    let arr = Array.isArray(_kvCache['crm:cadencias']) ? _kvCache['crm:cadencias'].slice() : getCadencias().slice();
    const id = (b.id || '').toString();
    if (id) { const ix = arr.findIndex(c => c.id === id); if (ix >= 0) arr[ix] = { id, nome, passos }; else arr.push({ id, nome, passos }); }
    else arr.push({ id: 'c' + Date.now(), nome, passos });
    await kvSet('crm:cadencias', arr);
    res.json({ ok: true });
  } catch (e) { console.error('[/crm cadencias]', e); res.status(500).json({ error: e.message || String(e) }); }
});
app.post('/crm/cadencias/:cid/delete', requireAuth, async (req, res) => {
  try {
    let arr = Array.isArray(_kvCache['crm:cadencias']) ? _kvCache['crm:cadencias'] : getCadencias();
    arr = arr.filter(c => c.id !== req.params.cid);
    await kvSet('crm:cadencias', arr);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: e.message || String(e) }); }
});

