      acao: (b.acao || 'criar_tarefa_ligacao').toString(),
      acaoParam: (b.acaoParam || '').toString().slice(0, 200),
      alvo: (b.alvo || 'dono').toString(),
      ativo: b.ativo !== false,
      criadoPor: req.session.user.name, criadoEm: Date.now(),
