// Converte proposta antiga (texto) → padrão novo estruturado, via IA
async function converterPropostaIA(texto, instrucoes) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return { erro: 'ANTHROPIC_API_KEY não configurada' };
  try {
    const A = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
    const anthropic = new A({ apiKey });
    const prompt = 'Você converte propostas comerciais ANTIGAS da Tudo de Filtro (tratamento de água: purificadores, bebedouros, filtros de entrada, poço, refis) para o padrão NOVO estruturado. Leia o texto abaixo e devolva SOMENTE um JSON válido (sem texto fora do JSON):\n{"items":[{"produto":"<nome>","qtd":<numero>,"valor":<valor unitário em number, sem R$>}],"desconto":<number>,"validade":"<ex: 15 dias>","formaPagamento":"<>","prazoEntrega":"<>","observacoes":"<>"}\nRegras: valores como número puro (sem R$ nem pontos de milhar); qtd default 1; se um campo não existir, use "" ou 0.\n' + (instrucoes ? ('AJUSTES pedidos pelo vendedor: ' + instrucoes + '\n') : '') + '\nPROPOSTA ANTIGA:\n' + texto;
    const r = await anthropic.messages.create({ model: 'claude-sonnet-4-5-20250929', max_tokens: 1500, messages: [{ role: 'user', content: prompt }] });
    const txt = (r.content && r.content[0] && r.content[0].text) || '';
    const m = txt.match(/\{[\s\S]*\}/);
    return m ? JSON.parse(m[0]) : { erro: 'resposta da IA sem JSON' };
  } catch (e) { return { erro: e.message || String(e) }; }
}
