// Conversor pro GERADOR de propostas (aceita texto OU arquivo PDF/imagem via visão do Claude)
async function converterPropostaGeradorIA(texto, instrucoes, arquivo) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return { erro: 'ANTHROPIC_API_KEY não configurada' };
  try {
    const A = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
    const anthropic = new A({ apiKey });
    const instr = 'Converta a proposta comercial ANTIGA da Tudo de Filtro (tratamento de água) para os campos do gerador novo. ' + (arquivo ? 'A proposta está no documento/imagem anexado. ' : '') + 'Devolva SOMENTE um JSON válido (sem texto fora):\n{"cliente":"","local":"","produtoNome":"","produtoSub":"","features":["",""],"valorProduto":<number>,"frete":<number, 0 se não>,"instalacao":<number, 0 se não>,"instalacaoCond":"","parcelas":<int>,"descontoPix":<number>,"validade":"","prazo":""}\nRegras: números puros (sem R$ nem milhar); features = características do produto (uma por item); se faltar um campo, use "" ou 0.\n' + (instrucoes ? ('Ajustes pedidos pelo vendedor: ' + instrucoes + '\n') : '') + (texto ? ('\nTEXTO DA PROPOSTA:\n' + texto) : '');
    const content = [];
    if (arquivo && arquivo.data) {
      if (arquivo.mediaType === 'application/pdf') content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: arquivo.data } });
      else if (/^image\//.test(arquivo.mediaType || '')) content.push({ type: 'image', source: { type: 'base64', media_type: arquivo.mediaType, data: arquivo.data } });
    }
    content.push({ type: 'text', text: instr });
    const r = await anthropic.messages.create({ model: 'claude-sonnet-4-5-20250929', max_tokens: 1500, messages: [{ role: 'user', content }] });
    const txt = (r.content && r.content[0] && r.content[0].text) || '';
    const m = txt.match(/\{[\s\S]*\}/);
    return m ? JSON.parse(m[0]) : { erro: 'resposta da IA sem JSON' };
  } catch (e) { return { erro: e.message || String(e) }; }
}
