// Endpoint principal: dashboard + clientes
app.get('/manutencao/data', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin';
  // Closer pode ver, mas só sua carteira (filtrado via meta.operadora === username OU CRM Owner)
  const username = req.session.user.username;

  try {
    const nowBr = nowBR();
    const today = todayBR();
    const inicio36m = new Date(nowBr); inicio36m.setMonth(inicio36m.getMonth() - 36);
    const inicioStr = inicio36m.toISOString().slice(0, 10);

    // Cache de 30min — reduz a pressão no Zoho. Bucket por meia-hora.
    // CRÍTICO: chave inclui role+username+view porque a resposta JÁ está filtrada por user;
    // sem isso um closer pegava a view filtrada de outro closer (bug 04/Mai/2026).
    const viewParam = req.query.view || 'default';
    const userScope = isAdmin ? 'admin' : `closer:${username}:${viewParam}`;
    const cacheKey = `manut:${today}:${nowBr.getHours()}:${Math.floor(nowBr.getMinutes()/30)}:${userScope}`;
    const cached = cacheGet(cacheKey);
    if (cached && req.query.nocache !== '1') return res.json(cached);

    // Usa cache compartilhado (refresh background) — load instant em 99% dos casos
    const won = await getWonDealsCached();
    console.log(`[manutencao] won total: ${won.length} deals (cache ${Math.round((Date.now()-_wonCacheAt)/1000)}s)`);

    const meta = loadManutMeta();
    const nowMs = Date.now();

    // Pra cada venda, calcula próxima manutenção
    let clientes = won.map(d => {
      const v = parseFloat(d.Amount) || 0;
      const dataCompra = new Date(d.Closing_Date || today);
      let produto = d.produtosReais || d.Produto_Vendido || '';
      // Categorização inteligente: prioriza Layout/Pipeline, fallback no produto
      let cat = categoriaManutInteligente(d);
      // === ERP cross-reference ===
      // Se categoria caiu em 'outros' OU produto vazio, tenta cruzar com a planilha do ERP por telefone
      const erpRow = erpLookup(d.Telefone_contato);
      let fonteErp = false;
      if (erpRow && (cat === 'outros' || !produto)) {
        if (erpRow.produtos) produto = erpRow.produtos;
        const novaCat = ERP_TO_VIDA[erpRow.categoria] || cat;
        if (novaCat && novaCat !== 'outros') cat = novaCat;
        fonteErp = true;
      }
      const cfg = VIDA_UTIL[cat];
      // Se já houve manutenção registrada (storage manual ou campo Zoho), usa ela como base
      // pro cálculo da próxima troca, em vez da data original da compra
      const metaCli = meta[d.id] || {};
      const ultimaManut = metaCli.ultimaManutencao || d.ultima_manuten_o || null;
      const baseProxima = ultimaManut ? new Date(ultimaManut) : new Date(dataCompra);
      const proxima = new Date(baseProxima);
      // Vida útil: prioridade
      //   1. Override manual (metaCli.produtoId vinculado a catálogo)
      //   2. Detecção por modelo (elemento de filtro entrada — Filtrali=24m, American/fibra=36m)
      //   3. Default da categoria (cfg.meses)
      const mesesEfetivos = (() => {
        if (metaCli.produtoId) {
          const p = (loadCatProdutos() || []).find(x => x.id === metaCli.produtoId);
          if (p && p.vidaUtilMeses > 0) return p.vidaUtilMeses;
        }
        // Pra categoria 'elemento' (filtro de entrada), detecta vida útil específica por modelo
        if (cat === 'elemento') {
          return detectarVidaUtilElemento(produto);
        }
        return cfg.meses;
      })();
      proxima.setMonth(proxima.getMonth() + mesesEfetivos);
      const diasParaVencer = Math.round((proxima - nowMs) / 86400000);
      const status = statusVencimento(diasParaVencer);

      // Metadados manuais
      const m = meta[d.id] || {};

      // CEP fica como meta override ou ERP (Zoho Deals não tem campo padronizado)
      const cepZoho = String(m.cep || erpRow?.cep || '').replace(/\D/g, '').slice(0, 8);
      return {
        id: d.id,
        nome: d.Deal_Name || '?',
        telefone: d.Telefone_contato || '',
        cidade: d.Cidade || '',
        cep: cepZoho || '',
        dataCompra: d.Closing_Date,
        ownerOriginal: d.Owner?.name || '',
        valor: v,
        pipeline: d.Pipeline || '',
        produto,
        produtosArr: d.produtosArr || [],
        categoria: cat,
        categoriaLabel: cfg.label,
        fonteErp,
        erpInfo: erpRow ? { ultimaCompra:erpRow.ultimaCompra, totalGasto:erpRow.totalGasto, nCompras:erpRow.nCompras, prioridadeErp:erpRow.prioridade } : null,
        ticketEstimado: cfg.ticket,
        proximaTroca: proxima.toISOString().slice(0, 10),
        diasParaVencer,
        status,
        // Metadados manuais
        statusManual: m.statusManual || null,
        operadora: m.operadora || null,
        observacao: m.observacao || '',
        ultimoContato: m.ultimoContato || null,
        ultimoTemplate: m.ultimoTemplate || null,
        ultimoTemplateData: m.ultimoTemplateData || null,
        etapa: m.etapa || 'base_sem_contato',
        motivoPerda: m.motivoPerda || null,
        precoManutencaoOverride: m.precoManutencao || null,
        timeline: Array.isArray(m.timeline) ? m.timeline.slice(-15) : [],
        prioridade: ((diasParaVencer < -30 || cfg.ticket >= 1500) ? 'alta' : diasParaVencer < 30 ? 'media' : 'baixa'),
        crmLink: d.id ? `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}` : '',
        source: 'zoho',
        // Núbia + tags locais (visíveis no card)
        iaAtendendo: !!m.iaAtende,
        tagsLocais: Array.isArray(m.tagsLocais) ? m.tagsLocais : [],
        funilTipo: m.funilTipo || (d.Closing_Date ? 'manutencao' : 'generico'),
      };
    });

    // === ADICIONA CLIENTES DO ERP que NÃO têm deal Zoho correspondente ===
    // (sobe TODOS os 5931 clientes da planilha pro Closy)
    const erpLista = loadErpLista();
    if (erpLista.length) {
      // Set de telefones já presentes no Zoho (várias variações pra cruzar)
      const telsZoho = new Set();
      for (const c of clientes) {
        const limpo = String(c.telefone || '').replace(/\D/g, '');
        if (limpo.length >= 8) {
          telsZoho.add(limpo.slice(-8));
          telsZoho.add(limpo.slice(-9));
        }
      }
      const ERP_CAT_TO_VIDA = ERP_TO_VIDA;
      let addCount = 0;
      for (const reg of erpLista) {
        const tLimpo = String(reg.telefone || '').replace(/\D/g, '');
        if (tLimpo.length < 7) continue;
        const v8 = tLimpo.slice(-8), v9 = tLimpo.slice(-9);
        if (telsZoho.has(v8) || telsZoho.has(v9)) continue; // já está no Zoho
        const cat = ERP_CAT_TO_VIDA[reg.categoria] || 'outros';
        const cfg = VIDA_UTIL[cat];
        const ultimaCompra = reg.ultimaCompra ? new Date(reg.ultimaCompra) : null;
        const proxima = ultimaCompra ? new Date(ultimaCompra) : new Date();
        proxima.setMonth(proxima.getMonth() + (reg.ciclo || cfg.meses));
        const dias = Math.round((proxima.getTime() - nowMs) / 86400000);
        const m = meta[reg.idErp] || {};
        clientes.push({
          id: reg.idErp,
          nome: reg.nome || '?',
          telefone: tLimpo,
          cidade: reg.cidade || '',
          dataCompra: reg.ultimaCompra,
          ownerOriginal: '',
          valor: reg.totalGasto || 0,
          pipeline: '',
          produto: reg.produtos || '',
          produtosArr: [],
          categoria: cat,
          categoriaLabel: cfg.label,
          ticketEstimado: cfg.ticket,
          fonteErp: true,
          erpInfo: { ultimaCompra: reg.ultimaCompra, totalGasto: reg.totalGasto, nCompras: reg.nCompras, prioridadeErp: reg.prioridade },
          proximaTroca: proxima.toISOString().slice(0, 10),
          diasParaVencer: dias,
          status: statusVencimento(dias),
          statusManual: m.statusManual || null,
          operadora: m.operadora || null,
          observacao: m.observacao || '',
          ultimoContato: m.ultimoContato || null,
          etapa: m.etapa || 'base_sem_contato',
          motivoPerda: m.motivoPerda || null,
          timeline: Array.isArray(m.timeline) ? m.timeline.slice(-15) : [],
          prioridade: ((dias < -30 || cfg.ticket >= 1500) ? 'alta' : dias < 30 ? 'media' : 'baixa'),
          crmLink: '', // sem deal Zoho ainda
          source: 'erp',
          iaAtendendo: !!m.iaAtende,
          tagsLocais: Array.isArray(m.tagsLocais) ? m.tagsLocais : [],
          funilTipo: m.funilTipo || 'manutencao', // ERP tem compra histórica
        });
        addCount++;
      }
      if (addCount) console.log(`[manutencao] +${addCount} clientes ERP-only adicionados (total: ${clientes.length})`);
    }

    // Closer: default = só MINHA carteira (carrega rápido).
    // Pode opt-in pra ?view=todos ou ?view=orfaos via UI.
    // Admin: sempre vê tudo.
    let clientesView = clientes;
    let viewMode;
    // === MINHA CARTEIRA: 3 caminhos possíveis pra um cliente ser "meu" ===
    // 1. meta.operadora === username (atribuído via Closy)
    // 2. ownerOriginal === u.crmOwner (atribuído via Zoho CRM direto — caso Fabiana/Catia/Larissa 04/Mai/2026)
    // 3. ownerOriginal case-insensitive match (defensivo contra "Catia americo" vs "Catia Americo")
    const crmOwnerName = (u?.crmOwner || '').trim();
    const crmOwnerLower = crmOwnerName.toLowerCase();
    const ehMeuCliente = (c) => {
      if (c.operadora === username) return true;
      if (!crmOwnerName) return false;
      const owner = String(c.ownerOriginal || '').trim();
      if (owner === crmOwnerName) return true;
      if (owner.toLowerCase() === crmOwnerLower) return true;
      return false;
    };
    if (isAdmin) {
      viewMode = 'admin';
    } else if (req.query.view === 'todos') {
      // Closer pediu ver tudo — limita a 800 mais relevantes (vencidos + vence 60d) pra não travar
      const maisRelevantes = clientes
        .filter(c => c.diasParaVencer < 60)
        .sort((a,b) => a.diasParaVencer - b.diasParaVencer)
        .slice(0, 800);
      clientesView = maisRelevantes;
      viewMode = 'todos_top800';
    } else if (req.query.view === 'orfaos') {
      clientesView = clientes.filter(c => !c.operadora && !c.ownerOriginal && c.diasParaVencer < 60).slice(0, 500);
      viewMode = 'orfaos_top500';
    } else {
      // Default closer: só carteira (Closy operadora OU Zoho Owner)
      clientesView = clientes.filter(ehMeuCliente);
      viewMode = 'minha_carteira';
    }
    // Substitui pra agregação considerar só a carteira do closer
    const _todosClientes = clientes;
    clientes = clientesView;

    // Agrega cards
    const ag = {
      viewMode,
      total: clientes.length,
      totalBaseGeral: _todosClientes.length,
      vencidos:    clientes.filter(c => c.diasParaVencer < 0).length,
      vencendoMes: clientes.filter(c => c.diasParaVencer >= 0 && c.diasParaVencer <= 30).length,
      prox30:      clientes.filter(c => c.diasParaVencer >= 0 && c.diasParaVencer <= 30).length,
      prox60:      clientes.filter(c => c.diasParaVencer >= 31 && c.diasParaVencer <= 60).length,
      prox90:      clientes.filter(c => c.diasParaVencer >= 61 && c.diasParaVencer <= 90).length,
      semOperadora: clientes.filter(c => c.diasParaVencer <= 30 && !c.operadora).length,
      potencial:   clientes.filter(c => c.diasParaVencer >= -90 && c.diasParaVencer <= 90).reduce((s, c) => s + c.ticketEstimado, 0),
    };

    // Por categoria
    const porCategoria = {};
    for (const c of clientes) {
      if (!porCategoria[c.categoria]) porCategoria[c.categoria] = { count: 0, vencidos: 0, valor: 0, label: VIDA_UTIL[c.categoria].label };
      porCategoria[c.categoria].count++;
      if (c.diasParaVencer < 0) porCategoria[c.categoria].vencidos++;
      if (c.diasParaVencer >= -90 && c.diasParaVencer <= 90) porCategoria[c.categoria].valor += c.ticketEstimado;
    }

    // Por mês (próximos 12 meses + último 12)
    const porMes = {};
    for (const c of clientes) {
      const [y, m] = c.proximaTroca.split('-');
      const key = `${y}-${m}`;
      if (!porMes[key]) porMes[key] = { count: 0, valor: 0 };
      porMes[key].count++;
      porMes[key].valor += c.ticketEstimado;
    }

    const out = {
      stats: ag,
      porCategoria,
      porMes,
      clientes: clientes.sort((a, b) => a.diasParaVencer - b.diasParaVencer),
      operadoras: CLOSERS_LIST.map(c => ({ username: c.username, name: c.name, team: c.team })),
      generatedAt: new Date().toISOString(),
    };
    cacheSet(cacheKey, out, 30 * 60 * 1000); // 30 min
    res.json(out);
  } catch (err) {
    console.error('manutencao error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

