// Detecta automaticamente o funil pelo cliente
function detectarFunilTipo(cliente) {
  // Se foi salvo manualmente, respeita
  if (cliente?.funilTipo === 'manutencao' || cliente?.funilTipo === 'generico') return cliente.funilTipo;
  // Já tem data de compra (Closing_Date no Zoho ou ERP) → Manutenção
  if (cliente?.dataCompra || cliente?.fonteErp) return 'manutencao';
  return 'generico';
}

