// Stages padrão (fallback) — usados quando metadata do Pipeline não está disponível
const ZOHO_STAGES = [
  'Leads Novos', 'IA sem Contato', 'Etapa IA', 'Primeiro Contato',
  'Em Qualificação', 'Em Atendimento', 'Analise ou vazão', 'Qualificado',
  'Proposta', 'Proposta Quente', 'Proposta Fria',
  'Fechado Ganho', 'Fechado Perdido',
];

// Cache de stages por Pipeline → carregado dinamicamente do Zoho
let _ZOHO_STAGES_BY_PIPELINE = null;
let _ZOHO_STAGES_LOADED_AT = 0;
async function loadZohoStagesByPipeline() {
  if (_ZOHO_STAGES_BY_PIPELINE && (Date.now() - _ZOHO_STAGES_LOADED_AT) < 6 * 3600000) return _ZOHO_STAGES_BY_PIPELINE;
  const tk = await getZohoToken();
  if (!tk) return {};
  try {
    const out = {};
    // Pra cada Layout, busca pipelines e stages
    for (const L of ZOHO_LAYOUTS) {
      const r = await fetch(`https://www.zohoapis.com/crm/v6/settings/pipeline?layout_id=${L.id}`, {
        headers: { Authorization: `Zoho-oauthtoken ${tk}` },
      });
      if (!r.ok) continue;
      const j = await r.json().catch(() => ({}));
      const pipelines = j.pipeline || j.data || [];
      for (const p of pipelines) {
        const pipeName = p.actual_name || p.api_name || p.display_value;
        if (!pipeName) continue;
        const stages = (p.maps || p.stages || []).map(s => s.actual_name || s.display_value || s.name).filter(Boolean);
        if (stages.length) out[pipeName] = stages;
      }
    }
    _ZOHO_STAGES_BY_PIPELINE = out;
    _ZOHO_STAGES_LOADED_AT = Date.now();
    console.log(`[zoho-stages] carregados ${Object.keys(out).length} pipelines`);
    return out;
  } catch(e) { console.warn('[zoho-stages]', e.message); return {}; }
}

// Versão rica: retorna metadata completo dos funis Zoho
// [{layoutId, layoutName, pipelineId, pipelineName, isDefault, stages: [{id, name, order, category, probability}]}]
let _ZOHO_FUNIS = null;
let _ZOHO_FUNIS_LOADED_AT = 0;
async function loadZohoFunis() {
  if (_ZOHO_FUNIS && (Date.now() - _ZOHO_FUNIS_LOADED_AT) < 6 * 3600000) return _ZOHO_FUNIS;
  const tk = await getZohoToken();
  if (!tk) return [];
  try {
    const out = [];
    for (const L of ZOHO_LAYOUTS) {
      const r = await fetch(`https://www.zohoapis.com/crm/v6/settings/pipeline?layout_id=${L.id}`, {
        headers: { Authorization: `Zoho-oauthtoken ${tk}` },
      });
      if (!r.ok) continue;
      const j = await r.json().catch(() => ({}));
      const pipelines = j.pipeline || j.data || [];
      for (const p of pipelines) {
        const pipeName = p.actual_name || p.api_name || p.display_value;
        if (!pipeName) continue;
        const stagesRaw = p.maps || p.stages || [];
        const stages = stagesRaw.map((s, idx) => ({
          id: s.id || null,
          name: s.actual_name || s.display_value || s.name,
          order: idx,
          category: s.forecast_category?.name || s.forecast_type || 'open',
          probability: typeof s.probability === 'number' ? s.probability : null,
        })).filter(s => s.name);
        if (!stages.length) continue;
        out.push({
          layoutId: L.id,
          layoutName: L.nome,
          pipelineId: p.id || null,
          pipelineName: pipeName,
          isDefault: !!p.default,
          stages,
        });
      }
    }
    _ZOHO_FUNIS = out;
    _ZOHO_FUNIS_LOADED_AT = Date.now();
    console.log(`[zoho-funis] carregados ${out.length} funis (${out.map(f=>f.pipelineName).join(', ')})`);
    return out;
  } catch(e) { console.warn('[zoho-funis]', e.message); return []; }
}

