// === CLOSY: FUNIS ESPELHADOS DO ZOHO (Fase 1) ===
// Lista todos os pipelines+stages, agrupados por Layout, prontos pra UI.
// Acrescenta funil sintético "Todos" que agrega stages comuns.
app.get('/closy/funis', requireAuth, async (req, res) => {
  try {
    const funis = await loadZohoFunis();
    // Funil agregado "Todos" — usa o conjunto único de stages que aparecem em qualquer funil
    const stagesAll = new Map();
    for (const f of funis) for (const s of f.stages) {
      if (!stagesAll.has(s.name)) stagesAll.set(s.name, { ...s, order: stagesAll.size });
    }
    const todos = {
      layoutId: '_all', layoutName: 'Todos', pipelineId: '_all', pipelineName: 'Todos os Funis',
      isDefault: false, isAggregate: true,
      stages: Array.from(stagesAll.values()),
    };
    res.json({ funis: [todos, ...funis] });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// === CLOSY: DEALS ATIVOS POR FUNIL ===
// Filtra deals do Zoho por Layout + Pipeline + (Stage). Retorna campos-chave do card.
// Query: ?layout=<id>&pipeline=<name>&stages=Stage1,Stage2&owner=<crmOwner>&tier=Diamante
app.get('/closy/deals', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const isAdmin = u.role === 'admin' || isGestor(u);
  const { layout, pipeline, stages, owner, tier } = req.query;
  try {
    const stagesAtivos = (stages ? stages.split(',') : ['Leads Novos','IA sem Contato','Etapa IA','Primeiro Contato','Em Qualificação','Qualificado','Proposta','Proposta Quente','Proposta Fria','Em Atendimento'])
      .map(s => s.trim()).filter(Boolean);
    const parts = [`(Stage:in:${stagesAtivos.join(',')})`];
    if (pipeline && pipeline !== '_all' && pipeline !== 'Todos os Funis') parts.push(`(Pipeline:equals:${pipeline})`);
    if (owner) parts.push(`(Owner:equals:${owner})`);
    else if (!isAdmin) parts.push(`(Owner:equals:${u.crmOwner})`);
    if (tier) parts.push(`(Tier_Lead:equals:${tier})`);
    const criteria = parts.length === 1 ? parts[0] : '(' + parts.join('and') + ')';
    const fields = 'Deal_Name,Stage,Pipeline,Layout,Tier_Lead,Amount,Owner,Telefone_contato,Cidade,Lead_Source,Tag,Produto_Vendido,Closing_Date,Last_Activity_Time,Created_Time,Modified_Time';
    const deals = await zohoSearch(criteria, fields, 200);
    // Filtra layout no client (Zoho search não filtra por Layout id; checa Layout.id no resultado)
    const filtered = (layout && layout !== '_all') ? deals.filter(d => d.Layout?.id === layout) : deals;
    const meta = loadManutMeta();
    const thresholds = loadStageThresholds();
    const catalogo = loadCatProdutos() || [];
    res.json({
      total: filtered.length,
      deals: filtered.map(d => {
        const m = meta[d.id] || {};
        const daysInStage = calcDaysInStage(d, m);
        const threshold = thresholds[d.Stage] || null;
        const stuck = daysInStage !== null && threshold !== null && daysInStage > threshold;
        const produtoVinculado = m.produtoId ? catalogo.find(x => x.id === m.produtoId) : null;
        return {
          id: d.id,
          nome: d.Deal_Name || '?',
          stage: d.Stage || '',
          pipeline: d.Pipeline || '',
          layout: d.Layout?.name || d.Layout?.display_label || '',
          layoutId: d.Layout?.id || '',
          tier: d.Tier_Lead || '',
          amount: parseFloat(d.Amount) || 0,
          owner: d.Owner?.name || '',
          ownerId: d.Owner?.id || '',
          phone: d.Telefone_contato || '',
          cidade: d.Cidade || '',
          leadSource: d.Lead_Source || '',
          tags: (d.Tag || []).map(t => t.name || t),
          produto: d.Produto_Vendido || '',
          produtoVinculadoId: produtoVinculado?.id || null,
          produtoVinculadoNome: produtoVinculado?.nome || null,
          produtoVinculadoVidaUtil: produtoVinculado?.vidaUtilMeses || null,
          closingDate: d.Closing_Date || null,
          lastActivity: d.Last_Activity_Time || null,
          createdAt: d.Created_Time || null,
          modifiedAt: d.Modified_Time || null,
          daysInStage,
          stageThreshold: threshold,
          stuck,
        };
      }),
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

