// Lista LEADS de uma categoria + bucket específico do forecast (drill-down)
// Query: ?bucket=2026-05 (ou 'vencidos') & cat=bebedouro_refil
app.get('/manutencao/forecast-leads', requireAuth, async (req, res) => {
  try {
    const { bucket, cat } = req.query;
    if (!bucket || !cat) return res.status(400).json({ error: 'bucket e cat obrigatórios' });
    if (!VIDA_UTIL[cat]) return res.status(400).json({ error: 'categoria inválida' });
    const u = USERS[req.session.user.username];
    const isAdminVisao = u?.role === 'admin' || isGestor(u);
    const username = req.session.user.username;
    const won = await getWonDealsCached();
    const meta = loadManutMeta();
    const precos = loadPrecosManut();
    const today = todayBR();
    const startMonth = new Date(today); startMonth.setDate(1); startMonth.setHours(0,0,0,0);
    let bucketStart = null, bucketEnd = null;
    if (bucket === 'vencidos') {
      bucketStart = 0; bucketEnd = startMonth.getTime();
    } else {
      const [yr, mo] = bucket.split('-').map(Number);
      if (!yr || !mo) return res.status(400).json({ error: 'bucket inválido (use YYYY-MM)' });
      bucketStart = new Date(yr, mo - 1, 1).getTime();
      bucketEnd = new Date(yr, mo, 1).getTime();
    }
    const leads = [];
    const catalogo = loadCatProdutos() || [];
    for (const d of won) {
      const dCat = categoriaManutInteligente(d);
      if (dCat !== cat) continue;
      const cfg = VIDA_UTIL[dCat]; if (!cfg) continue;
      const metaCli = meta[d.id] || {};
      if (!isAdminVisao && metaCli.operadora && metaCli.operadora !== username) continue;
      const dataCompra = new Date(d.Closing_Date || today);
      const ultima = metaCli.ultimaManutencao || d.ultima_manuten_o;
      const base = ultima ? new Date(ultima) : dataCompra;
      // Vida útil: produto vinculado > default da categoria
      const prodVinculado = metaCli.produtoId ? catalogo.find(x => x.id === metaCli.produtoId) : null;
      const mesesUso = (prodVinculado?.vidaUtilMeses > 0) ? prodVinculado.vidaUtilMeses : cfg.meses;
      const proxima = new Date(base); proxima.setMonth(proxima.getMonth() + mesesUso);
      const proxMs = proxima.getTime();
      if (proxMs < bucketStart || proxMs >= bucketEnd) continue;
      const preco = precoManutDe(metaCli, dCat, precos);
      leads.push({
        id: d.id,
        nome: d.Deal_Name || '?',
        telefone: d.Telefone_contato || '',
        cidade: d.Cidade || '',
        produto: d.Produto_Vendido || '',
        amount: parseFloat(d.Amount) || 0,
        owner: d.Owner?.name || '',
        operadora: metaCli.operadora || null,
        proximaTroca: proxima.toISOString().slice(0,10),
        diasParaVencer: Math.round((proxMs - Date.now()) / 86400000),
        preco,
        ultimaManutencao: ultima || null,
        crmLink: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}`,
      });
    }
    leads.sort((a,b) => a.diasParaVencer - b.diasParaVencer);
    res.json({
      bucket, cat, label: VIDA_UTIL[cat].label,
      total: leads.length,
      valorTotal: leads.reduce((s,l) => s + l.preco, 0),
      leads,
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// Ação em massa em deals: aceita action='nubia'|'etapa'|'owner'|'marcar_contatado'
app.post('/manutencao/forecast-leads/acao-massa', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const { dealIds, action, payload } = req.body || {};
  if (!Array.isArray(dealIds) || !dealIds.length) return res.status(400).json({ error: 'dealIds obrigatório' });
  if (!action) return res.status(400).json({ error: 'action obrigatório' });
  const lista = dealIds.slice(0, 100);
  const meta = loadManutMeta();
  let ok = 0;
  if (action === 'nubia') {
    for (const did of lista) {
      if (!meta[did]) meta[did] = {};
      addTimelineEvent(meta, did, {
        tipo:'nubia-disparada',
        label:`🤖 Núbia disparada via Forecast (${payload?.contexto||'manutenção'})`,
        by: u?.name || req.session.user.username,
      });
      ok++;
    }
  } else if (action === 'etapa') {
    const etapa = payload?.etapa;
    if (!etapa) return res.status(400).json({ error: 'payload.etapa obrigatório' });
    for (const did of lista) {
      if (!meta[did]) meta[did] = {};
      meta[did].etapa = etapa;
      meta[did].etapaUpdatedAt = new Date().toISOString();
      addTimelineEvent(meta, did, { tipo:'etapa', label:`Etapa: ${etapa} (ação em massa)`, by: u?.name });
      ok++;
    }
  } else if (action === 'owner') {
    const operadora = payload?.operadora;
    if (!operadora) return res.status(400).json({ error: 'payload.operadora obrigatório' });
    for (const did of lista) {
      if (!meta[did]) meta[did] = {};
      meta[did].operadora = operadora;
      addTimelineEvent(meta, did, { tipo:'operadora', label:`Operadora: ${operadora} (ação em massa)`, by: u?.name });
      ok++;
    }
  } else if (action === 'marcar_contatado') {
    for (const did of lista) {
      if (!meta[did]) meta[did] = {};
      meta[did].ultimoContato = new Date().toISOString().slice(0,10);
      addTimelineEvent(meta, did, { tipo:'contato', label:`📞 Contato registrado (ação em massa)`, by: u?.name });
      ok++;
    }
  } else {
    return res.status(400).json({ error: 'action inválida (use: nubia, etapa, owner, marcar_contatado)' });
  }
  saveManutMeta(meta);
  res.json({ ok: true, total: lista.length, sucesso: ok });
});

// === FORECAST DE FATURAMENTO DE MANUTENÇÃO ===
// Agrupa clientes Fechado Ganho por (mês, categoria) baseado em quando próxima manutenção vence.
// Query: ?meses=6 (default 6 meses olhando pra frente)
app.get('/manutencao/forecast', requireAuth, async (req, res) => {
  try {
    const mesesHorizonte = Math.max(1, Math.min(24, parseInt(req.query.meses, 10) || 6));
    const u = USERS[req.session.user.username];
    const isAdminVisao = u?.role === 'admin' || isGestor(u);
    const username = req.session.user.username;

    const won = await getWonDealsCached();
    const meta = loadManutMeta();
    const precos = loadPrecosManut();
    const metas = loadMetasManut();
    const today = todayBR();
    const nowMs = Date.now();
    const startMonth = new Date(today); startMonth.setDate(1); startMonth.setHours(0,0,0,0);
    // Buckets: mes corrente + N-1 próximos
    const buckets = [];
    for (let i = 0; i < mesesHorizonte; i++) {
      const d = new Date(startMonth); d.setMonth(d.getMonth() + i);
      buckets.push({
        ymd: `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,
        label: d.toLocaleDateString('pt-BR', { month:'long', year:'numeric', timeZone:'America/Sao_Paulo' }),
        ano: d.getFullYear(),
        mes: d.getMonth() + 1,
        startMs: d.getTime(),
        endMs: new Date(d.getFullYear(), d.getMonth() + 1, 1).getTime(),
        categorias: {},
        totalValor: 0,
        totalCount: 0,
      });
    }

    // Bucket extra: VENCIDOS (próxima manutenção já passou)
    const vencidos = { ymd: 'vencidos', label: 'Vencidos (atrasados)', categorias: {}, totalValor: 0, totalCount: 0 };

    const catalogoForecast = loadCatProdutos() || [];
    for (const d of won) {
      const cat = categoriaManutInteligente(d);
      const cfg = VIDA_UTIL[cat]; if (!cfg) continue;
      const metaCli = meta[d.id] || {};
      // Carteira: closer só vê os deles
      if (!isAdminVisao && metaCli.operadora && metaCli.operadora !== username) continue;
      const dataCompra = new Date(d.Closing_Date || today);
      const ultima = metaCli.ultimaManutencao || d.ultima_manuten_o;
      const base = ultima ? new Date(ultima) : dataCompra;
      // Vida útil: produto vinculado > default da categoria
      const prodVinc = metaCli.produtoId ? catalogoForecast.find(x => x.id === metaCli.produtoId) : null;
      const mesesUso = (prodVinc?.vidaUtilMeses > 0) ? prodVinc.vidaUtilMeses : cfg.meses;
      const proxima = new Date(base); proxima.setMonth(proxima.getMonth() + mesesUso);
      const proxMs = proxima.getTime();
      const preco = precoManutDe(metaCli, cat, precos);
      if (preco <= 0) continue;
      // Onde cai
      let alvo = null;
      if (proxMs < startMonth.getTime()) {
        alvo = vencidos;
      } else {
        alvo = buckets.find(b => proxMs >= b.startMs && proxMs < b.endMs);
      }
      if (!alvo) continue; // fora do horizonte (futuro distante)
      if (!alvo.categorias[cat]) alvo.categorias[cat] = { count: 0, valor: 0, label: cfg.label };
      alvo.categorias[cat].count++;
      alvo.categorias[cat].valor += preco;
      alvo.totalCount++;
      alvo.totalValor += preco;
    }

    // Anexa meta + atingimento por bucket × categoria
    for (const b of buckets) {
      for (const [cat, v] of Object.entries(b.categorias)) {
        const metaMensal = metas[cat]?.metaMensal || 0;
        v.metaMensal = metaMensal;
        v.atingimentoPct = metaMensal > 0 ? Math.round((v.valor / metaMensal) * 100) : null;
        v.responsaveis = metas[cat]?.responsaveis || [];
        v.cor = metas[cat]?.cor || '#888';
      }
    }

    res.json({
      mesesHorizonte,
      hoje: today,
      vencidos,
      buckets,
      metas,
      precos,
      totais: {
        valorTotal: buckets.reduce((s,b) => s + b.totalValor, 0),
        countTotal: buckets.reduce((s,b) => s + b.totalCount, 0),
        valorVencidos: vencidos.totalValor,
        countVencidos: vencidos.totalCount,
      },
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

