// Importa produtos via CSV (admin only)
// Formato: nome,categoria,precoManutencao,vidaUtilMeses,descricao
// (1ª linha = header; categoria = refil|elemento|bebedouro_refil|iron_free|scale_stop|outros)
app.post('/closy/produtos/importar-csv', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const { csv, modo } = req.body || {}; // modo: 'append' (default) | 'replace'
  if (!csv || typeof csv !== 'string') return res.status(400).json({ error: 'csv obrigatório' });
  const linhas = csv.split(/\r?\n/).filter(l => l.trim());
  if (linhas.length < 2) return res.status(400).json({ error: 'CSV precisa de pelo menos header + 1 linha' });
  // Parser ingênuo (assume CSV bem formado, sem aspas com vírgula interna)
  const header = linhas[0].toLowerCase().split(',').map(h => h.trim());
  const idx = {
    nome: header.indexOf('nome'),
    categoria: header.indexOf('categoria'),
    preco: header.findIndex(h => /preco|preço/.test(h)),
    vida: header.findIndex(h => /vida|meses/.test(h)),
    desc: header.findIndex(h => /desc|descrição|obs/.test(h)),
  };
  if (idx.nome < 0) return res.status(400).json({ error: 'CSV precisa coluna "nome"' });
  const novos = [];
  const erros = [];
  for (let i = 1; i < linhas.length; i++) {
    const cols = linhas[i].split(',').map(c => c.trim());
    const nome = cols[idx.nome];
    if (!nome) continue;
    const categoria = idx.categoria >= 0 ? cols[idx.categoria] : 'outros';
    if (!VIDA_UTIL[categoria]) {
      erros.push(`linha ${i+1}: categoria inválida "${categoria}" (use ${Object.keys(VIDA_UTIL).join('|')})`);
      continue;
    }
    novos.push({
      id: 'p_csv_' + Date.now() + '_' + i,
      nome: nome.slice(0, 120),
      categoria,
      precoManutencao: idx.preco >= 0 ? Number(cols[idx.preco]) || 0 : 0,
      vidaUtilMeses: idx.vida >= 0 ? Number(cols[idx.vida]) || VIDA_UTIL[categoria].meses : VIDA_UTIL[categoria].meses,
      descricao: idx.desc >= 0 ? (cols[idx.desc] || '').slice(0, 500) : '',
      ativo: true,
      updatedAt: new Date().toISOString(),
      updatedBy: u.name + ' (CSV)',
    });
  }
  const atual = modo === 'replace' ? [] : loadCatProdutos();
  saveCatProdutos([...atual, ...novos]);
  res.json({ ok: true, importados: novos.length, erros, totalAgora: atual.length + novos.length });
});

