// === CALCULADORA: CEP destino + (opcional) produtoId → distância + deslocamento + total ===
app.get('/manutencao/calcular-preco', requireAuth, async (req, res) => {
  const cepDestino = (req.query.cep || '').replace(/\D/g, '');
  const produtoId = req.query.produtoId || '';
  if (!cepDestino) return res.status(400).json({ error: 'cep obrigatório' });
  const regra = loadRegraDesloc();
  try {
    const [origem, destino] = await Promise.all([
      geocodeCep(regra.cepBase),
      geocodeCep(cepDestino),
    ]);
    if (!origem) return res.status(500).json({ error: 'falha geocoding CEP base ' + regra.cepBase });
    if (!destino) return res.status(404).json({ error: 'CEP destino não encontrado: ' + cepDestino });
    const distKm = haversineKm(origem.lat, origem.lng, destino.lat, destino.lng);
    const desloc = calcDeslocamento(distKm, regra);
    let produto = null, precoProduto = 0;
    if (produtoId) {
      produto = loadCatProdutos().find(p => p.id === produtoId);
      if (produto) precoProduto = Number(produto.precoManutencao) || 0;
    }
    res.json({
      origem: { cep: origem.cep, city: origem.city, state: origem.state, lat: origem.lat, lng: origem.lng },
      destino: { cep: destino.cep, city: destino.city, state: destino.state, district: destino.district, lat: destino.lat, lng: destino.lng },
      distanciaKm: Math.round(distKm * 10) / 10,
      deslocamento: desloc,
      produto: produto ? { id: produto.id, nome: produto.nome, categoria: produto.categoria, precoManutencao: precoProduto } : null,
      total: precoProduto + desloc.valor,
      regra: { kmGratis: regra.kmGratis, bloco: regra.bloco, precoBloco: regra.precoBloco, linear: regra.linear },
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

