// === FASE 3: ENDPOINT GENÉRICO DE UPDATE DE CAMPO (base pra Fases 3 + 6) ===
// Whitelist de campos editáveis pelo Closy (segurança — não mexer em campos sensíveis)
const CLOSY_EDITABLE_FIELDS = {
  // Zoho fields (sobem direto pro Zoho via PUT /Deals/:id)
  Stage:            { tipo: 'enum', target: 'zoho', label: 'Stage' },
  Amount:           { tipo: 'number', target: 'zoho', label: 'Valor (R$)' },
  Tier_Lead:        { tipo: 'enum', target: 'zoho', label: 'Tier', options: ['Diamante','Ouro','Prata','Bronze'] },
  Cidade:           { tipo: 'text', target: 'zoho', label: 'Cidade' },
  Lead_Source:      { tipo: 'text', target: 'zoho', label: 'Origem' },
  Produto_Vendido:  { tipo: 'text', target: 'zoho', label: 'Produto' },
  Closing_Date:     { tipo: 'date', target: 'zoho', label: 'Data fechamento' },
  Telefone_contato: { tipo: 'text', target: 'zoho', label: 'Telefone' },
  Email:            { tipo: 'email', target: 'zoho', label: 'Email' },
  Description:      { tipo: 'textarea', target: 'zoho', label: 'Descrição' },
  // Campos só do Closy (vivem em manut-meta)
  observacao:       { tipo: 'textarea', target: 'closy', label: 'Observação interna' },
  precoManutencao:  { tipo: 'number', target: 'closy', label: 'Preço manutenção (override)' },
  cep:              { tipo: 'text', target: 'closy', label: 'CEP' },
  ultimaManutencao: { tipo: 'date', target: 'closy', label: 'Última manutenção' },
  produtoId:        { tipo: 'enum', target: 'closy', label: 'Produto vinculado (catálogo)', dynamicOptions: 'produtos' },
};

// PUT/POST — campo individual (Zoho ou Closy local). Usado por Fase 3 (UI inline)
// e Fase 6 (API pública). Whitelist em CLOSY_EDITABLE_FIELDS.
app.post('/closy/deals/:dealId/field/:fieldName', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const { dealId, fieldName } = req.params;
  const { value } = req.body || {};
  const cfg = CLOSY_EDITABLE_FIELDS[fieldName];
  if (!cfg) return res.status(400).json({ error: `campo não editável: ${fieldName}. Permitidos: ${Object.keys(CLOSY_EDITABLE_FIELDS).join(', ')}` });
  if (String(dealId).startsWith('erp:') || String(dealId).startsWith('wati:')) {
    return res.status(400).json({ error: 'lead ainda não tem deal Zoho real — cadastre primeiro' });
  }
  // Closy-local: persistir em manut-meta
  if (cfg.target === 'closy') {
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    if (value === null || value === '' || (cfg.tipo === 'number' && Number(value) === 0)) {
      delete meta[dealId][fieldName];
    } else {
      meta[dealId][fieldName] = cfg.tipo === 'number' ? Number(value) : value;
    }
    addTimelineEvent(meta, dealId, { tipo:'campo', label:`✏️ ${cfg.label}: ${value || '(removido)'}`, by: u?.name || 'Sistema' });
    saveManutMeta(meta);
    return res.json({ ok: true, dealId, fieldName, value: meta[dealId][fieldName] || null, target: 'closy' });
  }
  // Zoho: PUT /Deals/:id
  const tk = await getZohoToken();
  if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
  try {
    let payloadValue = value;
    if (cfg.tipo === 'number') payloadValue = Number(value) || 0;
    if (cfg.tipo === 'date' && value) payloadValue = String(value).slice(0, 10);
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}`, {
      method: 'PUT',
      headers: { Authorization: `Zoho-oauthtoken ${tk}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: [{ [fieldName]: payloadValue }] }),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    if (result?.code !== 'SUCCESS') {
      console.warn('[update-field]', fieldName, 'falha:', result?.message);
      return res.status(400).json({ error: result?.message || 'Zoho rejeitou', details: result });
    }
    // Loga timeline localmente
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    addTimelineEvent(meta, dealId, { tipo:'campo-zoho', label:`📝 ${cfg.label}: ${payloadValue}`, by: u?.name || 'Sistema' });
    // Sales #1: rastreia Stage history pra calcular Days in Stage (server-side)
    if (fieldName === 'Stage') {
      if (!Array.isArray(meta[dealId].stageHistory)) meta[dealId].stageHistory = [];
      meta[dealId].stageHistory.push({ stage: payloadValue, ts: Date.now() });
      // Mantém só últimas 10 transições
      if (meta[dealId].stageHistory.length > 10) meta[dealId].stageHistory = meta[dealId].stageHistory.slice(-10);
      meta[dealId].stageZohoUpdatedAt = new Date().toISOString();
    }
    saveManutMeta(meta);
    res.json({ ok: true, dealId, fieldName, value: payloadValue, target: 'zoho' });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// === SALES #1: STAGE THRESHOLDS (admin) — quando deal está "travado" num stage ===
// Default: dias máximos esperados em cada stage. Acima disso, badge vermelho.
const STAGE_THRESHOLD_DEFAULT = {
  'Leads Novos': 1, 'IA sem Contato': 2, 'Etapa IA': 3,
  'Primeiro Contato': 3, 'Em Qualificação': 5, 'Analise ou vazão': 5,
  'Qualificado': 7, 'Em Atendimento': 7,
  'Proposta': 7, 'Proposta Quente': 5, 'Proposta Fria': 14,
};
function loadStageThresholds() {
  const saved = kvOrFile('closy-stage-thresholds', null, null);
  return saved || STAGE_THRESHOLD_DEFAULT;
}
function saveStageThresholds(t) { kvAndFile('closy-stage-thresholds', null, t); }

app.get('/closy/stage-thresholds', requireAuth, (req, res) => {
  res.json({ thresholds: loadStageThresholds(), default: STAGE_THRESHOLD_DEFAULT });
});

app.post('/closy/stage-thresholds', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const { thresholds } = req.body || {};
  if (!thresholds || typeof thresholds !== 'object') return res.status(400).json({ error: 'thresholds obrigatório' });
  const limpo = {};
  for (const [stage, dias] of Object.entries(thresholds)) {
    const n = Number(dias);
    if (!isNaN(n) && n > 0) limpo[stage] = n;
  }
  saveStageThresholds(limpo);
  res.json({ ok: true, thresholds: limpo });
});

// === SALES #3: FORECAST COMMIT — vendedor classifica deals da semana ===
// Storage: { 'username:YYYY-WW': [{ dealId, classificacao, evidencia1, evidencia2, ts, statusFinal }] }
function loadCommitForecasts() { return kvOrFile('closy-forecast-commits', null, {}); }
function saveCommitForecasts(d) { kvAndFile('closy-forecast-commits', null, d); }

function _semanaKey(date) {
  const d = new Date(date);
  d.setHours(0,0,0,0);
  // Algoritmo ISO week (mais simples: yearweek de domingo)
  const yr = d.getFullYear();
  const start = new Date(yr, 0, 1);
  const wk = Math.ceil(((d - start) / 86400000 + start.getDay() + 1) / 7);
  return `${yr}-W${String(wk).padStart(2,'0')}`;
}

app.get('/cockpit/commit-semana', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const username = req.session.user.username;
  const semana = req.query.semana || _semanaKey(new Date());
  const all = loadCommitForecasts();
  const commits = all[`${username}:${semana}`] || [];
  res.json({ username, semana, commits });
});

app.post('/cockpit/commit-semana', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const username = req.session.user.username;
  const { dealId, classificacao, evidencia1, evidencia2, semana } = req.body || {};
  if (!dealId || !classificacao) return res.status(400).json({ error: 'dealId + classificacao obrigatórios' });
  if (!['commit','best_case','pipeline'].includes(classificacao)) return res.status(400).json({ error: 'classificacao inválida' });
  if (classificacao === 'commit' && (!evidencia1 || !evidencia2)) {
    return res.status(400).json({ error: 'Commit exige 2 evidências (próximo passo + alinhamento decisor)' });
  }
  const wk = semana || _semanaKey(new Date());
  const key = `${username}:${wk}`;
  const all = loadCommitForecasts();
  if (!all[key]) all[key] = [];
  const idx = all[key].findIndex(c => c.dealId === dealId);
  const entry = {
    dealId, classificacao,
    evidencia1: evidencia1 || '',
    evidencia2: evidencia2 || '',
    ts: Date.now(),
    by: u.name || username,
  };
  if (idx >= 0) all[key][idx] = entry;
  else all[key].push(entry);
  saveCommitForecasts(all);
  res.json({ ok: true, entry });
});

app.delete('/cockpit/commit-semana/:dealId', requireAuth, (req, res) => {
  const username = req.session.user.username;
  const semana = req.query.semana || _semanaKey(new Date());
  const key = `${username}:${semana}`;
  const all = loadCommitForecasts();
  if (!all[key]) return res.json({ ok: true });
  all[key] = all[key].filter(c => c.dealId !== req.params.dealId);
  saveCommitForecasts(all);
  res.json({ ok: true });
});

// Accuracy: comparar commits vs ganhos da semana (cron noturno + endpoint admin)
app.get('/gestao/forecast-accuracy', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const all = loadCommitForecasts();
  const won = await getWonDealsCached();
  const wonIds = new Set(won.map(d => d.id));
  const result = {};
  for (const [key, commits] of Object.entries(all)) {
    const [user, semana] = key.split(':');
    const commitsOnly = commits.filter(c => c.classificacao === 'commit');
    const acertos = commitsOnly.filter(c => wonIds.has(c.dealId)).length;
    const total = commitsOnly.length;
    if (!result[user]) result[user] = [];
    result[user].push({
      semana,
      total_commits: total,
      ganhos: acertos,
      accuracy: total > 0 ? Math.round((acertos / total) * 100) : null,
    });
  }
  res.json({ result });
});

// === SALES #6: FUNNEL COMPARE — taxa de conversão stage→stage por vendedor ===
// Identifica gargalo individual de cada closer pra coaching focado.
app.get('/gestao/funnel-compare', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  try {
    const dias = Math.min(180, parseInt(req.query.dias, 10) || 90);
    const cutoffDate = new Date(Date.now() - dias * 86400000).toISOString().slice(0, 10);
    const stages = ['Leads Novos','Etapa IA','Primeiro Contato','Em Qualificação','Qualificado','Proposta','Em Atendimento','Fechado Ganho','Fechado Perdido'];
    // Busca deals movidos nos últimos N dias
    const deals = await zohoSearch(
      `(Modified_Time:between:${cutoffDate}T00:00:00-03:00,${todayBR()}T23:59:59-03:00)`,
      'Deal_Name,Stage,Owner,Created_Time,Modified_Time', 200
    );
    // Agrega: por owner, conta quantos passaram em cada stage
    // (proxy: deals atualmente em stage X ou que já foram via stageHistory)
    const meta = loadManutMeta();
    const byOwner = {};
    for (const d of deals) {
      const owner = d.Owner?.name || 'Sem owner';
      if (!byOwner[owner]) byOwner[owner] = { stageCount: {}, total: 0, ganhos: 0, perdidos: 0 };
      byOwner[owner].total++;
      const stageAtual = d.Stage;
      byOwner[owner].stageCount[stageAtual] = (byOwner[owner].stageCount[stageAtual] || 0) + 1;
      // History local (se tiver)
      const hist = meta[d.id]?.stageHistory;
      if (Array.isArray(hist)) {
        const visitados = new Set(hist.map(h => h.stage));
        for (const s of visitados) byOwner[owner].stageCount[s] = (byOwner[owner].stageCount[s] || 0) + 0.5; // peso menor pra não duplicar atual
      }
      if (stageAtual === 'Fechado Ganho') byOwner[owner].ganhos++;
      if (stageAtual === 'Fechado Perdido') byOwner[owner].perdidos++;
    }
    // Calcula taxas de conversão entre stages adjacentes
    const stagesAtivos = ['Leads Novos','Primeiro Contato','Em Qualificação','Qualificado','Proposta','Fechado Ganho'];
    const owners = Object.entries(byOwner).map(([owner, data]) => {
      const conv = {};
      for (let i = 0; i < stagesAtivos.length - 1; i++) {
        const a = stagesAtivos[i], b = stagesAtivos[i+1];
        const cntA = data.stageCount[a] || 0;
        const cntB = data.stageCount[b] || 0;
        conv[`${a}→${b}`] = cntA > 0 ? Math.round((cntB / cntA) * 100) : null;
      }
      return {
        owner,
        total: data.total,
        ganhos: data.ganhos,
        perdidos: data.perdidos,
        winRate: data.total > 0 ? Math.round((data.ganhos / data.total) * 100) : 0,
        conv,
      };
    });
    // Mediana do time pra cada conversão
    const mediana = {};
    const conversions = Object.keys(owners[0]?.conv || {});
    for (const k of conversions) {
      const vals = owners.map(o => o.conv[k]).filter(v => v !== null).sort((a,b) => a-b);
      mediana[k] = vals.length ? vals[Math.floor(vals.length / 2)] : null;
    }
    // Marca gap (vendedor com conversão > 10pp abaixo da mediana = "gap")
    for (const o of owners) {
      o.gaps = [];
      for (const [k, v] of Object.entries(o.conv)) {
        if (v !== null && mediana[k] !== null && (mediana[k] - v) >= 10) {
          o.gaps.push({ etapa: k, vendedor: v, time: mediana[k], gap: mediana[k] - v });
        }
      }
    }
    owners.sort((a,b) => b.winRate - a.winRate);
    res.json({ dias, totalDeals: deals.length, owners, mediana, conversions });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

