// Snapshot agregado: Google + Meta + Zoho (pra cards topo)
// Aceita: ?days=N OU ?start=YYYY-MM-DD&end=YYYY-MM-DD (custom)
app.get('/trafego/snapshot', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  try {
    let periodo, days, cutoffMs;
    if (req.query.start && req.query.end) {
      periodo = { start: req.query.start, end: req.query.end };
      cutoffMs = new Date(req.query.start + 'T00:00:00-03:00').getTime();
      days = Math.max(1, Math.round((new Date(req.query.end).getTime() - cutoffMs) / 86400000) + 1);
    } else {
      days = Math.max(1, Math.min(90, parseInt(req.query.days, 10) || 7));
      periodo = days;
      cutoffMs = Date.now() - days * 86400000;
    }
    const metaPeriod = (typeof periodo === 'object') ? periodo : `last_${days}_d`;
    const [googleCamps, metaCamps, won] = await Promise.all([
      googleAds.getCampaignMetrics(periodo).catch(e => ({ error: e.message, list: [] })),
      metaAds.getCampaigns(metaPeriod).catch(e => ({ error: e.message, list: [] })),
      getWonDealsCached().catch(() => []),
    ]);
    const gList = Array.isArray(googleCamps) ? googleCamps : [];
    const mList = Array.isArray(metaCamps) ? metaCamps : [];
    // Agregações topo
    const investGoogle = gList.reduce((s,c) => s + (c.cost_brl||0), 0);
    const investMeta = mList.reduce((s,c) => s + (c.spend_brl||0), 0);
    const totalInvest = investGoogle + investMeta;
    const leadsGoogle = gList.reduce((s,c) => s + (c.conversions||0), 0);
    const leadsMeta = mList.reduce((s,c) => s + (c.leads||0), 0);
    const totalLeads = leadsGoogle + leadsMeta;
    // Vendas do período (Closing_Date entre start e end OU últimos N dias)
    const endMs = req.query.end ? new Date(req.query.end + 'T23:59:59-03:00').getTime() : Date.now();
    const vendasPeriodo = (won || []).filter(d => {
      const cd = d.Closing_Date ? new Date(d.Closing_Date).getTime() : 0;
      return cd >= cutoffMs && cd <= endMs;
    });
    const receita = vendasPeriodo.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const totalVendas = vendasPeriodo.length;
    const cac = totalVendas > 0 ? totalInvest / totalVendas : null;
    const roas = totalInvest > 0 ? receita / totalInvest : null;
    const ticketMedio = totalVendas > 0 ? receita / totalVendas : null;
    const cpl = totalLeads > 0 ? totalInvest / totalLeads : null;
    const taxaLeadVenda = totalLeads > 0 ? (totalVendas / totalLeads) * 100 : null;

    res.json({
      days,
      timestamp: Date.now(),
      cards: {
        invest_total: totalInvest,
        invest_google: investGoogle,
        invest_meta: investMeta,
        leads: totalLeads,
        leads_google: leadsGoogle,
        leads_meta: leadsMeta,
        vendas: totalVendas,
        receita,
        cac, roas, ticket_medio: ticketMedio, cpl,
        taxa_lead_venda_pct: taxaLeadVenda,
      },
      por_canal: {
        google: { invest: investGoogle, leads: leadsGoogle, campanhas: gList.length },
        meta: { invest: investMeta, leads: leadsMeta, campanhas: mList.length },
      },
      campanhas_google: gList.slice(0, 30),
      campanhas_meta: mList.slice(0, 30),
      health: {
        google_creds: googleAds.status().hasCreds,
        meta_creds: metaAds.status().hasCreds,
      },
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

