// === CONFIGURAÇÕES DE INTEGRAÇÃO (preparado pra multi-tenant SaaS) ===
// Storage: tenant-config (Postgres KV). Hoje single-tenant; quando virar SaaS,
// vira { [tenantId]: { google_ads: {...}, meta_ads: {...} } }
function loadTenantConfig() { return kvOrFile('tenant-config', null, {}); }
function saveTenantConfig(c) { kvAndFile('tenant-config', null, c); }
function _maskSecret(v) {
  if (!v) return '';
  v = String(v);
  if (v.length < 8) return '••••';
  return '•••••••' + v.slice(-4);
}

// Aplica config carregada do KV nos libs (chamado no boot + após save)
function _aplicarTenantConfig() {
  const c = loadTenantConfig();
  if (c.google_ads && Object.keys(c.google_ads).length) googleAds.setCreds(c.google_ads);
  if (c.meta_ads && Object.keys(c.meta_ads).length) metaAds.setCreds(c.meta_ads);
}
setTimeout(_aplicarTenantConfig, 7000);

// GET /integracoes/config — retorna config atual mascarada
app.get('/integracoes/config', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const c = loadTenantConfig();
  // Mascara secrets — mostra só últimos 4 chars
  const masked = {
    google_ads: {
      GOOGLE_ADS_DEVELOPER_TOKEN: _maskSecret(c.google_ads?.GOOGLE_ADS_DEVELOPER_TOKEN || process.env.GOOGLE_ADS_DEVELOPER_TOKEN),
      GOOGLE_ADS_CLIENT_ID: _maskSecret(c.google_ads?.GOOGLE_ADS_CLIENT_ID || process.env.GOOGLE_ADS_CLIENT_ID),
      GOOGLE_ADS_CLIENT_SECRET: _maskSecret(c.google_ads?.GOOGLE_ADS_CLIENT_SECRET || process.env.GOOGLE_ADS_CLIENT_SECRET),
      GOOGLE_ADS_REFRESH_TOKEN: _maskSecret(c.google_ads?.GOOGLE_ADS_REFRESH_TOKEN || process.env.GOOGLE_ADS_REFRESH_TOKEN),
      GOOGLE_ADS_CUSTOMER_ID: c.google_ads?.GOOGLE_ADS_CUSTOMER_ID || process.env.GOOGLE_ADS_CUSTOMER_ID || '',
      GOOGLE_ADS_LOGIN_CUSTOMER_ID: c.google_ads?.GOOGLE_ADS_LOGIN_CUSTOMER_ID || process.env.GOOGLE_ADS_LOGIN_CUSTOMER_ID || '',
    },
    meta_ads: {
      META_ACCESS_TOKEN: _maskSecret(c.meta_ads?.META_ACCESS_TOKEN || process.env.META_ACCESS_TOKEN || process.env.META_ADS_ACCESS_TOKEN),
      META_AD_ACCOUNT_ID: c.meta_ads?.META_AD_ACCOUNT_ID || process.env.META_AD_ACCOUNT_ID || '',
    },
    fonte: {
      google_ads_via_kv: !!c.google_ads,
      meta_ads_via_kv: !!c.meta_ads,
    },
    status: { google: googleAds.status(), meta: metaAds.status() },
  };
  res.json(masked);
});

// POST /integracoes/config — atualiza secrets
app.post('/integracoes/config', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const { google_ads, meta_ads } = req.body || {};
  const c = loadTenantConfig();
  if (google_ads && typeof google_ads === 'object') {
    if (!c.google_ads) c.google_ads = {};
    // Só atualiza chaves não vazias (deixa user trocar 1 só sem precisar reescrever todas)
    for (const [k, v] of Object.entries(google_ads)) {
      if (v && String(v).trim() && !String(v).includes('•')) c.google_ads[k] = String(v).trim();
    }
  }
  if (meta_ads && typeof meta_ads === 'object') {
    if (!c.meta_ads) c.meta_ads = {};
    for (const [k, v] of Object.entries(meta_ads)) {
      if (v && String(v).trim() && !String(v).includes('•')) c.meta_ads[k] = String(v).trim();
    }
  }
  saveTenantConfig(c);
  _aplicarTenantConfig();
  res.json({ ok: true, status: { google: googleAds.status(), meta: metaAds.status() } });
});

