// === OAUTH STUB (pra quando virar SaaS) ===
// Quando o app Google estiver aprovado, esses endpoints fazem o fluxo:
// 1. /integracoes/oauth/google/start → redireciona pra Google authorize
// 2. /integracoes/oauth/google/callback?code=X → troca code por tokens, salva tenant-config
//
// Pra ativar, setar:
//   GOOGLE_OAUTH_CLIENT_ID + GOOGLE_OAUTH_CLIENT_SECRET (do app aprovado pelo Google)
//   PORTAL_URL (pra redirect_uri = PORTAL_URL/integracoes/oauth/google/callback)
app.get('/integracoes/oauth/google/start', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).send('admin only');
  const cid = process.env.GOOGLE_OAUTH_CLIENT_ID;
  if (!cid) return res.status(501).send('OAuth não configurado. Configure GOOGLE_OAUTH_CLIENT_ID + GOOGLE_OAUTH_CLIENT_SECRET no Railway pra ativar este fluxo.');
  const redirect = `${PORTAL_BASE}/integracoes/oauth/google/callback`;
  const params = new URLSearchParams({
    client_id: cid,
    redirect_uri: redirect,
    response_type: 'code',
    scope: 'https://www.googleapis.com/auth/adwords',
    access_type: 'offline',
    prompt: 'consent', // força refresh_token
    state: req.session.user.username,
  });
  res.redirect('https://accounts.google.com/o/oauth2/v2/auth?' + params.toString());
});

app.get('/integracoes/oauth/google/callback', requireAuth, async (req, res) => {
  const { code, error } = req.query;
  if (error) return res.status(400).send('OAuth erro: ' + error);
  if (!code) return res.status(400).send('Sem code');
  const cid = process.env.GOOGLE_OAUTH_CLIENT_ID;
  const csec = process.env.GOOGLE_OAUTH_CLIENT_SECRET;
  if (!cid || !csec) return res.status(501).send('OAuth não configurado');
  try {
    const params = new URLSearchParams({
      code, client_id: cid, client_secret: csec,
      redirect_uri: `${PORTAL_BASE}/integracoes/oauth/google/callback`,
      grant_type: 'authorization_code',
    });
    const r = await fetch('https://oauth2.googleapis.com/token', { method: 'POST', body: params });
    const d = await r.json();
    if (!d.refresh_token) return res.status(500).send('Sem refresh_token. Tenta acessar /integracoes/oauth/google/start de novo (revoke antes em myaccount.google.com/permissions).');
    // Salva no tenant-config
    const c = loadTenantConfig();
    if (!c.google_ads) c.google_ads = {};
    c.google_ads.GOOGLE_ADS_CLIENT_ID = cid;
    c.google_ads.GOOGLE_ADS_CLIENT_SECRET = csec;
    c.google_ads.GOOGLE_ADS_REFRESH_TOKEN = d.refresh_token;
    saveTenantConfig(c);
    _aplicarTenantConfig();
    res.redirect('/integracoes?oauth=google&ok=1');
  } catch(e) {
    res.status(500).send('Erro: ' + e.message);
  }
});

// Meta OAuth stub (Long-lived User Access Token via Facebook Login)
app.get('/integracoes/oauth/meta/start', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).send('admin only');
  const appId = process.env.META_OAUTH_APP_ID;
  if (!appId) return res.status(501).send('Meta OAuth não configurado. Setar META_OAUTH_APP_ID + META_OAUTH_APP_SECRET no Railway. Crie um app em developers.facebook.com.');
  const params = new URLSearchParams({
    client_id: appId,
    redirect_uri: `${PORTAL_BASE}/integracoes/oauth/meta/callback`,
    state: req.session.user.username,
    scope: 'ads_management,ads_read,business_management,read_insights',
  });
  res.redirect('https://www.facebook.com/v21.0/dialog/oauth?' + params.toString());
});

app.get('/integracoes/oauth/meta/callback', requireAuth, async (req, res) => {
  const { code, error } = req.query;
  if (error) return res.status(400).send('Meta OAuth erro: ' + error);
  if (!code) return res.status(400).send('Sem code');
  const appId = process.env.META_OAUTH_APP_ID;
  const appSec = process.env.META_OAUTH_APP_SECRET;
  if (!appId || !appSec) return res.status(501).send('OAuth não configurado');
  try {
    const r = await fetch(`https://graph.facebook.com/v21.0/oauth/access_token?client_id=${appId}&client_secret=${appSec}&redirect_uri=${encodeURIComponent(PORTAL_BASE + '/integracoes/oauth/meta/callback')}&code=${code}`);
    const d = await r.json();
    const shortToken = d.access_token;
    if (!shortToken) return res.status(500).send('Sem access_token');
    // Troca pra long-lived (60 dias)
    const r2 = await fetch(`https://graph.facebook.com/v21.0/oauth/access_token?grant_type=fb_exchange_token&client_id=${appId}&client_secret=${appSec}&fb_exchange_token=${shortToken}`);
    const d2 = await r2.json();
    const longToken = d2.access_token || shortToken;
    // Salva
    const c = loadTenantConfig();
    if (!c.meta_ads) c.meta_ads = {};
    c.meta_ads.META_ACCESS_TOKEN = longToken;
    saveTenantConfig(c);
    _aplicarTenantConfig();
    res.redirect('/integracoes?oauth=meta&ok=1');
  } catch(e) {
    res.status(500).send('Erro: ' + e.message);
  }
});

