// === HEALTH CHECK COMPLETO (9 checks do Tracking spec) ===
app.get('/trafego/health-check', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const checks = [];
  const now = Date.now();

  // Check 1: credenciais Google Ads
  const gStatus = googleAds.status();
  checks.push({
    id: 'google_creds',
    label: 'Credenciais Google Ads',
    status: gStatus.hasCreds ? 'green' : 'red',
    detail: gStatus.hasCreds ? `customer ${gStatus.customerId}` : 'Setar GOOGLE_ADS_* no Railway',
  });

  // Check 2: credenciais Meta Ads
  const mStatus = metaAds.status();
  checks.push({
    id: 'meta_creds',
    label: 'Credenciais Meta Ads',
    status: mStatus.hasCreds ? 'green' : 'red',
    detail: mStatus.hasCreds ? `account ${mStatus.accountId}` : 'Setar META_ACCESS_TOKEN + META_AD_ACCOUNT_ID',
  });

  // Check 3: Enhanced Conversion Value (warning persistente — manual no Google Ads)
  checks.push({
    id: 'enhanced_conv_value',
    label: 'Enhanced Conversion Value',
    status: 'yellow',
    detail: 'OFF — habilitar no Google Ads pra ROAS mais preciso (~+20%)',
  });

  // Check 4: % de leads recentes com Lead_Source preenchido
  try {
    const since = new Date(now - 30 * 86400000).toISOString().slice(0, 10);
    const recentes = await zohoSearch(
      `(Created_Time:greater_equal:${since}T00:00:00-03:00)`,
      'Deal_Name,Lead_Source,Created_Time',
      200,
    ).catch(() => []);
    const totalRec = recentes.length;
    const comSource = recentes.filter(d => d.Lead_Source && String(d.Lead_Source).trim()).length;
    const pct = totalRec > 0 ? (comSource / totalRec) * 100 : null;
    checks.push({
      id: 'leads_with_source',
      label: 'Leads (30d) com Lead_Source preenchido',
      status: pct == null ? 'yellow' : pct >= 90 ? 'green' : pct >= 70 ? 'yellow' : 'red',
      detail: pct == null ? 'sem dados' : `${pct.toFixed(0)}% (${comSource}/${totalRec})`,
    });
  } catch(e) {
    checks.push({ id: 'leads_with_source', label: 'Leads com Lead_Source', status: 'red', detail: 'erro: ' + e.message });
  }

  // Check 5: Atribuição Meta — % de leads Meta com confidence high/medium
  try {
    const store = loadMetaAttribStore();
    const total = Object.keys(store).length;
    const high = Object.values(store).filter(v => v.confidence === 'high').length;
    const medium = Object.values(store).filter(v => v.confidence === 'medium').length;
    const goodPct = total > 0 ? ((high + medium) / total) * 100 : null;
    checks.push({
      id: 'meta_attrib_quality',
      label: 'Atribuição Meta (cache phone→camada)',
      status: total === 0 ? 'yellow' : goodPct >= 60 ? 'green' : goodPct >= 30 ? 'yellow' : 'red',
      detail: total === 0 ? 'cache vazio (esperar webhooks)' : `${high} high · ${medium} medium · ${total - high - medium} low/none`,
    });
  } catch(e) {
    checks.push({ id: 'meta_attrib_quality', label: 'Atribuição Meta', status: 'red', detail: e.message });
  }

  // Check 6: Cache won-deals frescor
  const wonAge = (now - (typeof _wonCacheAt !== 'undefined' ? _wonCacheAt : 0)) / 60000;
  checks.push({
    id: 'won_cache_age',
    label: 'Cache won-deals (Zoho)',
    status: wonAge > 60 ? 'red' : wonAge > 30 ? 'yellow' : 'green',
    detail: `${Math.round(wonAge)}min de idade · ${(typeof _wonCache !== 'undefined' ? (_wonCache?.length||0) : 0)} deals`,
  });

  // Check 7: Webhooks WATI — última msg recebida
  try {
    const inbox = loadWatiInbox();
    const lastTs = Math.max(0, ...Object.values(inbox).map(m => m.ts || 0));
    const ageMin = lastTs > 0 ? (now - lastTs) / 60000 : Infinity;
    checks.push({
      id: 'wati_webhook_freshness',
      label: 'Última msg WATI recebida',
      status: ageMin > 120 ? 'red' : ageMin > 30 ? 'yellow' : 'green',
      detail: lastTs > 0 ? `há ${Math.round(ageMin)} min` : 'nunca',
    });
  } catch(e) { checks.push({ id: 'wati_webhook_freshness', label: 'Webhook WATI', status: 'red', detail: e.message }); }

  // Check 8: Audit log atividade
  const audit = loadTrafegoAudit();
  const ultimaAcao = audit.length > 0 ? audit[audit.length - 1].ts : 0;
  const horasUlt = ultimaAcao > 0 ? (now - ultimaAcao) / 3600000 : Infinity;
  checks.push({
    id: 'trafego_audit_atividade',
    label: 'Última ação no tráfego',
    status: 'green', // informativo
    detail: ultimaAcao > 0 ? `há ${Math.round(horasUlt)}h · ${audit.length} ações totais` : 'sem ações registradas',
  });

  // Check 9: Token Zoho
  const zStats = zoho.stats();
  checks.push({
    id: 'zoho_token',
    label: 'Token Zoho CRM',
    status: zStats.hasToken && zStats.expiresIn > 60000 ? 'green' : zStats.cooldownActive ? 'red' : 'yellow',
    detail: zStats.cooldownActive ? `RATE LIMIT (cooldown ${Math.round(zStats.cooldownRemainingMs/1000)}s)` : zStats.hasToken ? `expira em ${Math.round(zStats.expiresIn/60000)}min` : 'sem token',
  });

  const greens = checks.filter(c => c.status === 'green').length;
  const reds = checks.filter(c => c.status === 'red').length;
  const score = Math.round((greens / checks.length) * 100);
  res.json({
    score, total: checks.length, greens, reds,
    yellows: checks.length - greens - reds,
    checks,
    generated_at: now,
  });
});

// === CRON: Gestor IA proativo (4x/dia: 08/12/16/20 BRT) + reconciliação 03h ===
let _GESTOR_IA_LAST_HOUR = -1;
let _RECONCILIA_LAST_DAY = '';
async function _trafegoCronTick(){
  try {
    const nowBr = nowBR();
    const hour = nowBr.getHours();
    const minute = nowBr.getMinutes();
    const day = nowBr.toISOString().slice(0,10);
    // Gestor IA 4x/dia (skip domingo)
    const horasGestor = [8, 12, 16, 20];
    const isFimDeSemana = nowBr.getDay() === 0;
    if (!isFimDeSemana && horasGestor.includes(hour) && minute < 5 && _GESTOR_IA_LAST_HOUR !== hour) {
      _GESTOR_IA_LAST_HOUR = hour;
      console.log(`[trafego-cron] Gestor IA ${hour}h disparando...`);
      try {
        // Roda análise e salva resultado pra dashboard mostrar
        if (!process.env.ANTHROPIC_API_KEY) {
          console.warn('[gestor-ia cron] ANTHROPIC_API_KEY ausente'); return;
        }
        const days = 7;
        const [gList, mList, won] = await Promise.all([
          googleAds.getCampaignMetrics(days).catch(() => []),
          metaAds.getCampaigns(`last_${days}_d`).catch(() => []),
          getWonDealsCached().catch(() => []),
        ]);
        const cutoffMs = Date.now() - days * 86400000;
        const vendas = (won || []).filter(d => d.Closing_Date && new Date(d.Closing_Date).getTime() >= cutoffMs);
        const snapshot = {
          janela_dias: days, hora: hour,
          campanhas_google: gList, campanhas_meta: mList,
          vendas_periodo: { total: vendas.length, receita: vendas.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0) },
        };
        const Anthropic = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
        const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
        const msg = await anthropic.messages.create({
          model: 'claude-sonnet-4-20250514',
          max_tokens: 1500,
          system: SYSTEM_PROMPT_GESTOR_TRAFEGO,
          messages: [{ role: 'user', content: 'Snapshot atual:\n```json\n'+JSON.stringify(snapshot,null,2)+'\n```\n\nGere 3 ações priorizadas em JSON.' }],
        });
        const text = msg.content[0]?.text || '{}';
        let parsed = null;
        try { const m = text.match(/\{[\s\S]*\}/); parsed = m ? JSON.parse(m[0]) : null; } catch(_){}
        // Salva último resultado pra UI
        kvAndFile('trafego-gestor-ia-last', null, { generated_at: Date.now(), parsed, raw: text, hour });
        // Notifica Cliq se tem ação requires_human=false confidence > 0.8
        if (parsed?.actions) {
          const automaticaveis = parsed.actions.filter(a => !a.requires_human && a.confidence > 0.8);
          if (automaticaveis.length > 0) {
            try { await cliqAlert(`🎙️ Gestor IA (${hour}h): ${parsed.actions.length} ações sugeridas, ${automaticaveis.length} automatizáveis. Ver em /gestao-trafego`); } catch(_){}
          }
        }
        console.log(`[trafego-cron] Gestor IA ${hour}h OK · ${parsed?.actions?.length||0} ações`);
      } catch(e) { console.warn('[gestor-ia cron]', e.message); }
    }
    // Reconciliação 03h
    if (hour === 3 && minute < 5 && _RECONCILIA_LAST_DAY !== day) {
      _RECONCILIA_LAST_DAY = day;
      console.log('[trafego-cron] reconciliação noturna...');
      try {
        const cache = loadMetaAttribStore();
        const since = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
        const deals = await zohoSearch(`(Created_Time:greater_equal:${since}T00:00:00-03:00)`, 'Deal_Name,Telefone_contato,Lead_Source,Modified_Time,Tag', 200);
        let atual = 0;
        for (const d of deals) {
          const ph = String(d.Telefone_contato||'').replace(/\D/g,'');
          if (!ph) continue;
          const at = cache[ph];
          if (!at) continue;
          const lsAtual = String(d.Lead_Source||'').trim();
          const generico = !lsAtual || /^(whatsapp\s*org|manual|—|-)$/i.test(lsAtual);
          const modH = d.Modified_Time ? (Date.now()-new Date(d.Modified_Time).getTime())/3600000 : 999;
          const tags = (d.Tag||[]).map(t => t.name||t);
          if (!generico || modH < 24 || tags.includes('atrib_manual')) continue;
          try {
            await zoho.updateDeal(d.id, { Lead_Source: at.lead_source });
            await zoho.addTags(d.id, ['tracking_reconciliado', `atrib_${at.confidence}`]);
            atual++;
          } catch(_){}
        }
        console.log(`[trafego-cron] reconciliação ${atual}/${deals.length} atualizados`);
        kvAndFile('trafego-reconcilia-last', null, { ts: Date.now(), atualizados: atual, total: deals.length });
      } catch(e) { console.warn('[reconciliação cron]', e.message); }
    }
  } catch(e) { console.warn('[trafego-cron]', e.message); }
}
// Roda a cada 4min (margem suficiente pra catch dos horários)
setTimeout(() => {
  setInterval(_trafegoCronTick, 4 * 60 * 1000);
  console.log('[trafego-cron] cron ativado · Gestor IA 8/12/16/20h · Reconciliação 3h');
}, 30 * 1000);

