app.post('/trafego/google/campaign/:id/pause', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const { id } = req.params;
  const { campaignName, force } = req.body || {};
  // Approval Gate
  if (!force) {
    const gate = await _approvalGateCampanha(campaignName, 'google');
    if (!gate.ok) return res.status(409).json({ error: 'approval_gate_blocked', gate, suggestion: 'reduce_budget_30' });
  }
  try {
    await googleAds.pauseCampaign(id);
    _trafegoLog({ actor: u.name || u.username, action: 'pause', plataforma: 'google', target_id: id, target_name: campaignName, forced: !!force });
    try { await cliqAlert(`⚠️ ${u.name} pausou campanha Google "${campaignName||id}"${force?' (FORÇADO)':''}`); } catch(_){}
    res.json({ ok: true });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

