// Persona universal — aceita ?persona=estrategista|auditor|critico_criativos
app.post('/trafego/gestor-ia', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  if (!process.env.ANTHROPIC_API_KEY) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não setada' });
  const personaKey = (req.query.persona || req.body?.persona || 'estrategista');
  const persona = PERSONAS_TRAFEGO[personaKey] || PERSONAS_TRAFEGO.estrategista;
  // Filtro de plataforma: ambos | google | meta
  const plataforma = (req.query.plataforma || req.body?.plataforma || 'ambos').toLowerCase();
  try {
    // Pega snapshot recente (período do request OU 7 dias default)
    const periodo = (req.query.start && req.query.end) ? { start: req.query.start, end: req.query.end } : null;
    const days = periodo ? null : Math.max(1, Math.min(90, parseInt(req.query.days || req.query.dias, 10) || 7));
    const metaPeriod = periodo || `last_${days}_d`;
    const [gListRaw, mListRaw, won] = await Promise.all([
      plataforma === 'meta' ? Promise.resolve([]) : googleAds.getCampaignMetrics(periodo || days).catch(() => []),
      plataforma === 'google' ? Promise.resolve([]) : metaAds.getCampaigns(metaPeriod).catch(() => []),
      getWonDealsCached().catch(() => []),
    ]);
    const gList = gListRaw, mList = mListRaw;
    // Vendas do período
    const cutoffMs = periodo
      ? new Date(periodo.start + 'T00:00:00-03:00').getTime()
      : Date.now() - days * 86400000;
    const endMs = periodo ? new Date(periodo.end + 'T23:59:59-03:00').getTime() : Date.now();
    const vendas = (won || []).filter(d => {
      const cd = d.Closing_Date ? new Date(d.Closing_Date).getTime() : 0;
      return cd >= cutoffMs && cd <= endMs;
    });
    const snapshot = {
      janela_dias: days || `${periodo.start}→${periodo.end}`,
      foco: plataforma,
      campanhas_google: gList,
      campanhas_meta: mList,
      vendas_periodo: {
        total: vendas.length,
        receita: vendas.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0),
        por_lead_source: vendas.reduce((acc,d) => {
          const ls = d.Lead_Source || 'Sem origem';
          acc[ls] = (acc[ls] || 0) + 1;
          return acc;
        }, {}),
      },
      hora_local: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }),
    };
    // Chama Claude com modelo da persona (Opus pra análise profunda)
    const Anthropic = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
    const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
    const msg = await anthropic.messages.create({
      model: persona.modelo || 'claude-sonnet-4-20250514',
      max_tokens: 3000,
      system: persona.system,
      messages: [{ role: 'user', content: 'Snapshot atual TDF:\n```json\n' + JSON.stringify(snapshot, null, 2) + '\n```\n\nFaça sua análise completa em JSON estrito (sem texto antes/depois).' }],
    });
    const text = msg.content[0]?.text || '{}';
    let parsed = null;
    try {
      const m = text.match(/\{[\s\S]*\}/);
      parsed = m ? JSON.parse(m[0]) : null;
    } catch(_){}
    res.json({
      ok: true,
      persona: { key: personaKey, nome: persona.nome, icon: persona.icon, cor: persona.cor, modelo: persona.modelo },
      generated_at: Date.now(),
      raw: text,
      parsed,
      snapshot_summary: {
        google_campaigns: gList.length,
        meta_campaigns: mList.length,
        vendas: vendas.length,
        receita: snapshot.vendas_periodo.receita,
      },
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// === LEADS POR CANAL (FB / IG / Google) + breakdown por tier ===
app.get('/trafego/leads-por-canal', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  try {
    const periodo = (req.query.start && req.query.end) ? { start: req.query.start, end: req.query.end } : null;
    const days = periodo ? null : Math.max(1, Math.min(90, parseInt(req.query.days, 10) || 7));
    const sinceMs = periodo
      ? new Date(periodo.start + 'T00:00:00-03:00').getTime()
      : Date.now() - days * 86400000;
    const untilMs = periodo
      ? new Date(periodo.end + 'T23:59:59-03:00').getTime()
      : Date.now();
    const since = new Date(sinceMs).toISOString().slice(0, 10);
    // 1) Meta breakdown publisher_platform
    const metaPeriod = periodo || `last_${days}_d`;
    const metaPlatforms = await metaAds.getLeadsByPlatform(metaPeriod).catch(e => ({ error: e.message }));
    // 2) Google: conversions agregadas (não tem breakdown por placement claro como Meta)
    const gCamps = await googleAds.getCampaignMetrics(periodo || days).catch(() => []);
    const googleLeads = gCamps.reduce((s,c) => s + (c.conversions || 0), 0);
    const googleSpend = gCamps.reduce((s,c) => s + (c.cost_brl || 0), 0);
    // 3) Zoho: deals criados no período com Lead_Source identificado, group por canal × tier
    const deals = await zohoSearch(
      `(Created_Time:between:${since}T00:00:00-03:00,${new Date(untilMs).toISOString().slice(0,10)}T23:59:59-03:00)`,
      'Deal_Name,Lead_Source,Tier_Lead,Created_Time,Stage,Amount,Telefone_contato',
      300,
    ).catch(() => []);
    function detectarCanal(ls) {
      const s = String(ls || '').toLowerCase();
      if (/facebook|\bfb\b|meta\s*·\s*leadad/.test(s)) return 'facebook';
      if (/instagram|\big\b/.test(s)) return 'instagram';
      if (/google|gclid|search/.test(s)) return 'google';
      if (/whatsapp|wa\b/.test(s)) return 'whatsapp';
      if (/indica/.test(s)) return 'indicacao';
      return 'outros';
    }
    const dealsPorCanal = {};
    const dealsPorTier = { Diamante: [], Ouro: [], Prata: [], Bronze: [], '': [] };
    for (const d of deals) {
      const canal = detectarCanal(d.Lead_Source);
      if (!dealsPorCanal[canal]) dealsPorCanal[canal] = { count: 0, byTier: {Diamante:0,Ouro:0,Prata:0,Bronze:0}, deals: [] };
      dealsPorCanal[canal].count++;
      const tier = d.Tier_Lead || '';
      if (dealsPorCanal[canal].byTier[tier] !== undefined) dealsPorCanal[canal].byTier[tier]++;
      dealsPorCanal[canal].deals.push({
        id: d.id, nome: d.Deal_Name, tier, stage: d.Stage,
        leadSource: d.Lead_Source || '', phone: d.Telefone_contato,
        amount: parseFloat(d.Amount) || 0,
        crmLink: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}`,
      });
      if (dealsPorTier[tier]) dealsPorTier[tier].push({ id: d.id, nome: d.Deal_Name, canal, stage: d.Stage, leadSource: d.Lead_Source, phone: d.Telefone_contato });
    }
    res.json({
      periodo: { start: since, end: new Date(untilMs).toISOString().slice(0,10) },
      investimento: {
        google: googleSpend,
        meta_total: (metaPlatforms.facebook?.spend||0) + (metaPlatforms.instagram?.spend||0) + (metaPlatforms.audience_network?.spend||0),
        facebook: metaPlatforms.facebook?.spend || 0,
        instagram: metaPlatforms.instagram?.spend || 0,
        total: googleSpend + (metaPlatforms.facebook?.spend||0) + (metaPlatforms.instagram?.spend||0) + (metaPlatforms.audience_network?.spend||0),
      },
      leads: {
        google: googleLeads,
        facebook: metaPlatforms.facebook?.leads || 0,
        instagram: metaPlatforms.instagram?.leads || 0,
        audience_network: metaPlatforms.audience_network?.leads || 0,
        meta_total: (metaPlatforms.facebook?.leads||0) + (metaPlatforms.instagram?.leads||0) + (metaPlatforms.audience_network?.leads||0),
        total: googleLeads + (metaPlatforms.facebook?.leads||0) + (metaPlatforms.instagram?.leads||0),
      },
      cpl: {
        google: googleLeads > 0 ? googleSpend / googleLeads : null,
        facebook: (metaPlatforms.facebook?.leads||0) > 0 ? (metaPlatforms.facebook.spend / metaPlatforms.facebook.leads) : null,
        instagram: (metaPlatforms.instagram?.leads||0) > 0 ? (metaPlatforms.instagram.spend / metaPlatforms.instagram.leads) : null,
      },
      crm: {
        total_leads_criados: deals.length,
        por_canal: dealsPorCanal,
        por_tier: {
          Diamante: dealsPorTier.Diamante.length,
          Ouro: dealsPorTier.Ouro.length,
          Prata: dealsPorTier.Prata.length,
          Bronze: dealsPorTier.Bronze.length,
          sem_tier: dealsPorTier[''].length,
        },
        leads_diamante_ouro: [...dealsPorTier.Diamante, ...dealsPorTier.Ouro],
      },
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// === AUTO-NOTIFICAÇÃO Lead Qualificado (cron 5min checa novos Diamante/Ouro) ===
let _ULTIMA_NOTIF_TIER = {}; // { dealId: ts }
async function _checkNovosLeadsQualificados() {
  try {
    const since = new Date(Date.now() - 30 * 60 * 1000).toISOString(); // últimos 30min
    const deals = await zohoSearch(
      `((Tier_Lead:in:Diamante,Ouro)and(Modified_Time:greater_equal:${since}))`,
      'Deal_Name,Tier_Lead,Lead_Source,Telefone_contato,Owner,Stage,Amount,Modified_Time',
      50,
    ).catch(() => []);
    for (const d of deals) {
      // Já notificado nas últimas 24h?
      if (_ULTIMA_NOTIF_TIER[d.id] && (Date.now() - _ULTIMA_NOTIF_TIER[d.id]) < 24 * 3600 * 1000) continue;
      _ULTIMA_NOTIF_TIER[d.id] = Date.now();
      const tier = d.Tier_Lead;
      const ico = tier === 'Diamante' ? '💎' : '🥇';
      const nome = d.Deal_Name || '?';
      const phone = d.Telefone_contato || '';
      const owner = d.Owner?.name || '?';
      const fonte = d.Lead_Source || 'sem origem';
      const valor = parseFloat(d.Amount) ? `R$ ${Math.round(d.Amount).toLocaleString('pt-BR')}` : '';
      const msg = `${ico} *LEAD ${tier.toUpperCase()}* recém qualificado!\n\n` +
                  `👤 ${nome}\n📞 ${phone}\n🎯 Origem: ${fonte}\n` +
                  `📋 Stage: ${d.Stage}${valor?'\n💰 '+valor:''}\n` +
                  `👥 Owner: ${owner}\n\n` +
                  `🔗 ${PORTAL_BASE}/manutencao#${d.id}`;
      try { await zapiSend(PAULO_PHONE, msg); } catch(_){}
      try { await cliqAlert(`${ico} Lead ${tier}: ${nome} (${phone}) · ${fonte} · owner: ${owner}`); } catch(_){}
      console.log(`[lead-qualificado] notificado ${tier} dealId=${d.id} nome=${nome}`);
    }
    // Limpa entries muito antigas (>48h) pra não vazar memória
    const cutoff = Date.now() - 48 * 3600 * 1000;
    for (const id of Object.keys(_ULTIMA_NOTIF_TIER)) {
      if (_ULTIMA_NOTIF_TIER[id] < cutoff) delete _ULTIMA_NOTIF_TIER[id];
    }
  } catch(e) { console.warn('[lead-qualificado-cron]', e.message); }
}
// Roda a cada 5min
setTimeout(() => {
  _checkNovosLeadsQualificados();
  setInterval(_checkNovosLeadsQualificados, 5 * 60 * 1000);
}, 60 * 1000);

