// === MONITOR SLA NÚBIA: alerta lead SDR IA sem template em 5min ===
// Detecta token WATI quebrado em near real-time. Histórico (5/Mai e 6/Mai):
// token expirou silenciosamente, P90 saiu pra 3h+ porque ninguém viu até o fim do dia.
const _NUBIA_SLA_ALERTED = {}; // { dealId: ts } — evita spam (alerta 1 vez por deal)
let _NUBIA_SLA_LAST_BURST = 0; // ts do último alerta agregado de "vários leads sem template"
async function _checkNubiaSLA() {
  try {
    const nowMs = Date.now();
    const sinceISO = new Date(nowMs - 60 * 60 * 1000).toISOString(); // últimos 60min
    // Busca deals com tag SDR IA modificados nas últimas 1h
    const deals = await zohoSearch(
      `((Tag:in:SDR IA)and(Created_Time:greater_equal:${sinceISO}))`,
      'Deal_Name,Stage,Owner,Created_Time,Telefone_contato,Tag,Lead_Source',
      100,
    ).catch(() => []);
    if (!deals.length) return;

    // Stages elegíveis (cliente ainda não tá em conversa profunda — esperaria template)
    const STAGES_OK = /^(Primeiro Contato|Em Qualifica|Etapa IA|Analise ou vaz|An.lise ou vaz|Leads Novos)/i;
    const candidatos = deals.filter(d => {
      const created = new Date(d.Created_Time || 0).getTime();
      const ageMin = (nowMs - created) / 60000;
      // Janela: 5min < idade < 60min (já passou SLA mas ainda é hoje)
      if (ageMin < 5 || ageMin > 60) return false;
      if (!STAGES_OK.test(d.Stage || '')) return false;
      return true;
    });
    if (!candidatos.length) return;

    // Pra cada candidato, checa Notes — se NÃO tem "Primeiro contato", é violação
    const token = await getZohoToken();
    if (!token) return;
    const violacoes = [];
    for (const d of candidatos) {
      if (_NUBIA_SLA_ALERTED[d.id] && (nowMs - _NUBIA_SLA_ALERTED[d.id]) < 12 * 3600 * 1000) continue;
      const r = await fetch(
        `https://www.zohoapis.com/crm/v2/Deals/${d.id}/Notes?fields=Note_Title,Created_Time&per_page=20`,
        { headers: { Authorization: `Zoho-oauthtoken ${token}` } },
      ).catch(() => null);
      if (!r) continue;
      let notes = null;
      try { notes = r.status === 204 ? { data: [] } : await r.json(); } catch(_) { continue; }
      const has = (notes?.data || []).some(n => /primeiro contato/i.test(n.Note_Title || ''));
      if (has) continue;
      violacoes.push(d);
      _NUBIA_SLA_ALERTED[d.id] = nowMs;
    }
    if (!violacoes.length) return;

    // Alerta agregado (evita 1 mensagem por lead)
    const lista = violacoes.slice(0, 8).map(d => {
      const created = new Date(d.Created_Time || 0);
      const hh = String(created.getHours()).padStart(2,'0');
      const mm = String(created.getMinutes()).padStart(2,'0');
      const age = Math.round((nowMs - created.getTime())/60000);
      return `• ${hh}:${mm} (+${age}min) ${d.Deal_Name || '?'} — ${d.Stage || '?'}`;
    }).join('\n');
    const extra = violacoes.length > 8 ? `\n…+${violacoes.length - 8} outros` : '';
    const msg = `🚨 *Núbia SLA quebrado* — ${violacoes.length} lead(s) SDR IA sem template em 5min+:\n\n${lista}${extra}\n\n` +
                `Causa provável: token WATI revogado/expirado. Roda \`curl /api/v1/getContacts\` pra confirmar 401.`;
    try { await cliqAlert('alertassdr', msg); } catch(_){}
    try { if (typeof zapiSend === 'function' && typeof PAULO_PHONE !== 'undefined' && PAULO_PHONE) await zapiSend(PAULO_PHONE, msg); } catch(_){}
    _NUBIA_SLA_LAST_BURST = nowMs;
    console.log(`[nubia-sla] 🚨 ${violacoes.length} leads sem template — alerta disparado`);

    // Limpa entries antigas (>48h)
    const cutoff = nowMs - 48 * 3600 * 1000;
    for (const id of Object.keys(_NUBIA_SLA_ALERTED)) {
      if (_NUBIA_SLA_ALERTED[id] < cutoff) delete _NUBIA_SLA_ALERTED[id];
    }
  } catch(e) { console.warn('[nubia-sla-cron]', e.message); }
}
// Roda a cada 5min após boot
