// === BAND-AID: recovery automático leads SDR IA sem template ===
// Bug 06/Mai/2026: Núbia chama sendTemplate sem addContact antes — WATI rejeita
// silenciosamente. Workaround: addContact → sendTemplate em sequência.
// Recovery rodou manualmente 70 leads, 52 entregues (75%). Os 18 que falham
// têm número inválido (cliente digitou errado na LP). Esse cron faz o mesmo
// até a Núbia ser corrigida no main.py.
const _BANDAID_PROCESSED = new Set(); // dealIds já tentados
const NUBIA_BANDAID_STAGES_OK = /^(Em Qualifica|Primeiro Contato|Etapa IA|Analise ou vaz|An.lise ou vaz|Leads Novos)/i;
const NUBIA_BANDAID_TEMPLATE = process.env.NUBIA_BANDAID_TEMPLATE || 'tdf_followup_dia1';
const NUBIA_BANDAID_BROADCAST = 'tdf_portal_bandaid';

async function _watiAddContact(phone, name) {
  if (!WATI_TOKEN) return { ok: false, err: 'no token' };
  try {
    const r = await fetch(`${WATI_BASE}/api/v1/addContact/${encodeURIComponent(phone)}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${WATI_TOKEN}`,
        'Content-Type': 'application/json',
        'User-Agent': 'tdf-portal-bandaid/1.0',
      },
      body: JSON.stringify({ name, customParams: [{ name: 'name', value: name }] }),
    });
    if (!r.ok) return { ok: false, http: r.status };
    const j = await r.json().catch(() => ({}));
    return { ok: true, contactStatus: j?.contact?.contactStatus };
  } catch (e) { return { ok: false, err: e.message }; }
}

async function _watiSendTemplate(phone, name) {
  if (!WATI_TOKEN) return { ok: false, err: 'no token' };
  try {
    const r = await fetch(
      `${WATI_BASE}/api/v1/sendTemplateMessage?whatsappNumber=${encodeURIComponent(phone)}`,
      {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${WATI_TOKEN}`,
          'Content-Type': 'application/json',
          'User-Agent': 'tdf-portal-bandaid/1.0',
        },
        body: JSON.stringify({
          template_name: NUBIA_BANDAID_TEMPLATE,
          broadcast_name: NUBIA_BANDAID_BROADCAST,
          parameters: [{ name: 'name', value: name }],
        }),
      },
    );
    if (!r.ok) return { ok: false, http: r.status };
    const j = await r.json().catch(() => ({}));
    return { ok: !!j.validWhatsAppNumber, valid: j.validWhatsAppNumber, info: j.info };
  } catch (e) { return { ok: false, err: e.message }; }
}

async function _zohoCreateNote(dealId, content) {
  try {
    return await zoho.fetch(`/Deals/${dealId}/Notes`, {
      method: 'POST',
      body: { data: [{ Note_Title: 'Primeiro contato automático', Note_Content: content }] },
    });
  } catch(e) { return null; }
}

let _BANDAID_RUNNING = false;
async function _nubiaBandAid() {
  // KILL SWITCH — Paulo desligou em 02/jun/2026 (Núbia flodando + alucinando preço).
  // Pra reativar: remover env var DISABLE_NUBIA_BANDAID do Railway.
  if (process.env.DISABLE_NUBIA_BANDAID === '1') {
    return;
  }
  if (_BANDAID_RUNNING) return; // evita overlap
  _BANDAID_RUNNING = true;
  try {
    if (!WATI_TOKEN) return;
    const sinceISO = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString(); // últimas 2h
    const deals = await zohoSearch(
      `((Tag:in:SDR IA)and(Created_Time:greater_equal:${sinceISO}))`,
      'Deal_Name,Stage,Owner,Created_Time,Telefone_contato',
      80,
    ).catch(() => []);
    if (!deals.length) return;

    const candidatos = deals.filter(d => {
      if (!d.Telefone_contato) return false;
      if (!NUBIA_BANDAID_STAGES_OK.test(d.Stage || '')) return false;
      if (_BANDAID_PROCESSED.has(d.id)) return false;
      const ageMin = (Date.now() - new Date(d.Created_Time || 0).getTime()) / 60000;
      if (ageMin < 5) return false; // dá margem pra Núbia tentar primeiro
      if (ageMin > 120) return false; // muito antigo, deixa pra recovery manual
      return true;
    });
    if (!candidatos.length) return;

    // Pra cada candidato: checa se já tem nota "Primeiro contato"
    const token = await getZohoToken();
    if (!token) return;
    const sender = candidatos.slice(0, 30); // hard-cap 30 por tick (15min @ 3s gap)
    let okCount = 0, failCount = 0;
    for (const d of sender) {
      _BANDAID_PROCESSED.add(d.id);
      try {
        const r = await fetch(
          `https://www.zohoapis.com/crm/v2/Deals/${d.id}/Notes?fields=Note_Title&per_page=15`,
          { headers: { Authorization: `Zoho-oauthtoken ${token}` } },
        );
        let notes = null;
        try { notes = r.status === 204 ? { data: [] } : await r.json(); } catch(_) { continue; }
        const has = (notes?.data || []).some(n => /primeiro contato/i.test(n.Note_Title || ''));
        if (has) continue;
      } catch(_) { continue; }

      const phone = String(d.Telefone_contato).replace(/\D/g, '');
      const name = (d.Deal_Name || '').split(' ')[0] || 'cliente';

      // 1. addContact
      const ac = await _watiAddContact(phone, name);
      if (!ac.ok) { failCount++; continue; }
      // 2. sendTemplate
      const st = await _watiSendTemplate(phone, name);
      if (st.ok) {
        okCount++;
        await _zohoCreateNote(d.id, `tdf-portal band-aid 06/Mai. Template ${NUBIA_BANDAID_TEMPLATE} enviado pra ${phone}.`);
      } else {
        failCount++;
      }
      await new Promise(r => setTimeout(r, 3000)); // gap 3s pra não inflamar quality
    }
    if (okCount + failCount > 0) {
      console.log(`[nubia-bandaid] ${okCount} ok / ${failCount} fail (${sender.length} processados)`);
      if (okCount >= 3 && CLIQ_ZAPIKEY) {
        try { await cliqAlert('alertassdr', `🩹 Band-aid Núbia recuperou ${okCount} leads (${failCount} números inválidos). A Núbia precisa do fix do main.py.`); } catch(_){}
      }
    }
    // Cleanup do set se ficar grande (>500)
    if (_BANDAID_PROCESSED.size > 500) {
      _BANDAID_PROCESSED.clear();
    }
  } catch(e) {
    console.warn('[nubia-bandaid]', e.message);
  } finally {
    _BANDAID_RUNNING = false;
  }
}

// Roda a cada 30min após boot
setTimeout(() => {
  _nubiaBandAid();
  setInterval(_nubiaBandAid, 30 * 60 * 1000);
}, 3 * 60 * 1000);

