app.post('/admin/nubia-bandaid/run', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  if (_BANDAID_RUNNING) return res.json({ ok: false, error: 'já rodando' });
  await _nubiaBandAid();
  res.json({ ok: true, processed: _BANDAID_PROCESSED.size });
});

// === Monitor template approval + auto-disparo poço ===
// 3 templates submetidos 08/Mai aguardando indexação API WATI:
// - reengaja_poco_dor_direta_v1
// - reengaja_poco_familia_v2
// - reengaja_poco_custo_oculto_v3
// Painel WATI mostra APPROVED mas API getMessageTemplates ainda não retorna
// (delay típico 30min-2h). Quando virar consultável, dispara automaticamente
// pros 96 leads de poço redistribuídos do Guilherme (round-robin entre 3 templates).
const POCO_TEMPLATES = [
  'reengaja_poco_dor_direta_v1',
  'reengaja_poco_familia_v2',
  'reengaja_poco_custo_oculto_v3',
];
// IDs dos 96 leads salvos em /tmp/poco_ids_redist.json — copiar pra dentro do container
let _POCO_LEAD_IDS = [];
try {
  const fs = require('fs');
  const path = '/app/data/poco_ids_redist.json';
  if (fs.existsSync(path)) _POCO_LEAD_IDS = JSON.parse(fs.readFileSync(path, 'utf8'));
} catch(_){}
let _POCO_DISPATCH_DONE = false;
let _POCO_DISPATCH_RESULT = null;

async function _testTemplateAvailable(templateName) {
  // Tenta com número do Paulo (5511993XXXX) — só pra ver se template é reconhecido
  // sem consumir entrega. Vai retornar 400 com 'template_name missing/wrong' se não achou.
  const probePhone = '5511999999990'; // número fake — endpoint vai validar template ANTES do número
  try {
    const r = await fetch(`${WATI_BASE}/api/v1/sendTemplateMessage?whatsappNumber=${probePhone}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${WATI_TOKEN}`,
        'Content-Type': 'application/json',
        'User-Agent': 'tdf-portal-monitor/1.0',
      },
      body: JSON.stringify({
        template_name: templateName, broadcast_name: 'probe',
        parameters: [{ name: 'name', value: 'X' }],
      }),
    });
    if (r.ok) {
      // 200 + valid=false (numero fake) = template existe
      const j = await r.json().catch(() => ({}));
      if (j.result === true) return true;
    } else if (r.status === 400) {
      const t = await r.text();
      if (/template_name field is missing/i.test(t)) return false;
      // outros 400 → assume que template existe (ex: "valid=false")
      return true;
    }
  } catch(_){}
  return false;
}

async function _dispararPocoTemplates() {
  if (_POCO_DISPATCH_DONE) return { skipped: 'já disparado' };
  if (!WATI_TOKEN) return { error: 'no token' };
  if (!_POCO_LEAD_IDS.length) return { error: 'lista de IDs vazia' };

  // 1) Verifica disponibilidade dos 3 templates
  const checks = await Promise.all(POCO_TEMPLATES.map(_testTemplateAvailable));
  const ready = POCO_TEMPLATES.filter((_, i) => checks[i]);
  if (!ready.length) return { skipped: 'nenhum template disponível ainda' };
  console.log(`[poco-dispatch] templates prontos: ${ready.join(', ')}`);

  // 2) Pega dados dos leads do Zoho
  const token = await getZohoToken();
  if (!token) return { error: 'zoho indisponível' };

  let ok = 0, fail = 0, skip = 0;
  for (let i = 0; i < _POCO_LEAD_IDS.length; i++) {
    const dealId = _POCO_LEAD_IDS[i];
    try {
      const r = await fetch(
        `https://www.zohoapis.com/crm/v2/Deals/${dealId}?fields=Deal_Name,Telefone_contato,Stage`,
        { headers: { Authorization: `Zoho-oauthtoken ${token}` } },
      );
      if (!r.ok) { skip++; continue; }
      const data = await r.json();
      const d = (data.data || [])[0];
      if (!d || !d.Telefone_contato) { skip++; continue; }
      // Pula se já em estágio fechado/proposta
      if (/Fechado|Proposta/i.test(d.Stage || '')) { skip++; continue; }

      const phone = String(d.Telefone_contato).replace(/\D/g, '');
      const name = (d.Deal_Name || '').split(' ')[0] || 'cliente';
      const tpl = ready[i % ready.length]; // round-robin

      // addContact + sendTemplate (sequência que funciona)
      await _watiAddContact(phone, name);
      const send = await _watiSendTemplate(phone, name); // usa template default
      // override pra usar template do round-robin
      const r2 = await fetch(
        `${WATI_BASE}/api/v1/sendTemplateMessage?whatsappNumber=${phone}`,
        {
          method: 'POST',
          headers: { Authorization: `Bearer ${WATI_TOKEN}`, 'Content-Type': 'application/json', 'User-Agent': 'tdf-portal-poco-dispatch/1.0' },
          body: JSON.stringify({
            template_name: tpl, broadcast_name: 'poco_reengaja_08mai',
            parameters: [{ name: 'name', value: name }],
          }),
        },
      );
      const body2 = await r2.json().catch(() => ({}));
      if (body2.validWhatsAppNumber === true) {
        ok++;
        await _zohoCreateNote(dealId, `Reengajamento poço auto-disparado (${tpl}) em ${new Date().toLocaleString('pt-BR')}.`);
      } else {
        fail++;
      }
      await new Promise(r => setTimeout(r, 3000));
    } catch (e) { fail++; }
  }

  _POCO_DISPATCH_RESULT = { ok, fail, skip, total: _POCO_LEAD_IDS.length, templates_used: ready, at: new Date().toISOString() };
  _POCO_DISPATCH_DONE = ok > 0; // só marca done se ENTREGOU
  console.log(`[poco-dispatch] ${ok} ok / ${fail} fail / ${skip} skip`);

  // Alerta no Cliq
  try {
    await cliqAlert('alertassdr',
      `🌊 *Reengajamento Poço — auto-disparado*\n\n` +
      `Templates aprovados: ${ready.join(', ')}\n` +
      `Resultado: ✅ ${ok} entregues · ❌ ${fail} falha · ⏭ ${skip} pulados\n` +
      `Total alvo: ${_POCO_LEAD_IDS.length} leads de poço redistribuídos do Guilherme.`);
  } catch(_){}

  return _POCO_DISPATCH_RESULT;
}

// Cron: tenta a cada 15min até disparar com sucesso (depois para)
let _pocoCheckCount = 0;
async function _pocoCheckLoop() {
  if (_POCO_DISPATCH_DONE) return;
  if (!_POCO_LEAD_IDS.length) return;
  _pocoCheckCount++;
  const checks = await Promise.all(POCO_TEMPLATES.map(_testTemplateAvailable));
  const readyCount = checks.filter(Boolean).length;
  console.log(`[poco-monitor] tentativa #${_pocoCheckCount}: ${readyCount}/3 templates prontos`);
  if (readyCount > 0) {
    await _dispararPocoTemplates();
  }
}
setTimeout(() => {
  _pocoCheckLoop();
  setInterval(_pocoCheckLoop, 15 * 60 * 1000);
}, 5 * 60 * 1000);

