// === Relatório dos leads SDR IA pendentes (sem template "Primeiro contato") agrupado por owner ===
// POST /admin/nubia-pendentes-report → gera relatório + manda no Cliq #alertassdr
// GET  /admin/nubia-pendentes      → retorna JSON pro frontend
async function _buildNubiaPendentesReport() {
  const hoje = todayBR();
  const STAGES_OK_RX = /^(Em Qualifica|Primeiro Contato|Etapa IA|Analise ou vaz|An.lise ou vaz|Leads Novos)/i;
  // Busca SDR IA criados hoje
  const since = `${hoje}T00:00:00-03:00`;
  const deals = await zohoSearch(
    `((Tag:in:SDR IA)and(Created_Time:greater_equal:${since}))`,
    'Deal_Name,Stage,Owner,Created_Time,Telefone_contato,Lead_Source',
    200,
  ).catch(() => []);

  const elegiveis = deals.filter(d =>
    d.Telefone_contato && STAGES_OK_RX.test(d.Stage || '')
  );

  // Pra cada um, checa se tem nota "Primeiro contato"
  const token = await getZohoToken();
  if (!token) return { ok: false, error: 'zoho indisponível' };
  const pendentes = [];
  for (const d of elegiveis) {
    try {
      const r = await fetch(
        `https://www.zohoapis.com/crm/v2/Deals/${d.id}/Notes?fields=Note_Title&per_page=15`,
        { headers: { Authorization: `Zoho-oauthtoken ${token}` } },
      );
      let notes = null;
      try { notes = r.status === 204 ? { data: [] } : await r.json(); } catch(_) { continue; }
      const has = (notes?.data || []).some(n => /primeiro contato/i.test(n.Note_Title || ''));
      if (!has) pendentes.push(d);
    } catch(_) {}
  }

  // Agrupa por owner
  const byOwner = {};
  for (const d of pendentes) {
    const owner = d.Owner?.name || 'SEM OWNER';
    if (!byOwner[owner]) byOwner[owner] = [];
    byOwner[owner].push(d);
  }

  return { ok: true, hoje, total: pendentes.length, byOwner, pendentes };
}

app.get('/admin/nubia-pendentes', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  try {
    const r = await _buildNubiaPendentesReport();
    res.json(r);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/admin/nubia-pendentes-report', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  try {
    const data = await _buildNubiaPendentesReport();
    if (!data.ok) return res.status(500).json(data);
    if (!data.total) {
      return res.json({ ok: true, total: 0, msg: 'Nenhum lead pendente — Núbia em dia!' });
    }
    // Monta mensagem do Cliq
    const lines = [`📋 *Núbia — ${data.total} leads sem 1º contato hoje (${data.hoje})*`, ''];
    const owners = Object.entries(data.byOwner).sort((a, b) => b[1].length - a[1].length);
    for (const [owner, deals] of owners) {
      lines.push(`👤 *${owner}* — ${deals.length} leads:`);
      for (const d of deals.slice(0, 10)) {
        const h = (d.Created_Time || '').slice(11, 16);
        const stage = (d.Stage || '?').slice(0, 20);
        const name = (d.Deal_Name || '?').slice(0, 30);
        const phone = d.Telefone_contato || '?';
        const crmUrl = `https://crm.zoho.com/crm/org6311862000000004/tab/Potentials/${d.id}`;
        const watiUrl = `https://live.wati.io/2708/teamInbox/${String(phone).replace(/\D/g, '')}`;
        lines.push(`  • ${h} ${stage} — ${name} (${phone})`);
        lines.push(`    [Zoho](${crmUrl}) · [WATI](${watiUrl})`);
      }
      if (deals.length > 10) lines.push(`  …+${deals.length - 10} outros`);
      lines.push('');
    }
    lines.push('💡 Vendedores: clique no link [WATI] e mande "Oi" pro lead — isso valida o número e ativa a Núbia automaticamente.');
    const msg = lines.join('\n');
    try { await cliqAlert('alertassdr', msg); } catch(e) { console.warn('cliq:', e.message); }
    res.json({ ok: true, total: data.total, owners: owners.length, sentToCliq: !!CLIQ_ZAPIKEY });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

