app.get('/trafego/funnel', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  try {
    const periodo = (req.query.start && req.query.end) ? { start: req.query.start, end: req.query.end } : null;
    const days = periodo ? null : Math.max(1, Math.min(365, parseInt(req.query.days, 10) || 30));
    const sinceMs = periodo ? new Date(periodo.start + 'T00:00:00-03:00').getTime() : Date.now() - days * 86400000;
    const untilMs = periodo ? new Date(periodo.end + 'T23:59:59-03:00').getTime() : Date.now();
    const since = new Date(sinceMs).toISOString().slice(0,10);
    const until = new Date(untilMs).toISOString().slice(0,10);
    const metaPeriod = periodo || `last_${days}_d`;
    // Top do funil: cliques + leads de ads
    const [gCamps, mCamps] = await Promise.all([
      googleAds.getCampaignMetrics(periodo || days).catch(() => []),
      metaAds.getCampaigns(metaPeriod).catch(() => []),
    ]);
    const totalImpressoes = gCamps.reduce((s,c) => s + (c.impressions||0), 0) + mCamps.reduce((s,c) => s + (c.impressions||0), 0);
    const totalCliques = gCamps.reduce((s,c) => s + (c.clicks||0), 0) + mCamps.reduce((s,c) => s + (c.clicks||0), 0);
    const leadsAds = gCamps.reduce((s,c) => s + (c.conversions||0), 0) + mCamps.reduce((s,c) => s + (c.leads||0), 0);
    // Bottom do funil: deals Zoho criados no período
    const dealsCriados = await zohoSearch(
      `(Created_Time:between:${since}T00:00:00-03:00,${until}T23:59:59-03:00)`,
      'Deal_Name,Stage,Amount,Lead_Source,Created_Time',
      300,
    ).catch(() => []);
    // Conta por stage
    const porStage = {};
    let receitaGanha = 0;
    for (const d of dealsCriados) {
      const stage = d.Stage || 'Sem stage';
      porStage[stage] = (porStage[stage] || 0) + 1;
      if (stage === 'Fechado Ganho') receitaGanha += parseFloat(d.Amount) || 0;
    }
    // Etapas do funil — count cumulativo (deal "Em Qualificação" também passou por "Primeiro Contato", etc)
    const stagesQualif = ['Qualificado', 'Em Qualificação', 'Em Atendimento', 'Proposta', 'Proposta Quente', 'Proposta Fria', 'Fechado Ganho', 'Fechado Perdido'];
    const stagesProposta = ['Proposta', 'Proposta Quente', 'Proposta Fria', 'Em Atendimento', 'Fechado Ganho', 'Fechado Perdido'];
    const stagesGanho = ['Fechado Ganho'];
    const qualificados = dealsCriados.filter(d => stagesQualif.includes(d.Stage)).length;
    const propostas = dealsCriados.filter(d => stagesProposta.includes(d.Stage)).length;
    const ganhos = dealsCriados.filter(d => stagesGanho.includes(d.Stage)).length;
    const etapas = [
      { nome: 'Impressões', icon: '👁️', valor: totalImpressoes, ratio: null },
      { nome: 'Cliques', icon: '👆', valor: totalCliques, ratio: totalImpressoes > 0 ? totalCliques / totalImpressoes : null },
      { nome: 'Leads (Ads)', icon: '🎯', valor: Math.round(leadsAds), ratio: totalCliques > 0 ? leadsAds / totalCliques : null },
      { nome: 'Deals criados (CRM)', icon: '📋', valor: dealsCriados.length, ratio: leadsAds > 0 ? dealsCriados.length / leadsAds : null },
      { nome: 'Qualificados', icon: '✅', valor: qualificados, ratio: dealsCriados.length > 0 ? qualificados / dealsCriados.length : null },
      { nome: 'Em Proposta', icon: '📨', valor: propostas, ratio: qualificados > 0 ? propostas / qualificados : null },
      { nome: 'Vendas', icon: '🏆', valor: ganhos, ratio: propostas > 0 ? ganhos / propostas : null },
    ];
    res.json({
      periodo: { start: since, end: until },
      etapas,
      receita_ganha: receitaGanha,
      por_stage: porStage,
      total_deals: dealsCriados.length,
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === VENDAS POR CAMPANHA (cruzamento Meta+Google × Zoho Fechado Ganho) ===
// Resolve "Qual campanha vendeu de fato?" pegando spend declarado + revenue real (Zoho).
// Match fuzzy: tokeniza campaign_name e Lead_Source, conta overlap >=2 tokens significativos.
function _vpcTokenize(s) {
  if (!s) return [];
  const STOP = new Set(['tdf','br','meta','google','leadad','ctwa','campanha','ad','conv','utm','fb','ig']);
  return String(s)
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(t => t && t.length >= 3 && !STOP.has(t) && !/^\d+$/.test(t));
}
function _vpcScoreMatch(campaignTokens, leadSourceTokens) {
  if (!campaignTokens.length || !leadSourceTokens.length) return 0;
  const setLS = new Set(leadSourceTokens);
  let hits = 0;
  for (const t of campaignTokens) if (setLS.has(t)) hits++;
  return hits;
}
app.get('/trafego/vendas-por-campanha', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  try {
    const periodo = (req.query.start && req.query.end) ? { start: req.query.start, end: req.query.end } : null;
    const days = periodo ? null : Math.max(1, Math.min(365, parseInt(req.query.days, 10) || 30));
    const sinceMs = periodo ? new Date(periodo.start + 'T00:00:00-03:00').getTime() : Date.now() - days * 86400000;
    const untilMs = periodo ? new Date(periodo.end + 'T23:59:59-03:00').getTime() : Date.now();
    const since = new Date(sinceMs).toISOString().slice(0,10);
    const until = new Date(untilMs).toISOString().slice(0,10);
    const metaPeriod = periodo || `last_${days}_d`;

    const [gCamps, mCamps, dealsGanho] = await Promise.all([
      googleAds.getCampaignMetrics(periodo || days).catch(() => []),
      metaAds.getCampaigns(metaPeriod).catch(() => []),
      zohoSearch(
        `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${since},${until}))`,
        'Deal_Name,Amount,Owner,Closing_Date,Lead_Source,Pipeline,Tier_Lead,Created_Time',
        300,
      ).catch(() => []),
    ]);

    // Catálogo de campanhas (todas com spend > 0)
    const campanhas = [];
    for (const c of gCamps) {
      if ((c.cost || 0) <= 0 && (c.impressions || 0) <= 0) continue;
      campanhas.push({
        platform: 'Google',
        id: String(c.id || c.campaign_id || ''),
        name: c.name || c.campaign_name || '',
        spend: c.cost || 0,
        leads_plataforma: c.conversions || 0,
        impressions: c.impressions || 0,
        clicks: c.clicks || 0,
        tokens: _vpcTokenize(c.name || ''),
      });
    }
    for (const c of mCamps) {
      if ((c.spend || 0) <= 0 && (c.impressions || 0) <= 0) continue;
      campanhas.push({
        platform: 'Meta',
        id: String(c.id || ''),
        name: c.name || '',
        spend: c.spend || 0,
        leads_plataforma: c.leads || 0,
        impressions: c.impressions || 0,
        clicks: c.clicks || 0,
        tokens: _vpcTokenize(c.name || ''),
      });
    }

    // Match deals → campanha (fuzzy por tokens em Lead_Source)
    const semMatch = [];
    for (const d of dealsGanho) {
      const lsTokens = _vpcTokenize(d.Lead_Source || '');
      let bestIdx = -1, bestScore = 0;
      for (let i = 0; i < campanhas.length; i++) {
        const score = _vpcScoreMatch(campanhas[i].tokens, lsTokens);
        if (score > bestScore) { bestScore = score; bestIdx = i; }
      }
      const dealLite = {
        id: d.id, nome: d.Deal_Name, amount: parseFloat(d.Amount) || 0,
        owner: d.Owner?.name || '', closing: d.Closing_Date,
        lead_source: d.Lead_Source || '', tier: d.Tier_Lead || '',
      };
      if (bestIdx >= 0 && bestScore >= 2) {
        const c = campanhas[bestIdx];
        c.deals = c.deals || [];
        c.deals.push({ ...dealLite, match_score: bestScore });
      } else {
        semMatch.push({ ...dealLite, match_score: bestScore });
      }
    }

    // Calcula totais por campanha
    for (const c of campanhas) {
      c.deals = c.deals || [];
      c.deals_won = c.deals.length;
      c.revenue = c.deals.reduce((s, d) => s + d.amount, 0);
      c.roas_real = c.spend > 0 ? c.revenue / c.spend : null;
      c.cpa_real = c.deals_won > 0 ? c.spend / c.deals_won : null;
      // top 10 maiores
      c.deals.sort((a,b) => b.amount - a.amount);
      c.deals_top = c.deals.slice(0, 10);
      delete c.tokens; // limpa antes de enviar
    }

    // Ordena por revenue desc
    campanhas.sort((a,b) => b.revenue - a.revenue);

    const totalSpend = campanhas.reduce((s,c) => s + c.spend, 0);
    const totalRevenue = campanhas.reduce((s,c) => s + c.revenue, 0);
    const totalWon = campanhas.reduce((s,c) => s + c.deals_won, 0);
    const totalSemMatchRev = semMatch.reduce((s,d) => s + d.amount, 0);

    res.json({
      periodo: { start: since, end: until },
      campanhas,
      sem_match: {
        count: semMatch.length,
        revenue: totalSemMatchRev,
        deals: semMatch.sort((a,b) => b.amount - a.amount).slice(0, 50),
      },
      total: {
        spend: totalSpend,
        revenue: totalRevenue,
        deals_won: totalWon,
        roas: totalSpend > 0 ? totalRevenue / totalSpend : null,
        revenue_atribuido_pct: (totalRevenue + totalSemMatchRev) > 0
          ? totalRevenue / (totalRevenue + totalSemMatchRev) : 0,
        revenue_total_zoho: totalRevenue + totalSemMatchRev,
      },
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === DASHBOARD EXECUTIVO — endpoints novos ===

// Resumo do Dia: KPIs hoje + ontem comparado + melhor/pior + alerta principal
// Breakdown por CANAL (Google / Meta IG / Meta FB) com vendas atribuídas, CAC e ROAS por canal
// Aceita ?data=YYYY-MM-DD (default hoje BRT). Compara com dia anterior.
app.get('/trafego/resumo-dia', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  try {
    const dataAlvo = req.query.data && /^\d{4}-\d{2}-\d{2}$/.test(req.query.data)
      ? req.query.data
      : todayBR();
    const dataAlvoMs = new Date(dataAlvo + 'T12:00:00-03:00').getTime();
    const hoje = dataAlvo;
    const ontem = new Date(dataAlvoMs - 86400000).toISOString().slice(0,10);
    const periodoHoje = { start: hoje, end: hoje };
    const periodoOntem = { start: ontem, end: ontem };

    const [gHoje, mHoje, gOntem, mOntem, mPlatHoje, mPlatOntem, won] = await Promise.all([
      googleAds.getCampaignMetrics(periodoHoje).catch(() => []),
      metaAds.getCampaigns(periodoHoje).catch(() => []),
      googleAds.getCampaignMetrics(periodoOntem).catch(() => []),
      metaAds.getCampaigns(periodoOntem).catch(() => []),
      metaAds.getLeadsByPlatform(periodoHoje).catch(() => ({})),
      metaAds.getLeadsByPlatform(periodoOntem).catch(() => ({})),
      getWonDealsCached().catch(() => []),
    ]);

    function agreg(g, m) {
      const invest = (g.reduce((s,c) => s + (c.cost_brl||0), 0)) + (m.reduce((s,c) => s + (c.spend_brl||0), 0));
      const leads = (g.reduce((s,c) => s + (c.conversions||0), 0)) + (m.reduce((s,c) => s + (c.leads||0), 0));
      const impressions = (g.reduce((s,c) => s + (c.impressions||0), 0)) + (m.reduce((s,c) => s + (c.impressions||0), 0));
      const clicks = (g.reduce((s,c) => s + (c.clicks||0), 0)) + (m.reduce((s,c) => s + (c.clicks||0), 0));
      const cpl = leads > 0 ? invest / leads : null;
      const ctr = impressions > 0 ? (clicks / impressions) * 100 : null;
      const cpc = clicks > 0 ? invest / clicks : null;
      return { invest, leads, impressions, clicks, cpl, ctr, cpc };
    }
    const dHoje = agreg(gHoje, mHoje);
    const dOntem = agreg(gOntem, mOntem);

    // Vendas do dia
    const wonHoje = (won || []).filter(d => d.Closing_Date === hoje);
    const wonOntem = (won || []).filter(d => d.Closing_Date === ontem);
    const receitaHoje = wonHoje.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const receitaOntem = wonOntem.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const cacHoje = wonHoje.length > 0 ? dHoje.invest / wonHoje.length : null;
    const roasHoje = dHoje.invest > 0 ? receitaHoje / dHoje.invest : null;

    // === BREAKDOWN POR CANAL (Google / Meta IG / Meta FB) ===
    // Agregações por canal
    const googleAgg = {
      invest: gHoje.reduce((s,c) => s + (c.cost_brl||0), 0),
      leads: gHoje.reduce((s,c) => s + (c.conversions||0), 0),
      impressions: gHoje.reduce((s,c) => s + (c.impressions||0), 0),
      clicks: gHoje.reduce((s,c) => s + (c.clicks||0), 0),
    };
    const igAgg = { invest: mPlatHoje.instagram?.spend || 0, leads: mPlatHoje.instagram?.leads || 0 };
    const fbAgg = { invest: mPlatHoje.facebook?.spend || 0, leads: mPlatHoje.facebook?.leads || 0 };
    const audAgg = { invest: mPlatHoje.audience_network?.spend || 0, leads: mPlatHoje.audience_network?.leads || 0 };
    const msgAgg = { invest: mPlatHoje.messenger?.spend || 0, leads: mPlatHoje.messenger?.leads || 0 };

    // Atribuição de vendas por canal (match Lead_Source)
    function canalDoLeadSource(ls) {
      if (!ls) return 'sem_atrib';
      const l = String(ls).toLowerCase();
      if (/google|gads|adwords|gclid/.test(l)) return 'google';
      if (/instagram|^ig\b|\big\b/.test(l)) return 'meta_ig';
      if (/facebook|^fb\b|\bfb\b|messenger/.test(l)) return 'meta_fb';
      if (/meta\b|leadad|ctwa|fbclid/.test(l)) return 'meta_geral';
      return 'sem_atrib';
    }
    const vendasPorCanal = { google:{ count:0, receita:0 }, meta_ig:{ count:0, receita:0 }, meta_fb:{ count:0, receita:0 }, meta_geral:{ count:0, receita:0 }, sem_atrib:{ count:0, receita:0 } };
    for (const v of wonHoje) {
      const canal = canalDoLeadSource(v.Lead_Source);
      vendasPorCanal[canal].count++;
      vendasPorCanal[canal].receita += parseFloat(v.Amount) || 0;
    }
    // Função pra montar canal final com CAC + ROAS + CPL
    function montaCanal(label, color, agg, vendas) {
      const cpl = agg.leads > 0 ? agg.invest / agg.leads : null;
      const cac = vendas.count > 0 ? agg.invest / vendas.count : null;
      const roas = agg.invest > 0 ? vendas.receita / agg.invest : null;
      const ctr = agg.impressions > 0 ? (agg.clicks/agg.impressions)*100 : null;
      return {
        label, color,
        invest: agg.invest, leads: agg.leads,
        impressions: agg.impressions || null, clicks: agg.clicks || null,
        ctr, cpl,
        vendas: vendas.count, receita: vendas.receita,
        cac, roas,
      };
    }
    const canais = {
      google: montaCanal('Google', '#fbbc04', googleAgg, vendasPorCanal.google),
      meta_ig: montaCanal('Instagram', '#e4405f', igAgg, vendasPorCanal.meta_ig),
      meta_fb: montaCanal('Facebook', '#1877f2', fbAgg, vendasPorCanal.meta_fb),
    };
    if (audAgg.invest > 0 || audAgg.leads > 0) canais.audience_network = montaCanal('Audience Network', '#888', audAgg, { count:0, receita:0 });
    if (msgAgg.invest > 0 || msgAgg.leads > 0) canais.messenger = montaCanal('Messenger', '#a371f7', msgAgg, { count:0, receita:0 });
    // Meta atribuição genérica (quando não dá pra distinguir IG/FB no Lead_Source)
    const vendasMetaGeral = vendasPorCanal.meta_geral;
    const investMetaTotal = igAgg.invest + fbAgg.invest + audAgg.invest + msgAgg.invest;
    if (vendasMetaGeral.count > 0) {
      canais.meta_geral_extra = {
        label: 'Meta (genérico)', color: '#9ca3af',
        invest: 0, leads: 0, vendas: vendasMetaGeral.count, receita: vendasMetaGeral.receita,
        cac: null, roas: null,
        nota: 'Lead_Source diz "Meta" mas sem distinguir IG/FB. Atribuído como receita extra do mix Meta.',
      };
    }
    if (vendasPorCanal.sem_atrib.count > 0) {
      canais.sem_atribuicao = {
        label: 'Sem atribuição', color: '#666',
        invest: 0, leads: 0, vendas: vendasPorCanal.sem_atrib.count, receita: vendasPorCanal.sem_atrib.receita,
        nota: 'Lead_Source vazio ou não match com plataforma.',
      };
    }

    // Melhor / pior campanha (por ROAS hoje, fallback CPL)
    const todasCamps = [
      ...gHoje.map(c => ({ plat:'Google', name:c.name, invest:c.cost_brl||0, leads:c.conversions||0, impressions:c.impressions||0, clicks:c.clicks||0, ctr:c.ctr||null, id:c.id })),
      ...mHoje.map(c => ({ plat:'Meta', name:c.name, invest:c.spend_brl||0, leads:c.leads||0, impressions:c.impressions||0, clicks:c.clicks||0, ctr:c.ctr||null, id:c.id })),
    ].filter(c => c.invest > 0);
    todasCamps.forEach(c => { c.cpl = c.leads > 0 ? c.invest / c.leads : null; });
    const comInvest = todasCamps.filter(c => c.invest >= 10);
    const melhor = comInvest.filter(c => c.leads > 0).sort((a,b) => (a.cpl||1e9) - (b.cpl||1e9))[0] || null;
    const pior = comInvest.filter(c => c.leads === 0 || (c.cpl && c.cpl > 200)).sort((a,b) => b.invest - a.invest)[0] || null;

    // Delta vs ontem
    function delta(a, b) {
      if (!a || !b) return null;
      const d = ((a - b) / b) * 100;
      return Number.isFinite(d) ? Math.round(d) : null;
    }

    // Ação recomendada (lógica simples — IA real fica em /trafego/gestor-ia)
    let acao = '✅ Tudo no controle. Continue monitorando.';
    let acao_cor = '#22c55e';
    if (pior && pior.invest >= 50 && pior.leads === 0) {
      acao = `🔴 Pause "${pior.name}" — ${trMoneyServer(pior.invest)} sem 1 lead sequer.`;
      acao_cor = '#ef4444';
    } else if (melhor && melhor.cpl && melhor.cpl < 30 && melhor.invest < 100) {
      acao = `🚀 Aumente "${melhor.name}" — CPL ${trMoneyServer(melhor.cpl)} é excelente, escale verba.`;
      acao_cor = '#22c55e';
    } else if (dHoje.invest > 100 && wonHoje.length === 0 && dHoje.leads >= 5) {
      acao = `⚠️ ${dHoje.leads} leads hoje, 0 vendas. Cobre closer pra atender mais rápido.`;
      acao_cor = '#fbbf24';
    } else if (dHoje.cpl && dOntem.cpl && dHoje.cpl > dOntem.cpl * 1.3) {
      acao = `📈 CPL subiu ${delta(dHoje.cpl, dOntem.cpl)}% vs ontem. Revise criativos/keywords.`;
      acao_cor = '#fbbf24';
    }

    function deltaAbs(a, b) {
      if (a == null || b == null) return null;
      return Math.round(a - b);
    }
    res.json({
      hoje, ontem,
      kpis: {
        invest: { hoje: dHoje.invest, ontem: dOntem.invest, delta_pct: delta(dHoje.invest, dOntem.invest), delta_abs: deltaAbs(dHoje.invest, dOntem.invest) },
        leads: { hoje: dHoje.leads, ontem: dOntem.leads, delta_pct: delta(dHoje.leads, dOntem.leads), delta_abs: deltaAbs(dHoje.leads, dOntem.leads) },
        cpl:   { hoje: dHoje.cpl, ontem: dOntem.cpl, delta_pct: delta(dHoje.cpl, dOntem.cpl), delta_abs: deltaAbs(dHoje.cpl, dOntem.cpl) },
        vendas:{ hoje: wonHoje.length, ontem: wonOntem.length, delta_pct: delta(wonHoje.length, wonOntem.length), delta_abs: deltaAbs(wonHoje.length, wonOntem.length) },
        receita:{ hoje: receitaHoje, ontem: receitaOntem, delta_pct: delta(receitaHoje, receitaOntem), delta_abs: deltaAbs(receitaHoje, receitaOntem) },
        cac:   { hoje: cacHoje, ontem: wonOntem.length > 0 ? dOntem.invest / wonOntem.length : null },
        roas:  { hoje: roasHoje, ontem: dOntem.invest > 0 ? receitaOntem / dOntem.invest : null },
        ctr:   { hoje: dHoje.ctr, ontem: dOntem.ctr, delta_pct: delta(dHoje.ctr, dOntem.ctr) },
        cpc:   { hoje: dHoje.cpc, ontem: dOntem.cpc, delta_pct: delta(dHoje.cpc, dOntem.cpc) },
      },
      canais,
      melhor_campanha: melhor,
      pior_campanha: pior,
      acao_recomendada: { texto: acao, cor: acao_cor },
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});
function trMoneyServer(v) { return v == null ? '—' : 'R$ '+Math.round(Number(v)).toLocaleString('pt-BR'); }

// Comparação A vs B com qualquer período custom
// Query: ?a_start=YYYY-MM-DD&a_end=YYYY-MM-DD&b_start=YYYY-MM-DD&b_end=YYYY-MM-DD
// Retorna métricas dos 2 períodos + delta_pct + delta_abs
app.get('/trafego/comparar-periodos', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const { a_start, a_end, b_start, b_end } = req.query;
  if (!a_start || !a_end || !b_start || !b_end) {
    return res.status(400).json({ error: 'Params obrigatórios: a_start, a_end, b_start, b_end (YYYY-MM-DD)' });
  }
  const re = /^\d{4}-\d{2}-\d{2}$/;
  if (![a_start, a_end, b_start, b_end].every(d => re.test(d))) {
    return res.status(400).json({ error: 'Formato de data inválido (use YYYY-MM-DD)' });
  }
  const periodoA = { start: a_start, end: a_end };
  const periodoB = { start: b_start, end: b_end };
  try {
    const [gA, mA, gB, mB, mPlatA, mPlatB, won] = await Promise.all([
      googleAds.getCampaignMetrics(periodoA).catch(() => []),
      metaAds.getCampaigns(periodoA).catch(() => []),
      googleAds.getCampaignMetrics(periodoB).catch(() => []),
      metaAds.getCampaigns(periodoB).catch(() => []),
      metaAds.getLeadsByPlatform(periodoA).catch(() => ({})),
      metaAds.getLeadsByPlatform(periodoB).catch(() => ({})),
      getWonDealsCached().catch(() => []),
    ]);
    function agreg(g, m, mPlat, ini, fim) {
      const investG = g.reduce((s,c) => s + (c.cost_brl||0), 0);
      const investM = m.reduce((s,c) => s + (c.spend_brl||0), 0);
      const leadsG = g.reduce((s,c) => s + (c.conversions||0), 0);
      const leadsM = m.reduce((s,c) => s + (c.leads||0), 0);
      const impressions = g.reduce((s,c) => s + (c.impressions||0), 0) + m.reduce((s,c) => s + (c.impressions||0), 0);
      const clicks = g.reduce((s,c) => s + (c.clicks||0), 0) + m.reduce((s,c) => s + (c.clicks||0), 0);
      const iniMs = new Date(ini + 'T00:00:00-03:00').getTime();
      const fimMs = new Date(fim + 'T23:59:59-03:00').getTime();
      const wonP = (won||[]).filter(d => {
        const cd = d.Closing_Date ? new Date(d.Closing_Date).getTime() : 0;
        return cd >= iniMs && cd <= fimMs;
      });
      const receita = wonP.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
      const invest = investG + investM;
      const leads = leadsG + leadsM;
      return {
        invest, invest_google: investG, invest_meta: investM,
        invest_ig: mPlat.instagram?.spend || 0,
        invest_fb: mPlat.facebook?.spend || 0,
        leads, leads_google: leadsG, leads_meta: leadsM,
        leads_ig: mPlat.instagram?.leads || 0,
        leads_fb: mPlat.facebook?.leads || 0,
        impressions, clicks,
        cpl: leads > 0 ? invest / leads : null,
        ctr: impressions > 0 ? (clicks/impressions)*100 : null,
        cpc: clicks > 0 ? invest/clicks : null,
        vendas: wonP.length, receita,
        cac: wonP.length > 0 ? invest / wonP.length : null,
        roas: invest > 0 ? receita / invest : null,
      };
    }
    const A = agreg(gA, mA, mPlatA, a_start, a_end);
    const B = agreg(gB, mB, mPlatB, b_start, b_end);
    function comp(a, b) {
      if (a == null || b == null) return { pct: null, abs: null };
      const abs = a - b;
      const pct = b !== 0 ? Math.round((abs / b) * 100) : null;
      return { pct, abs };
    }
    const deltas = {};
    for (const k of Object.keys(A)) {
      deltas[k] = comp(A[k], B[k]);
    }
    res.json({
      periodo_a: periodoA,
      periodo_b: periodoB,
      a: A, b: B, deltas,
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Série temporal: dados diários por N dias (Investimento, Leads, CPL, CAC, ROAS, CTR)
app.get('/trafego/serie-temporal', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const dias = Math.max(3, Math.min(60, parseInt(req.query.dias, 10) || 14));
  try {
    const hojeMs = Date.now();
    const dates = [];
    for (let i = dias - 1; i >= 0; i--) {
      dates.push(new Date(hojeMs - i * 86400000).toISOString().slice(0,10));
    }
    // Roda chunks de 4 dias em paralelo pra não estourar API
    const won = await getWonDealsCached().catch(() => []);
    const series = [];
    for (let i = 0; i < dates.length; i += 4) {
      const lote = dates.slice(i, i+4);
      const results = await Promise.all(lote.map(async d => {
        const periodo = { start: d, end: d };
        const [g, m] = await Promise.all([
          googleAds.getCampaignMetrics(periodo).catch(() => []),
          metaAds.getCampaigns(periodo).catch(() => []),
        ]);
        const invest = (g.reduce((s,c) => s + (c.cost_brl||0), 0)) + (m.reduce((s,c) => s + (c.spend_brl||0), 0));
        const leads = (g.reduce((s,c) => s + (c.conversions||0), 0)) + (m.reduce((s,c) => s + (c.leads||0), 0));
        const impressions = (g.reduce((s,c) => s + (c.impressions||0), 0)) + (m.reduce((s,c) => s + (c.impressions||0), 0));
        const clicks = (g.reduce((s,c) => s + (c.clicks||0), 0)) + (m.reduce((s,c) => s + (c.clicks||0), 0));
        const wonDia = (won || []).filter(x => x.Closing_Date === d);
        const receita = wonDia.reduce((s,x) => s + (parseFloat(x.Amount)||0), 0);
        return {
          data: d,
          dow: ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][new Date(d+'T12:00:00-03:00').getDay()],
          invest_google: g.reduce((s,c) => s + (c.cost_brl||0), 0),
          invest_meta: m.reduce((s,c) => s + (c.spend_brl||0), 0),
          invest, leads, impressions, clicks,
          cpl: leads > 0 ? invest / leads : null,
          ctr: impressions > 0 ? (clicks/impressions)*100 : null,
          cpc: clicks > 0 ? invest/clicks : null,
          vendas: wonDia.length,
          receita,
          cac: wonDia.length > 0 ? invest / wonDia.length : null,
          roas: invest > 0 ? receita / invest : null,
        };
      }));
      series.push(...results);
    }
    res.json({ dias, series });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Alertas automáticos com regras de negócio
app.get('/trafego/alertas-auto', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const dias = Math.max(1, Math.min(30, parseInt(req.query.dias, 10) || 7));
  try {
    const periodo = (req.query.start && req.query.end)
      ? { start: req.query.start, end: req.query.end }
      : dias;
    const metaPeriod = (typeof periodo === 'object') ? periodo : `last_${dias}_d`;
    const [gCamps, mCamps, won] = await Promise.all([
      googleAds.getCampaignMetrics(periodo).catch(() => []),
      metaAds.getCampaigns(metaPeriod).catch(() => []),
      getWonDealsCached().catch(() => []),
    ]);
    const alertas = [];

    // Médias do período pra usar como baseline (EXCLUI campanhas em aprendizado)
    const todas = [
      ...gCamps.map(c => ({ plat:'Google', id:c.id, name:c.name, invest:c.cost_brl||0, leads:c.conversions||0, impressions:c.impressions||0, clicks:c.clicks||0, ctr:c.ctr, freq:null, idade_dias:c.idade_dias, em_aprendizado:c.em_aprendizado })),
      ...mCamps.map(c => ({ plat:'Meta', id:c.id, name:c.name, invest:c.spend_brl||0, leads:c.leads||0, impressions:c.impressions||0, clicks:c.clicks||0, ctr:c.ctr, freq:c.frequency, idade_dias:c.idade_dias, em_aprendizado:c.em_aprendizado })),
    ];
    todas.forEach(c => { c.cpl = c.leads > 0 ? c.invest / c.leads : null; });
    // Médias só com campanhas maduras (fora de aprendizado) pra não distorcer baseline
    const maduras = todas.filter(c => !c.em_aprendizado && c.invest >= 10);
    const comInvest = todas.filter(c => c.invest >= 10);
    const cplsValidos = maduras.filter(c => c.cpl != null).map(c => c.cpl);
    const cplMedio = cplsValidos.length ? cplsValidos.reduce((s,x) => s+x, 0) / cplsValidos.length : null;
    const ctrMedio = maduras.length ? maduras.reduce((s,c) => s+(c.ctr||0), 0) / maduras.length : null;

    // Regras — campanhas em aprendizado: NÃO geram alertas críticos, só info
    for (const c of comInvest) {
      // Em aprendizado: gera alerta INFO + skip os críticos
      if (c.em_aprendizado) {
        // Cria 1 alerta info mostrando que está aprendendo (só se gastou >R$30)
        if (c.invest >= 30) {
          alertas.push({
            tipo: 'em_aprendizado', severidade: 'info',
            titulo: '🆕 Campanha em fase de aprendizado',
            campanha: c.name, plataforma: c.plat, campanha_id: c.id,
            detalhe: `${c.idade_dias != null ? c.idade_dias+'d de vida' : 'recém-criada'} · ${c.leads} leads · ${trMoneyServer(c.invest)} gastos. Algoritmo precisa de tempo${c.plat==='Meta'?' (~50 conv pra sair do learning)':' (~7d ou 30 conv)'}.`,
            acao_sugerida: '⛔ NÃO mexer ainda — esperar maturação',
          });
        }
        continue; // pula os outros alertas pra essa campanha
      }
      // Gastando sem gerar lead — só pra campanhas MADURAS (>= 7d OU >= 30 conv histórico)
      if (c.invest >= 50 && c.leads === 0) {
        alertas.push({
          tipo: 'gasto_sem_lead', severidade: 'alta',
          titulo: 'Gastando sem gerar lead',
          campanha: c.name, plataforma: c.plat, campanha_id: c.id,
          detalhe: `${trMoneyServer(c.invest)} gastos · 0 leads · ${c.idade_dias != null ? c.idade_dias+'d de vida' : '(idade desconhecida)'}`,
          acao_sugerida: 'Pausar campanha',
          acao_endpoint: c.plat === 'Google' ? `/trafego/google/campaign/${c.id}/pause` : `/trafego/meta/campaign/${c.id}/pause`,
        });
      }
      // CPL muito acima da média (50%+ acima)
      if (cplMedio && c.cpl && c.cpl > cplMedio * 1.5 && c.invest >= 30) {
        alertas.push({
          tipo: 'cpl_alto', severidade: 'media',
          titulo: 'CPL acima da média do período',
          campanha: c.name, plataforma: c.plat, campanha_id: c.id,
          detalhe: `CPL ${trMoneyServer(c.cpl)} vs média ${trMoneyServer(cplMedio)} (+${Math.round((c.cpl/cplMedio-1)*100)}%)`,
          acao_sugerida: 'Revisar criativos/keywords',
        });
      }
      // CTR baixo (Meta + Google) — só com volume significativo + fora aprendizado
      if (c.impressions >= 2000 && c.ctr != null && c.ctr < 0.8) {
        alertas.push({
          tipo: 'ctr_baixo', severidade: 'media',
          titulo: 'CTR baixo (criativo cansado?)',
          campanha: c.name, plataforma: c.plat, campanha_id: c.id,
          detalhe: `CTR ${(c.ctr).toFixed(2)}% (ideal >1%) · ${c.impressions.toLocaleString('pt-BR')} impressões`,
          acao_sugerida: 'Trocar criativo/título',
        });
      }
      // Frequência alta no Meta — exige idade >7d
      if (c.plat === 'Meta' && c.freq != null && c.freq > 4 && c.invest >= 30) {
        alertas.push({
          tipo: 'freq_alta', severidade: 'media',
          titulo: 'Frequência alta — público saturado',
          campanha: c.name, plataforma: 'Meta', campanha_id: c.id,
          detalhe: `Freq ${c.freq.toFixed(1)} · público está saturando`,
          acao_sugerida: 'Trocar criativo ou expandir audiência',
        });
      }
      // Boa campanha pra escalar — exige >=7d (Meta dispara em learning se mexer)
      if (cplMedio && c.cpl && c.cpl < cplMedio * 0.6 && c.leads >= 3 && c.invest < 200 && (c.idade_dias == null || c.idade_dias >= 7)) {
        alertas.push({
          tipo: 'oportunidade_escala', severidade: 'oportunidade',
          titulo: '🚀 Oportunidade de escalar verba',
          campanha: c.name, plataforma: c.plat, campanha_id: c.id,
          detalhe: `CPL ${trMoneyServer(c.cpl)} (${Math.round((1-c.cpl/cplMedio)*100)}% abaixo da média) · ${c.leads} leads · só ${trMoneyServer(c.invest)} investido · ${c.idade_dias}d de vida`,
          acao_sugerida: 'Aumentar verba até 20% (acima disso reativa learning)',
        });
      }
    }

    // ROAS negativo (cruzar com Zoho — leads → vendas)
    const cutoffMs = (typeof periodo === 'object')
      ? new Date(periodo.start + 'T00:00:00-03:00').getTime()
      : Date.now() - dias * 86400000;
    const wonPeriodo = (won || []).filter(d => {
      const cd = d.Closing_Date ? new Date(d.Closing_Date).getTime() : 0;
      return cd >= cutoffMs;
    });
    const totalInvest = todas.reduce((s,c) => s + c.invest, 0);
    const receitaPeriodo = wonPeriodo.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const totalLeads = todas.reduce((s,c) => s + c.leads, 0);
    if (totalInvest >= 200 && receitaPeriodo / totalInvest < 1) {
      alertas.push({
        tipo: 'roas_negativo', severidade: 'alta',
        titulo: 'ROAS geral abaixo de 1x',
        detalhe: `Investido ${trMoneyServer(totalInvest)} · receita atribuída ${trMoneyServer(receitaPeriodo)} · ROAS ${(receitaPeriodo/totalInvest).toFixed(2)}x`,
        acao_sugerida: 'Cortar campanhas ruins + reforçar pipeline ativo',
      });
    }
    // Leads MUITOS, vendas POUCAS
    if (totalLeads >= 30 && wonPeriodo.length / totalLeads < 0.05) {
      alertas.push({
        tipo: 'lead_sem_venda', severidade: 'media',
        titulo: 'Volume de lead alto, conversão baixa',
        detalhe: `${totalLeads} leads · ${wonPeriodo.length} vendas (${((wonPeriodo.length/totalLeads)*100).toFixed(1)}% de conversão)`,
        acao_sugerida: 'Auditar atendimento closer (analisar funil em /gestao/raiox-vendedor)',
      });
    }

    // Ordena: alta > media > oportunidade > info
    const ordem = { alta: 0, media: 1, oportunidade: 2, info: 3, baixa: 4 };
    alertas.sort((a,b) => (ordem[a.severidade]||9) - (ordem[b.severidade]||9));

    res.json({
      periodo: typeof periodo === 'object' ? periodo : { dias },
      total: alertas.length,
      por_severidade: {
        alta: alertas.filter(a => a.severidade === 'alta').length,
        media: alertas.filter(a => a.severidade === 'media').length,
        oportunidade: alertas.filter(a => a.severidade === 'oportunidade').length,
        info: alertas.filter(a => a.severidade === 'info').length,
      },
      alertas,
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === SPEED TO LEAD: tempo entre criação do lead e primeiro contato (WATI outbound) ===
// Cruzamento: Zoho deals criados últimas N horas + WATI getMessages.
// Cache de speed por dealId em kv pra não estourar API a cada refresh.
app.get('/trafego/speed-to-lead', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const horas = Math.max(1, Math.min(168, parseInt(req.query.horas, 10) || 48));
  const limite = Math.max(10, Math.min(80, parseInt(req.query.limite, 10) || 50));
  try {
    const cutoffMs = Date.now() - horas * 3600000;
    const cutoffISO = new Date(cutoffMs).toISOString();
    const deals = await zohoSearch(
      `(Created_Time:greater_equal:${cutoffISO})`,
      'Deal_Name,Telefone_contato,Owner,Lead_Source,Stage,Tier_Lead,Created_Time,Last_Activity_Time,Pipeline,Amount',
      200,
    ).catch(() => []);
    const filtered = deals
      .filter(d => d.Telefone_contato)
      .sort((a,b) => (b.Created_Time||'').localeCompare(a.Created_Time||''))
      .slice(0, limite);

    const cacheKey = 'speed_lead_cache';
    const cache = (typeof _kvCache[cacheKey] === 'object') ? _kvCache[cacheKey] : {};
    const items = [];

    for (let i = 0; i < filtered.length; i += 4) {
      const lote = filtered.slice(i, i+4);
      const lots = await Promise.all(lote.map(async d => {
        // Cache hit (por dealId — tempo até primeiro contato não muda depois de respondido)
        if (cache[d.id] && cache[d.id].speed_min != null) {
          return { ...cache[d.id], deal: d };
        }
        const phoneClean = normalizarPhoneWati(d.Telefone_contato);
        const createdMs = new Date(d.Created_Time).getTime();
        let firstOutboundMs = null;
        try {
          const url = `${WATI_BASE}/api/v1/getMessages/${phoneClean}?pageSize=80&pageNumber=0`;
          const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
          if (r.ok) {
            const j = await r.json();
            const msgs = j.messages?.items || j.items || j.messages || [];
            // Itera buscando primeira msg outbound (owner=true) APÓS Created_Time
            const ordenadas = msgs
              .map(m => ({
                owner: m.owner === true || m.fromMe === true || m.eventType === 'sentMessage',
                ts: m.created || m.timestamp || 0,
                texto: m.text || m.body || m.finalText || '',
              }))
              .filter(m => m.texto)
              .sort((a,b) => (a.ts*1000 || 0) - (b.ts*1000 || 0));
            const firstOut = ordenadas.find(m => m.owner && (m.ts*1000 || 0) >= createdMs - 60000);
            if (firstOut) firstOutboundMs = firstOut.ts * 1000;
          }
        } catch(_){}
        const speed_min = firstOutboundMs ? Math.max(0, (firstOutboundMs - createdMs) / 60000) : null;
        const result = {
          dealId: d.id,
          speed_min,
          status: speed_min == null ? 'sem_contato' : speed_min <= 5 ? 'flash' : speed_min <= 30 ? 'rapido' : speed_min <= 120 ? 'lento' : speed_min <= 1440 ? 'muito_lento' : 'critico',
          checked_at: Date.now(),
        };
        cache[d.id] = result;
        return { ...result, deal: d };
      }));
      items.push(...lots);
    }
    kvSet(cacheKey, cache).catch(() => {});

    // Distribuição
    const total = items.length;
    const dist = {
      flash: 0,        // <=5min
      rapido: 0,       // 5-30min
      lento: 0,        // 30min-2h
      muito_lento: 0,  // 2h-24h
      critico: 0,      // >24h
      sem_contato: 0,  // ainda sem resposta
    };
    items.forEach(it => { if (dist[it.status] != null) dist[it.status]++; });
    const respondidos = items.filter(it => it.speed_min != null);
    const speedMedio = respondidos.length ? respondidos.reduce((s,it) => s+it.speed_min, 0) / respondidos.length : null;
    const speedMediano = respondidos.length ? [...respondidos].sort((a,b) => a.speed_min - b.speed_min)[Math.floor(respondidos.length/2)]?.speed_min : null;

    // Lista dos críticos (sem contato) ordenada por valor + tier
    const tierRank = { Diamante:0, Ouro:1, Prata:2, Bronze:3, '':4 };
    const criticos = items
      .filter(it => it.status === 'sem_contato' || it.status === 'critico' || it.status === 'muito_lento')
      .sort((a,b) => {
        const ta = tierRank[a.deal.Tier_Lead||''] ?? 4;
        const tb = tierRank[b.deal.Tier_Lead||''] ?? 4;
        if (ta !== tb) return ta - tb;
        return (parseFloat(b.deal.Amount)||0) - (parseFloat(a.deal.Amount)||0);
      })
      .slice(0, 30)
      .map(it => ({
        dealId: it.dealId,
        nome: it.deal.Deal_Name,
        telefone: it.deal.Telefone_contato,
        owner: it.deal.Owner?.name || '',
        tier: it.deal.Tier_Lead || '',
        valor: parseFloat(it.deal.Amount) || 0,
        lead_source: it.deal.Lead_Source || '',
        criado: it.deal.Created_Time,
        idade_horas: Math.round((Date.now() - new Date(it.deal.Created_Time).getTime()) / 3600000),
        speed_min: it.speed_min,
        status: it.status,
      }));

    res.json({
      total_analisados: total,
      janela_horas: horas,
      dist,
      pct: {
        flash: total > 0 ? Math.round(dist.flash/total*100) : 0,
        rapido: total > 0 ? Math.round((dist.flash+dist.rapido)/total*100) : 0,
        sem_contato: total > 0 ? Math.round(dist.sem_contato/total*100) : 0,
      },
      speed_medio_min: speedMedio,
      speed_mediano_min: speedMediano,
      criticos,
      // Diagnóstico textual
      diagnostico: (() => {
        const semCont = dist.sem_contato + dist.critico;
        if (total < 5) return { cor: '#9ca3af', texto: 'Pouco volume — sem dados suficientes pra diagnóstico (menos de 5 leads na janela).' };
        if (semCont > total * 0.3) return { cor: '#ef4444', texto: `🔴 Crítico — ${semCont}/${total} leads (${Math.round(semCont/total*100)}%) sem contato adequado. Speed to lead está prejudicando conversão.` };
        if (speedMedio && speedMedio > 60) return { cor: '#f59e0b', texto: `🟡 Atenção — speed médio ${Math.round(speedMedio)}min (>1h). Lead ficou frio antes do contato.` };
        if (dist.flash / total >= 0.5) return { cor: '#10b981', texto: `🟢 Excelente — ${Math.round(dist.flash/total*100)}% dos leads contatados em <5min.` };
        return { cor: '#10b981', texto: `🟢 Saudável — speed médio ${Math.round(speedMedio||0)}min. Time atendendo dentro do esperado.` };
      })(),
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === CAC POR PRODUTO ===
// Categoriza campanhas/leads em produtos (Filtro Entrada / Bebedouro / Iron Free / Scale Stop / Purificador / Refil)
// usando regex em campaign.name e Lead_Source. Cruza com Fechado Ganho.
app.get('/trafego/cac-por-produto', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const dias = Math.max(7, Math.min(90, parseInt(req.query.dias, 10) || 30));
  try {
    const periodo = (req.query.start && req.query.end) ? { start: req.query.start, end: req.query.end } : null;
    const days = periodo ? null : dias;
    const metaPeriod = periodo || `last_${days}_d`;
    const sinceMs = periodo ? new Date(periodo.start + 'T00:00:00-03:00').getTime() : Date.now() - days * 86400000;
    const untilMs = periodo ? new Date(periodo.end + 'T23:59:59-03:00').getTime() : Date.now();
    const sinceStr = new Date(sinceMs).toISOString().slice(0,10);
    const untilStr = new Date(untilMs).toISOString().slice(0,10);

    const [gCamps, mCamps, won] = await Promise.all([
      googleAds.getCampaignMetrics(periodo || days).catch(() => []),
      metaAds.getCampaigns(metaPeriod).catch(() => []),
      zohoSearch(
        `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${sinceStr},${untilStr}))`,
        'Deal_Name,Amount,Lead_Source,Produto_Vendido,Pipeline,Closing_Date',
        300,
      ).catch(() => []),
    ]);

    function categorizar(nome, leadSource, produto, pipeline) {
      const t = `${nome||''} ${leadSource||''} ${produto||''} ${pipeline||''}`.toLowerCase();
      if (/iron\s*free|ironfree/.test(t)) return 'Iron Free';
      if (/scale\s*stop|scalestop/.test(t)) return 'Scale Stop';
      if (/bebedour/.test(t)) return 'Bebedouro';
      if (/refil|aguasana|planeta\s*agua|wfs|sana|bbl|over\s*flow/.test(t)) return 'Refil';
      if (/purificador|af.?15|af.?25|af.?60|af.?100|af.?200|bliss|soft|premium/.test(t)) return 'Purificador';
      if (/filtro.?(de.?)?entrada|n[aã]o.?tratada|po[cç]o|caixa.?d.?[áa]gua/.test(t)) return 'Filtro de Entrada';
      if (/condom[ií]nio/.test(t)) return 'Condomínio';
      return 'Outros';
    }

    // Agreg por produto: invest, vendas, receita, leads
    const por = {}; // produto → { invest, leads, vendas, receita }
    function bumpInvest(produto, invest, leads) {
      if (!por[produto]) por[produto] = { invest:0, leads:0, vendas:0, receita:0 };
      por[produto].invest += invest;
      por[produto].leads += leads;
    }
    for (const c of gCamps) {
      const p = categorizar(c.name, '', '', '');
      bumpInvest(p, c.cost_brl||0, c.conversions||0);
    }
    for (const c of mCamps) {
      const p = categorizar(c.name, '', '', '');
      bumpInvest(p, c.spend_brl||0, c.leads||0);
    }
    for (const v of won) {
      const p = categorizar('', v.Lead_Source, v.Produto_Vendido, v.Pipeline);
      if (!por[p]) por[p] = { invest:0, leads:0, vendas:0, receita:0 };
      por[p].vendas++;
      por[p].receita += parseFloat(v.Amount) || 0;
    }
    // Calcula CAC e ROAS por produto
    const lista = Object.entries(por)
      .map(([produto, m]) => ({
        produto,
        invest: m.invest,
        leads: m.leads,
        vendas: m.vendas,
        receita: m.receita,
        cpl: m.leads > 0 ? m.invest / m.leads : null,
        cac: m.vendas > 0 ? m.invest / m.vendas : null,
        roas: m.invest > 0 ? m.receita / m.invest : null,
        ticket_medio: m.vendas > 0 ? m.receita / m.vendas : null,
      }))
      .filter(x => x.invest > 0 || x.vendas > 0 || x.leads > 0)
      .sort((a,b) => b.receita - a.receita);

    res.json({
      periodo: periodo || { dias },
      total_invest: lista.reduce((s,x) => s+x.invest, 0),
      total_vendas: lista.reduce((s,x) => s+x.vendas, 0),
      total_receita: lista.reduce((s,x) => s+x.receita, 0),
      produtos: lista,
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

