// Endpoint: lista TOP N deals em risco (Decay Score >= 70) — usado em /cockpit "Resgate Hoje"
app.get('/cockpit/resgate-hoje', requireAuth, async (req, res) => {
  try {
    const u = USERS[req.session.user.username];
    const isAdminVisao = u?.role === 'admin' || isGestor(u);
    const limit = Math.min(50, parseInt(req.query.limit, 10) || 10);
    const tk = await getZohoToken();
    if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
    // Busca deals abertos do user (closer) ou todos (admin/gestor)
    const stagesAbertas = 'Leads Novos,IA sem Contato,Etapa IA,Primeiro Contato,Em Qualificação,Qualificado,Proposta,Proposta Quente,Proposta Fria,Em Atendimento';
    let criteria = `(Stage:in:${stagesAbertas})`;
    if (!isAdminVisao && u?.crmOwner) criteria = `((Owner:equals:${u.crmOwner})and${criteria})`;
    const deals = await zohoSearch(criteria, 'Deal_Name,Stage,Amount,Owner,Telefone_contato,Cidade,Last_Activity_Time,Modified_Time,Created_Time,Tier_Lead', 200);
    const meta = loadManutMeta();
    const inbox = loadWatiInbox();
    // Tarefas hoje/futuras por dealId
    const tarefas = (typeof loadTarefas === 'function' ? loadTarefas() : {});
    const futuresByDeal = {};
    for (const t of Object.values(tarefas || {})) {
      if (!t.dealId || t.feito) continue;
      const ts = t.dataHora ? new Date(t.dataHora).getTime() : 0;
      if (ts > Date.now()) futuresByDeal[t.dealId] = true;
    }
    const scored = deals.map(d => {
      const m = meta[d.id] || {};
      const wi = inbox[d.id];
      const score = calcDecayScore(d, m, wi, !!futuresByDeal[d.id]);
      return {
        id: d.id,
        nome: d.Deal_Name || '?',
        stage: d.Stage || '',
        amount: parseFloat(d.Amount) || 0,
        tier: d.Tier_Lead || '',
        owner: d.Owner?.name || '',
        phone: d.Telefone_contato || '',
        cidade: d.Cidade || '',
        decayScore: score,
        lastClienteTs: wi?.ultimaClienteTs || null,
        lastNossaTs: wi?.ultimaNossaTs || null,
        lastZohoActivity: d.Last_Activity_Time || d.Modified_Time || null,
        hasFutureTask: !!futuresByDeal[d.id],
        ageDays: d.Created_Time ? Math.floor((Date.now() - new Date(d.Created_Time).getTime()) / 86400000) : null,
        crmLink: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}`,
      };
    });
    scored.sort((a,b) => b.decayScore - a.decayScore);
    const risco = scored.filter(d => d.decayScore >= 70).slice(0, limit);
    res.json({
      total: deals.length,
      emRisco: scored.filter(d => d.decayScore >= 70).length,
      decay70mais: scored.filter(d => d.decayScore >= 70).length,
      decay50_69: scored.filter(d => d.decayScore >= 50 && d.decayScore < 70).length,
      decay30_49: scored.filter(d => d.decayScore >= 30 && d.decayScore < 50).length,
      saudaveis: scored.filter(d => d.decayScore < 30).length,
      resgateHoje: risco,
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// Calcula Days in Stage pra um deal (helper exportado pra /closy/deals)
function calcDaysInStage(deal, metaCli) {
  const stage = deal.Stage || '';
  // 1ª opção: stageHistory local
  const hist = metaCli?.stageHistory;
  if (Array.isArray(hist) && hist.length) {
    // Pega última transição PRA o stage atual
    for (let i = hist.length - 1; i >= 0; i--) {
      if (hist[i].stage === stage) {
        return Math.max(0, Math.floor((Date.now() - hist[i].ts) / 86400000));
      }
    }
  }
  // 2ª opção: stageZohoUpdatedAt
  if (metaCli?.stageZohoUpdatedAt) {
    return Math.max(0, Math.floor((Date.now() - new Date(metaCli.stageZohoUpdatedAt).getTime()) / 86400000));
  }
  // 3ª opção: Zoho Modified_Time (proxy aproximada)
  if (deal.Modified_Time) {
    return Math.max(0, Math.floor((Date.now() - new Date(deal.Modified_Time).getTime()) / 86400000));
  }
  // 4ª: Created_Time
  if (deal.Created_Time) {
    return Math.max(0, Math.floor((Date.now() - new Date(deal.Created_Time).getTime()) / 86400000));
  }
  return null;
}

// === FASE 2: CUSTOM VIEWS (filtros salvos por user — tipo Custom Views do Zoho) ===
// Storage: { username: [{ id, nome, filtro:{layoutId, pipelineName, stages, owner, tier, busca}, criadoEm }] }
function loadCustomViews() { return kvOrFile('closy-custom-views', null, {}); }
function saveCustomViews(d) { kvAndFile('closy-custom-views', null, d); }

app.get('/closy/views', requireAuth, (req, res) => {
  const all = loadCustomViews();
  const myUser = req.session.user.username;
  const minhas = all[myUser] || [];
  // Compartilhadas: views com flag publica:true criadas por admin/gestor
  const compartilhadas = [];
  for (const [user, lista] of Object.entries(all)) {
    if (user === myUser) continue;
    for (const v of (lista || [])) {
      if (v.publica) compartilhadas.push({ ...v, criadoPor: user });
    }
  }
  res.json({ minhas, compartilhadas });
});

app.post('/closy/views', requireAuth, (req, res) => {
  const { id, nome, filtro, publica } = req.body || {};
  if (!nome) return res.status(400).json({ error: 'nome obrigatório' });
  const u = USERS[req.session.user.username];
  const myUser = req.session.user.username;
  const all = loadCustomViews();
  if (!all[myUser]) all[myUser] = [];
  const isAdmin = u?.role === 'admin' || isGestor(u);
  const novaView = {
    id: id || ('v_' + Date.now() + '_' + Math.random().toString(36).slice(2,7)),
    nome: String(nome).slice(0, 80),
    filtro: filtro || {},
    publica: isAdmin && !!publica, // só admin/gestor pode marcar como pública
    criadoEm: new Date().toISOString(),
    criadoPor: u?.name || myUser,
  };
  const idx = all[myUser].findIndex(v => v.id === novaView.id);
  if (idx >= 0) all[myUser][idx] = { ...all[myUser][idx], ...novaView };
  else all[myUser].push(novaView);
  saveCustomViews(all);
  res.json({ ok: true, view: novaView });
});

app.delete('/closy/views/:id', requireAuth, (req, res) => {
  const myUser = req.session.user.username;
  const all = loadCustomViews();
  if (!all[myUser]) return res.status(404).json({ error: 'view não encontrada' });
  const novo = all[myUser].filter(v => v.id !== req.params.id);
  if (novo.length === all[myUser].length) return res.status(404).json({ error: 'view não encontrada' });
  all[myUser] = novo;
  saveCustomViews(all);
  res.json({ ok: true });
});

