// === FASE 5: CAMPOS PERSONALIZADOS DO CLOSY (locais, não vão pro Zoho) ===
// Schema: { id, apiName, label, tipo: 'text'|'number'|'date'|'enum'|'bool'|'textarea',
//           options:[], required:bool, ordem:N, ativo:bool, createdAt, createdBy }
function loadClosyCustomFields() { return kvOrFile('closy-custom-fields', null, []); }
function saveClosyCustomFields(arr) { kvAndFile('closy-custom-fields', null, arr); }

// CRUD de schema de campo customizado (admin)
app.get('/closy/custom-fields', requireAuth, (req, res) => {
  const fields = loadClosyCustomFields();
  res.json({ fields: fields.filter(f => f.ativo !== false).sort((a,b) => (a.ordem||0) - (b.ordem||0)) });
});

app.post('/closy/custom-fields', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const { id, label, tipo, options, required, ordem, ativo, descricao } = req.body || {};
  if (!label) return res.status(400).json({ error: 'label obrigatório' });
  const TIPOS = ['text','number','date','enum','bool','textarea','url','phone'];
  if (tipo && !TIPOS.includes(tipo)) return res.status(400).json({ error: 'tipo inválido. Use: '+TIPOS.join(', ') });
  // apiName é gerado a partir do label (snake_case + prefix cf_)
  const apiName = id ? id.replace(/^cf_/, '') : String(label).toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 30);
  const finalId = 'cf_' + apiName;
  const fields = loadClosyCustomFields();
  // Se já existe outro campo com esse apiName e id é diferente, rejeita
  const conflito = fields.find(f => f.id === finalId && (id || '') !== finalId && id !== finalId);
  if (conflito) return res.status(400).json({ error: 'já existe campo com esse apiName: ' + finalId });
  const novo = {
    id: finalId,
    apiName,
    label: String(label).slice(0, 80),
    tipo: tipo || 'text',
    options: Array.isArray(options) ? options.filter(Boolean).map(o => String(o).slice(0, 60)) : [],
    required: !!required,
    ordem: Number(ordem) || fields.length + 1,
    ativo: ativo !== false,
    descricao: descricao ? String(descricao).slice(0, 200) : '',
    updatedAt: new Date().toISOString(),
    updatedBy: u?.name || 'Sistema',
    createdAt: fields.find(f => f.id === finalId)?.createdAt || new Date().toISOString(),
  };
  const idx = fields.findIndex(f => f.id === finalId);
  if (idx >= 0) fields[idx] = { ...fields[idx], ...novo };
  else fields.push(novo);
  saveClosyCustomFields(fields);
  res.json({ ok: true, field: novo });
});

app.delete('/closy/custom-fields/:id', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const fields = loadClosyCustomFields();
  const novo = fields.filter(f => f.id !== req.params.id);
  if (novo.length === fields.length) return res.status(404).json({ error: 'campo não encontrado' });
  saveClosyCustomFields(novo);
  res.json({ ok: true });
});

