app.post('/closy/deals/:dealId/custom/:fieldId', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  const { dealId, fieldId } = req.params;
  const { value } = req.body || {};
  const fields = loadClosyCustomFields();
  const cfg = fields.find(f => f.id === fieldId);
  if (!cfg) return res.status(400).json({ error: 'campo customizado não existe: ' + fieldId });
  if (cfg.required && (value == null || value === '')) {
    return res.status(400).json({ error: 'campo obrigatório: ' + cfg.label });
  }
  // Validação por tipo
  let valorLimpo = value;
  if (cfg.tipo === 'number') valorLimpo = Number(value);
  else if (cfg.tipo === 'bool') valorLimpo = !!value;
  else if (cfg.tipo === 'date' && value) valorLimpo = String(value).slice(0, 10);
  else if (cfg.tipo === 'enum' && value && cfg.options?.length) {
    if (!cfg.options.includes(value)) return res.status(400).json({ error: 'valor fora das opções: ' + cfg.options.join(', ') });
  }
  const meta = loadManutMeta();
  if (!meta[dealId]) meta[dealId] = {};
  if (!meta[dealId].customFields) meta[dealId].customFields = {};
  if (value === null || value === '' || (cfg.tipo === 'number' && isNaN(valorLimpo))) {
    delete meta[dealId].customFields[fieldId];
  } else {
    meta[dealId].customFields[fieldId] = valorLimpo;
  }
  addTimelineEvent(meta, dealId, { tipo:'campo-custom', label:`🏷️ ${cfg.label}: ${value || '(removido)'}`, by: u?.name || 'Sistema' });
  saveManutMeta(meta);
  res.json({ ok: true, dealId, fieldId, value: meta[dealId].customFields[fieldId] || null });
});

