// === BUSCA GLOBAL DE CLIENTE (Cmd+K palette) ===
// Busca em deals Zoho por nome/telefone/email + cache won-deals + ERP
// Retorna até 12 resultados ordenados por relevância
app.get('/api/v1/search', requireApiKeyOrAuth, async (req, res) => {
  const q = String(req.query.q || '').trim();
  if (!q || q.length < 2) return res.json({ results: [] });
  const qLower = q.toLowerCase();
  const qPhone = q.replace(/\D/g, '');
  const isPhone = qPhone.length >= 4;
  const results = [];
  const seen = new Set();

  // 1. Busca em won-deals cacheado (rápido, sem hit Zoho)
  try {
    const won = await getWonDealsCached();
    for (const d of won) {
      if (results.length >= 30) break;
      const nome = (d.Deal_Name || '').toLowerCase();
      const tel = String(d.Telefone_contato || '').replace(/\D/g, '');
      const email = (d.Email || '').toLowerCase();
      const cidade = (d.Cidade || '').toLowerCase();
      let match = false, score = 0;
      if (nome.includes(qLower)) { match = true; score = nome.startsWith(qLower) ? 100 : 80; }
      else if (isPhone && tel.includes(qPhone)) { match = true; score = 90; }
      else if (email.includes(qLower)) { match = true; score = 60; }
      else if (cidade.includes(qLower)) { match = true; score = 40; }
      if (match && !seen.has(d.id)) {
        seen.add(d.id);
        results.push({
          id: d.id,
          nome: d.Deal_Name || '?',
          phone: d.Telefone_contato || '',
          cidade: d.Cidade || '',
          stage: d.Stage || 'Fechado Ganho',
          owner: d.Owner?.name || '',
          tier: d.Tier_Lead || '',
          source: 'won',
          score,
        });
      }
    }
  } catch(_){}

  // 2. Busca Zoho ativo (em deals abertos não cacheados — só se nada encontrado ainda)
  if (results.length < 5) {
    try {
      const tk = await getZohoToken();
      if (tk) {
        let criteria;
        if (isPhone) criteria = `(Telefone_contato:starts_with:${qPhone.slice(-9)})`;
        else criteria = `(Deal_Name:starts_with:${q})`;
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/search?criteria=${encodeURIComponent(criteria)}&fields=Deal_Name,Telefone_contato,Cidade,Stage,Owner,Tier_Lead&per_page=15`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        if (r.ok) {
          const j = await r.json();
          for (const d of (j.data || [])) {
            if (seen.has(d.id)) continue;
            seen.add(d.id);
            results.push({
              id: d.id,
              nome: d.Deal_Name || '?',
              phone: d.Telefone_contato || '',
              cidade: d.Cidade || '',
              stage: d.Stage || '',
              owner: d.Owner?.name || '',
              tier: d.Tier_Lead || '',
              source: 'zoho',
              score: 70,
            });
          }
        }
      }
    } catch(e) { console.warn('[search/zoho]', e.message); }
  }

  results.sort((a,b) => (b.score||0) - (a.score||0));
  res.json({ q, total: results.length, results: results.slice(0, 12) });
});

// === FASE 6: API GENÉRICA PÚBLICA (X-API-Key auth, pra n8n/Zapier/scripts) ===
// Configurar key em CLOSY_API_KEY (Railway env). Se não setada, só funciona com sessão.
function requireApiKeyOrAuth(req, res, next) {
  const fromHeader = req.headers['x-api-key'] || req.headers['X-API-Key'];
  const fromQuery = req.query.api_key;
  const provided = fromHeader || fromQuery;
  const expected = process.env.CLOSY_API_KEY;
  if (expected && provided && provided === expected) return next();
  // Fallback: sessão logada (cookie)
  if (req.session?.user?.username && USERS[req.session.user.username]) return next();
  return res.status(401).json({ error: 'unauthorized — use X-API-Key header ou login' });
}

// GET /api/v1/deals/:dealId — retorna deal completo do Zoho (campos da whitelist + outros básicos)
app.get('/api/v1/deals/:dealId', requireApiKeyOrAuth, async (req, res) => {
  const { dealId } = req.params;
  if (String(dealId).startsWith('erp:') || String(dealId).startsWith('wati:')) {
    return res.status(400).json({ error: 'placeholder dealId — sem dados Zoho' });
  }
  const tk = await getZohoToken();
  if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
  try {
    const fields = Object.keys(CLOSY_EDITABLE_FIELDS).filter(k => CLOSY_EDITABLE_FIELDS[k].target === 'zoho').join(',') + ',Deal_Name,Owner,Pipeline,Layout,Tag,Last_Activity_Time,Created_Time,Modified_Time';
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=${fields}`, {
      headers: { Authorization: `Zoho-oauthtoken ${tk}` },
    });
    if (!r.ok) return res.status(r.status).json({ error: 'zoho ' + r.status });
    const j = await r.json();
    const d = j.data?.[0];
    if (!d) return res.status(404).json({ error: 'deal não encontrado' });
    // Mescla com closy local
    const meta = loadManutMeta()[dealId] || {};
    const closyFields = ['observacao', 'precoManutencao', 'cep', 'ultimaManutencao', 'etapa', 'operadora'];
    const closy = {};
    for (const k of closyFields) if (meta[k] !== undefined) closy[k] = meta[k];
    res.json({ id: dealId, zoho: d, closy });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /api/v1/deals/:dealId/field/:fieldName — retorna valor de um campo
app.get('/api/v1/deals/:dealId/field/:fieldName', requireApiKeyOrAuth, async (req, res) => {
  const { dealId, fieldName } = req.params;
  const cfg = CLOSY_EDITABLE_FIELDS[fieldName];
  if (!cfg) return res.status(400).json({ error: `campo desconhecido: ${fieldName}` });
  if (cfg.target === 'closy') {
    const meta = loadManutMeta()[dealId] || {};
    return res.json({ dealId, fieldName, value: meta[fieldName] || null, target: 'closy' });
  }
  if (String(dealId).startsWith('erp:') || String(dealId).startsWith('wati:')) {
    return res.status(400).json({ error: 'placeholder dealId — sem campo Zoho' });
  }
  const tk = await getZohoToken();
  if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
  try {
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=${fieldName}`, {
      headers: { Authorization: `Zoho-oauthtoken ${tk}` },
    });
    if (!r.ok) return res.status(r.status).json({ error: 'zoho ' + r.status });
    const j = await r.json();
    const d = j.data?.[0];
    res.json({ dealId, fieldName, value: d ? d[fieldName] : null, target: 'zoho' });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// PUT /api/v1/deals/:dealId/field/:fieldName — atualiza (mesma lógica do /closy/deals/.../field/...)
app.put('/api/v1/deals/:dealId/field/:fieldName', requireApiKeyOrAuth, express.json(), async (req, res) => {
  const { dealId, fieldName } = req.params;
  const { value } = req.body || {};
  const cfg = CLOSY_EDITABLE_FIELDS[fieldName];
  if (!cfg) return res.status(400).json({ error: `campo não editável: ${fieldName}` });
  if (String(dealId).startsWith('erp:') || String(dealId).startsWith('wati:')) {
    return res.status(400).json({ error: 'placeholder dealId — cadastre o lead primeiro' });
  }
  if (cfg.target === 'closy') {
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    if (value === null || value === '' || (cfg.tipo === 'number' && Number(value) === 0)) {
      delete meta[dealId][fieldName];
    } else {
      meta[dealId][fieldName] = cfg.tipo === 'number' ? Number(value) : value;
    }
    addTimelineEvent(meta, dealId, { tipo:'campo-api', label:`🔌 API: ${cfg.label} = ${value || '(removido)'}`, by: 'API Key' });
    saveManutMeta(meta);
    return res.json({ ok: true, dealId, fieldName, value: meta[dealId][fieldName] || null, target: 'closy' });
  }
  const tk = await getZohoToken();
  if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
  try {
    let payloadValue = value;
    if (cfg.tipo === 'number') payloadValue = Number(value) || 0;
    if (cfg.tipo === 'date' && value) payloadValue = String(value).slice(0, 10);
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}`, {
      method: 'PUT',
      headers: { Authorization: `Zoho-oauthtoken ${tk}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: [{ [fieldName]: payloadValue }] }),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    if (result?.code !== 'SUCCESS') return res.status(400).json({ error: result?.message || 'Zoho rejeitou', details: result });
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    addTimelineEvent(meta, dealId, { tipo:'campo-api-zoho', label:`🔌 API: ${cfg.label} = ${payloadValue}`, by: 'API Key' });
    saveManutMeta(meta);
    res.json({ ok: true, dealId, fieldName, value: payloadValue, target: 'zoho' });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

