// PUT — atualiza Stage do deal no Zoho
app.post('/manutencao/cliente/:dealId/stage', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin' || isGestor(u);
  const username = req.session.user.username;
  const { dealId } = req.params;
  const { stage } = req.body || {};
  if (!stage) return res.status(400).json({ error: 'stage obrigatório' });
  const meta = loadManutMeta();
  if (!isAdmin && meta[dealId]?.operadora && meta[dealId].operadora !== username) {
    return res.status(403).json({ error: 'cliente fora da sua carteira' });
  }
  if (dealId.startsWith('erp:')) return res.status(400).json({ error: 'cliente ERP-only ainda não tem deal Zoho. Crie primeiro.' });
  const tk = await getZohoToken();
  if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
  try {
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}`, {
      method:'PUT',
      headers: { Authorization: `Zoho-oauthtoken ${tk}`, 'Content-Type':'application/json' },
      body: JSON.stringify({ data: [{ Stage: stage }] }),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    if (result?.code !== 'SUCCESS') {
      // Erro comum: stage não pertence ao Pipeline atual do deal
      if (result?.message?.includes('Pipeline doesn\'t contain')) {
        // Carrega stages válidas do pipeline pra ajudar
        const dealR = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Pipeline`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        const dealJ = await dealR.json().catch(() => ({}));
        const pipeAtual = dealJ.data?.[0]?.Pipeline || '?';
        const stagesByPipe = await loadZohoStagesByPipeline().catch(() => ({}));
        const validas = stagesByPipe[pipeAtual] || [];
        return res.status(400).json({
          error: `O stage "${stage}" não existe no Pipeline "${pipeAtual}" desse deal.`,
          dica: validas.length ? `Stages válidas: ${validas.join(', ')}` : 'Verifique no Zoho o pipeline do deal.',
        });
      }
      return res.status(500).json({ error: result?.message || 'falha Zoho', raw: j });
    }
    if (!meta[dealId]) meta[dealId] = {};
    addTimelineEvent(meta, dealId, { tipo:'zoho-stage', label:`📊 Stage Zoho atualizado: ${stage}`, by: u?.name||username });
    saveManutMeta(meta);
    res.json({ ok:true, stage });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// PUT — muda Layout do deal no Zoho
app.post('/manutencao/cliente/:dealId/layout', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin' || isGestor(u);
  if (!isAdmin) return res.status(403).json({ error: 'apenas admin/gestor pode trocar layout' });
  const { dealId } = req.params;
  const { layoutId } = req.body || {};
  const layout = ZOHO_LAYOUTS.find(l => l.id === layoutId);
  if (!layout) return res.status(400).json({ error: 'layout inválido' });
  if (dealId.startsWith('erp:')) return res.status(400).json({ error: 'cliente ERP-only ainda não tem deal Zoho' });
  const tk = await getZohoToken();
  if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
  try {
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}`, {
      method:'PUT',
      headers: { Authorization: `Zoho-oauthtoken ${tk}`, 'Content-Type':'application/json' },
      body: JSON.stringify({ data: [{ Layout: { id: layoutId } }] }),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    if (result?.code !== 'SUCCESS') return res.status(500).json({ error: result?.message || 'falha Zoho', raw: j });
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    addTimelineEvent(meta, dealId, { tipo:'zoho-layout', label:`🗂️ Layout Zoho alterado: ${layout.nome}`, by: u?.name });
    saveManutMeta(meta);
    res.json({ ok:true, layout: layout.nome });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// Helper: detecta se IA (Núbia) está atendendo o lead
// Sinais: tag Nubia/IA no Zoho, OU timeline Closy com evento de núbia recente (7d)
function isIaAtendendoMeta(meta, dealId, dealTags) {
  // Tag Zoho
  const tagsTemNubia = Array.isArray(dealTags) && dealTags.some(t =>
    /nubia|n[uú]bia|sdr.*ia|atend.*ia|ia.*atend/i.test(typeof t === 'string' ? t : (t.name || ''))
  );
  if (tagsTemNubia) return true;
  // Timeline Closy
  const tl = meta?.[dealId]?.timeline || [];
  const cutoff = Date.now() - 7 * 86400000;
  return tl.some(ev => {
    const t = (ev.tipo || '') + ' ' + (ev.label || '');
    if (!/nubia|n[uú]bia|reengaj|sdr\s*ia/i.test(t)) return false;
    return new Date(ev.at).getTime() > cutoff;
  });
}

