app.post('/manutencao/cliente/:dealId/campo', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u) return res.status(401).json({ error: 'unauthenticated' });
  const { dealId } = req.params;
  const { campo, valor } = req.body || {};
  if (!campo || !CAMPOS_EDITAVEIS[campo]) return res.status(400).json({ error: 'campo inválido' });
  const cfg = CAMPOS_EDITAVEIS[campo];
  // Sanitiza
  let novoValor = valor;
  if (cfg.tipo === 'money' || cfg.tipo === 'number') {
    novoValor = parseFloat(String(valor).replace(/[^\d,.-]/g, '').replace(',', '.')) || 0;
  } else if (cfg.tipo === 'tel') {
    novoValor = String(valor || '').replace(/[^\d+]/g, '');
  } else if (cfg.tipo === 'date') {
    novoValor = String(valor || '').trim(); // espera YYYY-MM-DD
  } else {
    novoValor = String(valor || '').trim();
  }

  const meta = loadManutMeta();
  if (!meta[dealId]) meta[dealId] = {};

  // Pega valor atual (Zoho ou meta local) pra logar o "antes"
  let valorAnterior = null;
  if (cfg.localOnly) {
    valorAnterior = meta[dealId][campo] ?? null;
  } else if (!dealId.startsWith('erp:') && !dealId.startsWith('wati:')) {
    try {
      const tk = await getZohoToken();
      if (tk) {
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=${campo}`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        const j = await r.json().catch(() => ({}));
        valorAnterior = j.data?.[0]?.[campo] ?? null;
      }
    } catch(_){}
  }

  // Grava no Zoho APENAS se NÃO localOnly
  let zohoOk = true;
  if (!cfg.localOnly && !dealId.startsWith('erp:') && !dealId.startsWith('wati:')) {
    try {
      zohoOk = await zoho.updateDeal(dealId, { [campo]: novoValor });
    } catch(e) { console.warn('[campo update]', e.message); zohoOk = false; }
  }

  // Salva localOnly em meta SEMPRE
  if (cfg.localOnly) meta[dealId][campo] = novoValor;

  // Salva histórico local sempre
  if (!Array.isArray(meta[dealId].historicoMudancas)) meta[dealId].historicoMudancas = [];
  meta[dealId].historicoMudancas.push({
    campo,
    label: cfg.label,
    antes: valorAnterior,
    depois: novoValor,
    quem: u.name || u.username,
    quem_user: u.username,
    em: new Date().toISOString(),
    zoho_ok: cfg.localOnly ? null : zohoOk,
    local_only: !!cfg.localOnly,
  });
  if (meta[dealId].historicoMudancas.length > 100) {
    meta[dealId].historicoMudancas = meta[dealId].historicoMudancas.slice(-100);
  }
  // Compat antigo: Telefone_2 também em meta.telefone2 pra outras telas
  if (campo === 'Telefone_2') meta[dealId].telefone2 = novoValor;
  meta[dealId].updatedAt = new Date().toISOString();
  // Timeline
  addTimelineEvent(meta, dealId, {
    tipo: 'edicao',
    label: `${cfg.label}: "${valorAnterior||'∅'}" → "${novoValor||'∅'}"`,
    by: u.name || u.username,
  });
  saveManutMeta(meta);

  res.json({
    ok: true,
    campo,
    valor_anterior: valorAnterior,
    valor_novo: novoValor,
    zoho_atualizado: zohoOk,
    timestamp: new Date().toISOString(),
  });
});

