// === ViaCEP — busca endereço por CEP (proxy pro viacep.com.br) ===
app.get('/cep/:cep', requireAuth, async (req, res) => {
  const cep = String(req.params.cep || '').replace(/\D/g, '');
  if (cep.length !== 8) return res.status(400).json({ error: 'CEP precisa ter 8 dígitos' });
  try {
    const r = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
    if (!r.ok) return res.status(502).json({ error: 'viacep falhou' });
    const j = await r.json();
    if (j.erro) return res.status(404).json({ error: 'CEP não encontrado' });
    res.json({
      cep: j.cep,
      logradouro: j.logradouro || '',
      bairro: j.bairro || '',
      cidade: j.localidade || '',
      estado: j.uf || '',
      ibge: j.ibge || '',
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === HISTÓRICO DE COMPRAS — busca Fechado Ganho do mesmo cliente (por telefone OU por nome) ===
app.get('/manutencao/cliente/:dealId/historico-compras', requireAuth, async (req, res) => {
  const { dealId } = req.params;
  try {
    // Pega telefone + nome do deal atual
    let telefone = '', nome = '', email = '';
    if (!dealId.startsWith('erp:') && !dealId.startsWith('wati:')) {
      const tk = await getZohoToken();
      if (tk) {
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Telefone_contato,Deal_Name,Email`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        const j = await r.json().catch(() => ({}));
        const d = j.data?.[0];
        if (d) { telefone = d.Telefone_contato || ''; nome = d.Deal_Name || ''; email = d.Email || ''; }
      }
    }
    if (!telefone && !nome) return res.json({ compras: [], total: 0, fonte: 'sem dados' });
    const fields = 'Deal_Name,Amount,Stage,Closing_Date,Created_Time,Pipeline,Produto_Vendido,Owner,Telefone_contato';
    const compras = [];
    const seen = new Set();
    // Busca por telefone (se houver)
    if (telefone) {
      const phoneClean = telefone.replace(/\D/g, '');
      const variants = [phoneClean, phoneClean.replace(/^55/, ''), '55'+phoneClean.replace(/^55/, '')];
      for (const v of variants) {
        try {
          const r = await zohoSearch(`((Telefone_contato:equals:${v})and(Stage:equals:Fechado Ganho))`, fields, 50);
          for (const d of (r||[])) {
            if (seen.has(d.id) || d.id === dealId) continue;
            seen.add(d.id);
            compras.push(d);
          }
        } catch(_){}
      }
    }
    // Ordena mais recente primeiro
    compras.sort((a,b) => (b.Closing_Date||'').localeCompare(a.Closing_Date||''));
    const total = compras.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    res.json({
      compras: compras.map(d => ({
        dealId: d.id, nome: d.Deal_Name, valor: parseFloat(d.Amount)||0,
        produto: d.Produto_Vendido || '', pipeline: d.Pipeline || '',
        owner: d.Owner?.name || '', closingDate: d.Closing_Date || '', createdTime: d.Created_Time || '',
        crmLink: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}`,
      })),
      total,
      total_compras: compras.length,
      busca_telefone: telefone,
    });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === ATRIBUIR DEAL AUTOMATICAMENTE A UM CLOSER (CRM owner ou round-robin) ===
// Lógica:
//  1. Lê Owner Zoho do deal. Se mapear pra um closer ativo (USERS[].crmOwner match),
//     atribui pra ele.
//  2. Se Owner não está na lista de USERS ativos, faz round-robin entre os closers
//     ATIVOS — preferindo o mesmo team baseado no Pipeline:
//       Pipeline 'Funil água não tratada' → team 'filtro'/'poco'
//       Pipeline 'Geral' (purificador/bebedouro) → team 'filtro'/'bebedouro'
//  3. Atualiza meta.operadora local + grava timeline.
//  4. NÃO altera Owner no Zoho (pra não bagunçar o histórico). Apenas atribui localmente.
function _activeClosers() {
  // Closers ativos: role 'closer' OU 'posvenda'. Exclui admin/CEO e qualquer com `desligado:true`.
  return Object.entries(USERS)
    .filter(([_, u]) => (u.role === 'closer' || u.role === 'posvenda') && !u.desligado)
    .map(([username, u]) => ({ username, ...u }));
}
async function _atribuirRoundRobin(team) {
  const todos = _activeClosers();
  const pool = team ? todos.filter(c => c.team === team) : todos;
  const final = pool.length ? pool : todos;
  if (!final.length) return null;
  const counterKey = team ? `rr_counter_${team}` : 'rr_counter_all';
  const cur = (typeof _kvCache[counterKey] === 'number') ? _kvCache[counterKey] : 0;
  const next = cur % final.length;
  kvSet(counterKey, cur + 1).catch(() => {});
  return final[next];
}
function _ownerToCloser(ownerNameOrEmail) {
  if (!ownerNameOrEmail) return null;
  const norm = String(ownerNameOrEmail).toLowerCase().trim();
  const todos = _activeClosers();
  // Match exato no crmOwner OU primeira parte do nome
  return todos.find(c => {
    const cm = String(c.crmOwner || '').toLowerCase().trim();
    if (cm === norm) return true;
    const firstName = norm.split(' ')[0];
    return cm.startsWith(firstName) || cm.split(' ')[0] === firstName;
  }) || null;
}
app.post('/manutencao/cliente/:dealId/atribuir-auto', requireAuth, async (req, res) => {
  const { dealId } = req.params;
  const u = USERS[req.session.user.username];
  if (!u) return res.status(401).json({ error: 'unauthenticated' });
  // Closer comum também pode atribuir? Sim — pra puxar pra si um lead órfão.
  // Mas só admin/gestor pode reatribuir um lead que já tem operadora.
  const isAdmin = u.role === 'admin' || isGestor(u);
  const meta = loadManutMeta();
  const prev = meta[dealId] || {};
  if (prev.operadora && prev.operadora !== u.username && !isAdmin) {
    return res.status(403).json({ error: 'lead já atribuído a outro closer; só admin/gestor pode reatribuir' });
  }
  // Pega Owner Zoho + Pipeline
  let ownerZohoName = '';
  let pipeline = '';
  if (!dealId.startsWith('erp:') && !dealId.startsWith('wati:')) {
    try {
      const tk = await getZohoToken();
      if (tk) {
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Owner,Pipeline,Stage`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        const j = await r.json().catch(() => ({}));
        const d = j.data?.[0];
        if (d) {
          ownerZohoName = d.Owner?.name || d.Owner?.email || '';
          pipeline = d.Pipeline || '';
        }
      }
    } catch(_){}
  }
  // Primeiro tenta mapear Owner Zoho
  let alvo = _ownerToCloser(ownerZohoName);
  let motivo = alvo ? 'crm_owner_ativo' : null;
  // Se Owner não bate ou inativo, round-robin
  if (!alvo) {
    let teamPref = '';
    if (/n[aã]o tratada|po[cç]o/i.test(pipeline)) teamPref = 'poco';
    else if (/filtro|entrada/i.test(pipeline)) teamPref = 'filtro';
    else teamPref = 'bebedouro'; // default Geral → bebedouro
    alvo = await _atribuirRoundRobin(teamPref);
    motivo = alvo ? `round_robin_${teamPref}` : null;
  }
  if (!alvo) {
    // Fallback: round robin geral
    alvo = await _atribuirRoundRobin('');
    motivo = alvo ? 'round_robin_geral' : null;
  }
  if (!alvo) return res.status(500).json({ error: 'nenhum closer ativo disponível' });
  // Aplica
  if (!meta[dealId]) meta[dealId] = {};
  const userName = u.name || u.username;
  addTimelineEvent(meta, dealId, {
    tipo: 'atribuicao',
    label: `Atribuído auto pra ${alvo.name} (${motivo})${ownerZohoName?' · CRM owner: '+ownerZohoName:''}`,
    by: userName,
  });
  const prevOperadora = prev.operadora || null;
  meta[dealId].operadora = alvo.username;
  meta[dealId].updatedAt = new Date().toISOString();
  saveManutMeta(meta);
  _auditLogSafe({
    action_type: 'lead_assigned',
    action_origin: (alvo.username === u.username && !isAdmin) ? 'seller_manual' : 'manager_manual',
    crm_module: 'Deals',
    crm_record_id: String(dealId),
    crm_record_name: prev.nome || meta[dealId].nome || null,
    actor_id: u.username,
    actor_name: userName,
    seller_responsible_before: prevOperadora ? (USERS[prevOperadora]?.name || prevOperadora) : null,
    seller_responsible_after: alvo.name || alvo.username,
    reason: `atribuir-auto: ${motivo}${ownerZohoName ? ' (CRM owner: '+ownerZohoName+')' : ''}`,
    rule_triggered: motivo,
    related_channel: 'portal',
    metadata_json: { team: alvo.team, owner_zoho: ownerZohoName, pipeline, endpoint: 'atribuir-auto' }
  });
  res.json({
    ok: true,
    atribuido_a: alvo.username,
    closer_name: alvo.name,
    team: alvo.team,
    motivo,
    owner_zoho: ownerZohoName,
    pipeline,
  });
});

// === BATCH AUTO-ATRIBUIÇÃO de todos os deals sem operadora (admin/gestor) ===
app.post('/inbox/atribuir-orfaos', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const inbox = loadWatiInbox();
  const meta = loadManutMeta();
  const orfaos = Object.values(inbox).filter(m => {
    const dealMeta = meta[m.dealId] || {};
    return !dealMeta.operadora && m.dealId && !String(m.dealId).startsWith('wati:');
  });
  const limite = Math.min(orfaos.length, parseInt(req.body?.limite, 10) || 50);
  const resultados = [];
  for (const conv of orfaos.slice(0, limite)) {
    try {
      // Pega owner Zoho
      let ownerZohoName = '';
      let pipeline = '';
      try {
        const tk = await getZohoToken();
        if (tk) {
          const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${conv.dealId}?fields=Owner,Pipeline`, {
            headers: { Authorization: `Zoho-oauthtoken ${tk}` },
          });
          const j = await r.json().catch(() => ({}));
          const d = j.data?.[0];
          if (d) { ownerZohoName = d.Owner?.name || ''; pipeline = d.Pipeline || ''; }
        }
      } catch(_){}
      let alvo = _ownerToCloser(ownerZohoName);
      let motivo = alvo ? 'crm_owner_ativo' : null;
      if (!alvo) {
        let teamPref = /n[aã]o tratada|po[cç]o/i.test(pipeline) ? 'poco'
          : /filtro|entrada/i.test(pipeline) ? 'filtro' : 'bebedouro';
        alvo = await _atribuirRoundRobin(teamPref);
        motivo = alvo ? `round_robin_${teamPref}` : null;
      }
      if (!alvo) { resultados.push({ dealId: conv.dealId, erro: 'sem closer disponível' }); continue; }
      if (!meta[conv.dealId]) meta[conv.dealId] = {};
      const prevOperadora = meta[conv.dealId].operadora || null;
      addTimelineEvent(meta, conv.dealId, {
        tipo: 'atribuicao',
        label: `Atribuído auto (batch) pra ${alvo.name} (${motivo})`,
        by: u.name,
      });
      meta[conv.dealId].operadora = alvo.username;
      meta[conv.dealId].updatedAt = new Date().toISOString();
      _auditLogSafe({
        action_type: 'lead_assigned',
        action_origin: 'manager_manual',
        crm_module: 'Deals',
        crm_record_id: String(conv.dealId),
        crm_record_name: meta[conv.dealId].nome || null,
        actor_id: u.username,
        actor_name: u.name,
        seller_responsible_before: prevOperadora ? (USERS[prevOperadora]?.name || prevOperadora) : null,
        seller_responsible_after: alvo.name || alvo.username,
        reason: `atribuir-orfaos batch: ${motivo}${ownerZohoName ? ' (CRM owner: '+ownerZohoName+')' : ''}`,
        rule_triggered: motivo,
        related_channel: 'portal',
        metadata_json: { team: alvo.team, owner_zoho: ownerZohoName, pipeline, endpoint: 'atribuir-orfaos' }
      });
      resultados.push({ dealId: conv.dealId, atribuido_a: alvo.username, motivo });
    } catch(e) {
      resultados.push({ dealId: conv.dealId, erro: e.message });
    }
  }
  saveManutMeta(meta);
  res.json({
    total_orfaos: orfaos.length,
    processados: resultados.length,
    sucesso: resultados.filter(r => !r.erro).length,
    erros: resultados.filter(r => r.erro).length,
    resultados,
  });
});

