// === IA IDENTIFICA PRODUTO (no funil genérico) ===
// Lê a conversa WATI + Lead_Source + city e responde qual produto o lead quer
app.post('/manutencao/cliente/:dealId/identificar-produto-ia', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u) return res.status(401).json({ error: 'unauthenticated' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não configurada' });
  const { dealId } = req.params;
  // Pega contexto Zoho
  let dealZoho = {};
  if (!dealId.startsWith('erp:') && !dealId.startsWith('wati:')) {
    try {
      const tk = await getZohoToken();
      if (tk) {
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Deal_Name,Telefone_contato,Cidade,Lead_Source,Pipeline,Tipo_de_Agua,Description,Created_Time`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        const j = await r.json().catch(() => ({}));
        dealZoho = j.data?.[0] || {};
      }
    } catch(_){}
  }
  // Pega conversa WATI
  let mensagens = [];
  if (dealZoho.Telefone_contato && WATI_TOKEN) {
    try {
      const url = `${WATI_BASE}/api/v1/getMessages/${normalizarPhoneWati(dealZoho.Telefone_contato)}?pageSize=40&pageNumber=0`;
      const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
      if (r.ok) {
        const j = await r.json();
        const items = j.messages?.items || j.items || j.messages || [];
        mensagens = items.map(m => ({
          owner: m.owner === true || m.fromMe === true || m.eventType === 'sentMessage',
          texto: m.text || m.body || m.finalText || '',
        })).filter(m => m.texto).reverse();
      }
    } catch(_){}
  }
  const conversa = mensagens.map(m => `${m.owner?'NÓS':'CLIENTE'}: ${m.texto}`).join('\n').slice(-4000);
  const SYSTEM = `Você é um analista comercial da Tudo de Filtro especialista em identificar qual produto o lead quer baseado na conversa WhatsApp + dados do CRM.

PRODUTOS DA TUDO DE FILTRO:
- Filtro de Entrada (caixa d'água) — pra água da rua + bombeada, mais filtragem geral. Iron Free (água de poço com ferro), Scale Stop (anti-incrustação)
- Bebedouro Industrial AF (15/25/30/60/100/200 pessoas) — pra empresa/comercio
- Purificador (Bliss/Soft/Premium) — uso doméstico ou pequeno escritório
- Refil (manutenção de purificador existente)
- Condomínio (sistemas grandes)

ETAPAS DO FUNIL DE CONSCIÊNCIA:
- consciencia: lead não sabe o tamanho do problema
- descoberta: precisa mapear fonte de água, qtd pessoas, dor
- qualificacao: tem orçamento/timing definido
- proposta: já recebeu preço

Responda SOMENTE em JSON:
{
  "produto_provavel": "Filtro de Entrada | Bebedouro | Purificador | Refil | Iron Free | Scale Stop | Condomínio | Indeterminado",
  "modelo_sugerido": "se aplicável (ex: AF 25, Bliss, Iron Free)",
  "confianca": "alta | media | baixa",
  "etapa_atual": "consciencia | descoberta | qualificacao | proposta",
  "perguntas_faltando": ["pergunta 1 pra qualificar", "pergunta 2"],
  "explicacao_curta": "1 frase de até 200 chars dizendo o porquê",
  "sugestao_proxima_msg": "mensagem WhatsApp pronta pra mandar (PT-BR, máx 280 chars)"
}`;
  const userMsg = `=== CONTEXTO ZOHO ===
Nome/Empresa: ${dealZoho.Deal_Name || '?'}
Cidade: ${dealZoho.Cidade || '?'}
Origem: ${dealZoho.Lead_Source || '?'}
Pipeline: ${dealZoho.Pipeline || '?'}
Tipo Água: ${dealZoho.Tipo_de_Agua || '?'}
Descrição: ${dealZoho.Description || '?'}
Criado: ${dealZoho.Created_Time || '?'}

=== CONVERSA WATI (${mensagens.length} msgs) ===
${conversa || '(sem mensagens)'}`;
  try {
    const Anthropic = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
    const anthropic = new Anthropic({ apiKey });
    const r = await anthropic.messages.create({
      model: 'claude-sonnet-4-5-20250929',
      max_tokens: 1200,
      system: SYSTEM,
      messages: [{ role: 'user', content: userMsg }],
    });
    const txt = r.content?.[0]?.text || '';
    let parsed = null;
    try {
      const m = txt.match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
    } catch(_){}
    if (!parsed) return res.json({ raw: txt, error: 'IA não retornou JSON válido' });
    res.json({ ...parsed, total_mensagens: mensagens.length });
  } catch(e) {
    console.error('[identificar-produto-ia]', e.message);
    res.status(500).json({ error: 'IA falhou: ' + e.message });
  }
});

