// === TAGS LOCAIS no deal (não Zoho — quick categorização) ===
app.post('/manutencao/cliente/:dealId/tagLocal', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u) return res.status(401).json({ error: 'unauthenticated' });
  const { dealId } = req.params;
  const { tag, action } = req.body || {}; // action: 'add' | 'remove'
  if (!tag) return res.status(400).json({ error: 'tag obrigatória' });
  const meta = loadManutMeta();
  if (!meta[dealId]) meta[dealId] = {};
  if (!Array.isArray(meta[dealId].tagsLocais)) meta[dealId].tagsLocais = [];
  const cleanTag = String(tag).trim().slice(0, 30);
  if (action === 'remove') {
    meta[dealId].tagsLocais = meta[dealId].tagsLocais.filter(t => t !== cleanTag);
  } else {
    if (!meta[dealId].tagsLocais.includes(cleanTag)) meta[dealId].tagsLocais.push(cleanTag);
  }
  meta[dealId].updatedAt = new Date().toISOString();
  saveManutMeta(meta);
  res.json({ ok: true, tags: meta[dealId].tagsLocais });
});

// === MASS ACTION no Kanban ===
// POST /manutencao/mass-action { dealIds: [], action: 'mover_etapa' | 'atribuir_op' | 'nubia_on' | 'nubia_off' | 'add_tag' | 'criar_tarefa', payload: {} }
app.post('/manutencao/mass-action', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u) return res.status(401).json({ error: 'unauthenticated' });
  const { dealIds, action, payload } = req.body || {};
  if (!Array.isArray(dealIds) || !dealIds.length) return res.status(400).json({ error: 'dealIds obrigatório' });
  if (!action) return res.status(400).json({ error: 'action obrigatório' });
  const meta = loadManutMeta();
  let okCount = 0, errCount = 0;
  const log = [];
  for (const dealId of dealIds.slice(0, 100)) { // cap em 100 por chamada
    try {
      if (!meta[dealId]) meta[dealId] = {};
      if (action === 'mover_etapa') {
        meta[dealId].etapa = payload?.etapa || meta[dealId].etapa;
        addTimelineEvent(meta, dealId, { tipo:'etapa', label:`Etapa: ${payload?.etapa} (mass action)`, by: u.name || u.username });
      } else if (action === 'atribuir_op') {
        meta[dealId].operadora = payload?.operadora || null;
        addTimelineEvent(meta, dealId, { tipo:'operadora', label:`Operadora: ${payload?.operadora || '∅'} (mass)`, by: u.name || u.username });
      } else if (action === 'nubia_on') {
        meta[dealId].iaAtende = true;
        addTimelineEvent(meta, dealId, { tipo:'nubia_toggle', label:'🤖 Núbia ATIVADA (mass)', by: u.name || u.username });
      } else if (action === 'nubia_off') {
        meta[dealId].iaAtende = false;
        addTimelineEvent(meta, dealId, { tipo:'nubia_toggle', label:'🤖 Núbia DESATIVADA (mass)', by: u.name || u.username });
      } else if (action === 'add_tag') {
        if (!Array.isArray(meta[dealId].tagsLocais)) meta[dealId].tagsLocais = [];
        const t = String(payload?.tag||'').trim().slice(0, 30);
        if (t && !meta[dealId].tagsLocais.includes(t)) meta[dealId].tagsLocais.push(t);
      } else {
        log.push({ dealId, erro: 'action inválida' });
        errCount++;
        continue;
      }
      meta[dealId].updatedAt = new Date().toISOString();
      log.push({ dealId, ok: true });
      okCount++;
    } catch(e) {
      log.push({ dealId, erro: e.message });
      errCount++;
    }
  }
  saveManutMeta(meta);
  res.json({ ok: true, action, sucesso: okCount, erros: errCount, total: dealIds.length, log });
});

// === ADICIONAR/REMOVER TAGS NO DEAL (Zoho) ===
// POST body: { tags: ['tagA', 'tagB'] } — adiciona uma ou várias
app.post('/manutencao/cliente/:dealId/tags', requireAuth, async (req, res) => {
  const { dealId } = req.params;
  const tags = Array.isArray(req.body?.tags) ? req.body.tags
    : (req.body?.tag ? [req.body.tag] : []);
  if (!tags.length) return res.status(400).json({ error: 'tag(s) obrigatória(s)' });
  // Sanitiza: trim, max 30 chars, sem chars problemáticos pra URL
  const clean = tags.map(t => String(t).trim().slice(0, 30)).filter(t => t && !/[#?&]/.test(t));
  if (!clean.length) return res.status(400).json({ error: 'tag inválida' });
  try {
    const ok = await zoho.addTags(dealId, clean);
    if (!ok) return res.status(500).json({ error: 'falha ao adicionar tag (Zoho)' });
    res.json({ ok: true, added: clean });
  } catch(e) { res.status(500).json({ error: e.message }); }
});
app.delete('/manutencao/cliente/:dealId/tags/:tagName', requireAuth, async (req, res) => {
  const { dealId, tagName } = req.params;
  if (!tagName) return res.status(400).json({ error: 'tagName obrigatório' });
  try {
    const ok = await zoho.removeTags(dealId, [tagName]);
    if (!ok) return res.status(500).json({ error: 'falha ao remover tag (Zoho)' });
    res.json({ ok: true, removed: tagName });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

// === DIRETOR DE VENDAS IA — coach completo com SPIN + objeções + produtos ===
const DIRETOR_SYSTEM_PROMPT = `Você é o **Diretor de Vendas IA da Tudo de Filtro** (Tudo de Filtro, 20+ anos, São José dos Campos/SP). Sua missão: ajudar closers a fechar mais e melhor via WhatsApp, sem pressão e sem prometer o que não entrega. Você fala como um diretor experiente que esteve em milhares de visitas — direto, prático, brasileiro.

## CATÁLOGO E REGRAS DE OURO
- **Purificadores**: R$800–2.500. Refil 6–12 meses. Pode passar preço.
- **Bebedouros industriais**: R$1.500–6.000. Refil 3–6 meses. Qualificar quantidade + aplicação + voltagem ANTES de preço. NÃO perguntar gelada/natural cedo.
- **Filtro de Entrada / American Filter**: R$1.500–5.000. Refil 12–24m. **NUNCA preço sem visita técnica.**
- **Iron Free**: R$5k–15k. **SÓ para água de poço. NUNCA concessionária.** Núbia/closer educa, mas preço só com visita.
- **Scale Stop / Abrandador**: R$3k–10k. **NUNCA preço sem visita técnica.**
- **Frete grátis**: só SP capital + região imediata. Outras regiões, calcular.
- **Ferro na água**: só existe em poço. Concessionária NÃO tem ferro.

## ANTI-PADRÕES (NUNCA FAÇA)
- NUNCA pressionar ou criar urgência falsa.
- NUNCA prometer "filtra tudo" ou "água 100% pura".
- NUNCA dar preço de Iron Free, Scale Stop ou Filtro de Entrada sem visita.
- NUNCA empurrar Iron Free pra concessionária.
- NUNCA usar corporativês ("estimado cliente", "prezado", "à disposição").
- NUNCA mandar proposta antes de entender dor + decisor + prazo.

## TEMPERATURA DO LEAD
- **Frio**: 1–3 mensagens, perguntas genéricas, não disse problema. → Qualifique. Não proponha.
- **Morno**: descreveu dor, perguntou preço/refil, mas hesita. → Aprofunde dor + impacto + próximo passo concreto.
- **Quente**: pediu proposta, perguntou prazo entrega, falou "quero fechar". → Confirme decisor + fechamento + agende.

## DECISÃO TÁTICA (qual ação tomar)
1. Não sei a dor real? → **Qualifique** (1 pergunta de cada vez).
2. Produto técnico (Iron Free/Scale Stop/Filtro Entrada) sem visita? → **Agende visita**.
3. Sei a dor mas tem objeção? → **Quebre a objeção** antes de propor.
4. Dor clara + decisor + prazo? → **Mande proposta + peça compromisso**.
5. Mais de 2h parado em estágio Quente? → **Reengaje com pergunta direta**.

## SPIN LEVE + ESCADA DE COMPROMISSO
- **Situação**: 1 pergunta sobre contexto (família, vazão, fonte de água).
- **Problema**: o que incomoda hoje? (gosto, cheiro, mancha, ferro, custo refil).
- **Implicação**: o que isso causa? (criança não bebe, mancha roupa, gasto galão).
- **Need-payoff**: como seria resolver? → cria valor antes do preço.
- Toda mensagem termina com **próximo passo concreto** (data, hora, ação).

## QUEBRA DE OBJEÇÕES
- **"Vou pensar"** → "Tranquilo. O que ficou em dúvida — preço, instalação ou se serve pro seu caso?"
- **"Tá caro"** → "Entendo. Comparando com o quê? Galão, outro filtro ou expectativa? Te mostro o custo por dia."
- **"Preciso falar com esposa/marido"** → "Show. Quer que eu mande um resumo curto pra vocês decidirem juntos? Ou marco uma call rápida com os dois?"
- **"Já tenho um filtro"** → "Ótimo, qual modelo? Pergunto porque dependendo da fonte de água o seu pode não tá pegando ferro/cloro do jeito certo."
- **"Não é prioridade agora"** → "Sem stress. Posso te chamar daqui 30/60 dias? Enquanto isso, qual o maior incômodo com a água hoje?"
- **"Água daqui é boa"** → "É boa sim, mas a tubulação da rua e a caixa d'água acumulam. Já reparou sedimento no fundo?"
- **"Vou comprar mais barato em outro lugar"** → "Pode ser uma boa. Só checa 3 coisas: certificação INMETRO, prazo do refil e quem instala. Tô aqui se quiser comparar."
- **"É só ligar pra concessionária"** → "Concessionária resolve até a rua. Da rua pra dentro (caixa, encanamento) é com você. Faz sentido?"
- **"Vou ver no Mercado Livre"** → "Pode achar mais barato sim. Confere se tem assistência aqui na região e refil disponível — é o que pega depois."
- **"Não tenho tempo agora"** → "Sem problema. 2 minutos: me diz só a fonte da água (rua ou poço) que já te oriento o caminho certo."

## TOM
Brasileiro, cordial, direto. Frases curtas. Zero corporativês. Pode usar "show", "tranquilo", "faz sentido?", "bora". Trate por você.

## OUTPUT (JSON ESTRITO, SEM MARKDOWN, SEM TEXTO FORA DO JSON)
{
  "diagnostico": "1-2 linhas: onde o cliente tá, produto provável, temperatura (frio/morno/quente)",
  "estrategia": ["bullet 1", "bullet 2", "bullet 3"],
  "mensagem_sugerida": "Texto pronto pra colar no WhatsApp. PT-BR. Máx 320 chars. Termina com pergunta aberta ou CTA com data/hora."
}

Se faltar info crítica (fonte de água, quantidade, dor), o mensagem_sugerida deve ser uma PERGUNTA DE QUALIFICAÇÃO, não uma proposta.`;

// === ANÁLISE DE FUNIL/GARGALO DA CONVERSA WATI ===
// Diferente do /inbox/diretor-vendas (que sugere "o que mandar agora"), esse foca
// em DIAGNÓSTICO: em qual etapa do funil o lead travou e por quê. Saída pra coaching.
const ANALISE_FUNIL_PROMPT = `Você é um auditor de vendas sênior especialista em SPIN Selling, NEPQ e SDR de bebedouros/filtros industriais. Sua tarefa: ler a conversa WhatsApp entre um closer e um lead e identificar EXATAMENTE em que etapa do funil de consciência/decisão o lead travou e POR QUÊ.

ETAPAS DO FUNIL (em ordem):
1. consciencia — lead não sabe o tamanho do problema dele (água ruim, manutenção cara, equipamento errado)
2. descoberta — closer ainda não mapeou: fonte de água, qtd pessoas, aplicação, dor real, urgência
3. qualificacao — descoberta feita, falta confirmar tier (Diamante/Ouro/Prata) + voltagem + orçamento + prazo
4. proposta — preço passado, aguardando reação/negociação
5. fechamento — lead aceitou em principio, falta detalhe (forma pgto, entrega, instalação)

SINTOMAS POSSÍVEIS (escolha 1-3 que evidenciam o travamento, com citação literal da conversa):
- preco_cedo_demais — closer passou preço sem mapear dor/aplicação
- sem_descoberta — nenhuma pergunta SPIN (Situação, Problema, Implicação, Necessidade)
- sem_urgencia — closer não criou senso de urgência (custo de continuar como está)
- objecao_nao_tratada — cliente levantou objeção e closer ignorou ou só deu desconto
- sem_consciencia_dor — cliente não foi educado sobre impacto do problema atual
- desqualificado_lead — closer não filtrou se cliente tem orçamento/autoridade
- sem_proxima_acao — closer encerrou sem agendar próximo passo
- abandono_closer — closer deixou de responder >24h após interesse demonstrado
- abandono_cliente — cliente parou de responder após preço/proposta
- script_robotico — closer respondeu por copy/paste sem personalizar
- gatilho_morto — última msg do closer foi pergunta fechada (sim/não) sem CTA

Responda SOMENTE em JSON neste formato exato:
{
  "stage_atual_zoho": "(o stage que o Zoho diz)",
  "stage_funil_real": "consciencia|descoberta|qualificacao|proposta|fechamento",
  "stage_travou_em": "(qual das 5 etapas o lead efetivamente parou)",
  "diagnostico_curto": "1 frase de até 180 chars dizendo o gargalo principal",
  "sintomas": [
    { "tipo": "preco_cedo_demais", "severidade": "alta|media|baixa", "evidencia": "citação literal de até 200 chars da conversa" }
  ],
  "score_qualidade_conversa": 0-100,
  "perda_provavel": "alta|media|baixa",
  "proxima_acao": "1 frase prescritiva: o que o closer DEVE fazer agora pra recuperar",
  "padrao_recorrente_suspeita": "se você notou um vício clássico (ex: closer passa preço sem qualificar), descreva em 1 frase. Senão null"
}

Score 0-100: 0=conversa morta sem chance · 30=sintomas graves · 60=corrigível · 85+=conversa bem conduzida só esperando momento de fechar.`;

app.post('/manutencao/cliente/:dealId/analise-funil', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não configurado' });
  const { dealId } = req.params;
  const phone = req.body?.phone;
  if (!phone) return res.status(400).json({ error: 'phone obrigatório no body' });
  const phoneClean = normalizarPhoneWati(phone);
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });

  // Mensagens WATI
  let mensagens = [];
  try {
    const url = `${WATI_BASE}/api/v1/getMessages/${phoneClean}?pageSize=40&pageNumber=0`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
    if (r.ok) {
      const j = await r.json();
      const items = j.messages?.items || j.items || j.messages || [];
      mensagens = items.map(m => ({
        owner: m.owner === true || m.fromMe === true || m.eventType === 'sentMessage',
        texto: m.text || m.body || m.finalText || '',
        ts: m.created || m.timestamp || '',
      })).filter(m => m.texto).reverse();
    }
  } catch(_){}

  if (mensagens.length < 3) {
    return res.json({
      diagnostico_curto: 'Conversa muito curta pra análise (<3 mensagens). Aguarde mais interação.',
      sintomas: [], score_qualidade_conversa: null, perda_provavel: 'indeterminado',
      proxima_acao: 'Aguardar mais mensagens ou puxar conversa.',
      total_mensagens: mensagens.length,
    });
  }

  // Contexto Zoho
  let dealZoho = {};
  if (dealId && !dealId.startsWith('erp:')) {
    try {
      const tk = await getZohoToken();
      if (tk) {
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Deal_Name,Stage,Pipeline,Tier_Lead,Lead_Source,Cidade,Tipo_de_Agua,Produto_Vendido,Amount,Owner,Created_Time,Last_Activity_Time`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        const j = await r.json().catch(() => ({}));
        dealZoho = j.data?.[0] || {};
      }
    } catch(_){}
  }

  const conversa = mensagens.map(m => `${m.owner?'CLOSER':'CLIENTE'}: ${m.texto}`).join('\n');
  const userMsg = `=== DEAL ZOHO ===
Nome: ${dealZoho.Deal_Name || '?'}
Stage: ${dealZoho.Stage || '?'}
Pipeline: ${dealZoho.Pipeline || '?'}
Tier: ${dealZoho.Tier_Lead || '?'}
Cidade: ${dealZoho.Cidade || '?'}
Tipo Água: ${dealZoho.Tipo_de_Agua || 'não info'}
Produto: ${dealZoho.Produto_Vendido || '?'}
Valor: ${dealZoho.Amount ? 'R$ '+dealZoho.Amount : '?'}
Owner (closer): ${dealZoho.Owner?.name || '?'}
Created: ${dealZoho.Created_Time || '?'}
Última atividade: ${dealZoho.Last_Activity_Time || '?'}

=== CONVERSA WATI (${mensagens.length} msgs) ===
${conversa.slice(-6000)}`;

  try {
    const anthropic = new Anthropic({ apiKey });
    const r = await anthropic.messages.create({
      model: 'claude-sonnet-4-5-20250929',
      max_tokens: 1500,
      system: ANALISE_FUNIL_PROMPT,
      messages: [{ role: 'user', content: userMsg }],
    });
    const txt = r.content?.[0]?.text || '';
    let parsed = null;
    try {
      const m = txt.match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
    } catch(_){}
    if (!parsed) return res.json({ raw: txt, error: 'IA não retornou JSON válido' });
    res.json({
      ...parsed,
      total_mensagens: mensagens.length,
      owner: dealZoho.Owner?.name || '?',
      analisado_em: new Date().toISOString(),
    });
  } catch(e) {
    console.error('analise-funil err:', e.message);
    res.status(500).json({ error: 'IA falhou: ' + e.message });
  }
});

// === RAIO-X DE FUNIL POR VENDEDOR (admin/gestor) ===
// Roda análise em batch nos deals travados >Ndias do vendedor e agrega padrões.
app.get('/gestao/raiox-funil-vendedor', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não configurado' });
  const closerKey = req.query.closer;
  if (!closerKey || !USERS[closerKey]) return res.status(400).json({ error: 'closer query obrigatório' });
  const target = USERS[closerKey];
  const ownerName = target.crmOwner;
  const diasMinParado = Math.max(3, Math.min(30, parseInt(req.query.dias_parado, 10) || 7));
  const limite = Math.max(3, Math.min(15, parseInt(req.query.limite, 10) || 8));

  try {
    // Pega deals abertos do owner com Last_Activity > N dias
    const cutoffMs = Date.now() - diasMinParado * 86400000;
    const cutoffDate = new Date(cutoffMs).toISOString().slice(0, 10);
    const stagesAbertas = 'Primeiro Contato,Em Qualificação,Qualificado,Proposta,Proposta Quente,Proposta Fria,Em Atendimento';
    const deals = await zohoSearch(
      `((Owner:equals:${ownerName})and(Stage:in:${stagesAbertas})and(Last_Activity_Time:before:${cutoffDate}T23:59:59-03:00))`,
      'Deal_Name,Stage,Pipeline,Tier_Lead,Telefone_contato,Last_Activity_Time,Created_Time,Amount',
      50,
    ).catch(() => []);

    // Filtra os com phone e ordena: Diamante/Ouro primeiro, depois mais valor
    const tierRank = { Diamante: 0, Ouro: 1, Prata: 2, Bronze: 3, '': 4 };
    const candidatos = deals
      .filter(d => d.Telefone_contato)
      .sort((a,b) => {
        const ta = tierRank[a.Tier_Lead || ''] ?? 4;
        const tb = tierRank[b.Tier_Lead || ''] ?? 4;
        if (ta !== tb) return ta - tb;
        return (parseFloat(b.Amount)||0) - (parseFloat(a.Amount)||0);
      })
      .slice(0, limite);

    if (candidatos.length === 0) {
      return res.json({
        closer: target.name, total_analisados: 0, total_travados: 0,
        mensagem: `Nenhum deal aberto parado >${diasMinParado}d com telefone.`,
      });
    }

    // Roda análise em paralelo (máx 4 em paralelo pra não estourar API)
    const anthropic = new Anthropic({ apiKey });
    const analises = [];
    const chunks = [];
    for (let i = 0; i < candidatos.length; i += 4) chunks.push(candidatos.slice(i, i+4));
    for (const chunk of chunks) {
      const results = await Promise.all(chunk.map(async (d) => {
        const phoneClean = normalizarPhoneWati(d.Telefone_contato);
        let mensagens = [];
        try {
          const url = `${WATI_BASE}/api/v1/getMessages/${phoneClean}?pageSize=40&pageNumber=0`;
          const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
          if (r.ok) {
            const j = await r.json();
            const items = j.messages?.items || j.items || j.messages || [];
            mensagens = items.map(m => ({
              owner: m.owner === true || m.fromMe === true || m.eventType === 'sentMessage',
              texto: m.text || m.body || m.finalText || '',
            })).filter(m => m.texto).reverse();
          }
        } catch(_){}
        if (mensagens.length < 3) return { dealId: d.id, deal: d, sem_conversa: true };
        const conversa = mensagens.map(m => `${m.owner?'CLOSER':'CLIENTE'}: ${m.texto}`).join('\n');
        const userMsg = `Stage: ${d.Stage} | Tier: ${d.Tier_Lead||'?'} | Valor: ${d.Amount||'?'}\n\nConversa:\n${conversa.slice(-4500)}`;
        try {
          const r = await anthropic.messages.create({
            model: 'claude-sonnet-4-5-20250929',
            max_tokens: 900,
            system: ANALISE_FUNIL_PROMPT,
            messages: [{ role: 'user', content: userMsg }],
          });
          const txt = r.content?.[0]?.text || '';
          const m = txt.match(/\{[\s\S]*\}/);
          if (!m) return { dealId: d.id, deal: d, erro_parse: true };
          const parsed = JSON.parse(m[0]);
          return { dealId: d.id, deal: d, analise: parsed };
        } catch(e) {
          return { dealId: d.id, deal: d, erro: e.message };
        }
      }));
      analises.push(...results);
    }

    // Agrega
    const validas = analises.filter(a => a.analise);
    const sintomasCount = {};
    const stageTravouCount = {};
    let scoreTotal = 0, scoreCount = 0;
    for (const a of validas) {
      const an = a.analise;
      if (typeof an.score_qualidade_conversa === 'number') {
        scoreTotal += an.score_qualidade_conversa;
        scoreCount++;
      }
      const stage = an.stage_travou_em || 'desconhecido';
      stageTravouCount[stage] = (stageTravouCount[stage] || 0) + 1;
      for (const s of (an.sintomas || [])) {
        const k = s.tipo || 'desconhecido';
        if (!sintomasCount[k]) sintomasCount[k] = { count: 0, severidades: { alta: 0, media: 0, baixa: 0 } };
        sintomasCount[k].count++;
        if (s.severidade) sintomasCount[k].severidades[s.severidade] = (sintomasCount[k].severidades[s.severidade] || 0) + 1;
      }
    }
    const topSintomas = Object.entries(sintomasCount).sort((a,b) => b[1].count - a[1].count).slice(0, 5)
      .map(([tipo, v]) => ({ tipo, ...v }));
    const stageGargalo = Object.entries(stageTravouCount).sort((a,b) => b[1] - a[1])[0];

    res.json({
      closer: target.name,
      params: { dias_min_parado: diasMinParado, limite },
      total_analisados: validas.length,
      total_candidatos: analises.length,
      score_medio: scoreCount > 0 ? Math.round(scoreTotal / scoreCount) : null,
      stage_gargalo: stageGargalo ? { stage: stageGargalo[0], count: stageGargalo[1] } : null,
      top_sintomas: topSintomas,
      casos: validas.map(a => ({
        dealId: a.dealId,
        nome: a.deal.Deal_Name,
        tier: a.deal.Tier_Lead || '',
        stage: a.deal.Stage,
        valor: parseFloat(a.deal.Amount) || 0,
        ultima_atividade: a.deal.Last_Activity_Time,
        diagnostico: a.analise.diagnostico_curto,
        score: a.analise.score_qualidade_conversa,
        stage_travou: a.analise.stage_travou_em,
        sintomas_principais: (a.analise.sintomas || []).slice(0, 2).map(s => s.tipo),
        proxima_acao: a.analise.proxima_acao,
      })).sort((a,b) => (a.score||50) - (b.score||50)),
    });
  } catch(e) {
    console.error('raiox-funil err:', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.post('/inbox/diretor-vendas', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não configurado' });
  const { phone, dealId, contextoExtra } = req.body || {};
  if (!phone) return res.status(400).json({ error: 'phone obrigatório' });
  const phoneClean = normalizarPhoneWati(phone);
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });

  // Pega histórico WATI (até 30 últimas msgs)
  let mensagens = [];
  try {
    const url = `${WATI_BASE}/api/v1/getMessages/${phoneClean}?pageSize=30&pageNumber=0`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
    if (r.ok) {
      const j = await r.json();
      const items = j.messages?.items || j.items || j.messages || [];
      mensagens = items.map(m => ({
        owner: m.owner === true || m.fromMe === true || m.eventType === 'sentMessage',
        texto: m.text || m.body || m.finalText || '',
      })).filter(m => m.texto).reverse();
    }
  } catch(_){}

  // Contexto Closy
  const meta = loadManutMeta();
  const cli = dealId ? meta[dealId] || {} : {};
  const propostas = loadPropostas();
  const prop = dealId ? propostas[dealId] : null;
  // Dados do deal Zoho
  let dealZoho = {};
  if (dealId && !dealId.startsWith('erp:')) {
    try {
      const tk = await getZohoToken();
      if (tk) {
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Deal_Name,Stage,Pipeline,Layout,Tier_Lead,Lead_Source,Cidade,Tipo_de_Agua,Produto_Vendido,Description`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        const j = await r.json().catch(() => ({}));
        dealZoho = j.data?.[0] || {};
      }
    } catch(_){}
  }

  const conversa = mensagens.length ? mensagens.map(m => `${m.owner?'NÓS':'CLIENTE'}: ${m.texto}`).join('\n') : '(sem histórico ainda)';
  const contexto = `
=== CONTEXTO DO LEAD ===
Nome: ${dealZoho.Deal_Name || cli.nome || 'desconhecido'}
Cidade: ${dealZoho.Cidade || '?'}
Tipo de água: ${dealZoho.Tipo_de_Agua || 'não informado'}
Tier (qualidade do lead): ${dealZoho.Tier_Lead || '?'}
Stage Zoho: ${dealZoho.Stage || '?'}
Pipeline: ${dealZoho.Pipeline || '?'}
Origem: ${dealZoho.Lead_Source || '?'}
Produto interesse: ${dealZoho.Produto_Vendido || '?'}
Etapa Closy: ${cli.etapa || '?'}
Observações do CRM: ${cli.observacao || '—'}
${prop ? `PROPOSTA EM ABERTO: R$ ${prop.total} (${prop.items?.length||0} itens) · validade ${prop.validade}` : 'Sem proposta aberta'}
${contextoExtra ? `\nContexto adicional do closer: ${contextoExtra}` : ''}

=== CONVERSA WATI ===
${conversa.slice(-3500)}
`.trim();

  try {
    const anthropic = new Anthropic({ apiKey });
    const r = await anthropic.messages.create({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1200,
      system: DIRETOR_SYSTEM_PROMPT,
      messages: [{ role:'user', content: contexto + '\n\nO closer está pedindo ajuda. Analise e responda no formato JSON especificado.' }],
    });
    const txt = r.content?.[0]?.text || '';
    let parsed = null;
    try {
      const m = txt.match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
    } catch(_){}
    if (!parsed) return res.json({ raw: txt, error: 'IA não retornou JSON válido' });
    res.json({
      diagnostico: parsed.diagnostico || '',
      estrategia: parsed.estrategia || '',
      mensagemSugerida: parsed.mensagem_sugerida || parsed.mensagemSugerida || '',
      modelo: 'claude-sonnet-4',
    });
  } catch(e) {
    res.status(500).json({ error: 'IA falhou: ' + e.message });
  }
});

// === IA SUGESTÃO DE RESPOSTA + RESUMO (chat closer) ===
// POST /inbox/ia-sugerir { phone } → analisa últimas N mensagens e sugere 3 respostas
app.post('/inbox/ia-sugerir', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não configurado' });
  const { phone, dealId } = req.body || {};
  if (!phone) return res.status(400).json({ error: 'phone obrigatório' });
  const phoneClean = String(phone).replace(/\D/g, '');
  // Busca mensagens (mesma lógica do /inbox/mensagens)
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });
  let mensagens = [];
  try {
    const url = `${WATI_BASE}/api/v1/getMessages/${phoneClean}?pageSize=20&pageNumber=0`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
    if (r.ok) {
      const j = await r.json();
      const items = j.messages?.items || j.items || j.messages || [];
      mensagens = items.map(m => ({
        owner: m.owner === true || m.fromMe === true,
        texto: m.text || m.body || '',
      })).filter(m => m.texto).reverse(); // reverse pra cronológico
    }
  } catch(_){}
  if (!mensagens.length) return res.json({ sugestoes: ['Olá! Tudo bem? Aqui é da Tudo de Filtro.'], aviso: 'Sem histórico — sugestão genérica' });

  // Contexto do cliente (Closy meta)
  const meta = loadManutMeta();
  const cli = dealId ? meta[dealId] || {} : {};
  const propostas = loadPropostas();
  const prop = dealId ? propostas[dealId] : null;
  const conversa = mensagens.map(m => `${m.owner ? 'NÓS' : 'CLIENTE'}: ${m.texto}`).join('\n');

  try {
    const anthropic = new Anthropic({ apiKey });
    const r = await anthropic.messages.create({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 600,
      messages: [{
        role: 'user',
        content: `Você é um SDR experiente da Tudo de Filtro (filtros de água, bebedouros, purificadores). Analise a conversa abaixo e sugira EXATAMENTE 3 respostas curtas (máx 280 caracteres cada) que o vendedor pode mandar agora pro cliente.

REGRAS:
- Português brasileiro, tom amigável mas profissional
- Sem "olá" se já cumprimentou antes
- Foco em qualificação (quantas pessoas, fonte da água, problema atual) ou avanço (proposta, agendamento)
- Se cliente pediu preço, ofereça avaliação técnica gratuita antes
- Se cliente esfriou, retome o interesse com pergunta aberta
- NUNCA prometa preço sem visita técnica em produtos como Iron Free / Filtro de Entrada

CONTEXTO DO CLIENTE (Closy):
- Etapa: ${cli.etapa || 'desconhecida'}
- Última observação: ${cli.observacao || '—'}
${prop ? `- Proposta enviada: R$ ${prop.total} (${prop.items?.length||0} itens)` : '- Sem proposta enviada'}

CONVERSA:
${conversa.slice(-3000)}

RESPONDA EM JSON: { "sugestoes": ["resposta 1", "resposta 2", "resposta 3"] }`,
      }],
    });
    const txt = r.content?.[0]?.text || '';
    let parsed = { sugestoes: [] };
    try {
      const m = txt.match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
    } catch(_){}
    res.json({ sugestoes: parsed.sugestoes || [], modelo: 'claude-sonnet-4' });
  } catch(e) {
    res.status(500).json({ error: 'IA falhou: '+e.message });
  }
});

// POST /inbox/ia-resumir { phone, dealId } → gera resumo da conversa e salva em notas
app.post('/inbox/ia-resumir', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não configurado' });
  const { phone, dealId } = req.body || {};
  if (!phone || !dealId) return res.status(400).json({ error: 'phone e dealId obrigatórios' });
  const phoneClean = String(phone).replace(/\D/g, '');
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });
  let mensagens = [];
  try {
    const url = `${WATI_BASE}/api/v1/getMessages/${phoneClean}?pageSize=50&pageNumber=0`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
    if (r.ok) {
      const j = await r.json();
      const items = j.messages?.items || j.items || j.messages || [];
      mensagens = items.map(m => ({
        owner: m.owner === true || m.fromMe === true,
        texto: m.text || m.body || '',
      })).filter(m => m.texto).reverse();
    }
  } catch(_){}
  if (!mensagens.length) return res.status(400).json({ error: 'sem histórico pra resumir' });
  const conversa = mensagens.map(m => `${m.owner ? 'NÓS' : 'CLIENTE'}: ${m.texto}`).join('\n');
  try {
    const anthropic = new Anthropic({ apiKey });
    const r = await anthropic.messages.create({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 600,
      messages: [{
        role: 'user',
        content: `Resuma essa conversa de vendas em 4-6 bullets objetivos. Foque em: o que cliente pediu, dores/objeções, produto interessado, decisões, próximo passo combinado. Português brasileiro, direto.

CONVERSA:
${conversa.slice(-6000)}

Resposta apenas o resumo em bullets, sem introdução.`,
      }],
    });
    const resumo = r.content?.[0]?.text || '';
    const dt = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

    // 1) Salva em notas do Closy (legado, compat)
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    const obsAtual = meta[dealId].observacao || '';
    meta[dealId].observacao = (obsAtual ? obsAtual + '\n\n' : '') + `--- Resumo IA · ${dt} ---\n${resumo}`;
    addTimelineEvent(meta, dealId, { tipo:'ia', label:`🤖 Resumo IA gerado e salvo nas notas`, by: u.name });
    saveManutMeta(meta);

    // 2) Cria Note no Zoho CRM (que replica pro Closy via integração)
    let zohoNoteOk = false;
    let zohoNoteErr = null;
    try {
      const noteRes = await zoho.fetch(`/Deals/${dealId}/Notes`, {
        method: 'POST',
        body: {
          data: [{
            Note_Title: `🤖 Resumo IA - ${dt}`,
            Note_Content: `Gerado por IA (Closy) com base no histórico WhatsApp.\nVendedor: ${u.name}\n\n${resumo}`,
          }],
        },
      });
      zohoNoteOk = !!(noteRes?.data?.[0]?.code === 'SUCCESS' || noteRes?.data?.[0]?.status === 'success');
      if (!zohoNoteOk) zohoNoteErr = JSON.stringify(noteRes).slice(0, 200);
    } catch (e) {
      zohoNoteErr = e.message;
    }

    res.json({ ok: true, resumo, zoho_note: zohoNoteOk, zoho_err: zohoNoteErr });
  } catch(e) {
    res.status(500).json({ error: 'IA falhou: '+e.message });
  }
});

