// === REGISTRAR TENTATIVA DE CONTATO ===
// Body: { canal: 'wati'|'zapi'|'goto', mensagem?, autoEtapa? }
// - canal=zapi + mensagem → envia via Z-API
// - canal=wati + mensagem → tenta sendSessionMessage (falha se >24h)
// - canal=goto → apenas registra (chamada feita externamente)
// Sempre: log timeline, atualiza ultimoContato, move etapa se base_sem_contato
app.post('/manutencao/cliente/:dealId/registrar-contato', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin';
  const username = req.session.user.username;
  const { dealId } = req.params;
  const { canal, mensagem, observacao } = req.body || {};
  if (!['wati','zapi','goto'].includes(canal)) return res.status(400).json({ error: 'canal inválido (wati/zapi/goto)' });

  const meta = loadManutMeta();
  const prev = meta[dealId] || {};
  if (!isAdmin && prev.operadora && prev.operadora !== username) {
    return res.status(403).json({ error: 'esse cliente não está na sua carteira' });
  }

  // Pega o telefone do cliente (busca rápida no Zoho)
  let phone = '';
  try {
    const token = await getZohoToken();
    if (token) {
      const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Telefone_contato,Deal_Name`, {
        headers: { Authorization: `Zoho-oauthtoken ${token}` },
      });
      const j = await r.json().catch(() => ({}));
      phone = j.data?.[0]?.Telefone_contato || '';
    }
  } catch(_){}

  let resultadoEnvio = { ok: true, info: 'apenas registrado' };

  if (canal === 'zapi' && mensagem) {
    if (!phone) resultadoEnvio = { ok:false, error:'telefone não encontrado no Zoho' };
    else {
      const r = await zapiSend(phone, mensagem);
      resultadoEnvio = r;
    }
  } else if (canal === 'wati' && mensagem) {
    if (!phone) resultadoEnvio = { ok:false, error:'telefone não encontrado no Zoho' };
    else if (!WATI_TOKEN) resultadoEnvio = { ok:false, error:'WATI_TOKEN não configurado' };
    else {
      try {
        const phoneClean = String(phone).replace(/\D/g, '');
        const url = `${WATI_BASE}/api/v1/sendSessionMessage/${normalizarPhoneWati(phoneClean)}?messageText=${encodeURIComponent(mensagem)}`;
        const r = await fetch(url, { method:'POST', headers: { Authorization: `Bearer ${WATI_TOKEN}` }});
        const j = await r.json().catch(() => ({}));
        if (!r.ok || j.result === false) {
          resultadoEnvio = { ok:false, error: j.message || `WATI ${r.status} — fora da janela 24h? Use Z-API ou Disparo em massa (template).` };
        } else {
          resultadoEnvio = { ok:true, sent:true };
        }
      } catch(e) { resultadoEnvio = { ok:false, error:e.message }; }
    }
  }

  // Se o envio falhou, NÃO loga timeline nem move etapa (pra não enganar o operador)
  if (!resultadoEnvio.ok) {
    return res.status(400).json({ error: resultadoEnvio.error, canal, fallback: canal === 'wati' ? 'Tente Z-API (não tem janela 24h) ou disparo em massa via template.' : null });
  }

  // Sucesso: registra timeline + ultimoContato + move etapa
  if (!meta[dealId]) meta[dealId] = {};
  const userName = u?.name || username;
  const today = todayBR();
  const labelCanal = { wati:'WATI (sessão)', zapi:'Z-API', goto:'GoTo (ligação)' }[canal];
  const lblMsg = mensagem ? ` — "${String(mensagem).slice(0, 60)}${String(mensagem).length>60?'...':''}"` : (canal==='goto' ? ' — chamada registrada' : ' — inbox aberto');
  addTimelineEvent(meta, dealId, {
    tipo: 'contato',
    label: `📞 ${labelCanal}${lblMsg}`,
    by: userName,
    canal,
  });
  meta[dealId].ultimoContato = today;
  if (observacao) meta[dealId].observacao = observacao;
  // Auto-move etapa de base_sem_contato → tentativa_contato
  if (!meta[dealId].etapa || meta[dealId].etapa === 'base_sem_contato') {
    addTimelineEvent(meta, dealId, { tipo:'etapa', label:`Etapa: tentativa_contato (auto, via ${canal})`, by:userName });
    meta[dealId].etapa = 'tentativa_contato';
  }
  meta[dealId].updatedAt = new Date().toISOString();
  meta[dealId].updatedBy = userName;
  saveManutMeta(meta);

  res.json({ ok:true, canal, etapa: meta[dealId].etapa, ultimoContato: today, envio: resultadoEnvio });
});

// Helper: atualiza campo de última manutenção no Zoho quando lead fecha
async function zohoUpdateUltimaManutencao(dealId) {
  const token = await getZohoToken();
  if (!token) return { ok:false, error:'zoho indisponível' };
  try {
    const today = todayBR();
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}`, {
      method: 'PUT',
      headers: { Authorization: `Zoho-oauthtoken ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: [{ ultima_manuten_o: today }] }),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    return { ok: result?.code === 'SUCCESS', raw: j };
  } catch(e) { return { ok:false, error:e.message }; }
}

// Atualiza Deal no Zoho com campos arbitrários (usado no fluxo de fechar venda)
async function zohoUpdateDealFields(dealId, fields) {
  const token = await getZohoToken();
  if (!token) return { ok:false, error:'zoho indisponível' };
  try {
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}`, {
      method: 'PUT',
      headers: { Authorization: `Zoho-oauthtoken ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: [fields] }),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    return { ok: result?.code === 'SUCCESS', raw: j };
  } catch(e) { return { ok:false, error:e.message }; }
}

// Lê deal completo pra decidir se PUT (deal em proposta) ou POST novo (recorrência)
async function zohoGetDealFull(dealId) {
  const token = await getZohoToken();
  if (!token) return null;
  try {
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}`, {
      headers: { Authorization: `Zoho-oauthtoken ${token}` },
    });
    const j = await r.json().catch(() => ({}));
    return (j.data && j.data[0]) || null;
  } catch(_) { return null; }
}

// Cria deal novo (usado quando cliente já tem deal anterior "Fechado Ganho" e vem trocar refil)
async function zohoCreateDeal(fields) {
  const token = await getZohoToken();
  if (!token) return { ok:false, error:'zoho indisponível' };
  try {
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals`, {
      method: 'POST',
      headers: { Authorization: `Zoho-oauthtoken ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: [fields] }),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    return {
      ok: result?.code === 'SUCCESS',
      newDealId: result?.details?.id || null,
      raw: j,
    };
  } catch(e) { return { ok:false, error:e.message }; }
}

// Endpoint: fechar venda com TODAS as infos (valor, produto, forma de pagamento, local, observação)
// Atualiza Zoho (Amount, Produto_Vendido, Local_Compra, Stage='Fechado Ganho', Closing_Date, ultima_manuten_o)
// + grava metadados locais (formaPagamento, observação, audit log)
app.post('/manutencao/cliente/:dealId/fechar-venda', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin';
  const username = req.session.user.username;
  const userName = u?.name || username;
  const { dealId } = req.params;
  const { valor, produto, formaPagamento, localCompra, observacao } = req.body || {};

  // Validações
  const valorNum = parseFloat(valor);
  if (!valorNum || valorNum <= 0) return res.status(400).json({ error: 'valor obrigatório e > 0' });
  if (!localCompra) return res.status(400).json({ error: 'localCompra obrigatório' });
  if (!produto) return res.status(400).json({ error: 'produto obrigatório' });

  // Carteira check (closer só fecha venda da própria)
  const meta = loadManutMeta();
  if (!isAdmin && meta[dealId]?.operadora && meta[dealId].operadora !== username) {
    return res.status(403).json({ error: 'cliente não é da sua carteira' });
  }

  const today = todayBR();
  if (!meta[dealId]) meta[dealId] = {};
  meta[dealId].etapa = 'finalizado_ganho';
  meta[dealId].Local_Compra = localCompra;
  meta[dealId].formaPagamento = formaPagamento || null;
  meta[dealId].valorFechamento = valorNum;
  meta[dealId].produtoFechamento = produto;
  meta[dealId].observacaoFechamento = observacao || null;
  meta[dealId].ultimaManutencao = today;
  meta[dealId].fechadoEm = new Date().toISOString();
  meta[dealId].fechadoPor = username;
  meta[dealId].updatedBy = userName;
  meta[dealId].etapaUpdatedAt = new Date().toISOString();

  addTimelineEvent(meta, dealId, {
    tipo: 'venda',
    label: `✅ Venda fechada por ${userName}: R$ ${valorNum.toLocaleString('pt-BR',{minimumFractionDigits:2})} · ${produto}` +
           (formaPagamento ? ` · ${formaPagamento}` : '') +
           ` · ${localCompra}` +
           (observacao ? `\nObs: ${observacao}` : ''),
    by: userName,
  });
  saveManutMeta(meta);

  // === Lógica híbrida no Zoho ===
  // - Se deal atual em "Proposta"/outras stages → PUT (fecha existente)
  // - Se deal JÁ era "Fechado Ganho" (recorrência: troca de refil) → POST cria deal NOVO
  //   linkado ao mesmo Contact/Account, preservando histórico da venda original
  const dealAtual = await zohoGetDealFull(dealId).catch(() => null);
  const stageAtual = (dealAtual?.Stage || '').toLowerCase();
  const jaEraGanho = stageAtual.includes('fechado') && stageAtual.includes('ganho');

  let zohoResult = { ok: false, mode: null };
  let novoDealId = null;

  if (!jaEraGanho) {
    // CASO 1: Deal estava em outra stage (Proposta etc) → fecha ele
    const zohoFields = {
      Amount: valorNum,
      Produto_Vendido: produto,
      Local_Compra: localCompra,
      Stage: 'Fechado Ganho',
      Closing_Date: today,
      ultima_manuten_o: today,
    };
    const r = await zohoUpdateDealFields(dealId, zohoFields).catch(e => ({ ok:false, error:e.message }));
    zohoResult = { ...r, mode: 'put_existente' };
  } else {
    // CASO 2: Cliente já tinha venda fechada → cria novo deal pra essa troca,
    // mantendo o pai intacto e preservando histórico financeiro.
    const nomeCliente = dealAtual?.Deal_Name || meta[dealId]?.nome || 'Cliente';
    const novoDealFields = {
      Deal_Name: `${nomeCliente} — Troca refil ${today}`,
      Stage: 'Fechado Ganho',
      Amount: valorNum,
      Closing_Date: today,
      Produto_Vendido: produto,
      Local_Compra: localCompra,
      ultima_manuten_o: today,
      // Copia contexto do deal pai (Pipeline, Layout, Contact, Account, Owner)
      ...(dealAtual?.Pipeline && { Pipeline: dealAtual.Pipeline }),
      ...(dealAtual?.Layout?.id && { Layout: { id: dealAtual.Layout.id } }),
      ...(dealAtual?.Contact_Name?.id && { Contact_Name: { id: dealAtual.Contact_Name.id } }),
      ...(dealAtual?.Account_Name?.id && { Account_Name: { id: dealAtual.Account_Name.id } }),
      ...(dealAtual?.Owner?.id && { Owner: { id: dealAtual.Owner.id } }),
      ...(dealAtual?.Telefone_contato && { Telefone_contato: dealAtual.Telefone_contato }),
      ...(dealAtual?.Email && { Email: dealAtual.Email }),
      // Tag pra identificar que esse deal é uma troca recorrente
      Tag: [{ name: 'Reflow' }, { name: 'Troca Refil' }],
    };
    const r = await zohoCreateDeal(novoDealFields).catch(e => ({ ok:false, error:e.message }));
    novoDealId = r.newDealId;
    zohoResult = { ...r, mode: 'post_novo_deal' };
    // Atualiza só o ultima_manuten_o no deal pai (não muda Amount/Stage/Closing_Date dele)
    if (zohoResult.ok) {
      await zohoUpdateUltimaManutencao(dealId).catch(() => {});
    }
  }

  // Salva referência do novo deal no meta (pra rastrear histórico)
  if (novoDealId) {
    meta[dealId].dealsRefil = meta[dealId].dealsRefil || [];
    meta[dealId].dealsRefil.push({ id: novoDealId, valor: valorNum, produto, data: today });
    saveManutMeta(meta);
  }

  // Audit log
  try {
    _auditLogSafe({
      action_type: 'sale_closed',
      action_origin: 'closer_manual',
      crm_module: 'Deals',
      crm_record_id: String(dealId),
      crm_record_name: meta[dealId]?.nome || null,
      actor_id: username,
      actor_name: userName,
      payload: {
        valor: valorNum, produto, formaPagamento, localCompra, observacao,
        zoho_mode: zohoResult.mode, zoho_ok: zohoResult.ok,
        novoDealId,
      },
    });
  } catch(_){}

  res.json({
    ok: true,
    dealId,
    novoDealId,
    zoho: zohoResult,
    salvoLocal: true,
    venda: { valor: valorNum, produto, formaPagamento, localCompra, observacao, fechadoEm: meta[dealId].fechadoEm },
  });
});

// Mover etapa do Kanban — closer pode mover apenas leads da carteira dele
app.post('/manutencao/etapa/:dealId', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin';
  const username = req.session.user.username;
  if (!isAdmin) {
    const meta = loadManutMeta();
    if (meta[req.params.dealId]?.operadora !== username) return res.status(403).json({ error: 'cliente não é da sua carteira' });
  }
  const { dealId } = req.params;
  const { etapa, motivoPerda, observacaoEtapa } = req.body || {};
  if (!ETAPAS_CLOSY.find(e => e.id === etapa)) return res.status(400).json({ error: 'etapa inválida' });
  if (etapa === 'finalizado_perdido' && !motivoPerda) {
    return res.status(400).json({ error: 'motivo de perda obrigatório pra finalizar perdido' });
  }
  // CASO ESPECIAL: "comprou em outro lugar" → não fecha como perdido, volta pra base
  if (etapa === 'finalizado_perdido' && MOTIVOS_PERDA_REAGENDA.includes(motivoPerda)) {
    return res.status(400).json({
      error: 'Esse motivo não fecha como perdido — use o endpoint /reagendar-base com data de recontato',
      code: 'reagendar_em_vez_de_perder',
      motivos_que_reagendam: MOTIVOS_PERDA_REAGENDA,
    });
  }
  // VALIDAÇÃO obrigatória: pra fechar venda, precisa de Local_Compra preenchido
  if (etapa === 'finalizado_ganho') {
    const metaCheck = loadManutMeta();
    const localCompra = metaCheck[dealId]?.Local_Compra;
    if (!localCompra) {
      return res.status(400).json({
        error: 'Pra fechar venda preencha "Local da compra" antes (Loja física / Online / Tele ativo / Receptivo / etc).',
        code: 'local_compra_obrigatorio',
        campo_faltando: 'Local_Compra',
      });
    }
  }
  const meta = loadManutMeta();
  if (!meta[dealId]) meta[dealId] = {};
  const userName = USERS[req.session.user.username]?.name || '?';
  const etapaAnterior = meta[dealId].etapa || 'base_sem_contato';
  if (etapaAnterior !== etapa) {
    const etapaLabel = ETAPAS_CLOSY.find(e => e.id === etapa)?.label || etapa;
    addTimelineEvent(meta, dealId, {
      tipo:'etapa',
      label:`Movido pra "${etapaLabel}"${motivoPerda?` (motivo: ${motivoPerda})`:''}${observacaoEtapa?` — ${observacaoEtapa}`:''}`,
      by:userName,
    });
  }
  meta[dealId].etapa = etapa;
  if (motivoPerda) meta[dealId].motivoPerda = motivoPerda;
  if (observacaoEtapa) meta[dealId].observacaoEtapa = observacaoEtapa;
  meta[dealId].etapaUpdatedAt = new Date().toISOString();
  meta[dealId].updatedBy = userName;

  // Quando vai pra "Finalizado Ganho" → atualiza Zoho com data da última manutenção
  // + marca pra recalcular próxima troca no próximo refresh
  let zohoUpdate = null;
  if (etapa === 'finalizado_ganho') {
    meta[dealId].ultimaManutencao = todayBR();
    zohoUpdate = await zohoUpdateUltimaManutencao(dealId);
    addTimelineEvent(meta, dealId, {
      tipo: 'venda',
      label: `Manutenção vendida! Última troca: ${todayBR()}. ${zohoUpdate?.ok?'Zoho atualizado.':'Zoho falhou: '+(zohoUpdate?.error||'?')}`,
      by: userName,
    });
  }

  saveManutMeta(meta);

  // Quando vai pra "Agendado" e ainda não tem OS no Auvo → cria automaticamente
  // (só se a flag autoAuvo === true vier do front, pra evitar criar OS sem confirmar)
  let auvoAutoOs = null;
  if (etapa === 'agendado' && !meta[dealId].auvoTaskId && req.body?.autoAuvo === true) {
    const r = await criarOsAuvoParaDeal(dealId, req.body.auvoOpts || {});
    if (r.ok) {
      meta[dealId].auvoTaskId = r.taskId;
      meta[dealId].auvoTaskDate = r.taskDate;
      addTimelineEvent(meta, dealId, {
        tipo:'auvo-os',
        label:`📅 OS Auvo #${r.taskId} criada automaticamente pra ${r.taskDate}`,
        by: userName,
        auvoTaskId: r.taskId,
      });
      saveManutMeta(meta);
      auvoAutoOs = { ok:true, taskId: r.taskId, taskDate: r.taskDate };
    } else {
      auvoAutoOs = { ok:false, error: r.error };
    }
  }

  res.json({ ok: true, meta: meta[dealId], zohoUpdate, auvoAutoOs });
});

