function loadFunis() {
  const v = kvOrFile('funis-closy', FUNIS_FILE, null);
  if (Array.isArray(v) && v.length) return v;
  return [...FUNIS_TEMPLATES];
}
function saveFunis(funis) { kvAndFile('funis-closy', FUNIS_FILE, funis); }

app.get('/manutencao/funis', requireAuth, (req, res) => {
  res.json({ funis: loadFunis(), templates: FUNIS_TEMPLATES });
});

app.post('/manutencao/funis', requireAuth, (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { funil } = req.body || {};
  if (!funil || !funil.id || !funil.nome || !Array.isArray(funil.etapas) || !funil.etapas.length) {
    return res.status(400).json({ error: 'funil precisa de id, nome, etapas[]' });
  }
  // Valida etapas
  for (const e of funil.etapas) {
    if (!e.id || !e.label) return res.status(400).json({ error: 'cada etapa precisa de id + label' });
  }
  // Garante etapa final ganho/perdido (sistema usa essas pra agregação)
  const ids = funil.etapas.map(e => e.id);
  if (!ids.includes('finalizado_ganho') || !ids.includes('finalizado_perdido')) {
    return res.status(400).json({ error: 'todo funil precisa ter as etapas finalizado_ganho e finalizado_perdido' });
  }
  const funis = loadFunis();
  const idx = funis.findIndex(f => f.id === funil.id);
  if (idx >= 0) funis[idx] = { ...funis[idx], ...funil };
  else funis.push(funil);
  saveFunis(funis);
  res.json({ ok:true, funil: funis[idx >= 0 ? idx : funis.length - 1] });
});

app.delete('/manutencao/funis/:id', requireAuth, (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { id } = req.params;
  if (id === 'default') return res.status(400).json({ error: 'não dá pra apagar o funil padrão' });
  const funis = loadFunis();
  const novo = funis.filter(f => f.id !== id);
  if (novo.length === funis.length) return res.status(404).json({ error: 'funil não encontrado' });
  saveFunis(novo);
  res.json({ ok:true });
});

app.get('/manutencao/funis-page', requireAuth, (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.redirect('/manutencao');
  res.render('funis-closy', { user: req.session.user });
});

