function loadRegrasManut() {
  try { return JSON.parse(require('fs').readFileSync(REGRAS_FILE, 'utf8')); }
  catch { return REGRAS_DEFAULT; }
}
function saveRegrasManut(rules) {
  try { require('fs').mkdirSync(path.dirname(REGRAS_FILE), { recursive: true });
        require('fs').writeFileSync(REGRAS_FILE, JSON.stringify(rules, null, 2)); } catch(_){}
}

function loadDisparos() {
  try { return JSON.parse(require('fs').readFileSync(DISPAROS_FILE, 'utf8')); }
  catch { return {}; }
}
function saveDisparos(d) {
  try { require('fs').mkdirSync(path.dirname(DISPAROS_FILE), { recursive: true });
        require('fs').writeFileSync(DISPAROS_FILE, JSON.stringify(d, null, 2)); } catch(_){}
}

// Identifica qual regra se aplica a um deal (1° match)
// Suporta pseudo-tokens no pattern: __layout:NomeLayout e __pipeline:NomePipeline
// pra capturar deals via metadados (ex: Telemarketing + Fúnil Base = bebedouro)
function regraDoDeal(deal, regras) {
  const layoutName = (deal.Layout?.name || deal.Layout?.display_label || '').toString();
  const pipeName = (deal.Pipeline || '').toString();
  const blob = (deal.produtosReais || deal.Produto_Vendido || '') + ' ' + (deal.Deal_Name || '');
  // Inclui tokens de layout/pipeline pro regex bater
  const blobCompleto = `${blob} __layout:${layoutName} __pipeline:${pipeName}`;
  for (const r of regras) {
    if (!r.ativo) continue;
    try {
      if (new RegExp(r.pattern, 'i').test(blobCompleto)) return r;
    } catch(_){}
  }
  return null;
}

