app.get('/manutencao/regras', requireAuth, (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  res.json({ regras: loadRegrasManut(), default: REGRAS_DEFAULT });
});
app.post('/manutencao/regras', requireAuth, (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { regras } = req.body || {};
  if (!Array.isArray(regras)) return res.status(400).json({ error:'regras precisa ser array' });
  // Valida cada regra
  for (const r of regras) {
    if (!r.id || !r.pattern || !r.meses || !r.label) return res.status(400).json({ error: 'regra incompleta: '+JSON.stringify(r) });
    try { new RegExp(r.pattern); } catch(e) { return res.status(400).json({ error: 'regex inválido em '+r.id+': '+e.message }); }
  }
  saveRegrasManut(regras);
  res.json({ ok: true, total: regras.length });
});

// === HELPER Zoho: criar Task ===
async function zohoCreateTask({ dealId, ownerId, subject, description, dueDate, status='Not Started', priority='High' }) {
  const token = await getZohoToken();
  if (!token) return { ok:false, error:'zoho indisponível' };
  const body = { data: [{
    Subject: subject,
    What_Id: dealId,
    $se_module: 'Deals',
    Description: description || '',
    Due_Date: dueDate, // YYYY-MM-DD
    Status: status,
    Priority: priority,
    ...(ownerId ? { Owner: { id: ownerId } } : {}),
  }] };
  try {
    const r = await fetch('https://www.zohoapis.com/crm/v6/Tasks', {
      method:'POST', headers:{ Authorization:`Zoho-oauthtoken ${token}`, 'Content-Type':'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json();
    const result = j.data?.[0];
    if (result?.code === 'SUCCESS') return { ok:true, taskId: result.details?.id };
    return { ok:false, error: result?.message || JSON.stringify(j).slice(0,200) };
  } catch(e) { return { ok:false, error:e.message }; }
}

// === HELPER: enviar email via SMTP suite UOL ===
// Tenta nodemailer (envio direto); se falhar, fallback pra fila JSON.
let _SMTP_TRANSPORTER = null;
function _getSmtpTransporter() {
  if (_SMTP_TRANSPORTER) return _SMTP_TRANSPORTER;
  try {
    const nodemailer = require('nodemailer');
    _SMTP_TRANSPORTER = nodemailer.createTransport({
      host: process.env.SMTP_HOST || 'smtp.suite.uol',
      port: parseInt(process.env.SMTP_PORT || '587', 10),
      secure: false, // TLS via STARTTLS
      auth: {
        user: process.env.SMTP_USER || 'informativo@tudodefiltro.com.br',
        pass: process.env.SMTP_PASS || '',
      },
    });
    return _SMTP_TRANSPORTER;
  } catch(e) {
    console.warn('[smtp] nodemailer não disponível:', e.message);
    return null;
  }
}
async function enviarEmailDireto({ to, subject, html, text, replyTo }) {
  if (!to) return { ok:false, error:'sem destinatário' };
  const t = _getSmtpTransporter();
  const fromEmail = process.env.SMTP_USER || 'informativo@tudodefiltro.com.br';
  const fromName = 'Diretor TDF';
  if (t && process.env.SMTP_PASS) {
    try {
      const info = await t.sendMail({
        from: `${fromName} <${fromEmail}>`,
        to,
        subject,
        text: text || '',
        html,
        replyTo: replyTo || fromEmail,
      });
      return { ok:true, messageId: info.messageId, queued:false };
    } catch(e) {
      console.error('[smtp send]', e.message);
      // Cai pro fallback
    }
  }
  // Fallback: enfileira em JSON
  const pendentes = path.join(__dirname, 'data/emails-pendentes.json');
  let arr = [];
  try { arr = JSON.parse(require('fs').readFileSync(pendentes, 'utf8')); } catch(_){}
  arr.push({ to, subject, html, text, createdAt: new Date().toISOString() });
  try {
    require('fs').mkdirSync(path.dirname(pendentes), { recursive: true });
    require('fs').writeFileSync(pendentes, JSON.stringify(arr, null, 2));
  } catch(_){}
  return { ok:true, queued:true, motivo: 'SMTP indisponível ou sem SMTP_PASS' };
}

// Compat com a função antiga
async function sendEmailManut(toEmail, toName, subject, htmlBody) {
  return enviarEmailDireto({ to: toName ? `${toName} <${toEmail}>` : toEmail, subject, html: htmlBody });
}

// Endpoint admin genérico — envia e-mail arbitrário pelo informativo@tudodefiltro.com.br
