// === WATI API: send template + list templates (disparo em massa) ===
const WATI_BASE = (process.env.WATI_BASE_URL || 'https://live-mt-server.wati.io/2708').replace(/\/$/, '');
// Strip "Bearer " prefix se vier no env (resiliência — código adiciona Bearer no header)
const WATI_TOKEN = (process.env.WATI_TOKEN || '').replace(/^Bearer\s+/i, '');

let _watiTemplateCache = null; // { templateName: {customParams,...} }

async function watiListTemplates() {
  if (!WATI_TOKEN) return { templates: [], error: 'WATI_TOKEN não configurado' };
  try {
    // Pagina TODAS as páginas (até 10 = 2000 templates)
    let all = [];
    for (let pageNumber = 1; pageNumber <= 10; pageNumber++) {
      const url = `${WATI_BASE}/api/v1/getMessageTemplates?pageSize=200&pageNumber=${pageNumber}`;
      const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
      if (!r.ok) break;
      const j = await r.json();
      const items = j.messageTemplates || j.data || [];
      if (!items.length) break;
      all.push(...items);
      if (items.length < 200) break;
    }
    const list = all.map(t => ({
      name: t.elementName || t.name,
      category: t.category || '',
      language: t.language || 'pt_BR',
      status: t.status || '',
      body: t.body || (t.components?.find(c => c.type === 'BODY')?.text) || '',
      header: t.header || (t.components?.find(c => c.type === 'HEADER')?.text) || '',
      footer: t.footer || (t.components?.find(c => c.type === 'FOOTER')?.text) || '',
      varCount: (((t.body || '').match(/\{\{\d+\}\}/g)) || []).length,
      customParams: t.customParams || [],  // 14/Mai/2026: precisa pra mapear paramName real (não posicional)
    })).filter(t => /APPROVED/i.test(t.status) || !t.status);
    // Cache em memória pro disparo-massa usar paramName correto
    _watiTemplateCache = {};
    list.forEach(t => { _watiTemplateCache[t.name] = t; });
    return { templates: list };
  } catch (e) {
    return { templates: [], error: e.message };
  }
}

async function watiSendTemplate(phone, templateName, parameters = []) {
  if (!WATI_TOKEN) return { ok: false, error: 'WATI_TOKEN não configurado' };
  const phoneClean = String(phone).replace(/\D/g, '');
  try {
    // 14/Mai/2026 fix: WATI v1 espera parameters com paramName REAL (não posicional "1","2").
    // Template define customParams: [{paramName: 'name', paramValue: 'Paulo'}]
    // Bug anterior mandava {name:"1",value:"João"} → WATI rejeitava "Check your template".
    // Agora busca paramNames do template cacheado e usa.
    if (!_watiTemplateCache) {
      try { await watiListTemplates(); } catch(_){}
    }
    const tplMeta = _watiTemplateCache?.[templateName];
    const paramNames = (tplMeta?.customParams || []).map(p => p.paramName);
    const url = `${WATI_BASE}/api/v1/sendTemplateMessage?whatsappNumber=${normalizarPhoneWati(phoneClean)}`;
    const body = {
      template_name: templateName,
      broadcast_name: `disparo_${Date.now()}`,
      parameters: parameters.map((p, i) => ({
        name: paramNames[i] || String(i + 1), // usa paramName real se disponível
        value: String(p),
      })),
    };
    const r = await fetch(url, {
      method: 'POST',
      headers: { Authorization: `Bearer ${WATI_TOKEN}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json().catch(() => ({}));
    // 14/Mai/2026: WATI retorna 200 + result:true mesmo quando NÃO entrega (validWhatsAppNumber:false)
    // Bug histórico: deals marcados como enviados, cliente nunca recebeu.
    const validWA = j.validWhatsAppNumber;
    const result = j.result;
    const success = r.ok && result !== false && validWA !== false;
    if (!success) {
      const reason = !r.ok ? `HTTP ${r.status}` :
                     result === false ? `wati result=false` :
                     validWA === false ? `validWhatsAppNumber=false` :
                     'unknown';
      console.log(`[watiSendTemplate] FAIL ${phoneClean} tpl=${templateName}: ${reason} | raw=${JSON.stringify(j).slice(0, 200)}`);
      return { ok: false, status: r.status, raw: j, error: `${reason}: ${j.info || j.message || ''}`.slice(0, 200) };
    }
    return { ok: true, status: r.status, raw: j };
  } catch (e) {
    console.log(`[watiSendTemplate] EXCEPTION ${phoneClean} tpl=${templateName}: ${e.message}`);
    return { ok: false, error: e.message };
  }
}

// 06/Mai/2026: registra qual template foi enviado pra cada deal + quando.
// Usado pra exibir nos cards do /manutencao ("Último template: tdf_followup_d1_v1 — 06/05/2026").
// Também grava na timeline pra rastrear histórico de envios.
function registrarUltimoTemplate(dealId, templateName, by = 'sistema') {
  if (!dealId || !templateName) return;
  try {
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    const nowIso = new Date().toISOString();
    meta[dealId].ultimoTemplate = templateName;
    meta[dealId].ultimoTemplateData = nowIso;
    meta[dealId].ultimoContato = nowIso.slice(0, 10);
    meta[dealId].updatedAt = nowIso;
    if (typeof addTimelineEvent === 'function') {
      addTimelineEvent(meta, dealId, {
        tipo: 'template',
        label: `Template enviado: ${templateName}`,
        by,
      });
    }
    saveManutMeta(meta);
  } catch (e) {
    console.error('[registrarUltimoTemplate]', e.message);
  }
}

// === INBOX CONVERSACIONAL (WATI) ===
// GET /inbox/conversas → lista conversas recentes (com inbound nos últimos 7d)
app.get('/inbox/conversas', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const isAdmin = u.role === 'admin' || isGestor(u);
  const username = req.session.user.username;
  const myCrmOwner = u.crmOwner;

  const inbox = loadWatiInbox();
  const meta = loadManutMeta();

  // AUTO-MOVE: lead que tá na inbox = respondeu = está em conversa.
  // Se etapa Closy é base/tentativa → promove pra em_conversa. Roda EM CADA load.
  let etapasMovidas = 0;
  for (const m of Object.values(inbox)) {
    const etapaAtual = meta[m.dealId]?.etapa || 'base_sem_contato';
    if (['base_sem_contato', 'tentativa_contato'].includes(etapaAtual)) {
      if (!meta[m.dealId]) meta[m.dealId] = {};
      addTimelineEvent(meta, m.dealId, {
        tipo:'etapa',
        label:`Etapa: em_conversa (auto, cliente respondeu via ${m.canal||'WATI'})`,
        by:'Sistema',
      });
      meta[m.dealId].etapa = 'em_conversa';
      meta[m.dealId].updatedAt = new Date().toISOString();
      etapasMovidas++;
    }
  }
  if (etapasMovidas) {
    saveManutMeta(meta);
    console.log(`[inbox/conversas] auto-move: ${etapasMovidas} leads → em_conversa`);
  }

  // Constrói lista de conversas a partir do storage de inbox WATI
  let convs = Object.values(inbox).map(m => {
    const dealMeta = meta[m.dealId] || {};
    const iaAtendendo = isIaAtendendoMeta(meta, m.dealId, []); // tags Zoho enriquecidas no batch abaixo
    // semDealZoho: dealId é placeholder 'wati:phone' OU storage marcou explicitamente
    const semDealZoho = !!m.semDealZoho || String(m.dealId||'').startsWith('wati:');
    return {
      dealId: m.dealId,
      phone: m.phone,
      ultimaMsg: m.text,
      count: m.count || 1,
      ts: m.ts,
      visto: m.visto || false,
      operadora: dealMeta.operadora || null,
      etapa: dealMeta.etapa || 'base_sem_contato',
      sourceWati: m.sourceWati || '',
      produtoWati: m.produtoWati || '',
      nomeWati: m.nomeWati || '',
      canal: m.canal || 'wati', // wati | zapi — usado pra filtro e badge na UI
      semDealZoho,
      iaAtendendo, // true se Núbia atendendo (timeline + tag Zoho)
    };
  });

  // Enriquece com nome do cliente + Owner Zoho (em batch) — exclui placeholders 'wati:' e 'erp:'
  const dealIds = convs.map(c => c.dealId).filter(d => d && !d.startsWith('erp:') && !d.startsWith('wati:'));
  const ownersZoho = {}; // dealId → owner name
  if (dealIds.length) {
    try {
      const token = await getZohoToken();
      if (token) {
        // Busca em paralelo (limite 50 deals + 5 paralelo)
        const limit = 50;
        const targets = dealIds.slice(0, limit);
        for (let i = 0; i < targets.length; i += 5) {
          const lote = targets.slice(i, i + 5);
          await Promise.all(lote.map(async id => {
            try {
              const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${id}?fields=Deal_Name,Tier_Lead,Owner,Lead_Source,Stage,Tag`, {
                headers: { Authorization: `Zoho-oauthtoken ${token}` },
              });
              if (r.ok) {
                const j = await r.json();
                const d = j.data?.[0];
                const conv = convs.find(c => c.dealId === id);
                if (d && conv) {
                  conv.nome = d.Deal_Name || conv.phone;
                  conv.tier = d.Tier_Lead || '-';
                  conv.ownerZoho = d.Owner?.name || '';
                  conv.leadSource = d.Lead_Source || '';
                  conv.stageZoho = d.Stage || '';
                  conv.tags = (d.Tag || []).map(t => t.name || t);
                  // Pré-lead: tag 'pré-lead' OU stage anterior a Qualificado (e não Fechado)
                  const stagePre = /^(IA sem Contato|Leads Novos|Etapa IA|Primeiro Contato|Em Qualifica)/i;
                  const stageQualOuFrente = /^(Qualificado|Proposta|Em Atendimento|Fechado)/i;
                  conv.preLead = (conv.tags.includes('pré-lead') || conv.tags.includes('pre-lead'))
                    || (stagePre.test(conv.stageZoho) && !stageQualOuFrente.test(conv.stageZoho));
                  // Recheca IA atendendo agora COM as tags Zoho
                  conv.iaAtendendo = isIaAtendendoMeta(meta, id, d.Tag);
                  ownersZoho[id] = d.Owner?.name || '';
                }
              }
            } catch(_){}
          }));
        }
      }
    } catch(e) { console.warn('inbox enrich:', e.message); }
  }

  // INBOX LIBERADO: todos veem todas as conversas (todo closer tem cadastro WATI).
  // Owner Zoho fica como info no card mas não filtra.

  // Continua com o restante (já enriqueceu acima, mantém compatibilidade do código antigo)
  if (false) {
    try {
      const token = await getZohoToken();
      if (token) {
        for (const id of dealIds.slice(0, 50)) {
          const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${id}?fields=Deal_Name,Tier_Lead`, {
            headers: { Authorization: `Zoho-oauthtoken ${token}` }
          });
          if (r.ok) {
            const j = await r.json();
            const d = j.data?.[0];
            const conv = convs.find(c => c.dealId === id);
            if (d && conv) {
              conv.nome = d.Deal_Name || conv.phone;
              conv.tier = d.Tier_Lead || '-';
            }
          }
        }
      }
    } catch(e) { console.warn('inbox enrich:', e.message); }
  }

  convs.sort((a,b) => b.ts - a.ts);
  res.json({ total: convs.length, naoVistos: convs.filter(c => !c.visto).length, conversas: convs });
});

// GET /inbox/mensagens?phone=X&todas=1&canal=wati|zapi → histórico da conversa
// todas=1 → busca várias páginas (até 1000 mensagens) pra pegar histórico completo
// canal=zapi → busca histórico do Z-API em vez do WATI
app.get('/inbox/mensagens', requireAuth, async (req, res) => {
  const phone = (req.query.phone || '').replace(/\D/g, '');
  if (!phone) return res.status(400).json({ error: 'phone obrigatório' });
  const canal = (req.query.canal === 'zapi') ? 'zapi' : 'wati';

  // === Z-API histórico ===
  if (canal === 'zapi') {
    const inst = process.env.ZAPI_INSTANCE_ID || process.env.ZAPI_INSTANCE;
    const tok = process.env.ZAPI_TOKEN;
    const ct = process.env.ZAPI_CLIENT_TOKEN;
    if (!inst || !tok) {
      return res.json({ mensagens: [], error: 'Z-API não configurado (ZAPI_INSTANCE_ID / ZAPI_TOKEN ausentes)' });
    }
    try {
      const url = `https://api.z-api.io/instances/${inst}/token/${tok}/chat-messages/${phone}`;
      const r = await fetch(url, { headers: ct ? { 'Client-Token': ct } : {} });
      const j = await r.json().catch(() => ({}));
      if (!r.ok || j.error) {
        const msg = j?.error || `HTTP ${r.status}`;
        if (String(msg).toLowerCase().includes('connected')) {
          return res.json({ mensagens: [], error: 'Z-API desconectado do WhatsApp. Acesse o painel Z-API e refaça a conexão (escaneie QR Code).' });
        }
        return res.json({ mensagens: [], error: `Z-API: ${msg}` });
      }
      const items = j.messages || j.items || j.data || (Array.isArray(j) ? j : []);
      const mensagens = items.map(m => {
        let texto = m.text || m.body || m.message || m.caption || '';
        if (!texto) {
          if (m.image) texto = '[imagem]';
          else if (m.video) texto = '[vídeo]';
          else if (m.audio) texto = '[áudio]';
          else if (m.document) texto = '[documento]';
        }
        return {
          texto,
          tipo: m.type || 'text',
          timestamp: m.timestamp || m.momment || m.dateTime || 0,
          owner: m.fromMe === true || m.isGroup === false && m.fromMe,
          isSystem: false,
          operatorName: m.fromMe ? 'Z-API' : null,
          templateName: null,
          status: m.status || 'sent',
        };
      }).filter(m => m.texto || m.tipo !== 'text');
      return res.json({ mensagens, total: mensagens.length, completo: false, canal: 'zapi' });
    } catch (e) {
      return res.json({ mensagens: [], error: `Z-API erro: ${e.message}` });
    }
  }

  // === WATI histórico (default) ===
  if (!WATI_TOKEN) return res.json({ mensagens: [], error: 'WATI_TOKEN não configurado' });
  const todas = req.query.todas === '1';
  const maxPages = todas ? 5 : 1;       // 1000 vs 200 mensagens
  const pageSize = 200;                  // WATI suporta até 200 por página
  try {
    let allItems = [];
    for (let pageNumber = 0; pageNumber < maxPages; pageNumber++) {
      const url = `${WATI_BASE}/api/v1/getMessages/${normalizarPhoneWati(phone)}?pageSize=${pageSize}&pageNumber=${pageNumber}`;
      const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
      if (!r.ok) break;
      const j = await r.json();
      const items = j.messages?.items || j.items || j.messages || [];
      if (!items.length) break;
      allItems.push(...items);
      if (items.length < pageSize) break; // chegou no fim
    }
    const mensagens = allItems.map(m => {
      // Texto pode vir em vários campos
      let texto = m.text || m.body || m.finalText
        || m.image?.caption || m.video?.caption || m.audio?.caption || m.document?.caption
        || m.eventDescription || '';
      if (!texto) {
        if (m.image) texto = '[imagem]';
        else if (m.video) texto = '[vídeo]';
        else if (m.audio) texto = '[áudio]';
        else if (m.document) texto = `[documento: ${m.document?.fileName||'arquivo'}]`;
        else if (m.template) texto = `[template: ${m.template?.elementName||'?'}]`;
      }
      // Identificação CORRETA do remetente:
      // - eventType='ticket' → log do sistema (nem cliente nem nós)
      // - eventType='message' + owner:false → cliente respondeu
      // - eventType='broadcastMessage'|'sentMessage' OU owner:true → nós mandamos
      const evt = m.eventType || '';
      const isSystem = evt === 'ticket' || evt === 'system';
      const isCliente = evt === 'message' && m.owner === false;
      const isNos = !isSystem && (evt === 'broadcastMessage' || evt === 'sentMessage' || m.owner === true || m.fromMe === true);
      return {
        texto,
        tipo: m.type || 'text',
        eventType: evt,
        timestamp: m.timestamp || m.created || 0,
        owner: isNos,                      // true = nós (verde, direita)
        isSystem,                          // true = log do sistema (centro)
        operatorName: m.operatorName || m.operatorEmail || (evt === 'broadcastMessage' ? 'Broadcast' : null),
        templateName: m.template?.elementName || null,
        status: m.status || m.statusString || 'sent',
      };
    }).reverse();
    res.json({ mensagens, total: mensagens.length, completo: !todas && mensagens.length >= pageSize });
  } catch(e) {
    res.json({ mensagens: [], error: e.message });
  }
});

// POST /inbox/responder { phone, text } → manda mensagem session (24h window)
app.post('/inbox/responder', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const { phone, text } = req.body || {};
  if (!phone || !text) return res.status(400).json({ error: 'phone e text obrigatórios' });
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });

  // Closer só pode responder se cliente está na carteira dele
  const phoneClean = String(phone).replace(/\D/g, '');
  // INBOX LIBERADO: qualquer closer pode responder qualquer conversa
  // (todo closer tem cadastro WATI; quem mandar a msg vai constar como operatorName)

  try {
    const url = `${WATI_BASE}/api/v1/sendSessionMessage/${normalizarPhoneWati(phoneClean)}?messageText=${encodeURIComponent(text)}`;
    const r = await fetch(url, {
      method: 'POST',
      headers: { Authorization: `Bearer ${WATI_TOKEN}` },
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return res.status(500).json({ error: j.message || `wati ${r.status}` });

    // Marca conversa como vista
    const inbox = loadWatiInbox();
    const dealId = await dealIdByPhone(phoneClean);
    if (dealId && inbox[dealId]) {
      inbox[dealId].visto = true;
      saveWatiInbox(inbox);
    }
    res.json({ ok: true, sent: true, by: u.name });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

