// GET /lead/ultima-atividade/:dealId → cruza GoTo + WATI + timeline + tarefas
app.get('/lead/ultima-atividade/:dealId', requireAuth, async (req, res) => {
  const { dealId } = req.params;
  const meta = loadManutMeta();
  const m = meta[dealId] || {};
  const eventos = []; // { tipo, label, ts, fonte }
  // 1. Timeline Closy
  for (const ev of (m.timeline || [])) {
    eventos.push({ tipo: ev.tipo, label: ev.label, ts: new Date(ev.at).getTime(), fonte: 'closy', by: ev.by });
  }
  // 2. Inbox WATI
  const inbox = loadWatiInbox();
  if (inbox[dealId]) {
    eventos.push({ tipo:'wati-msg', label:`Cliente respondeu: "${(inbox[dealId].text||'').slice(0,80)}"`, ts: inbox[dealId].ts, fonte: 'wati' });
  }
  // 3. Tarefas vinculadas
  const tarefas = loadTarefas();
  for (const t of Object.values(tarefas)) {
    if (t.dealId !== dealId) continue;
    eventos.push({ tipo:'tarefa', label:`📋 ${t.titulo} (${t.status})`, ts: new Date(t.criadoEm).getTime(), fonte:'tarefa' });
    if (t.completedAt) eventos.push({ tipo:'tarefa-feita', label:`✅ ${t.titulo} concluída`, ts: new Date(t.completedAt).getTime(), fonte:'tarefa' });
  }
  // 4. GoTo (chamadas) — pega telefone do deal e cruza com gotoStats se disponível
  // Por agora, só usa eventos da timeline tipo 'contato' canal:'goto'
  // Ordena por ts desc
  eventos.sort((a, b) => b.ts - a.ts);
  const ultima = eventos[0] || null;
  res.json({
    ultima: ultima ? { ...ultima, atFmt: new Date(ultima.ts).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}), horasAtras: Math.round((Date.now() - ultima.ts) / 3600000) } : null,
    todas: eventos.slice(0, 30),
    diasSemAtividade: ultima ? Math.floor((Date.now() - ultima.ts) / 86400000) : null,
  });
});

