// GET /tarefas/lembretes → tarefas do user que disparam popup AGORA
// (dataHora - lembreteMin <= now <= dataHora + 5min)
app.get('/tarefas/lembretes', requireAuth, (req, res) => {
  const username = req.session.user.username;
  const u = USERS[username];
  const isAdmin = u?.role === 'admin' || isGestor(u);
  const all = loadTarefas();
  const now = Date.now();
  const lembretes = Object.values(all).filter(t => {
    if (t.status !== 'aberta') return false;
    if (!isAdmin && t.atribuidoA !== username && t.criadoPor !== username) return false;
    const ts = new Date(t.dataHora).getTime();
    const inicioJanela = ts - (t.lembreteMin || 5) * 60000;
    const fimJanela = ts + 5 * 60000;
    return now >= inicioJanela && now <= fimJanela;
  });
  res.json({ lembretes });
});

