// === SSE (Server-Sent Events) — push em tempo real pra inbox ===
const _SSE_CLIENTES = new Set();
function sseBroadcast(evento, dados) {
  const msg = `event: ${evento}\ndata: ${JSON.stringify(dados)}\n\n`;
  for (const res of _SSE_CLIENTES) {
    try { res.write(msg); } catch(_){}
  }
}
app.get('/inbox/stream', requireAuth, (req, res) => {
  res.set({
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  res.flushHeaders();
  res.write(`event: hello\ndata: ${JSON.stringify({ ts: Date.now() })}\n\n`);
  _SSE_CLIENTES.add(res);
  const hb = setInterval(() => { try { res.write(': heartbeat\n\n'); } catch(_){} }, 25000);
  req.on('close', () => { clearInterval(hb); _SSE_CLIENTES.delete(res); });
});

