// === CADASTRAR LEAD MANUAL no Zoho (form completo) ===
// Migra conversa de placeholder 'wati:phone' pro dealId real após cadastro manual.
// Movimenta entrada do inbox storage e libera o placeholder.
app.post('/inbox/migrar-orfao', requireAuth, (req, res) => {
  const { oldKey, newDealId } = req.body || {};
  if (!oldKey || !newDealId) return res.status(400).json({ error: 'oldKey e newDealId obrigatórios' });
  if (!String(oldKey).startsWith('wati:')) return res.status(400).json({ error: 'oldKey precisa começar com wati:' });
  const inbox = loadWatiInbox();
  if (!inbox[oldKey]) return res.json({ ok:true, semMigracao:true });
  const entry = { ...inbox[oldKey], dealId: newDealId, semDealZoho: false };
  inbox[newDealId] = entry;
  delete inbox[oldKey];
  saveWatiInbox(inbox);
  console.log(`[inbox] migrado órfão ${oldKey} → ${newDealId}`);
  res.json({ ok:true, dealId: newDealId });
});

app.post('/inbox/cadastrar-lead', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const { nome, telefone, cidade, email, produto, observacao, leadSource } = req.body || {};
  if (!nome || !telefone) return res.status(400).json({ error: 'nome e telefone obrigatórios' });
  const phoneClean = String(telefone).replace(/\D/g, '');
  if (phoneClean.length < 10) return res.status(400).json({ error: 'telefone inválido' });
  const phoneWithDdi = phoneClean.length === 10 || phoneClean.length === 11 ? '55' + phoneClean : phoneClean;
  // Verifica se já existe
  const existente = await dealIdByPhone(phoneWithDdi);
  if (existente) {
    return res.json({ ok: false, jaExiste: true, dealId: existente, message: 'Já existe deal pra esse número' });
  }
  const tk = await getZohoToken();
  if (!tk) return res.status(500).json({ error: 'zoho indisponível' });
  try {
    const body = {
      data: [{
        Deal_Name: String(nome).slice(0, 100),
        Stage: 'Leads Novos',
        Pipeline: 'Geral',
        Layout: { id: '6311862000037730183' }, // Telemarketing — default da org mudou
        Telefone_contato: phoneWithDdi,
        Cidade: cidade || '',
        Email: email || '',
        Lead_Source: leadSource || 'Manual · CRM Closy',
        Produto_Vendido: produto || '',
        Description: `Cadastrado manualmente por ${u.name}.${observacao ? ' Obs: '+observacao : ''}`,
      }],
    };
    const r = await fetch('https://www.zohoapis.com/crm/v6/Deals', {
      method:'POST',
      headers: { Authorization: `Zoho-oauthtoken ${tk}`, 'Content-Type':'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json().catch(() => ({}));
    const result = j.data?.[0];
    if (result?.code !== 'SUCCESS') {
      return res.status(500).json({ error: result?.message || 'falha ao criar deal', raw: j });
    }
    const dealId = result.details?.id;
    _PHONE_DEAL_CACHE[phoneWithDdi] = dealId;
    // Loga timeline
    const meta = loadManutMeta();
    if (!meta[dealId]) meta[dealId] = {};
    addTimelineEvent(meta, dealId, {
      tipo:'cadastro',
      label:`✏️ Lead cadastrado manualmente${observacao?': '+observacao:''}`,
      by: u.name,
    });
    saveManutMeta(meta);
    res.json({
      ok: true, dealId, phone: phoneWithDdi,
      crmLink: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${dealId}`,
    });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

