// === AUTO-ATRIBUIR OPERADORA — WATI → Zoho → IA → Round Robin ===
app.post('/manutencao/cliente/:dealId/auto-atribuir', requireAuth, async (req, res) => {
  if (!isGestor(USERS[req.session.user.username]) && USERS[req.session.user.username]?.role !== 'admin') {
    return res.status(403).json({ error: 'apenas gestor/CEO' });
  }
  const { dealId } = req.params;
  const meta = loadManutMeta();
  const m = meta[dealId] || {};
  // Já tem operadora? respeita
  if (m.operadora) return res.json({ ok:true, jaTinha: true, operadora: m.operadora, fonte: 'closy' });
  let escolhida = null;
  let fonte = '';
  let info = {};
  // Busca dados do deal Zoho + dados do WATI pelo telefone
  let phone = '', dealZoho = null;
  try {
    const tk = await getZohoToken();
    if (tk && !dealId.startsWith('erp:')) {
      const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Telefone_contato,Owner,Layout,Pipeline,Produto_Vendido,Lead_Source,Cidade,Tipo_de_Agua,Description`, {
        headers: { Authorization: `Zoho-oauthtoken ${tk}` },
      });
      const j = await r.json().catch(() => ({}));
      dealZoho = j.data?.[0];
      phone = dealZoho?.Telefone_contato || '';
    }
  } catch(_){}

  // 1) Operador atribuído no WATI
  if (phone && WATI_TOKEN) {
    try {
      const phoneClean = String(phone).replace(/\D/g,'');
      const url = `${WATI_BASE}/api/v1/getContacts?pageSize=1&pageNumber=0&attribute=phone&value=${encodeURIComponent(phoneClean)}`;
      const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
      if (r.ok) {
        const j = await r.json();
        const c = (j.contact_list || j.contacts || [])[0];
        if (c) {
          const cp = watiCustomParams(c);
          const wAssigned = c.assignedTo || c.assignedToOperator || cp.assigned_to || cp.responsavel;
          if (wAssigned) {
            // Tenta achar closer com nome similar
            const closer = CLOSERS_LIST.find(cl =>
              cl.name?.toLowerCase().includes((wAssigned||'').toLowerCase()) ||
              cl.crmOwner?.toLowerCase().includes((wAssigned||'').toLowerCase()) ||
              cl.username === (wAssigned||'').toLowerCase()
            );
            if (closer) { escolhida = closer.username; fonte = 'wati'; info.watiAssigned = wAssigned; }
          }
        }
      }
    } catch(_){}
  }

  // 2) Owner Zoho
  if (!escolhida && dealZoho?.Owner?.name) {
    const closer = CLOSERS_LIST.find(c => c.crmOwner === dealZoho.Owner.name);
    if (closer) { escolhida = closer.username; fonte = 'zoho_owner'; info.zohoOwner = dealZoho.Owner.name; }
  }

  // 3) IA decide baseado em produto/categoria/cidade
  if (!escolhida) {
    const layoutN = (dealZoho?.Layout?.name || '').toLowerCase();
    const pipelineN = (dealZoho?.Pipeline || '').toLowerCase();
    const produto = (dealZoho?.Produto_Vendido || '').toLowerCase();
    const tipoAgua = (dealZoho?.Tipo_de_Agua || '').toLowerCase();
    const blob = layoutN + ' ' + pipelineN + ' ' + produto + ' ' + tipoAgua;
    let team = null;
    if (/bebedouro|telemarketing|fúnil\s*base|funil\s*base|resfriador/i.test(blob)) team = 'bebedouro';
    else if (/po[çc]o|n[aã]o.*tratada|iron\s*free|abrandador/i.test(blob)) team = 'poco';
    else if (/loja|f[ií]sica/i.test(blob)) team = 'filtro';
    else team = 'filtro'; // default
    // Pega closer com menos atribuições atuais nesse team (round robin smart)
    const candidatos = CLOSERS_LIST.filter(c => c.team === team);
    if (candidatos.length) {
      const cargas = {};
      for (const c of candidatos) cargas[c.username] = 0;
      for (const dm of Object.values(meta)) {
        if (dm.operadora && cargas.hasOwnProperty(dm.operadora)) cargas[dm.operadora]++;
      }
      const escolhido = candidatos.sort((a,b) => cargas[a.username] - cargas[b.username])[0];
      if (escolhido) { escolhida = escolhido.username; fonte = 'ia_team_'+team; info.team = team; info.cargas = cargas; }
    }
  }

  // 4) Round-robin geral (último fallback)
  if (!escolhida) {
    const cargas = {};
    for (const c of CLOSERS_LIST) cargas[c.username] = 0;
    for (const dm of Object.values(meta)) {
      if (dm.operadora && cargas.hasOwnProperty(dm.operadora)) cargas[dm.operadora]++;
    }
    const escolhido = CLOSERS_LIST.sort((a,b) => cargas[a.username] - cargas[b.username])[0];
    if (escolhido) { escolhida = escolhido.username; fonte = 'round_robin'; }
  }

  if (!escolhida) return res.status(500).json({ error: 'sem closers disponíveis' });

  // Salva
  if (!meta[dealId]) meta[dealId] = {};
  meta[dealId].operadora = escolhida;
  addTimelineEvent(meta, dealId, {
    tipo:'operadora',
    label:`👤 Auto-atribuída pra ${escolhida} (fonte: ${fonte})`,
    by:'Sistema',
  });
  saveManutMeta(meta);
  res.json({ ok:true, operadora: escolhida, fonte, info });
});

// === BUSCAR CONTATO no WATI por nome/telefone (qualquer época) ===
app.get('/inbox/buscar', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const q = (req.query.q || '').trim();
  if (q.length < 3) return res.json({ contatos: [] });
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });
  try {
    // WATI suporta search via param ou name
    const isPhone = /^[\d\s()+-]+$/.test(q);
    const url = isPhone
      ? `${WATI_BASE}/api/v1/getContacts?pageSize=20&pageNumber=0&attribute=phone&value=${encodeURIComponent(q.replace(/\D/g,''))}`
      : `${WATI_BASE}/api/v1/getContacts?pageSize=20&pageNumber=0&name=${encodeURIComponent(q)}`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
    if (!r.ok) return res.json({ contatos: [], error: 'wati '+r.status });
    const j = await r.json();
    let items = j.contact_list || j.contacts || j.items || [];
    // Filtro local extra (caso o WATI ignore o param)
    if (!items.length || (q.length >= 3 && !items.some(c => (c.fullName||c.firstName||'').toLowerCase().includes(q.toLowerCase()) || (c.phone||'').includes(q.replace(/\D/g,''))))) {
      // Fallback: busca em getContacts geral e filtra local (até 200)
      const url2 = `${WATI_BASE}/api/v1/getContacts?pageSize=200&pageNumber=0`;
      const r2 = await fetch(url2, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
      if (r2.ok) {
        const j2 = await r2.json();
        const all = j2.contact_list || [];
        items = all.filter(c => {
          const nm = (c.fullName||c.firstName||'').toLowerCase();
          const ph = (c.phone||'').toString();
          return isPhone ? ph.includes(q.replace(/\D/g,'')) : nm.includes(q.toLowerCase());
        }).slice(0, 20);
      }
    }
    const contatos = await Promise.all(items.map(async c => {
      const cp = watiCustomParams(c);
      const phone = c.phone || cp.phone || '';
      let dealId = null;
      if (phone) dealId = await dealIdByPhone(phone);
      return {
        phone, nome: c.fullName || c.firstName || cp.name || '?',
        ultimaAtividade: cp.ultima_atividade || '',
        statusConversa: cp.status_conversa || '',
        produto: cp.produto_interesse || '',
        source: cp.source_url || '',
        dealId, // null se não tem deal Zoho
      };
    }));
    res.json({ contatos });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

