// POST /inbox/anexar { phone, dataUrl: 'data:image/jpeg;base64,...', filename }
// Envia mídia (imagem/doc/audio) via WATI sendSessionFile (aceita payload base64)
app.post('/inbox/anexar', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const { phone, dataUrl, filename, caption } = req.body || {};
  if (!phone || !dataUrl) return res.status(400).json({ error: 'phone e dataUrl obrigatórios' });
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });
  const phoneClean = String(phone).replace(/\D/g, '');
  // Closer só pode anexar se cliente está na carteira dele
  // INBOX LIBERADO: qualquer closer pode anexar
  const m = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!m) return res.status(400).json({ error: 'dataUrl inválido' });
  const mime = m[1];
  const buf = Buffer.from(m[2], 'base64');
  if (buf.length > 8 * 1024 * 1024) return res.status(400).json({ error: 'arquivo muito grande (max 8MB)' });
  try {
    // WATI sendSessionFile aceita multipart com 'file' field
    const form = new FormData();
    form.append('file', new Blob([buf], { type: mime }), filename || 'arquivo');
    if (caption) form.append('caption', caption);
    const url = `${WATI_BASE}/api/v1/sendSessionFile/${normalizarPhoneWati(phoneClean)}`;
    const r = await fetch(url, {
      method: 'POST',
      headers: { Authorization: `Bearer ${WATI_TOKEN}` },
      body: form,
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || j.result === false) return res.status(500).json({ error: j.message || `WATI ${r.status} — pode estar fora da janela 24h` });
    res.json({ ok: true, sent: true, mime, bytes: buf.length });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

