// === Z-API: diagnóstico + auto-setup do webhook ===
app.get('/admin/zapi-diag', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).send('admin only');
  const out = {
    has_creds: !!(ZAPI_INSTANCE && ZAPI_TOKEN && ZAPI_CLIENT_TOKEN),
    instance: ZAPI_INSTANCE ? ZAPI_INSTANCE.slice(0,12)+'...' : null,
    expectedWebhookUrl: (process.env.PORTAL_URL || 'https://tdf-portal-production.up.railway.app') + '/webhooks/zapi',
    webhooks: {},
    instanceStatus: null,
  };
  if (!out.has_creds) return res.json(out);
  const base = `https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}`;
  const headers = { 'Client-Token': ZAPI_CLIENT_TOKEN };
  // Status do telefone (conectado?)
  try {
    const r = await fetch(`${base}/status`, { headers });
    out.instanceStatus = await r.json().catch(() => ({}));
  } catch(e) { out.instanceStatus = { error: e.message }; }
  // Webhooks atuais
  for (const tipo of ['received','delivery','message-status','disconnected','connected']) {
    try {
      const r = await fetch(`${base}/webhook-${tipo}`, { headers });
      out.webhooks[tipo] = await r.json().catch(() => ({}));
    } catch(e) { out.webhooks[tipo] = { error: e.message }; }
  }
  res.json(out);
});

