// POST /admin/wati-setup-webhook → configura webhook do WATI pra apontar pro n8n wati-porteiro
app.post('/admin/wati-setup-webhook', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  if (!WATI_TOKEN) return res.status(500).json({ error: 'WATI_TOKEN não configurado' });
  // Destino padrão: n8n wati-porteiro (substitui /webhook/wati-webhook). Pode customizar via body.url.
  const target = (req.body && req.body.url) || 'https://tdf-n8n-production.up.railway.app/webhook/wati-webhook';
  const results = {};
  // WATI usa endpoint configureWebhook ou updateWebhook
  for (const cfg of [
    { method: 'POST', path: '/api/v1/configureWebhook', body: { webhookUrl: target } },
    { method: 'POST', path: '/api/v1/updateWebhook', body: { webhookUrl: target } },
    { method: 'PUT', path: '/api/v1/webhook', body: { url: target } },
  ]) {
    try {
      const r = await fetch(`${WATI_BASE}${cfg.path}`, {
        method: cfg.method,
        headers: { Authorization: `Bearer ${WATI_TOKEN}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(cfg.body),
      });
      results[cfg.path] = { status: r.status, body: (await r.text()).slice(0, 300) };
      if (r.ok) break; // primeira que aceitar, paramos
    } catch(e) { results[cfg.path] = { error: e.message }; }
  }
  res.json({ ok: true, target, attempts: results, hint: 'Se nenhuma rota aceitou: configurar manualmente em https://live-mt-server.wati.io/2708 → Configuration → Webhook' });
});

