app.get('/admin/webhooks-status', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin only' });
  const N8N_BASE = 'https://tdf-n8n-production.up.railway.app';
  const PORTAL = process.env.PORTAL_URL || 'https://tdf-portal-production.up.railway.app';
  const out = {
    webhooks_esperados: {
      wati_porteiro: `${N8N_BASE}/webhook/wati-webhook`,
      zapi_inbound: `${PORTAL}/webhooks/zapi`,
      zoho_score_lead: `${N8N_BASE}/webhook/score-lead-tdf`,
      fb_lead_ads: `${N8N_BASE}/webhook/fb-leadgen`,
      google_ads_intake: `${N8N_BASE}/webhook/google-ads`,
      ctwa: `${N8N_BASE}/webhook/ctwa`,
      wpforms: `${N8N_BASE}/webhook/wpforms`,
      leadster: `${N8N_BASE}/webhook/leadster`,
      mariane_sdr: `${N8N_BASE}/webhook/mariane-sdr`,
    },
    status: {},
  };
  // 1) WATI atual
  if (WATI_TOKEN) {
    for (const path of ['/api/v1/webhooks', '/api/v2/webhooks']) {
      try {
        const r = await fetch(`${WATI_BASE}${path}`, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
        if (r.ok) { out.status.wati = await r.json().catch(() => ({})); break; }
      } catch(_){}
    }
    if (!out.status.wati) out.status.wati = { hint: 'WATI API não expõe webhook config — verificar manualmente no painel' };
  }
  // 2) Z-API atual
  if (ZAPI_INSTANCE && ZAPI_TOKEN) {
    try {
      const r = await fetch(`https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}/webhook-received`, {
        headers: { 'Client-Token': ZAPI_CLIENT_TOKEN },
      });
      out.status.zapi = await r.json().catch(() => ({}));
    } catch(e) { out.status.zapi = { error: e.message }; }
  }
  // 3) Zoho Workflow Rules (lista todas, mostra Webhook URLs)
  try {
    const tk = await getZohoToken();
    if (tk) {
      const r = await fetch('https://www.zohoapis.com/crm/v6/settings/automation/workflow_rules?module=Deals', {
        headers: { Authorization: `Zoho-oauthtoken ${tk}` },
      });
      const j = await r.json().catch(() => ({}));
      out.status.zoho_workflows = (j.workflow_rules || []).map(w => ({
        name: w.name, trigger: w.trigger?.type, active: w.active,
      })).slice(0, 30);
    }
  } catch(e) { out.status.zoho_workflows = { error: e.message }; }
  // 4) Test reachability dos endpoints n8n (cada webhook)
  out.status.n8n_webhooks_reachable = {};
  for (const [k, url] of Object.entries(out.webhooks_esperados)) {
    if (!url.includes('n8n-production')) continue;
    try {
      const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
      out.status.n8n_webhooks_reachable[k] = { status: r.status, ok: r.ok };
    } catch(e) { out.status.n8n_webhooks_reachable[k] = { error: e.message }; }
  }
  res.json(out);
});

// POST /inbox/zapi-anexar { phone, dataUrl, filename, caption, tipo: 'audio'|'image'|'document'|'video' }
// Envia mídia via Z-API (fora da janela 24h) — exige Z-API configurada
app.post('/inbox/zapi-anexar', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  if (!ZAPI_INSTANCE || !ZAPI_TOKEN) return res.status(500).json({ error: 'Z-API não configurada' });
  const { phone, dataUrl, filename, caption, tipo } = req.body || {};
  if (!phone || !dataUrl) return res.status(400).json({ error: 'phone e dataUrl obrigatórios' });
  const phoneClean = String(phone).replace(/\D/g, '');
  // Detecta tipo via dataUrl se não passado
  const m = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!m) return res.status(400).json({ error: 'dataUrl inválido' });
  const mime = m[1];
  const tipoFinal = tipo || (
    mime.startsWith('audio/') ? 'audio' :
    mime.startsWith('image/') ? 'image' :
    mime.startsWith('video/') ? 'video' : 'document'
  );
  // Z-API aceita data URL diretamente em alguns endpoints, mas é mais confiável passar o base64 puro
  // ou hospedar em URL pública. Aqui mandamos data URL inteira (suportado).
  try {
    let url, body;
    if (tipoFinal === 'audio') {
      url = `https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}/send-audio`;
      body = { phone: phoneClean, audio: dataUrl };
    } else if (tipoFinal === 'image') {
      url = `https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}/send-image`;
      body = { phone: phoneClean, image: dataUrl, caption: caption || '' };
    } else if (tipoFinal === 'video') {
      url = `https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}/send-video`;
      body = { phone: phoneClean, video: dataUrl, caption: caption || '' };
    } else {
      // document — Z-API exige extensão na URL
      const ext = (filename||'arquivo').split('.').pop().toLowerCase().slice(0,5) || 'pdf';
      url = `https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}/send-document/${ext}`;
      body = { phone: phoneClean, document: dataUrl, fileName: filename || `arquivo.${ext}`, caption: caption || '' };
    }
    const r = await fetch(url, {
      method: 'POST',
      headers: { 'Client-Token': ZAPI_CLIENT_TOKEN, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) return res.status(500).json({ error: j.error || j.message || `Z-API ${r.status}` });
    res.json({ ok: true, sent: true, tipo: tipoFinal, result: j });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

