  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });
  const { phone, templateName, params = [], dealId: dealIdHint } = req.body || {};
  if (!phone || !templateName) return res.status(400).json({ error: 'phone e templateName obrigatórios' });
  const phoneClean = String(phone).replace(/\D/g, '');
  // INBOX LIBERADO: qualquer closer pode enviar template
  const r = await watiSendTemplate(phoneClean, templateName, params);
  if (!r.ok) return res.status(500).json({ error: r.error || 'falha ao enviar template' });
  // 06/Mai/2026: registrar último template enviado pra exibir no /manutencao.
  // Se o front mandou dealId no body, usa direto; senão tenta achar pelo phone no inbox.
  let dealId = dealIdHint;
