// GET /inbox/notifs/poll → notificações pra usuário logado (closer só vê carteira dele)
app.get('/inbox/notifs/poll', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.json({ notifs: [] });
  const username = req.session.user.username;
  const since = parseInt(req.query.since) || 0;
  const inbox = loadWatiInbox();
  const meta = loadManutMeta();
  const candidatos = [];
  // TTL server-side: descarta mensagens com mais de 60min — não notifica
  // mensagens "antigas" (cliente já viu, vendedor nem tá olhando, etc.)
  const ttlCutoff = Date.now() - 60 * 60 * 1000;
  // INBOX LIBERADO: todos veem todas as notificações (sem filtro de carteira)
  for (const m of Object.values(inbox)) {
    if (m.visto) continue;
    if (m.ts <= since) continue;
    if ((m.ts || 0) < ttlCutoff) continue;
    const dealMeta = meta[m.dealId] || {};
    candidatos.push({ m, dealMeta });
  }
  // Enriquece com nome do cliente (Zoho) — top 20 mais recentes
  candidatos.sort((a, b) => b.m.ts - a.m.ts);
  const top = candidatos.slice(0, 20);
  const tk = await getZohoToken().catch(() => null);
  const notifs = [];
  for (const { m, dealMeta } of top) {
    let nome = '';
    if (tk && m.dealId && !m.dealId.startsWith('erp:')) {
      try {
        const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${m.dealId}?fields=Deal_Name`, {
          headers: { Authorization: `Zoho-oauthtoken ${tk}` },
        });
        if (r.ok) {
          const j = await r.json();
          nome = j.data?.[0]?.Deal_Name || '';
        }
      } catch(_){}
    }
    notifs.push({
      dealId: m.dealId, phone: m.phone, nome, text: (m.text||'').slice(0,140),
      ts: m.ts, canal: m.canal || 'wati',
      operadora: dealMeta.operadora || null, etapa: dealMeta.etapa || 'base_sem_contato',
    });
  }
  res.json({ notifs, total: candidatos.length, serverTs: Date.now() });
});

