// Disparo em massa via WATI (template aprovado)
// Body: { dealIds, templateName, paramsPorDeal: { dealId: [param1, param2] } | parametrosFixos: [p1, p2], canal: 'wati' }
app.post('/manutencao/disparo-massa', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { dealIds, templateName, paramsPorDeal, parametrosFixos, canal, modoTeste } = req.body || {};

  if (!Array.isArray(dealIds) || !dealIds.length) return res.status(400).json({ error: 'dealIds obrigatório' });
  if (!templateName) return res.status(400).json({ error: 'templateName obrigatório' });
  const limite = dealIds.slice(0, 200);

  const c = (canal || 'wati').toLowerCase();
  if (c !== 'wati') {
    return res.status(400).json({ error: 'WhatsApp Business ainda não configurado pra disparo em massa. Use canal=wati.' });
  }

  // Resposta imediata (processamento em background)
  res.json({ ok: true, started: true, total: limite.length, modoTeste: !!modoTeste });

  // Processa em background
  setTimeout(async () => {
    const startedAt = Date.now();
    const results = { ok: 0, falhas: [], total: limite.length };
    const userName = USERS[req.session.user.username]?.name || '?';
    console.log(`[disparo-massa] START template=${templateName} total=${limite.length} por=${userName}${modoTeste?' (TESTE)':''}`);
    // 14/Mai/2026 fix: IDs com prefixo "erp:" são ERP-only (sem deal no Zoho).
    // Telefone está no próprio ID. Nome vem do ERP index.
    // Sem o fix, todos os ERP-only falhavam com "sem telefone".
    const dealsInfo = {};
    const idsZoho = [];
    for (const id of limite) {
      if (typeof id === 'string' && id.startsWith('erp:')) {
        const phone = id.slice(4); // remove "erp:"
        const erpRow = erpLookup(phone) || {};
        dealsInfo[id] = {
          name: erpRow.nome || erpRow.razaoSocial || 'Cliente',
          phone: phone,
          isErp: true,
        };
      } else {
        idsZoho.push(id);
      }
    }
    // Pra IDs do Zoho, busca via API
    for (const id of idsZoho) {
      try {
        const tk = await getZohoToken();
        const url = `https://www.zohoapis.com/crm/v6/Deals/${id}?fields=Deal_Name,Telefone_contato`;
        const r = await fetch(url, { headers: { Authorization: `Zoho-oauthtoken ${tk}` } });
        if (r.ok) {
          const j = await r.json();
          const d = j.data?.[0];
          if (d) dealsInfo[id] = { name: d.Deal_Name, phone: d.Telefone_contato };
        }
      } catch(_){}
    }
    const erpCount = Object.values(dealsInfo).filter(d => d.isErp).length;
    const zohoCount = Object.values(dealsInfo).filter(d => !d.isErp).length;
    console.log(`[disparo-massa] dealsInfo: ERP=${erpCount} Zoho=${zohoCount} total=${Object.keys(dealsInfo).length}/${limite.length}`);

    for (const id of limite) {
      const info = dealsInfo[id];
      if (!info?.phone) {
        results.falhas.push({ dealId: id, error: 'sem telefone' });
        console.log(`[disparo-massa] FAIL ${id}: sem telefone`);
        continue;
      }
      const params = (paramsPorDeal && paramsPorDeal[id]) || parametrosFixos || [info.name, ''];
      if (modoTeste) { results.ok++; continue; }
      try {
        const r = await watiSendTemplate(info.phone, templateName, params);
        if (r.ok) {
          results.ok++;
          registrarUltimoTemplate(id, templateName, userName || 'mass-action');
        } else {
          const err = r.error || `wati ${r.status}`;
          results.falhas.push({ dealId: id, phone: info.phone, error: err });
          console.log(`[disparo-massa] FAIL ${id} ${info.phone}: ${err}`);
        }
      } catch (e) {
        results.falhas.push({ dealId: id, error: e.message });
        console.log(`[disparo-massa] EXC ${id}: ${e.message}`);
      }
      await new Promise(r => setTimeout(r, 1500)); // rate limit ~40 msgs/min
    }

    // Resumo dos motivos de falha (top 5)
    const motivosFalha = {};
    results.falhas.forEach(f => {
      const k = (f.error || 'unknown').slice(0, 80);
      motivosFalha[k] = (motivosFalha[k] || 0) + 1;
    });
    const topFalhas = Object.entries(motivosFalha).sort((a,b) => b[1]-a[1]).slice(0, 5);
    const elapsedS = Math.round((Date.now()-startedAt)/1000);
    console.log(`[disparo-massa] DONE template=${templateName} ok=${results.ok}/${results.total} falhas=${results.falhas.length} elapsed=${elapsedS}s`);
    if (topFalhas.length) console.log(`[disparo-massa] TOP FALHAS: ${topFalhas.map(([k,v]) => `${v}× "${k}"`).join(' | ')}`);

    // Notifica Paulo com detalhe dos motivos de falha
    try {
      const detalheFalhas = topFalhas.length ? `\nFalhas principais:\n${topFalhas.map(([k,v]) => `• ${v}× ${k}`).join('\n')}` : '';
      await zapiSend(PAULO_PHONE, `📨 [Disparo Massa] "${templateName}"\n✅ ${results.ok}/${results.total} enviados${modoTeste?' (TESTE)':''}\n❌ ${results.falhas.length} falhas\n⏱ ${elapsedS}s\nPor: ${userName}${detalheFalhas}`);
    } catch(_){}
  }, 100);
});

// 14/Mai/2026: Unificação de cidades duplicadas (TAUBATE/TAUBATÉ/Taubaté/SP → Taubaté).
// Body: { ops: [{ canonica: "Taubaté", variacoes: ["TAUBATE","TAUBATÉ","Taubaté/SP"] }] }
// Atualiza Cidade no Zoho pra todos os deals com variação == versão canônica.
app.post('/manutencao/unificar-cidades', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { ops } = req.body || {};
  if (!Array.isArray(ops) || !ops.length) return res.status(400).json({ error: 'ops obrigatório' });

  // Estima total de deals afetados (pra resposta imediata)
  const won = await getWonDealsCached();
  let totalDeals = 0;
  const opsExpanded = ops.map(o => {
    const variacoes = new Set((o.variacoes || []).filter(Boolean));
    if (!variacoes.size || !o.canonica) return null;
    const ids = won.filter(d => d.Cidade && variacoes.has(d.Cidade)).map(d => d.id);
    totalDeals += ids.length;
    return { canonica: o.canonica.trim(), dealIds: ids };
  }).filter(Boolean);

  // Resposta imediata; processa em background
  res.json({ ok: true, started: true, totalGrupos: opsExpanded.length, totalDeals });

  const userName = USERS[req.session.user.username]?.name || '?';
  setTimeout(async () => {
    const summary = { atualizados: 0, falhas: 0, grupos: [] };
    for (const op of opsExpanded) {
      const r = { canonica: op.canonica, ok: 0, fail: 0 };
      // Atualiza em chunks de 100 (limite Zoho PUT bulk)
      for (let i = 0; i < op.dealIds.length; i += 100) {
        const chunk = op.dealIds.slice(i, i + 100);
        try {
          const tk = await getZohoToken();
          const payload = { data: chunk.map(id => ({ id, Cidade: op.canonica })) };
          const resp = await fetch('https://www.zohoapis.com/crm/v6/Deals', {
            method: 'PUT',
            headers: { Authorization: `Zoho-oauthtoken ${tk}`, 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
          });
          if (resp.ok) {
            const j = await resp.json();
            (j.data || []).forEach(rec => { if (rec.code === 'SUCCESS') { r.ok++; summary.atualizados++; } else { r.fail++; summary.falhas++; } });
          } else {
            r.fail += chunk.length;
            summary.falhas += chunk.length;
          }
        } catch (e) {
          r.fail += chunk.length;
          summary.falhas += chunk.length;
        }
        await new Promise(rs => setTimeout(rs, 300)); // rate limit
      }
      summary.grupos.push(r);
    }
    // Invalida cache won pra refletir mudanças
    try { _wonCache = null; _wonCacheAt = 0; } catch(_){}
    try {
      await zapiSend(PAULO_PHONE, `🔧 [Unificar Cidades] ${summary.atualizados} deal(s) atualizado(s) / ${summary.falhas} falha(s). Por: ${userName}`);
    } catch(_){}
    console.log('[unificar-cidades]', JSON.stringify(summary).slice(0, 500));
  }, 100);
});


