const META_CLOSY_FILE = path.join(__dirname, 'data/meta-closy.json');
function loadMetaClosy() { return kvOrFile('meta-closy', META_CLOSY_FILE, {}); }
function saveMetaClosy(d) { kvAndFile('meta-closy', META_CLOSY_FILE, d); }

