// Atribuição em massa
app.post('/manutencao/distribuir', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin';
  const userIsGestor = isGestor(u);
  if (!isAdmin && !userIsGestor) return res.status(403).json({ error: 'admin/gestor only' });
  const username = req.session.user.username;
  const { dealIds, operadora, modo, criarTarefa, dadosCliente, operadoras } = req.body || {};
  if (!Array.isArray(dealIds) || !dealIds.length) return res.status(400).json({ error: 'dealIds obrigatório' });

  // GUARD: se for gestor (não admin), só pode atribuir pra operadores do MESMO time
  if (!isAdmin && userIsGestor) {
    const meuTime = u?.team;
    const targets = (operadora ? [operadora] : []).concat(Array.isArray(operadoras) ? operadoras : []);
    for (const opUser of targets) {
      const targetTeam = USERS[opUser]?.team;
      if (targetTeam !== meuTime) {
        return res.status(403).json({ error: `gestor só atribui pra operadores do time '${meuTime}' (${opUser} está em '${targetTeam||'?'}')` });
      }
    }
  }

  const meta = loadManutMeta();
  const tarefas = criarTarefa ? loadTarefas() : null;
  let atribuidos = 0;
  let tarefasCriadas = 0;
  // Mapa dealId → operadora atribuída (pra criar tarefa pra cada um)
  const atribuicaoMap = {};

  // Mapa dealId → operadora anterior (pra audit log seller_responsible_before)
  const prevMap = {};
  for (const id of dealIds) prevMap[id] = (meta[id] && meta[id].operadora) || null;

  function _logDistribuir(id, op) {
    const prevOp = prevMap[id];
    const cliente = (dadosCliente||{})[id] || {};
    _auditLogSafe({
      action_type: 'lead_assigned',
      action_origin: 'manager_manual',
      crm_module: 'Deals',
      crm_record_id: String(id),
      crm_record_name: cliente.nome || meta[id]?.nome || null,
      actor_id: username,
      actor_name: u?.name || username,
      seller_responsible_before: prevOp ? (USERS[prevOp]?.name || prevOp) : null,
      seller_responsible_after: USERS[op]?.name || op,
      reason: `distribuir (massa): modo=${modo||'unico'}`,
      rule_triggered: `distribuicao_massa_${modo||'unico'}`,
      related_channel: 'portal',
      metadata_json: { endpoint: 'distribuir', modo: modo||'unico' }
    });
  }

  if (modo === 'equilibrado' && Array.isArray(operadora)) {
    dealIds.forEach((id, i) => {
      const op = operadora[i % operadora.length];
      if (!meta[id]) meta[id] = {};
      meta[id].operadora = op;
      meta[id].updatedAt = new Date().toISOString();
      addTimelineEvent(meta, id, { tipo:'operadora', label:`Atribuído a ${op} (distribuição massa)`, by: u.name||username });
      atribuicaoMap[id] = op;
      _logDistribuir(id, op);
      atribuidos++;
    });
  } else if (operadora) {
    dealIds.forEach(id => {
      if (!meta[id]) meta[id] = {};
      meta[id].operadora = operadora;
      meta[id].updatedAt = new Date().toISOString();
      addTimelineEvent(meta, id, { tipo:'operadora', label:`Atribuído a ${operadora}`, by: u.name||username });
      atribuicaoMap[id] = operadora;
      _logDistribuir(id, operadora);
      atribuidos++;
    });
  }

  // Criar tarefas pra cada deal atribuído (se solicitado)
  if (criarTarefa && tarefas) {
    const titulo = String(criarTarefa.titulo || 'Ligar pra cliente').slice(0, 200);
    const dataHoraBase = criarTarefa.dataHora ? new Date(criarTarefa.dataHora).getTime() : (Date.now() + 60*60000);
    const espacarMin = parseInt(criarTarefa.espacarMin, 10) || 0; // 0 = todos no mesmo horário
    const lembreteMin = parseInt(criarTarefa.lembreteMin, 10) || 5;
    let i = 0;
    Object.entries(atribuicaoMap).forEach(([dealId, op]) => {
      const cliente = (dadosCliente||{})[dealId] || { nome: '?', telefone: '' };
      const dataHora = new Date(dataHoraBase + i * espacarMin * 60000);
      const tid = 't_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6) + '_' + i;
      tarefas[tid] = {
        id: tid,
        dealId,
        dealNome: cliente.nome || '?',
        titulo,
        dataHora: dataHora.toISOString(),
        lembreteMin,
        observacao: criarTarefa.observacao || '',
        criadoPor: username,
        criadoPorNome: u?.name || username,
        atribuidoA: op,
        atribuidos: [op],
        atribuidos_nomes: [USERS[op]?.name || op],
        status: 'aberta',
        criadoEm: new Date().toISOString(),
      };
      addTimelineEvent(meta, dealId, {
        tipo: 'tarefa',
        label: `📋 Tarefa criada (mass): "${titulo}" pra ${dataHora.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}`,
        by: u.name||username,
      });
      tarefasCriadas++;
      i++;
    });
    saveTarefas(tarefas);
  }

  saveManutMeta(meta);
  res.json({ ok: true, atribuidos, tarefas_criadas: tarefasCriadas });
});

// === AUVO: gestão de equipes em campo ===
const AUVO_BASE = process.env.AUVO_BASE_URL || 'https://api.auvo.com.br/v2';
const AUVO_KEY = process.env.AUVO_API_KEY || '';
const AUVO_TOK = process.env.AUVO_TOKEN || '';
let _auvoCache = { token: null, expiresAt: 0 };

async function getAuvoToken() {
  if (!AUVO_KEY || !AUVO_TOK) throw new Error('AUVO_API_KEY/AUVO_TOKEN não configurados');
  if (_auvoCache.token && Date.now() < _auvoCache.expiresAt - 60000) return _auvoCache.token;
  const url = `${AUVO_BASE}/login/?apiKey=${AUVO_KEY}&apiToken=${AUVO_TOK}`;
  const r = await fetch(url);
  const j = await r.json();
  if (!j.result?.authenticated) throw new Error('Auvo auth fail: ' + (j.result?.message || JSON.stringify(j).slice(0,200)));
  _auvoCache.token = j.result.accessToken;
  _auvoCache.expiresAt = new Date(j.result.expiration.replace(' ', 'T') + 'Z').getTime();
  return _auvoCache.token;
}

async function auvoCall(path, opts = {}) {
  const token = await getAuvoToken();
  const r = await fetch(`${AUVO_BASE}${path}`, {
    ...opts,
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}`, ...(opts.headers||{}) },
  });
  if (r.status === 403) throw new Error('Auvo rate limit (400 req/min)');
  return r.json();
}

// Normaliza coordenadas que vêm como inteiros (-232038675 → -23.20)
function normalizeLatLng(v) {
  if (v == null) return null;
  if (Math.abs(v) > 180) return v / 1e7;
  return v;
}

