// Cache de tasks Auvo dos últimos 12 meses, indexado por telefone (last9) e nome
let _AUVO_INDEX = null;
let _AUVO_INDEX_AT = 0;
async function buildAuvoIndex() {
  // TTL 1h
  if (_AUVO_INDEX && (Date.now() - _AUVO_INDEX_AT) < 3600000) return _AUVO_INDEX;
  const today = todayBR();
  const dStart = new Date(); dStart.setDate(dStart.getDate() - 365);
  const startStr = dStart.toISOString().slice(0,10);
  const filter = encodeURIComponent(JSON.stringify({ startDate: startStr, endDate: today }));
  const all = [];
  for (let page = 1; page <= 10; page++) {
    try {
      const j = await auvoCall(`/tasks/?paramFilter=${filter}&page=${page}&pageSize=200&order=desc`);
      const arr = j?.result?.entityList || j?.entityList || [];
      if (!arr.length) break;
      all.push(...arr);
      if (arr.length < 200) break;
    } catch(e) { console.log('[auvo-index]', e.message); break; }
  }
  // Indexa por telefone last9 (extraído de phoneOrPhones / customerPhone / phone1) e por nome lowercase
  const byPhone = {}, byName = {};
  for (const t of all) {
    const phones = [t.customerPhone, t.phone1, t.phone, t.contactPhone, t.cellPhone].filter(Boolean);
    for (const p of phones) {
      const k = String(p).replace(/\D/g,'').slice(-9);
      if (k && k.length >= 8) {
        if (!byPhone[k]) byPhone[k] = [];
        byPhone[k].push(t);
      }
    }
    const nm = (t.customerDescription || t.customerName || '').toLowerCase().trim();
    if (nm) {
      if (!byName[nm]) byName[nm] = [];
      byName[nm].push(t);
    }
  }
  _AUVO_INDEX = { byPhone, byName, total: all.length, generatedAt: new Date().toISOString() };
  _AUVO_INDEX_AT = Date.now();
  console.log(`[auvo-index] ${all.length} tasks · ${Object.keys(byPhone).length} fones · ${Object.keys(byName).length} nomes`);
  return _AUVO_INDEX;
}

// Endpoint: visitas Auvo de um cliente específico
app.get('/manutencao/cliente/:dealId/auvo', requireAuth, async (req, res) => {
  try {
    const u = USERS[req.session.user.username];
    const isAdmin = u?.role === 'admin';
    const username = req.session.user.username;
    const { dealId } = req.params;
    const meta = loadManutMeta();
    if (!isAdmin && meta[dealId]?.operadora && meta[dealId].operadora !== username) {
      return res.status(403).json({ error: 'cliente fora da sua carteira' });
    }
    // Busca telefone + nome do cliente no Zoho
    const token = await getZohoToken();
    if (!token) return res.status(500).json({ error: 'zoho indisponível' });
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Telefone_contato,Deal_Name`, {
      headers: { Authorization: `Zoho-oauthtoken ${token}` },
    });
    const j = await r.json().catch(() => ({}));
    const deal = j.data?.[0];
    if (!deal) return res.json({ visitas: [], aviso: 'deal não encontrado' });

    const telefone = deal.Telefone_contato || '';
    const nome = (deal.Deal_Name || '').toLowerCase().trim();

    if (!AUVO_KEY || !AUVO_TOK) return res.json({ visitas: [], aviso: 'Auvo não configurado' });

    const idx = await buildAuvoIndex();
    const last9 = String(telefone).replace(/\D/g,'').slice(-9);
    let matches = [];
    if (last9 && idx.byPhone[last9]) matches = matches.concat(idx.byPhone[last9]);
    // Busca também por nome (matching aproximado: primeiras 2 palavras do deal)
    const tokens = nome.split(/\s+/).filter(t => t.length >= 4);
    if (tokens.length >= 1) {
      for (const k of Object.keys(idx.byName)) {
        if (tokens.every(t => k.includes(t))) {
          for (const v of idx.byName[k]) {
            if (!matches.includes(v)) matches.push(v);
          }
        }
      }
    }
    // Dedup + sort por checkInDate desc
    const seen = new Set();
    const visitas = matches.filter(t => {
      if (seen.has(t.taskID || t.id)) return false;
      seen.add(t.taskID || t.id);
      return true;
    }).map(t => ({
      id: t.taskID || t.id,
      cliente: t.customerDescription || t.customerName,
      tipo: t.taskTypeDescription || '',
      status: t.status,
      tecnico: t.userToName,
      checkIn: t.checkInDate,
      checkOut: t.checkOutDate,
      endereco: t.address,
      resumo: (t.summary || t.description || '').slice(0, 280),
      prioridade: t.priority,
      taskDate: t.taskDate || t.scheduleDate,
    })).sort((a, b) => new Date(b.checkIn || b.taskDate || 0) - new Date(a.checkIn || a.taskDate || 0));

    res.json({
      total: visitas.length,
      visitas: visitas.slice(0, 30),
      indexedAt: idx.generatedAt,
    });
  } catch (e) {
    console.error('[auvo cliente]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// === FOTOS DE INSTALAÇÃO (AUVO) ===
// Extrai URLs de foto de uma task — Auvo retorna em campos diferentes dependendo do tipo
function extrairFotosTask(task) {
  if (!task) return [];
  const fotos = [];
  const seen = new Set();
  const push = (url, descr) => {
    if (!url) return;
    const u = String(url).trim();
    if (!u.startsWith('http')) return;
    if (seen.has(u)) return;
    seen.add(u);
    fotos.push({ url: u, descricao: descr || '', filename: u.split('/').pop().split('?')[0] || `foto_${fotos.length+1}.jpg` });
  };
  // Tentamos várias estruturas possíveis
  if (Array.isArray(task.images)) task.images.forEach((x, i) => push(typeof x === 'string' ? x : x?.url || x?.imageUrl, `foto ${i+1}`));
  if (Array.isArray(task.arrayOfImages)) task.arrayOfImages.forEach((x, i) => push(x?.url || x?.imageUrl || x, x?.description));
  if (Array.isArray(task.attachments)) task.attachments.forEach(a => push(a?.url || a?.fileUrl, a?.fileName || a?.description));
  if (Array.isArray(task.photos)) task.photos.forEach((x, i) => push(typeof x === 'string' ? x : x?.url, `foto ${i+1}`));
  if (Array.isArray(task.taskAttachments)) task.taskAttachments.forEach(a => push(a?.url || a?.fileUrl, a?.fileName));
  // Também tenta dentro de checklist/questionário (Auvo guarda fotos lá)
  if (Array.isArray(task.questionnaires)) {
    task.questionnaires.forEach(q => {
      if (Array.isArray(q?.questions)) {
        q.questions.forEach(qq => {
          if (Array.isArray(qq?.answers)) {
            qq.answers.forEach(a => { if (typeof a === 'string' && /^https?:\/\//.test(a)) push(a, qq?.questionDescription); });
          }
          if (qq?.answer && typeof qq.answer === 'string' && /^https?:\/\//.test(qq.answer)) push(qq.answer, qq?.questionDescription);
        });
      }
    });
  }
  return fotos;
}

// Endpoint: lista todas as fotos das visitas Auvo de um cliente
app.get('/manutencao/cliente/:dealId/auvo-fotos', requireAuth, async (req, res) => {
  try {
    const u = USERS[req.session.user.username];
    const isAdmin = u?.role === 'admin';
    const username = req.session.user.username;
    const { dealId } = req.params;
    const meta = loadManutMeta();
    if (!isAdmin && meta[dealId]?.operadora && meta[dealId].operadora !== username) {
      return res.status(403).json({ error: 'cliente fora da sua carteira' });
    }
    if (!AUVO_KEY || !AUVO_TOK) return res.json({ visitas: [], aviso: 'Auvo não configurado' });

    // Reusa o cruzamento do endpoint /auvo (mesma lógica fone+nome)
    const token = await getZohoToken();
    if (!token) return res.status(500).json({ error: 'zoho indisponível' });
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Telefone_contato,Deal_Name`, {
      headers: { Authorization: `Zoho-oauthtoken ${token}` },
    });
    const j = await r.json().catch(() => ({}));
    const deal = j.data?.[0];
    if (!deal) return res.json({ visitas: [], aviso: 'deal não encontrado' });

    const idx = await buildAuvoIndex();
    const last9 = String(deal.Telefone_contato||'').replace(/\D/g,'').slice(-9);
    const nome = (deal.Deal_Name||'').toLowerCase().trim();
    const tokens = nome.split(/\s+/).filter(t => t.length >= 4);
    let candidatos = [];
    if (last9 && idx.byPhone[last9]) candidatos = candidatos.concat(idx.byPhone[last9]);
    if (tokens.length >= 1) {
      for (const k of Object.keys(idx.byName)) {
        if (tokens.every(t => k.includes(t))) {
          for (const v of idx.byName[k]) if (!candidatos.includes(v)) candidatos.push(v);
        }
      }
    }

    // Busca task completa pra cada candidato (paralelo, capa em 10 visitas)
    const taskIds = [...new Set(candidatos.map(t => t.taskID || t.id).filter(Boolean))].slice(0, 10);
    const visitasComFotos = [];
    for (const tid of taskIds) {
      try {
        const det = await auvoCall(`/tasks/${tid}/`);
        const taskFull = det?.result?.entity || det?.entity || det?.result || det;
        const fotos = extrairFotosTask(taskFull);
        if (fotos.length) {
          visitasComFotos.push({
            taskId: tid,
            cliente: taskFull.customerDescription || taskFull.customerName,
            tipo: taskFull.taskTypeDescription,
            tecnico: taskFull.userToName,
            checkIn: taskFull.checkInDate,
            endereco: taskFull.address,
            fotos,
          });
        }
      } catch(e) { console.log('[auvo-fotos task '+tid+']', e.message); }
    }

    const totalFotos = visitasComFotos.reduce((s, v) => s + v.fotos.length, 0);
    res.json({ visitas: visitasComFotos, totalFotos, indexedAt: idx.generatedAt });
  } catch (e) {
    console.error('[auvo-fotos]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// Helper: baixa URL e sobe como anexo no Zoho Deal
async function zohoAttachUrlToDeal(dealId, fileUrl, fileName) {
  const dl = await fetch(fileUrl);
  if (!dl.ok) throw new Error(`falha download: ${dl.status}`);
  const blob = await dl.blob();
  const form = new FormData();
  form.append('file', blob, fileName || 'foto.jpg');
  const token = await getZohoToken();
  const up = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}/Attachments`, {
    method: 'POST',
    headers: { Authorization: `Zoho-oauthtoken ${token}` },
    body: form,
  });
  const j = await up.json().catch(() => ({}));
  const result = j.data?.[0];
  if (result?.code !== 'SUCCESS') throw new Error(result?.message || `zoho attach ${up.status}: ${JSON.stringify(j)}`);
  return result.details;
}

// === LISTA TaskTypes e Users do Auvo (pra UI escolher ao criar OS) ===
let _AUVO_REFS_CACHE = null;
let _AUVO_REFS_AT = 0;
async function getAuvoRefs() {
  if (_AUVO_REFS_CACHE && (Date.now() - _AUVO_REFS_AT) < 6 * 3600000) return _AUVO_REFS_CACHE;
  if (!AUVO_KEY || !AUVO_TOK) return { taskTypes: [], users: [] };
  try {
    const [ttJ, usJ] = await Promise.all([
      auvoCall('/taskTypes/?paramFilter=&page=1&pageSize=100&order=asc').catch(() => ({})),
      auvoCall('/users/?paramFilter=&page=1&pageSize=100&order=asc').catch(() => ({})),
    ]);
    const taskTypes = (ttJ?.result?.entityList || ttJ?.entityList || []).map(t => ({
      id: t.id || t.taskTypeId, descricao: t.description || t.name || t.taskTypeDescription,
    }));
    const users = (usJ?.result?.entityList || usJ?.entityList || []).map(u => ({
      id: u.userId || u.id, nome: u.name || u.userName, ativo: u.active !== false,
    })).filter(u => u.ativo);
    _AUVO_REFS_CACHE = { taskTypes, users };
    _AUVO_REFS_AT = Date.now();
    console.log(`[auvo-refs] ${taskTypes.length} tipos · ${users.length} técnicos`);
    return _AUVO_REFS_CACHE;
  } catch(e) { console.error('[auvo-refs]', e.message); return { taskTypes: [], users: [] }; }
}

