// === CRIAR OS NO AUVO PARTIR DE UM CLIENTE DO CRM CLOSY ===
function proximoDiaUtil(date = new Date()) {
  const d = new Date(date);
  d.setDate(d.getDate() + 1);
  while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() + 1);
  d.setHours(9, 0, 0, 0);
  return d;
}

async function criarOsAuvoParaDeal(dealId, opts = {}) {
  if (!AUVO_KEY || !AUVO_TOK) return { ok:false, error:'Auvo não configurado' };
  // Busca dados do cliente
  const tokenZ = await getZohoToken();
  if (!tokenZ) return { ok:false, error:'Zoho indisponível' };
  const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Deal_Name,Telefone_contato,Cidade,Produto_Vendido,Description,Owner`, {
    headers: { Authorization: `Zoho-oauthtoken ${tokenZ}` },
  });
  const j = await r.json().catch(() => ({}));
  const deal = j.data?.[0];
  if (!deal) return { ok:false, error:'deal não encontrado no Zoho' };

  const refs = await getAuvoRefs();
  const taskTypeId = opts.taskTypeId || refs.taskTypes[0]?.id;
  const userTo = opts.userTo || refs.users[0]?.id;
  if (!taskTypeId) return { ok:false, error:'nenhum TaskType disponível no Auvo' };
  if (!userTo) return { ok:false, error:'nenhum técnico Auvo disponível' };

  const dt = opts.taskDate ? new Date(opts.taskDate) : proximoDiaUtil();
  const taskDateStr = dt.toISOString().slice(0, 19).replace('T', ' ');
  const scheduleDate = dt.toISOString().slice(0, 10);
  const meta = loadManutMeta();
  const m = meta[dealId] || {};
  const produto = deal.Produto_Vendido || '?';

  const body = {
    taskTypeId,
    userTo,
    taskDate: taskDateStr,
    scheduleDate,
    address: deal.Cidade || '',
    customerDescription: deal.Deal_Name || '',
    customerPhone: deal.Telefone_contato || '',
    summary: `Manutenção/Recompra · ${produto}`,
    description: `Cliente: ${deal.Deal_Name}\nTel: ${deal.Telefone_contato}\nCidade: ${deal.Cidade}\nProduto: ${produto}\nObservação CRM: ${m.observacao || '—'}\n\nCriado automaticamente pelo CRM Closy.`,
    priority: 1,
  };

  try {
    const created = await auvoCall('/tasks/', {
      method: 'POST',
      body: JSON.stringify(body),
    });
    const taskId = created?.result?.entity?.taskID || created?.result?.entity?.id || created?.entity?.taskID || created?.taskID;
    if (!taskId) {
      console.error('[auvo-create-os] resposta inesperada:', JSON.stringify(created).slice(0, 500));
      return { ok:false, error: created?.message || created?.result?.errors?.[0]?.message || 'Auvo não retornou taskID', raw: created };
    }
    return { ok:true, taskId, taskDate: taskDateStr, userTo, taskTypeId };
  } catch(e) {
    return { ok:false, error: e.message };
  }
}

app.post('/manutencao/cliente/:dealId/criar-os-auvo', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  const isAdmin = u?.role === 'admin';
  const username = req.session.user.username;
  const { dealId } = req.params;
  const meta = loadManutMeta();
  if (!isAdmin && meta[dealId]?.operadora && meta[dealId].operadora !== username) {
    return res.status(403).json({ error: 'cliente fora da sua carteira' });
  }
  const result = await criarOsAuvoParaDeal(dealId, req.body || {});
  if (!result.ok) return res.status(400).json(result);

  // Loga timeline e marca etapa como agendado se ainda não estiver
  const userName = u?.name || username;
  if (!meta[dealId]) meta[dealId] = {};
  meta[dealId].auvoTaskId = result.taskId;
  meta[dealId].auvoTaskDate = result.taskDate;
  addTimelineEvent(meta, dealId, {
    tipo:'auvo-os',
    label:`📅 OS Auvo criada (#${result.taskId}) pra ${result.taskDate}`,
    by: userName,
    auvoTaskId: result.taskId,
  });
  if (meta[dealId].etapa !== 'agendado' && meta[dealId].etapa !== 'finalizado_ganho') {
    addTimelineEvent(meta, dealId, { tipo:'etapa', label:'Etapa: agendado (auto, OS criada no Auvo)', by: userName });
    meta[dealId].etapa = 'agendado';
  }
  meta[dealId].updatedAt = new Date().toISOString();
  meta[dealId].updatedBy = userName;
  saveManutMeta(meta);

  res.json({ ok:true, taskId: result.taskId, taskDate: result.taskDate, etapa: meta[dealId].etapa });
});

// Endpoint: sincroniza fotos das visitas Auvo do cliente → Zoho como anexos
app.post('/manutencao/cliente/:dealId/anexar-fotos-zoho', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { dealId } = req.params;
  try {
    // Reusa o /auvo-fotos pra pegar as fotos (chamada interna via função)
    const tokenZ = await getZohoToken();
    if (!tokenZ) return res.status(500).json({ error: 'zoho indisponível' });

    // Busca lista de fotos do mesmo jeito do endpoint anterior
    const r = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Telefone_contato,Deal_Name`, {
      headers: { Authorization: `Zoho-oauthtoken ${tokenZ}` },
    });
    const j = await r.json().catch(() => ({}));
    const deal = j.data?.[0];
    if (!deal) return res.status(404).json({ error: 'deal não encontrado' });

    const idx = await buildAuvoIndex();
    const last9 = String(deal.Telefone_contato||'').replace(/\D/g,'').slice(-9);
    const nome = (deal.Deal_Name||'').toLowerCase().trim();
    const tokens = nome.split(/\s+/).filter(t => t.length >= 4);
    let candidatos = [];
    if (last9 && idx.byPhone[last9]) candidatos = candidatos.concat(idx.byPhone[last9]);
    if (tokens.length >= 1) {
      for (const k of Object.keys(idx.byName)) {
        if (tokens.every(t => k.includes(t))) {
          for (const v of idx.byName[k]) if (!candidatos.includes(v)) candidatos.push(v);
        }
      }
    }
    const taskIds = [...new Set(candidatos.map(t => t.taskID || t.id).filter(Boolean))].slice(0, 10);

    // Busca anexos já existentes no Zoho pra evitar duplicar
    let existentes = new Set();
    try {
      const ax = await fetch(`https://www.zohoapis.com/crm/v6/Deals/${dealId}/Attachments`, {
        headers: { Authorization: `Zoho-oauthtoken ${tokenZ}` },
      });
      if (ax.ok) {
        const aj = await ax.json();
        (aj.data || []).forEach(a => existentes.add(a.File_Name));
      }
    } catch(_){}

    const log = { tasks: 0, fotosTotal: 0, anexados: 0, jaExistiam: 0, falhas: [] };
    for (const tid of taskIds) {
      try {
        const det = await auvoCall(`/tasks/${tid}/`);
        const taskFull = det?.result?.entity || det?.entity || det?.result || det;
        const fotos = extrairFotosTask(taskFull);
        if (!fotos.length) continue;
        log.tasks++;
        const dataVisita = (taskFull.checkInDate || taskFull.taskDate || '').slice(0, 10);
        for (let i = 0; i < fotos.length; i++) {
          const f = fotos[i];
          // Nome padronizado: Auvo_<dataVisita>_<taskId>_<i>.jpg
          const fname = `Auvo_${dataVisita || 'visita'}_T${tid}_${i+1}_${(f.filename||'foto.jpg').replace(/[^A-Za-z0-9._-]/g,'_').slice(-30)}`;
          log.fotosTotal++;
          if (existentes.has(fname)) { log.jaExistiam++; continue; }
          try {
            await zohoAttachUrlToDeal(dealId, f.url, fname);
            log.anexados++;
          } catch(e) { log.falhas.push({ url: f.url, erro: e.message }); }
        }
      } catch(e) { log.falhas.push({ taskId: tid, erro: e.message }); }
    }

    // Loga timeline
    if (log.anexados > 0) {
      const meta = loadManutMeta();
      const userName = USERS[req.session.user.username]?.name || req.session.user.username;
      addTimelineEvent(meta, dealId, {
        tipo:'auvo-fotos',
        label:`📎 ${log.anexados} foto(s) Auvo anexadas no Zoho (de ${log.tasks} visita${log.tasks>1?'s':''})`,
        by: userName,
      });
      saveManutMeta(meta);
    }

    res.json({ ok: true, ...log });
  } catch (e) {
    console.error('[anexar-fotos]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// Dashboard agregado: técnicos + última posição GPS + OS do dia
app.get('/auvo/dashboard', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  try {
    const cacheKey = `auvo-dash:${todayBR()}:${nowBR().getHours()}:${Math.floor(nowBR().getMinutes()/3)}`;
    const cached = cacheGet(cacheKey);
    if (cached && req.query.nocache !== '1') return res.json(cached);

    const today = todayBR();
    const taskFilter = encodeURIComponent(JSON.stringify({ startDate: today, endDate: today, status: 4 }));
    const [usersJ, tasksJ] = await Promise.all([
      auvoCall(`/users/?paramFilter=&page=1&pageSize=100&order=asc`),
      auvoCall(`/tasks/?paramFilter=${taskFilter}&page=1&pageSize=100&order=desc`),
    ]);

    const users = (usersJ.result?.entityList || []).map(u => ({
      id: u.userID, name: u.name, login: u.login,
      address: u.address || '',
      basePoint: u.basePoint ? { lat: normalizeLatLng(u.basePoint.latitude), lng: normalizeLatLng(u.basePoint.longitude) } : null,
      disponivel: !u.unavailableForTasks,
      tipo: u.userType?.description || 'User',
      gpsFreq: u.gpsFrequency || 0,
    })).filter(u => u.tipo === 'User'); // só técnicos, não managers

    const tasks = (tasksJ.result?.entityList || []).map(t => ({
      id: t.taskID, externalId: t.externalId,
      idUserTo: t.idUserTo, userToName: t.userToName,
      idCustomer: t.idCustomer, customerDescription: t.customerDescription || t.customerName,
      taskType: t.taskType, taskTypeDescription: t.taskTypeDescription,
      status: t.taskStatus, // 0=Opened ... 5=Paused
      priority: t.priority,
      orientation: t.orientation,
      address: t.address,
      checkInDate: t.checkInDate, checkOutDate: t.checkOutDate,
      taskDate: t.taskDate,
      summary: t.summary,
    }));

    // GPS: última posição por user em paralelo (chunks de 5)
    const userIds = users.map(u => u.id);
    const gpsByUser = {};
    for (let i = 0; i < userIds.length; i += 5) {
      const lote = userIds.slice(i, i+5);
      await Promise.all(lote.map(async uid => {
        try {
          const filter = encodeURIComponent(JSON.stringify({ userId: uid, getLastKnowPosition: true }));
          const j = await auvoCall(`/gps/?paramFilter=${filter}&page=1&pageSize=1&order=desc`);
          const last = j.result?.entityList?.[0];
          if (last) gpsByUser[uid] = {
            lat: normalizeLatLng(last.latitude),
            lng: normalizeLatLng(last.longitude),
            ts: last.positionDate,
            accuracy: last.accuracy,
            battery: last.batteryLevel,
            operator: last.networkOperatorName,
          };
        } catch(_){}
      }));
    }

    // Stats agregadas
    const STATUS_LABEL = { 0:'Aberta', 1:'Em deslocamento', 2:'Check-in feito', 3:'Concluída', 4:'Cancelada', 5:'Pausada' };
    const stats = {
      tecnicosTotal: users.length,
      tecnicosDisponiveis: users.filter(u => u.disponivel).length,
      osHoje: tasks.length,
      osPorStatus: {},
      osPorTecnico: {},
    };
    for (const t of tasks) {
      const lbl = STATUS_LABEL[t.status] || `Status ${t.status}`;
      stats.osPorStatus[lbl] = (stats.osPorStatus[lbl]||0) + 1;
      const k = t.userToName || `User ${t.idUserTo}`;
      stats.osPorTecnico[k] = (stats.osPorTecnico[k]||0) + 1;
    }

    const out = { stats, users, tasks, gpsByUser, statusLabels: STATUS_LABEL, generatedAt: new Date().toISOString() };
    cacheSet(cacheKey, out, 180000); // 3 min
    res.json(out);
  } catch (err) {
    console.error('auvo dashboard:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// === Z-API: status, QR Code, restart ===
async function zapiCall(path, opts = {}) {
  if (!ZAPI_INSTANCE || !ZAPI_TOKEN) return { ok: false, error: 'Z-API não configurado (ZAPI_INSTANCE/ZAPI_TOKEN)' };
  const url = `https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}${path}`;
  try {
    const r = await fetch(url, {
      method: opts.method || 'GET',
      headers: { 'Client-Token': ZAPI_CLIENT_TOKEN, 'Content-Type': 'application/json', ...(opts.headers||{}) },
      body: opts.body,
    });
    const ct = r.headers.get('content-type') || '';
    if (ct.includes('application/json')) {
      const j = await r.json();
      return { ok: r.ok, status: r.status, data: j };
    }
    if (ct.startsWith('image/')) {
      const buf = await r.arrayBuffer();
      return { ok: r.ok, status: r.status, image: Buffer.from(buf), contentType: ct };
    }
    const txt = await r.text();
    return { ok: r.ok, status: r.status, text: txt };
  } catch (e) { return { ok: false, error: e.message }; }
}

