// === BASE DE CONTATOS WHATSAPP (Z-API) ===
// Lista contatos da conta pareada — paginação Z-API: page/pageSize
app.get('/admin/whatsapp/contatos', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const page = parseInt(req.query.page) || 1;
  const pageSize = Math.min(parseInt(req.query.pageSize) || 100, 200);
  const r = await zapiCall(`/contacts?page=${page}&pageSize=${pageSize}`);
  if (!r.ok) return res.status(500).json({ error: r.error || 'falha Z-API', status: r.status });

  // Z-API retorna array direto OU {contacts:[]}. Normaliza.
  const arr = Array.isArray(r.data) ? r.data : (r.data?.contacts || r.data?.entityList || []);

  // Cruza com Zoho pra identificar quem JÁ é deal
  const phones = arr.map(c => String(c.phone || c.id || '').replace(/\D/g,'').slice(-9)).filter(Boolean);
  const jaCliente = {};
  // Cruzamento leve (em batches de 5) só pra os primeiros 50 — economiza Zoho
  const subset = phones.slice(0, 50);
  for (let i = 0; i < subset.length; i += 5) {
    const lote = subset.slice(i, i+5);
    await Promise.all(lote.map(async last9 => {
      try {
        const deals = await zohoSearch(`(Telefone_contato:contains:${last9})`, 'Deal_Name,Stage,id', 1);
        if (deals.length) jaCliente[last9] = { dealId: deals[0].id, name: deals[0].Deal_Name, stage: deals[0].Stage };
      } catch(_){}
    }));
  }

  const contatos = arr.map(c => {
    const phoneClean = String(c.phone || c.id || '').replace(/\D/g,'');
    const last9 = phoneClean.slice(-9);
    return {
      phone: phoneClean,
      name: c.name || c.short || c.notify || c.pushname || '',
      isMyContact: c.isMyContact !== false,
      jaCliente: jaCliente[last9] || null,
    };
  }).filter(c => c.phone);

  res.json({ total: contatos.length, page, pageSize, contatos });
});

// Converter contato → Lead/Deal no Zoho
app.post('/admin/whatsapp/converter-lead', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { phone, nome, cidade, produtoInteresse, observacao } = req.body || {};
  if (!phone || !nome) return res.status(400).json({ error: 'phone e nome obrigatórios' });

  const token = await getZohoToken();
  if (!token) return res.status(500).json({ error: 'zoho indisponível' });

  const phoneClean = String(phone).replace(/\D/g,'');
  const userName = USERS[req.session.user.username]?.name || 'Sistema';

  try {
    // Verifica se já existe deal pra esse telefone
    const last9 = phoneClean.slice(-9);
    const existing = await zohoSearch(`(Telefone_contato:contains:${last9})`, 'Deal_Name,id,Stage', 1);
    if (existing.length) {
      return res.json({ ok: false, jaExiste: true, dealId: existing[0].id, name: existing[0].Deal_Name, stage: existing[0].Stage });
    }

    // Cria novo deal
    const body = {
      data: [{
        Deal_Name: nome,
        Stage: 'Leads Novos',
        Pipeline: 'Geral',
        Layout: { id: '6311862000037730183' }, // Telemarketing — default da org mudou
        Telefone_contato: phoneClean,
        Lead_Source: 'WhatsApp Orgânico',
        Cidade: cidade || '',
        Produto_Vendido: produtoInteresse || '',
        Description: `Convertido do WhatsApp Z-API por ${userName}.${observacao?' Obs: '+observacao:''}`,
      }],
    };

    const r = await fetch('https://www.zohoapis.com/crm/v6/Deals', {
      method: 'POST',
      headers: { Authorization: `Zoho-oauthtoken ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const j = await r.json();
    const result = j.data?.[0];
    if (result?.code !== 'SUCCESS') return res.status(500).json({ error: result?.message || 'falha criar deal', raw: j });

    // Notifica Paulo
    try { await zapiSend(PAULO_PHONE, `[Contato → Lead] ${nome} (${phoneClean}) criado por ${userName}`); } catch(_){}

    res.json({ ok: true, dealId: result.details?.id, crmLink: `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${result.details?.id}` });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

