// === ÁREA ADM: Usuários + Metas (storage persistente em disco) ===
const ADM_DIR = path.join(__dirname, 'data');
const USERS_FILE = path.join(ADM_DIR, 'users.json');
const METAS_FILE = path.join(ADM_DIR, 'metas.json');
try { require('fs').mkdirSync(ADM_DIR, { recursive: true }); } catch(_){}

function loadJsonFile(p, fallback){
  try { return JSON.parse(require('fs').readFileSync(p, 'utf8')); } catch { return fallback; }
}
function saveJsonFile(p, obj){
  require('fs').writeFileSync(p, JSON.stringify(obj, null, 2));
}

// Carrega overrides — Postgres (kv_store) é fonte de verdade, arquivo é fallback dev local.
// Railway tem filesystem efêmero, então salvar APENAS em arquivo perde tudo a cada deploy.
let _USERS_OVERRIDE = loadJsonFile(USERS_FILE, {});
let _METAS_OVERRIDE = loadJsonFile(METAS_FILE, {});

// Aplica overrides nos objetos em memória (sync — fallback de arquivo)
Object.assign(USERS, _USERS_OVERRIDE);
Object.assign(METAS_ABRIL, _METAS_OVERRIDE);

// Quando o PG terminar de carregar, sobrescreve com a fonte de verdade
kvLoadAll().then(() => {
  const usersKv = _kvCache['users-override'];
  if (usersKv && typeof usersKv === 'object' && Object.keys(usersKv).length) {
    _USERS_OVERRIDE = usersKv;
    Object.assign(USERS, _USERS_OVERRIDE);
    console.log(`[users] sincronizado do PG: ${Object.keys(_USERS_OVERRIDE).length} overrides`);
  } else if (Object.keys(_USERS_OVERRIDE).length) {
    // Migração one-shot: PG vazio mas tem arquivo — sobe pro PG
    kvSet('users-override', _USERS_OVERRIDE).then(() => console.log(`[users] migrado arquivo → PG (${Object.keys(_USERS_OVERRIDE).length})`)).catch(()=>{});
  }
  const metasKv = _kvCache['metas-override'];
  if (metasKv && typeof metasKv === 'object' && Object.keys(metasKv).length) {
    _METAS_OVERRIDE = metasKv;
    Object.assign(METAS_ABRIL, _METAS_OVERRIDE);
    console.log(`[metas] sincronizado do PG: ${Object.keys(_METAS_OVERRIDE).length} overrides`);
  } else if (Object.keys(_METAS_OVERRIDE).length) {
    kvSet('metas-override', _METAS_OVERRIDE).then(() => console.log(`[metas] migrado arquivo → PG (${Object.keys(_METAS_OVERRIDE).length})`)).catch(()=>{});
  }
}).catch(e => console.warn('[users/metas kv load]', e.message));

