// === SQUADS — metas + membros multi-team ===
function getSquadMetas() { return _kvCache['squad-metas'] || {}; }
function saveSquadMetas(m) { return kvSet('squad-metas', m); }

// Mapeia faturamento real do mês por squad (cruza WON_CACHE × USERS.teams)
async function computeSquadFaturamentoMes() {
  const won = (await getWonDealsCached()) || [];
  const ym = todayBR().slice(0, 7); // 'YYYY-MM'
  const ownerToTeams = new Map();
  for (const u of Object.values(USERS)) {
    if (u.crmOwner) ownerToTeams.set(String(u.crmOwner).toLowerCase(), getUserTeams(u));
  }
  const fatBySquad = Object.fromEntries(SQUAD_KEYS.map(k => [k, 0]));
  const countBySquad = Object.fromEntries(SQUAD_KEYS.map(k => [k, 0]));
  for (const d of won) {
    if ((d.Closing_Date || '').slice(0, 7) !== ym) continue;
    const owner = (d.Owner?.name || '').toLowerCase();
    const teams = ownerToTeams.get(owner) || [];
    if (!teams.length) continue;
    const valor = parseFloat(d.Amount) || 0;
    // Distribui o valor para TODAS as squads do owner (overlap intencional — Empresa não soma duplicado, ver abaixo)
    for (const t of teams) {
      if (fatBySquad[t] === undefined) continue;
      fatBySquad[t] += valor;
      countBySquad[t]++;
    }
  }
  // Empresa = soma sem duplicação (cada deal uma vez)
  let fatEmpresa = 0;
  let countEmpresa = 0;
  for (const d of won) {
    if ((d.Closing_Date || '').slice(0, 7) !== ym) continue;
    fatEmpresa += parseFloat(d.Amount) || 0;
    countEmpresa++;
  }
  return { fatBySquad, countBySquad, fatEmpresa, countEmpresa };
}

app.get('/admin/squads/data', requireAuth, async (req, res) => {
  if (USERS[req.session.user.username]?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  try {
    const metas = getSquadMetas();
    const { fatBySquad, countBySquad, fatEmpresa, countEmpresa } = await computeSquadFaturamentoMes();
    const squads = SQUADS.map(s => {
      const membros = Object.entries(USERS)
        .filter(([_, u]) => userInSquad(u, s.key))
        .map(([username, u]) => ({ username, name: u.name, crmOwner: u.crmOwner, role: u.role }));
      const meta = metas[s.key] || { faturamento: 0, vendas: 0 };
      const fat = Math.round(fatBySquad[s.key] || 0);
      const pct = meta.faturamento ? Math.round(fat / meta.faturamento * 100) : 0;
      return { ...s, membros, meta, faturamentoMes: fat, vendasMes: countBySquad[s.key] || 0, pct };
    });
    const metaEmpresa = SQUADS.reduce((s, sq) => s + (metas[sq.key]?.faturamento || 0), 0);
    res.json({
      squads,
      empresa: {
        metaTotal: metaEmpresa,
        faturamentoMes: Math.round(fatEmpresa),
        vendasMes: countEmpresa,
        pct: metaEmpresa ? Math.round(fatEmpresa / metaEmpresa * 100) : 0,
      },
      // Lista de TODOS os usuários com role closer/sdr/posvenda + admin pra UI de checkboxes
      todosUsuarios: Object.entries(USERS)
        .filter(([_, u]) => u.role !== 'admin' || u.nivel !== 'ceo')
        .map(([username, u]) => ({ username, name: u.name, role: u.role, teams: getUserTeams(u) })),
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

