app.post('/gestao/premiacoes-extras', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const { id, titulo, descricao, premio, regras, inicio, fim, time, produtoCategoria, ativa, icone, cor } = req.body || {};
  if (!titulo) return res.status(400).json({ error: 'titulo obrigatório' });
  const lista = loadPremiacoesExtras();
  const item = {
    id: id || ('px_' + Date.now() + '_' + Math.random().toString(36).slice(2,5)),
    titulo: String(titulo).slice(0, 200),
    descricao: String(descricao || '').slice(0, 1500),
    premio: String(premio || '').slice(0, 300),
    regras: String(regras || '').slice(0, 1500),
    inicio: inicio || new Date().toISOString().slice(0,10),
    fim: fim || null,
    time: time || 'todos', // 'todos' | 'bebedouro' | 'filtro' | 'poco' | 'loja'
    produtoCategoria: produtoCategoria || null,
    icone: icone || '🏆',
    cor: cor || '#fbbf24',
    ativa: ativa !== false,
    criadoPor: u.name || u.username,
    criadoEm: new Date().toISOString(),
  };
  if (id) {
    const idx = lista.findIndex(p => p.id === id);
    if (idx >= 0) {
      lista[idx] = { ...lista[idx], ...item, atualizadoEm: new Date().toISOString() };
    } else {
      lista.push(item);
    }
  } else {
    lista.push(item);
  }
  savePremiacoesExtras(lista);
  res.json({ ok: true, premiacao: item });
});

