app.post('/gestao/melhorar-texto-ia', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(500).json({ error: 'ANTHROPIC_API_KEY não configurada' });
  const { texto, tipo, contexto } = req.body || {};
  if (!texto || !texto.trim()) return res.status(400).json({ error: 'texto vazio' });
  const tipos = {
    titulo: 'Título de premiação/campanha de vendas. Curto, impactante, motivador.',
    descricao: 'Descrição completa da campanha. Explicar contexto, objetivo, mecânica em 2-3 parágrafos curtos.',
    premio: 'Descrição do prêmio. Curto, atrativo, deixar claro o que ganha.',
    regras: 'Regras claras e objetivas. Lista numerada com critérios mensuráveis.',
    motivo_call: 'Motivo de uma ligação pra closer fazer. Curto, no imperativo.',
    geral: 'Texto comercial pra time de vendas. Direto, sem floreio.',
  };
  const SYSTEM = `Você é um copywriter sênior da Tudo de Filtro especializado em comunicação interna pra time de vendas. Recebe um texto rascunho e melhora MANTENDO a intenção original, só refinando.

REGRAS:
- Mantenha a essência da mensagem original
- Português brasileiro coloquial profissional
- Direto, sem clichê motivacional vazio
- ${tipos[tipo] || tipos.geral}
- ${contexto ? 'Contexto adicional: ' + contexto : ''}

Retorne APENAS o texto melhorado, sem comentário antes/depois.`;
  try {
    const Anthropic = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
    const anthropic = new Anthropic({ apiKey });
    const r = await anthropic.messages.create({
      model: 'claude-sonnet-4-5-20250929',
      max_tokens: 1500,
      system: SYSTEM,
      messages: [{ role: 'user', content: 'Texto rascunho:\n\n' + texto }],
    });
    const melhorado = (r.content?.[0]?.text || '').trim();
    res.json({ ok: true, original: texto, melhorado });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

