app.get('/admin/metas-time-produto', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const metas = loadMetasTimeProduto();
  res.json({ metas, times: TIMES_DISPONIVEIS, produtos: PRODUTOS_META });
});

app.post('/admin/metas-time-produto', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { metas } = req.body || {};
  if (!metas || typeof metas !== 'object') return res.status(400).json({ error: 'metas obrigatório' });
  const limpo = {};
  const timesValidos = TIMES_DISPONIVEIS.map(t => t.id);
  const produtosValidos = PRODUTOS_META.map(p => p.id);
  for (const [team, prods] of Object.entries(metas)) {
    if (!timesValidos.includes(team)) continue;
    limpo[team] = {};
    for (const [prod, cfg] of Object.entries(prods || {})) {
      if (!produtosValidos.includes(prod)) continue;
      const qtd = Math.max(0, parseInt(cfg.meta_qtd, 10) || 0);
      const rs = Math.max(0, parseFloat(cfg.meta_rs) || 0);
      if (qtd === 0 && rs === 0) continue; // pula vazio
      limpo[team][prod] = { meta_qtd: qtd, meta_rs: rs };
    }
    if (!Object.keys(limpo[team]).length) delete limpo[team];
  }
  saveMetasTimeProduto(limpo);
  res.json({ ok: true, metas: limpo });
});

// Progresso de cada meta vs realizado (mês atual)
app.get('/admin/metas-time-produto/progresso', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  try {
    const metas = loadMetasTimeProduto();
    const today = todayBR();
    const monthStart = `${today.slice(0,7)}-01`;
    const won = await zohoSearch(
      `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`,
      'Deal_Name,Amount,Owner,Lead_Source,Produto_Vendido,Pipeline,Closing_Date',
      400,
    ).catch(() => []);
    // Enriquece com produtos REAIS do Orçamento (Quoted_Items) pra categorização precisa
    await enrichDealsWithProducts(won, { limit: 400, parallel: 8 });

    // Categoriza cada won em produto (prioriza produtosReais do Orçamento)
    function catProduto(d) {
      const t = `${d.produtosReais||''} ${d.Deal_Name||''} ${d.Lead_Source||''} ${d.Produto_Vendido||''} ${d.Pipeline||''}`.toLowerCase();
      if (/iron\s*free|ironfree/.test(t)) return 'iron_free';
      if (/scale\s*stop/.test(t)) return 'scale_stop';
      if (/bebedour/.test(t)) return 'bebedouro';
      if (/refil|aguasana|planeta\s*agua|wfs|over\s*flow|sana|bbl/.test(t)) return 'refil';
      if (/condom[ií]nio/.test(t)) return 'condominio';
      if (/loja|presencial/.test(t)) return 'loja';
      if (/purificador|af.?15|af.?25|bliss|soft|premium/.test(t)) return 'purificador';
      if (/filtro.?(de.?)?entrada|n[aã]o.?tratada|po[cç]o|caixa.?d.?[áa]gua/.test(t)) return 'filtro_entrada';
      return 'outros';
    }
    // Mapeia owner → team
    function ownerToTeam(ownerName) {
      if (!ownerName) return null;
      const n = ownerName.toLowerCase().split(' ')[0];
      for (const [user, cfg] of Object.entries(USERS)) {
        if (cfg.crmOwner && cfg.crmOwner.toLowerCase().split(' ')[0] === n) return cfg.team;
      }
      return null;
    }

    // Realizado: { team: { produto: { qtd, rs } } }
    const realizado = {};
    for (const d of won) {
      const team = ownerToTeam(d.Owner?.name);
      const prod = catProduto(d);
      if (!team) continue;
      if (!realizado[team]) realizado[team] = {};
      if (!realizado[team][prod]) realizado[team][prod] = { qtd: 0, rs: 0 };
      realizado[team][prod].qtd++;
      realizado[team][prod].rs += parseFloat(d.Amount) || 0;
    }
    // Monta progresso por meta
    const progresso = {};
    for (const [team, prods] of Object.entries(metas)) {
      progresso[team] = {};
      for (const [prod, cfg] of Object.entries(prods)) {
        const real = realizado[team]?.[prod] || { qtd: 0, rs: 0 };
        progresso[team][prod] = {
          meta_qtd: cfg.meta_qtd,
          meta_rs: cfg.meta_rs,
          real_qtd: real.qtd,
          real_rs: real.rs,
          pct_qtd: cfg.meta_qtd > 0 ? Math.round((real.qtd / cfg.meta_qtd) * 100) : null,
          pct_rs: cfg.meta_rs > 0 ? Math.round((real.rs / cfg.meta_rs) * 100) : null,
        };
      }
    }
    res.json({ mes: today.slice(0,7), metas, progresso, realizado, total_deals: won.length });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

