// === UNIFICAÇÃO DE CIDADES (Zoho Cidade field) ===
// Mapping manual de abreviações + variações conhecidas pra forma canônica
const CIDADE_ALIASES = {
  // São José dos Campos / Vale do Paraíba
  'sjc': 'São José dos Campos',
  's.j. dos campos': 'São José dos Campos',
  's.j. campos': 'São José dos Campos',
  'sj campos': 'São José dos Campos',
  's jose dos campos': 'São José dos Campos',
  's. jose dos campos': 'São José dos Campos',
  'são jose dos campos': 'São José dos Campos',
  'sao jose dos campos': 'São José dos Campos',
  'sao jose campos': 'São José dos Campos',
  'são josé campos': 'São José dos Campos',
  'são josé dos campos sp': 'São José dos Campos',
  'sao jose dos campos sp': 'São José dos Campos',
  'sao josé dos campos': 'São José dos Campos',
  // outras grandes
  'sp': 'São Paulo',
  'sao paulo': 'São Paulo',
  'são paulo': 'São Paulo',
  'rj': 'Rio de Janeiro',
  'rio de janeiro': 'Rio de Janeiro',
  'bh': 'Belo Horizonte',
  'belo horizonte': 'Belo Horizonte',
  'rp': 'Ribeirão Preto',
  'ribeirao preto': 'Ribeirão Preto',
  'ribeirão preto': 'Ribeirão Preto',
  'campinas': 'Campinas',
  'taubaté': 'Taubaté',
  'taubate': 'Taubaté',
  'jacareí': 'Jacareí',
  'jacarei': 'Jacareí',
  'pindamonhangaba': 'Pindamonhangaba',
  'pinda': 'Pindamonhangaba',
  'sjcampos': 'São José dos Campos',
  'caçapava': 'Caçapava',
  'cacapava': 'Caçapava',
  'guaratinguetá': 'Guaratinguetá',
  'guaratingueta': 'Guaratinguetá',
  'são sebastião': 'São Sebastião',
  'sao sebastiao': 'São Sebastião',
  'caraguatatuba': 'Caraguatatuba',
  'caragua': 'Caraguatatuba',
  'ubatuba': 'Ubatuba',
  'são josé do rio preto': 'São José do Rio Preto',
  'sao jose do rio preto': 'São José do Rio Preto',
  'sjrp': 'São José do Rio Preto',
};
function _cidadeNormalizarKey(s) {
  if (!s) return '';
  return String(s)
    .normalize('NFD').replace(/[̀-ͯ]/g, '') // remove acentos
    .toLowerCase()
    .trim()
    .replace(/[\s/.,_-]+/g, ' ') // colapsa whitespace + pontuação
    .replace(/\s*-\s*sp$|\s+sp$/i, '') // remove "- SP" / " SP" no final
    .replace(/\s+/g, ' ');
}
function cidadeCanonica(s) {
  if (!s) return '';
  const k = _cidadeNormalizarKey(s);
  if (!k) return '';
  if (CIDADE_ALIASES[k]) return CIDADE_ALIASES[k];
  // Default: title case com preposições minúsculas
  const stops = new Set(['de','do','da','dos','das','e','d','di']);
  const titleCased = k.split(' ').map((w, i) => {
    if (i > 0 && stops.has(w)) return w;
    return w.charAt(0).toUpperCase() + w.slice(1);
  }).join(' ');
  return titleCased;
}

// GET /admin/cidades/discover — lista variantes de cidade no banco LOCAL (ERP + manut-meta)
// Default: puxa do ERP (base completa de clientes históricos). Opcional: ?fonte=zoho usa Zoho.
app.get('/admin/cidades/discover', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const fonte = req.query.fonte || 'base'; // 'base' (ERP+manut local) | 'zoho' | 'tudo'
  try {
    let cidadesCount = {};
    let totalRegistros = 0;
    let fonteUsada = [];

    // FONTE 1: Base ERP local (pega todos os clientes históricos)
    if (fonte === 'base' || fonte === 'tudo') {
      const erpLista = loadErpLista();
      for (const reg of erpLista) {
        totalRegistros++;
        const c = String(reg.cidade || '').trim();
        if (!c) continue;
        cidadesCount[c] = (cidadesCount[c] || 0) + 1;
      }
      fonteUsada.push(`ERP local (${erpLista.length} clientes)`);
    }

    // FONTE 2: Zoho (opcional, se solicitado)
    if (fonte === 'zoho' || fonte === 'tudo') {
      const meses = Math.max(1, Math.min(60, parseInt(req.query.meses, 10) || 24));
      const since = new Date(Date.now() - meses * 30 * 86400000).toISOString();
      const fields = 'Deal_Name,Cidade,Created_Time';
      let zohoCount = 0;
      for (let pg = 1; pg <= 10; pg++) {
        const url = `https://www.zohoapis.com/crm/v6/Deals/search?criteria=(Created_Time:greater_equal:${since})&fields=${fields}&page=${pg}&per_page=200`;
        const tk = await getZohoToken();
        if (!tk) break;
        const r = await fetch(url, { headers: { Authorization: `Zoho-oauthtoken ${tk}` } });
        if (!r.ok) break;
        const j = await r.json();
        const data = j.data || [];
        if (!data.length) break;
        for (const d of data) {
          totalRegistros++;
          zohoCount++;
          const c = (d.Cidade || '').trim();
          if (!c) continue;
          cidadesCount[c] = (cidadesCount[c] || 0) + 1;
        }
        if (data.length < 200) break;
      }
      fonteUsada.push(`Zoho últimos ${meses}m (${zohoCount} deals)`);
    }
    const totalDeals = totalRegistros;
    // Agrupa por chave normalizada
    const grupos = {};
    for (const [variante, count] of Object.entries(cidadesCount)) {
      const canonica = cidadeCanonica(variante);
      const key = _cidadeNormalizarKey(canonica) || _cidadeNormalizarKey(variante);
      if (!grupos[key]) grupos[key] = { canonica, variantes: [], total: 0 };
      grupos[key].variantes.push({ nome: variante, count });
      grupos[key].total += count;
    }
    // Filtra apenas grupos onde HÁ unificação (>1 variante OU variante diferente da canônica)
    const lista = Object.values(grupos)
      .map(g => ({
        ...g,
        precisa_unificar: g.variantes.length > 1 || g.variantes.some(v => v.nome !== g.canonica),
        variantes: g.variantes.sort((a,b) => b.count - a.count),
      }))
      .sort((a,b) => b.total - a.total);
    res.json({
      total_deals: totalDeals,
      total_cidades_unicas: Object.keys(cidadesCount).length,
      grupos: lista,
      precisam_unificar: lista.filter(g => g.precisa_unificar).length,
      meses_analisados: meses,
    });
  } catch(e) {
    console.error('[cidades discover]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// POST /admin/cidades/aplicar — aplica mapping nos deals (em batch via updateDeal)
// Body: { mapping: { 'SJC': 'São José dos Campos', ... }, dry_run: false }
app.post('/admin/cidades/aplicar', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { mapping, dry_run } = req.body || {};
  if (!mapping || typeof mapping !== 'object' || !Object.keys(mapping).length) {
    return res.status(400).json({ error: 'mapping obrigatório (objeto { variante: canonica })' });
  }
  // Constrói criteria buscando deals com qualquer das variantes
  const variantes = Object.keys(mapping);
  const fields = 'Deal_Name,Cidade';
  try {
    let totalEncontrados = 0;
    let atualizados = 0;
    const erros = [];
    const log = [];
    for (let pg = 1; pg <= 10; pg++) {
      const tk = await getZohoToken();
      if (!tk) break;
      // Busca paginada por cada variante (Zoho não aceita IN no Cidade direto)
      // Estratégia: 1 query por variante de até 200 deals
      let dealsToUpdate = [];
      for (const v of variantes) {
        if (mapping[v] === v) continue; // mesma string, skip
        const url = `https://www.zohoapis.com/crm/v6/Deals/search?criteria=(Cidade:equals:${encodeURIComponent(v)})&fields=${fields}&page=${pg}&per_page=200`;
        try {
          const r = await fetch(url, { headers: { Authorization: `Zoho-oauthtoken ${tk}` } });
          if (!r.ok) continue;
          const j = await r.json();
          const data = j.data || [];
          for (const d of data) {
            if (d.Cidade === v && mapping[v] && mapping[v] !== v) {
              dealsToUpdate.push({ id: d.id, deal_name: d.Deal_Name, cidade_antes: v, cidade_depois: mapping[v] });
            }
          }
        } catch(_){}
      }
      totalEncontrados += dealsToUpdate.length;
      if (!dealsToUpdate.length) break;
      // Aplica updates em paralelo (chunks de 5)
      if (!dry_run) {
        for (let i = 0; i < dealsToUpdate.length; i += 5) {
          const chunk = dealsToUpdate.slice(i, i+5);
          const results = await Promise.all(chunk.map(async d => {
            try {
              const ok = await zoho.updateDeal(d.id, { Cidade: d.cidade_depois });
              return { ...d, ok };
            } catch(e) { return { ...d, ok: false, erro: e.message }; }
          }));
          results.forEach(r => {
            if (r.ok) atualizados++;
            else erros.push({ deal_id: r.id, deal_name: r.deal_name, erro: r.erro || 'falha' });
            log.push(r);
          });
        }
      } else {
        log.push(...dealsToUpdate);
      }
      if (dealsToUpdate.length < variantes.length * 200) break; // aproximação
      break; // por enquanto roda 1 página apenas pra evitar loop excessivo
    }
    res.json({
      dry_run: !!dry_run,
      total_encontrados: totalEncontrados,
      atualizados,
      erros: erros.length,
      sample_erros: erros.slice(0, 10),
      log: log.slice(0, 50),
    });
  } catch(e) {
    console.error('[cidades aplicar]', e.message);
    res.status(500).json({ error: e.message });
  }
});

