  atividade_faixa_40: { pts: 40, desc: 'Faixa 21-40 atividades' },
  atividade_faixa_60: { pts: 90, desc: 'Faixa 41-60 atividades' },
  atividade_faixa_80: { pts: 150, desc: 'Faixa 61-80 atividades' },
  atividade_faixa_100: { pts: 250, desc: 'Faixa 81-100+ atividades' },
  // === VENDAS (forte) ===
  deal_ganho: { pts: 50, desc: 'Venda fechada' },
  deal_ganho_24h: { pts: 80, desc: 'Venda em ate 24h (flash)' },
