// === Closer dispara Núbia pro próprio lead ===
app.post('/cockpit/nubia-meu-lead', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (!u?.crmOwner) return res.status(401).json({ error: 'unauthenticated' });

  const { dealId } = req.body || {};
  if (!dealId) return res.status(400).json({ error: 'dealId obrigatório' });

  try {
    // Busca o deal e verifica se pertence ao closer
    const token = await getZohoToken();
    if (!token) return res.status(500).json({ error: 'zoho indisponível' });
    const url = `https://www.zohoapis.com/crm/v6/Deals/${dealId}?fields=Deal_Name,Owner,Telefone_contato,Pipeline,Stage`;
    const r = await fetch(url, { headers: { Authorization: `Zoho-oauthtoken ${token}` } });
    if (!r.ok) return res.status(404).json({ error: 'deal não encontrado' });
    const data = await r.json();
    const d = data.data?.[0];
    if (!d) return res.status(404).json({ error: 'deal não encontrado' });

    // Admin pode disparar pra qualquer; closer só pra próprio
    if (u.role !== 'admin' && d.Owner?.name !== u.crmOwner) {
      return res.status(403).json({ error: 'esse lead não é seu' });
    }
    if (!d.Telefone_contato) return res.status(400).json({ error: 'lead sem telefone' });

    const result = await nubiaOutreach([d], 'closer_solicitou');
    // Notifica admin
    try { await zapiSend(PAULO_PHONE, `[Núbia solicitada] ${u.name} pediu Núbia pro lead "${d.Deal_Name}" (${d.Stage}). Status: ${result.sent?'✓ enviado':'✗ falhou'}`); } catch(_){}
    res.json({ ok: result.sent > 0, ...result, deal: d.Deal_Name });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// === Helper: contagem de atividades (Tasks) por deal pra um owner ===
async function getTasksCountByDeal(ownerName) {
  const cacheKey = `tasks-count:${ownerName}`;
  const cached = cacheGet(cacheKey);
  if (cached) return cached;

  try {
    const token = await getZohoToken();
    if (!token) return {};
    // Busca tasks do owner — relacionadas a deals
    const url = `https://www.zohoapis.com/crm/v6/Tasks/search?criteria=(Owner:equals:${encodeURIComponent(ownerName)})&fields=What_Id,Who_Id,Status,Created_Time&per_page=200`;
    const r = await fetch(url, { headers: { Authorization: `Zoho-oauthtoken ${token}` } });
    if (r.status === 204) { cacheSet(cacheKey, {}, 600000); return {}; }
    if (!r.ok) return {};
    const data = await r.json();
    const tasks = data.data || [];
    const counts = {};
    for (const t of tasks) {
      const dealId = t.What_Id?.id || t.Who_Id?.id;
      if (!dealId) continue;
      counts[dealId] = (counts[dealId] || 0) + 1;
    }
    cacheSet(cacheKey, counts, 600000); // 10 min
    return counts;
  } catch (e) {
    console.error('getTasksCountByDeal:', e.message);
    return {};
  }
}

// === Ranking ANUAL por grupo (Filtro de Entrada / Bebedouro / Loja) ===
app.get('/cockpit/anual-ranking', requireAuth, async (req, res) => {
  try {
    const nowBr = nowBR();
    const yearStart = `${nowBr.getFullYear()}-01-01`;
    const today = todayBR();
    const cacheKey = `anual-ranking:${today}`;
    const cached = cacheGet(cacheKey);
    if (cached) return res.json(cached);

    const won = await zohoSearch(
      `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${yearStart},${today}))`,
      'Deal_Name,Amount,Owner,Closing_Date,Pipeline,Layout', 200
    );

    const ranks = { filtro: {}, bebedouro: {}, loja: {} };
    for (const d of won) {
      const c = canalDeal(d);
      if (!ranks[c]) continue; // ignora 'outros'
      const owner = d.Owner?.name || '?';
      const v = parseFloat(d.Amount) || 0;
      if (!ranks[c][owner]) ranks[c][owner] = { name: owner, vendas: 0, fat: 0 };
      ranks[c][owner].vendas++;
      ranks[c][owner].fat += v;
    }

    const formatRank = m => Object.values(m)
      .sort((a,b) => b.fat - a.fat)
      .map((r, i) => ({ pos: i+1, ...r, ticketMedio: r.vendas ? Math.round(r.fat/r.vendas) : 0 }));

    const out = {
      ano: nowBr.getFullYear(),
      filtro:    formatRank(ranks.filtro),
      bebedouro: formatRank(ranks.bebedouro),
      loja:      formatRank(ranks.loja),
      total: {
        filtro:    Object.values(ranks.filtro).reduce((s,r)=>s+r.fat, 0),
        bebedouro: Object.values(ranks.bebedouro).reduce((s,r)=>s+r.fat, 0),
        loja:      Object.values(ranks.loja).reduce((s,r)=>s+r.fat, 0),
      },
      generatedAt: new Date().toISOString(),
    };
    cacheSet(cacheKey, out, 600000); // 10 min
    res.json(out);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

