app.get('/cockpit/coins/ranking', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  // Lista de closers disponíveis pra o admin selecionar
  const closers = Object.entries(USERS)
    .filter(([_, x]) => x.role === 'closer')
    .map(([username, x]) => ({ username, name: x.name, crmOwner: x.crmOwner, team: x.team }));
  res.json({ closers });
});

app.get('/cockpit/coins', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  const isAdmin = loggedUser?.role === 'admin';
  let targetUser = loggedUser;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) targetUser = USERS[req.query.closer];
  if (!targetUser?.crmOwner) return res.json({ error: 'user not mapped' });

  try {
    const ownerName = targetUser.crmOwner;
    const now = new Date();
    const today = todayBR();
    const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
    const meta = METAS_ABRIL[ownerName] || { faturamento: 90000 };

    // Coins: conta apenas vendas dos últimos 12 meses (coins mais antigos expiram)
    const dozeAtras = new Date(now);
    dozeAtras.setFullYear(dozeAtras.getFullYear() - 1);
    const dozeAtrasStr = dozeAtras.toISOString().slice(0, 10);
    const onzeMesesAtras = new Date(now);
    onzeMesesAtras.setMonth(onzeMesesAtras.getMonth() - 11);
    const onzeMesesStr = onzeMesesAtras.toISOString().slice(0, 10);
    const dozeMesesAtras2 = new Date(now);
    dozeMesesAtras2.setMonth(dozeMesesAtras2.getMonth() - 12);
    const dozeMesesStr2 = dozeMesesAtras2.toISOString().slice(0, 10);

    const won = await zohoSearch(
      `((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${dozeAtrasStr},${today}))`,
      'Deal_Name,Amount,Closing_Date,Created_Time,Produto_Vendido', 200
    );
    // Enriquece com produtos reais (Quoted_Items) — fallback Produto_Vendido se sem quote
    await enrichDealsWithProducts(won, { limit: 100 });

    // Coins que expiram no próximo mês (vendas de 11-12 meses atrás)
    const expirandoProxMes = won.filter(d => d.Closing_Date >= dozeMesesStr2 && d.Closing_Date < onzeMesesStr);

    let coinsEarned = 0;
    const coinHistory = [];

    for (const d of won) {
      const amt = parseFloat(d.Amount) || 0;
      // Coins base escalonado por ticket
      let coinsBase = 50; // >= R$4.000
      if (amt < 1500) coinsBase = 10;
      else if (amt < 2100) coinsBase = 15;
      else if (amt < 2700) coinsBase = 20;
      else if (amt < 3500) coinsBase = 30;
      else if (amt < 4000) coinsBase = 40;
      coinsEarned += coinsBase;
      coinHistory.push({ coins: coinsBase, reason: `Venda R$${amt.toFixed(0)}: ${d.Deal_Name?.slice(0,25)}`, type: 'venda' });

      const created = new Date(d.Created_Time || '2020-01-01');
      const closed = new Date(d.Closing_Date || today);
      if ((closed - created) < 86400000) {
        coinsEarned += COIN_RULES.deal_flash;
        coinHistory.push({ coins: COIN_RULES.deal_flash, reason: `Flash <24h: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (amt >= 10000) {
        coinsEarned += COIN_RULES.deal_high_ticket;
        coinHistory.push({ coins: COIN_RULES.deal_high_ticket, reason: `High Ticket: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      // Produtos REAIS via Quoted_Items (fallback Produto_Vendido se sem quote)
      const prodSrc = (d.produtosReais || d.Produto_Vendido || '');
      if (/iron free/i.test(prodSrc)) {
        coinsEarned += COIN_RULES.deal_iron_free;
        coinHistory.push({ coins: COIN_RULES.deal_iron_free, reason: `Iron Free: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (amt >= 20000) {
        coinsEarned += COIN_RULES.deal_venda_20k;
        coinHistory.push({ coins: COIN_RULES.deal_venda_20k, reason: `Venda >R$20k: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (/instala[cç][aã]o|R\$\s*590/i.test(prodSrc + ' ' + (d.Deal_Name || ''))) {
        coinsEarned += COIN_RULES.deal_instalacao;
        coinHistory.push({ coins: COIN_RULES.deal_instalacao, reason: `Instalacao: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      // Produto-specific coins (só ticket >= R$4.000 ganha bonus de produto)
      const coinProd = (prodSrc + ' ' + (d.Deal_Name || '')).toLowerCase();
      if (amt < 4000) { /* skip product bonuses for low tickets */ } else {
      if (/af[\s-]?200|200\s*litros/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_beb_af200;
        coinHistory.push({ coins: COIN_RULES.deal_beb_af200, reason: `AF 200: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      } else if (/af[\s-]?100|100\s*litros/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_beb_af100;
        coinHistory.push({ coins: COIN_RULES.deal_beb_af100, reason: `AF 100: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      } else if (/af[\s-]?60|60\s*litros/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_beb_af60;
        coinHistory.push({ coins: COIN_RULES.deal_beb_af60, reason: `AF 60: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      } else if (/af[\s-]?25|25\s*litros/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_beb_af25;
        coinHistory.push({ coins: COIN_RULES.deal_beb_af25, reason: `AF 25: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      } else if (/af[\s-]?15|15\s*litros|bebedouro|refrigerador/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_beb_af15;
        coinHistory.push({ coins: COIN_RULES.deal_beb_af15, reason: `AF 15: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (/inox.*5000|5000.*inox|af.*5000/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_af5000;
        coinHistory.push({ coins: COIN_RULES.deal_af5000, reason: `AF Inox 5000: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      } else if (/inox.*3500|3500.*inox|af.*3500/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_af3500;
        coinHistory.push({ coins: COIN_RULES.deal_af3500, reason: `AF Inox 3500: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      } else if (/inox.*2500|2500.*inox|af.*2500/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_af2500;
        coinHistory.push({ coins: COIN_RULES.deal_af2500, reason: `AF Inox 2500: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (/scale stop/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_scale_stop;
        coinHistory.push({ coins: COIN_RULES.deal_scale_stop, reason: `Scale Stop: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (/v[aá]lvula|valvula/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_valvula;
        coinHistory.push({ coins: COIN_RULES.deal_valvula, reason: `Valvula: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (/condom[ií]nio/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_condominio;
        coinHistory.push({ coins: COIN_RULES.deal_condominio, reason: `Condominio: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      if (/5000|alta vaz/i.test(coinProd)) {
        coinsEarned += COIN_RULES.deal_alta_vazao;
        coinHistory.push({ coins: COIN_RULES.deal_alta_vazao, reason: `Alta Vazao: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      // Bonus agua de poço
      const pipeline = (d.Pipeline || '').toLowerCase();
      if (/po[cç]o|agua.*n[aã]o.*tratada|iron free/i.test(coinProd + ' ' + pipeline)) {
        coinsEarned += COIN_RULES.deal_poco;
        coinHistory.push({ coins: COIN_RULES.deal_poco, reason: `Agua de poco: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      // Combo bonus
      const cTemFiltro = /american filter|fibra|filtrali|light filter|inox/i.test(coinProd);
      const cTemValvula = /v[aá]lvula|valvula/i.test(coinProd);
      const cTemInstalacao = /instala[cç][aã]o|R\$\s*590/i.test(coinProd);
      if (cTemFiltro && cTemValvula && cTemInstalacao) {
        coinsEarned += COIN_RULES.deal_combo;
        coinHistory.push({ coins: COIN_RULES.deal_combo, reason: `COMBO completo: ${d.Deal_Name?.slice(0,25)}`, type: 'bonus' });
      }
      } // end if amt >= 4000
    }

    // Meta bonus
    const fat = won.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    if (fat >= meta.faturamento) {
      coinsEarned += COIN_RULES.meta_batida;
      coinHistory.push({ coins: COIN_RULES.meta_batida, reason: 'Meta mensal batida!', type: 'meta' });
    }

    // Dia limpo bonus (estimate)
    const diasLimpos = Math.max(0, now.getDate() - 2);
    coinsEarned += diasLimpos * COIN_RULES.dia_limpo;

    // Multiplicador de coins por faturamento
    const fatMesCoins = won.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    let coinMultiplier = 0.5;
    let coinMultMsg = '';
    if (fatMesCoins >= 90000) {
      coinMultiplier = 1.0;
      coinMultMsg = `✅ Faturamento R$ ${(fatMesCoins/1000).toFixed(0)}k >= R$ 90k — coins a 100%!`;
    } else if (fatMesCoins >= 75000) {
      coinMultiplier = 0.8;
      coinMultMsg = `⚠️ Faturamento R$ ${(fatMesCoins/1000).toFixed(0)}k — coins a 80%. Falta R$ ${((90000-fatMesCoins)/1000).toFixed(0)}k pra 100%`;
    } else {
      coinMultiplier = 0.5;
      coinMultMsg = `🔴 Faturamento R$ ${(fatMesCoins/1000).toFixed(0)}k < R$ 75k — coins a 50%! Falta R$ ${((75000-fatMesCoins)/1000).toFixed(0)}k pra 80%`;
    }
    coinHistory.unshift({ coins: 0, reason: coinMultMsg, type: coinMultiplier >= 1 ? 'meta' : 'warning' });
    coinsEarned = Math.round(coinsEarned * coinMultiplier);

    // Subtract redemptions
    const redemptions = loadRedemptions();
    const myRedemptions = redemptions.filter(r => r.user === req.session.user.username);
    const totalSpent = myRedemptions.reduce((s, r) => s + r.cost, 0);
    const available = coinsEarned - totalSpent;

    // Expiração rolling: coins de cada venda expiram 12 meses após aquela venda
    // Calcular coins que expiram no próximo mês
    let coinsExpirando = 0;
    for (const d of expirandoProxMes) {
      coinsExpirando += COIN_RULES.deal_ganho;
      const amt = parseFloat(d.Amount) || 0;
      if (amt >= 20000) coinsExpirando += COIN_RULES.deal_venda_20k;
      if (amt >= 10000) coinsExpirando += COIN_RULES.deal_high_ticket;
      if (/iron free/i.test(d.produtosReais || d.Produto_Vendido || '')) coinsExpirando += COIN_RULES.deal_iron_free;
    }

    // Próxima expiração
    const vendasMaisAntigas = won.filter(d => d.Closing_Date).sort((a,b) => (a.Closing_Date||'').localeCompare(b.Closing_Date||''));
    const maisAntiga = vendasMaisAntigas[0];
    let expiracaoLabel = 'sem expiracao';
    let diasParaExpirar = 365;
    if (maisAntiga) {
      const dataExpira = new Date(maisAntiga.Closing_Date);
      dataExpira.setFullYear(dataExpira.getFullYear() + 1);
      diasParaExpirar = Math.max(0, Math.round((dataExpira - now) / 86400000));
      expiracaoLabel = `${String(dataExpira.getDate()).padStart(2,'0')}/${String(dataExpira.getMonth()+1).padStart(2,'0')}/${dataExpira.getFullYear()}`;
    }

    let expiracaoMsg = '';
    if (coinsExpirando > 0) expiracaoMsg = `${coinsExpirando} coins expiram no proximo mes! Resgate antes de perder.`;
    else if (diasParaExpirar <= 60) expiracaoMsg = `Seus coins mais antigos expiram em ${diasParaExpirar} dias.`;
    else expiracaoMsg = 'Coins expiram 12 meses apos serem ganhos. Venda mais e resgate antes!';

    // === Credit Bonzão da Semana e Rei do Mês (200 / 500 coins) ===
    // Cruza com /cockpit/rankings-especiais; se este closer está no topo, soma os coins.
    try {
      const re = await fetch(`http://localhost:${process.env.PORT||3000}/cockpit/rankings-especiais`, {
        headers: { Cookie: req.headers.cookie || '' },
      });
      if (re.ok) {
        const rk = await re.json();
        if (rk?.bonzao?.crmOwner === ownerName) {
          coinsEarned += COIN_RULES.bonzao_semana;
          coinHistory.unshift({ coins: COIN_RULES.bonzao_semana, reason: '👑 Bonzão da Semana', type: 'meta' });
        }
        if (rk?.rei?.crmOwner === ownerName) {
          coinsEarned += COIN_RULES.rei_mes;
          coinHistory.unshift({ coins: COIN_RULES.rei_mes, reason: '👑 Rei do Mês', type: 'meta' });
        }
      }
    } catch(_){} // se falhar, não bloqueia

    const available2 = coinsEarned - totalSpent;

    res.json({
      closer: targetUser.name,
      totalCoins: available2,
      totalEarned: coinsEarned,
      totalSpent,
      expiracaoLabel,
      diasParaExpirar,
      expiracaoMsg,
      coinsExpirando,
      history: coinHistory.slice(0, 20),
      redemptions: myRedemptions.slice(-10).reverse(),
      store: TDF_STORE,
      canRedeem: available >= 700,
    });
  } catch (err) { res.json({ error: err.message }); }
});

// Coins redemption
const REDEMPTIONS_FILE = '/data/tdf_redemptions.json';
function loadRedemptions() {
  try { return JSON.parse(require('fs').readFileSync(REDEMPTIONS_FILE, 'utf8')); } catch { return []; }
}
function saveRedemptions(data) {
  try { require('fs').writeFileSync(REDEMPTIONS_FILE, JSON.stringify(data, null, 2)); } catch(e) { console.error('Save redemptions error:', e.message); }
}

app.post('/cockpit/coins/redeem', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  if (!loggedUser) return res.json({ error: 'not logged in' });

  const { itemId } = req.body;
  const item = TDF_STORE.find(i => i.id === itemId);
  if (!item) return res.json({ error: 'item not found' });

  // Get current coins
  try {
    const coinsRes = await new Promise((resolve) => {
      const mockReq = { session: req.session, query: {} };
      const mockRes = { json: (data) => resolve(data) };
      // Reuse coins endpoint logic inline
      resolve(null);
    });

    // Calculate coins (simplified - same logic as /cockpit/coins)
    const ownerName = loggedUser.crmOwner;
    const now = new Date();
    const today = todayBR();
    const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;

    const won = await zohoSearch(
      `((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:2026-01-01,${today}))`,
      'Deal_Name,Amount,Closing_Date,Created_Time,Produto_Vendido', 200
    );
    // Produtos REAIS via Quoted_Items
    await enrichDealsWithProducts(won, { limit: 100 });

    let totalEarned = 0;
    for (const d of won) {
      totalEarned += COIN_RULES.deal_ganho;
      const amt = parseFloat(d.Amount) || 0;
      const created = new Date(d.Created_Time || '2020-01-01');
      const closed = new Date(d.Closing_Date || today);
      if ((closed - created) < 86400000) totalEarned += COIN_RULES.deal_flash;
      if (amt >= 10000) totalEarned += COIN_RULES.deal_high_ticket;
      const prodSrc = d.produtosReais || d.Produto_Vendido || '';
      if (/iron free/i.test(prodSrc)) totalEarned += COIN_RULES.deal_iron_free;
      if (/instala/i.test(prodSrc + (d.Deal_Name || ''))) totalEarned += COIN_RULES.deal_instalacao;
    }
    totalEarned += Math.max(0, now.getDate() - 2) * COIN_RULES.dia_limpo;

    // Subtract previous redemptions
    const redemptions = loadRedemptions();
    const myRedemptions = redemptions.filter(r => r.user === req.session.user.username);
    const totalSpent = myRedemptions.reduce((s, r) => s + r.cost, 0);
    const available = totalEarned - totalSpent;

    if (available < item.custo) {
      return res.json({ error: `Saldo insuficiente. Voce tem ${available} coins, precisa de ${item.custo}` });
    }

    // Register redemption
    const redemption = {
      id: Date.now().toString(),
      user: req.session.user.username,
      userName: loggedUser.name,
      itemId: item.id,
      itemName: item.nome,
      cost: item.custo,
      status: 'pending',
      createdAt: new Date().toISOString(),
    };
    redemptions.push(redemption);
    saveRedemptions(redemptions);

    // Alert Paulo via Z-API
    await zapiSend(PAULO_PHONE, `🪙 RESGATE DE COINS!\n\n👤 ${loggedUser.name}\n🎁 ${item.nome} (${item.icon})\n💰 ${item.custo} coins\n💳 Saldo restante: ${available - item.custo} coins\n\nAprovar no portal ou responder OK.`);

    res.json({ success: true, item: item.nome, cost: item.custo, remaining: available - item.custo });
  } catch (err) {
    res.json({ error: err.message });
  }
});

