const METAS_PESSOAIS_FILE = '/data/tdf_metas_pessoais.json';
function loadMetasPessoais() { try { return JSON.parse(require('fs').readFileSync(METAS_PESSOAIS_FILE, 'utf8')); } catch { return {}; } }
function saveMetasPessoais(data) { try { require('fs').writeFileSync(METAS_PESSOAIS_FILE, JSON.stringify(data, null, 2)); } catch(e) { console.error('Save metas error:', e.message); } }

app.get('/meta-pessoal', requireAuth, (req, res) => {
  res.render('meta-pessoal', { user: req.session.user, store: JSON.stringify(TDF_STORE) });
});

app.get('/meta-pessoal/data', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  if (!loggedUser?.crmOwner) return res.json({ error: 'user not mapped' });

  try {
    const ownerName = loggedUser.crmOwner;
    const now = new Date();
    const today = todayBR();
    const dozeAtras = new Date(now); dozeAtras.setFullYear(dozeAtras.getFullYear() - 1);

    const won = await zohoSearch(
      `((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${dozeAtras.toISOString().slice(0,10)},${today}))`,
      'Deal_Name,Amount,Closing_Date,Produto_Vendido', 200
    );
    // Produtos REAIS via Quoted_Items
    await enrichDealsWithProducts(won, { limit: 80 });

    // Current coins (simplified)
    let coinsAtual = 0;
    for (const d of won) {
      const amt = parseFloat(d.Amount) || 0;
      if (amt < 1500) coinsAtual += 10;
      else if (amt < 2100) coinsAtual += 15;
      else if (amt < 2700) coinsAtual += 20;
      else if (amt < 3500) coinsAtual += 30;
      else if (amt < 4000) coinsAtual += 40;
      else coinsAtual += 50;
      if (amt >= 20000) coinsAtual += 200;
      if (amt >= 10000) coinsAtual += 100;
      const prodSrc = d.produtosReais || d.Produto_Vendido || '';
      if (/iron free/i.test(prodSrc)) coinsAtual += 250;
      if (/scale stop/i.test(prodSrc)) coinsAtual += 120;
      if (/5000/i.test(prodSrc)) coinsAtual += 150;
      if (/3500/i.test(prodSrc)) coinsAtual += 100;
      if (/2500/i.test(prodSrc)) coinsAtual += 80;
    }
    const diasLimpos = Math.max(0, now.getDate() - 2);
    coinsAtual += diasLimpos * 5;

    // Subtract redemptions
    const redemptions = loadRedemptions();
    const myRedemptions = redemptions.filter(r => r.user === req.session.user.username);
    const totalSpent = myRedemptions.reduce((s, r) => s + r.cost, 0);
    coinsAtual -= totalSpent;

    // Monthly avg coins
    const mesesAtivos = Math.max(1, Math.ceil((now - dozeAtras) / (30 * 86400000)));
    const mediaCoins = Math.round((coinsAtual + totalSpent) / mesesAtivos);

    // Load personal goal
    const metas = loadMetasPessoais();
    const minhaMetaId = metas[req.session.user.username]?.premioId || null;
    const minhaMeta = TDF_STORE.find(i => i.id === minhaMetaId);

    // Calculate progress
    let metaInfo = null;
    if (minhaMeta) {
      const falta = Math.max(0, minhaMeta.custo - coinsAtual);
      const mesesPraAlcancar = mediaCoins > 0 ? Math.ceil(falta / mediaCoins) : 99;
      const pct = Math.round(coinsAtual / minhaMeta.custo * 100);
      const coinsHoje = won.filter(d => d.Closing_Date === today).length * 40; // estimate
      const metaDiaria = Math.round(falta / Math.max(1, 30 * mesesPraAlcancar) * 30);

      // Status
      let status = 'no_caminho';
      if (pct >= 100) status = 'atingiu';
      else if (mediaCoins < metaDiaria * 0.7) status = 'abaixo';
      else if (mediaCoins > metaDiaria * 1.2) status = 'acima';

      metaInfo = {
        premio: minhaMeta,
        falta, pct: Math.min(pct, 100), mesesPraAlcancar, metaDiaria, status,
        coinsHoje,
      };
    }

    res.json({
      closer: loggedUser.name,
      coinsAtual, mediaCoins, totalSpent,
      minhaMeta: metaInfo,
      store: TDF_STORE,
    });
  } catch (err) { res.json({ error: err.message }); }
});

app.post('/meta-pessoal/set', requireAuth, (req, res) => {
  const { premioId } = req.body;
  const item = TDF_STORE.find(i => i.id === premioId);
  if (!item) return res.json({ error: 'premio not found' });
  const metas = loadMetasPessoais();
  metas[req.session.user.username] = { premioId, setAt: new Date().toISOString(), premioNome: item.nome };
  saveMetasPessoais(metas);
  res.json({ success: true, premio: item.nome });
});

// --- Forecast ---
app.get('/cockpit/forecast', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  const isAdmin = loggedUser?.role === 'admin';
  let targetUser = loggedUser;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) targetUser = USERS[req.query.closer];
  if (!targetUser?.crmOwner) return res.json({ error: 'user not mapped' });

  try {
    const ownerName = targetUser.crmOwner;
    const now = new Date();
    const today = todayBR();
    const thisMonthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
    const meta = METAS_ABRIL[ownerName] || { faturamento: 90000 };
    const diaAtual = now.getDate();
    const diasNoMes = new Date(now.getFullYear(), now.getMonth()+1, 0).getDate();
    const diasRestantes = diasNoMes - diaAtual;
    const diasUteis = Math.max(1, Math.round(diasRestantes * 5/7));

    // Last 3 months for trend
    const months = [];
    for (let i = 0; i < 3; i++) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const start = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;
      const endDay = i === 0 ? today : `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${new Date(d.getFullYear(), d.getMonth()+1, 0).getDate()}`;
      months.push({ start, end: endDay, label: `${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}` });
    }

    const filterOwner = !(isAdmin && !req.query.closer);
    const results = await Promise.all(months.map(m => {
      const criteria = filterOwner
        ? `((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${m.start},${m.end}))`
        : `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${m.start},${m.end}))`;
      return zohoSearch(criteria, 'Amount,Closing_Date', 200);
    }));

    const monthData = months.map((m, i) => {
      const deals = results[i] || [];
      const fat = deals.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
      return { ...m, fat, vendas: deals.length };
    });

    // Current month
    const fatAtual = monthData[0].fat;
    const mediaDia = diaAtual > 0 ? fatAtual / diaAtual : 0;
    const projecao = Math.round(fatAtual + mediaDia * diasRestantes);
    const pctMeta = Math.round(fatAtual / meta.faturamento * 100);

    // Trend (avg last 2 months at same day)
    const fatMesPassado = monthData[1]?.fat || 0;
    const fatRetrasado = monthData[2]?.fat || 0;
    const mediaMesesAnt = (fatMesPassado + fatRetrasado) / 2;

    // Propostas abertas (pipeline value)
    const propostas = await zohoSearch(
      filterOwner
        ? `((Owner:equals:${ownerName})and(Stage:in:Proposta Quente,Proposta Fria,Proposta))`
        : '(Stage:in:Proposta Quente,Proposta Fria,Proposta)',
      'Amount', 200
    );
    const valorPropostas = propostas.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);

    // Risk assessment
    let risco = 'baixo';
    if (projecao < meta.faturamento * 0.7) risco = 'alto';
    else if (projecao < meta.faturamento) risco = 'medio';

    // What's needed
    const gap = Math.max(0, meta.faturamento - fatAtual);
    const necessarioDia = diasUteis > 0 ? Math.round(gap / diasUteis) : gap;

    res.json({
      closer: targetUser.name,
      mesAtual: { label: monthData[0].label, fat: fatAtual, vendas: monthData[0].vendas, pctMeta },
      projecao, risco, gap, necessarioDia, diasRestantes, diasUteis,
      mediaDia: Math.round(mediaDia),
      meta: meta.faturamento,
      meses: monthData,
      propostas: { total: propostas.length, valor: valorPropostas },
      trend: {
        mesPassado: fatMesPassado,
        retrasado: fatRetrasado,
        media: Math.round(mediaMesesAnt),
        diffVsMedia: mediaMesesAnt > 0 ? Math.round((fatAtual - mediaMesesAnt) / mediaMesesAnt * 100) : 0,
      },
    });
  } catch (err) { res.json({ error: err.message }); }
});

// --- Closy Scores Integration ---
const CLOSY_URL = process.env.CLOSY_URL || 'https://closy-app-production.up.railway.app';
const CLOSY_API_KEY = process.env.CLOSY_API_KEY || 'tdf-portal-closy-2026';

app.get('/cockpit/closy', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  const isAdmin = loggedUser?.role === 'admin';
  let targetUser = loggedUser;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) targetUser = USERS[req.query.closer];

  try {
    const cacheKey = `closy:${targetUser.name}`;
    let data = cacheGet(cacheKey);
    if (!data) {
      const url = `${CLOSY_URL}/api/public/scores?key=${CLOSY_API_KEY}&days=30`;
      const r = await fetch(url, { headers: { 'x-api-key': CLOSY_API_KEY } });
      if (!r.ok) return res.json({ error: `Closy ${r.status}`, sellers: [] });
      data = await r.json();
      cacheSet(cacheKey, data, 600000); // 10min cache
    }

    // Filter for specific closer if not admin viewing all
    const closerName = targetUser.name;
    const mySeller = data.sellers?.find(s => s.name?.toLowerCase().includes(closerName.toLowerCase()));

    res.json({
      closer: closerName,
      mySeller: mySeller || null,
      allSellers: isAdmin && !req.query.closer ? data.sellers : [],
      totalCalls: data.totalCalls || 0,
    });
  } catch (err) {
    res.json({ error: err.message, sellers: [] });
  }
});

// --- Alertas Automáticos Cliq ---
const CLIQ_ZAPIKEY = process.env.CLIQ_ZAPIKEY || '';

async function cliqAlert(channel, message) {
  if (!CLIQ_ZAPIKEY) return;
  try {
    await fetch(`https://cliq.zoho.com/api/v2/channelsbyname/${channel}/message?zapikey=${CLIQ_ZAPIKEY}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: message }),
    });
  } catch(e) { console.error('Cliq alert error:', e.message); }
}

// Auto-alerts endpoint (can be called by cron or manually)
app.get('/gestao/auto-alerts', requireAuth, async (req, res) => {
  const isAdmin = USERS[req.session.user.username]?.role === 'admin';
  if (!isAdmin) return res.status(403).json({ error: 'admin only' });

  try {
    const now = new Date();
    const today = todayBR();
    const nowMs = Date.now();
    const alerts = [];

    const active = await zohoSearch(
      '(Stage:in:Primeiro Contato,Em Qualificação,Etapa IA,Analise ou vazão,Qualificado,Proposta Quente,Proposta Fria,Em Atendimento,Proposta)',
      'Deal_Name,Stage,Tier_Lead,Amount,Owner,Last_Activity_Time,Created_Time,Lead_Source,Telefone_contato', 200
    );

    // 1. Leads Google sem contato >5min
    const googleSemContato = active.filter(d => {
      if (!/google/i.test(d.Lead_Source)) return false;
      if (!/Primeiro Contato|Etapa IA/i.test(d.Stage)) return false;
      const created = new Date(d.Created_Time || '2020-01-01');
      if ((nowMs - created.getTime()) > 72 * 3600000) return false; // ignore old
      const lastAct = new Date(d.Last_Activity_Time || d.Created_Time || '2020-01-01');
      return Math.abs(lastAct - created) < 300000; // never touched
    });
    if (googleSemContato.length > 0) {
      const msg = `🔴 ${googleSemContato.length} LEAD(S) GOOGLE SEM CONTATO!\n${googleSemContato.slice(0,5).map(d => `• ${d.Deal_Name} → ${d.Owner?.name || '?'}`).join('\n')}`;
      alerts.push({ tipo: 'critico', msg });
      await zapiSend(PAULO_PHONE, msg);
      if (CLIQ_ZAPIKEY) await cliqAlert('alertassdr', msg);
    }

    // 2. Propostas >R$5k sem follow-up 24h
    const propAltas = active.filter(d => {
      if (!/Proposta/i.test(d.Stage)) return false;
      if ((parseFloat(d.Amount) || 0) < 5000) return false;
      return (nowMs - new Date(d.Last_Activity_Time || '2020-01-01').getTime()) > 24 * 3600000;
    });
    if (propAltas.length > 0) {
      const valor = propAltas.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
      const msg = `⚠️ ${propAltas.length} PROPOSTA(S) >R$5k SEM FOLLOW-UP 24H!\nValor parado: R$ ${(valor/1000).toFixed(0)}k\n${propAltas.slice(0,5).map(d => `• ${d.Deal_Name} R$${d.Amount} → ${d.Owner?.name || '?'}`).join('\n')}`;
      alerts.push({ tipo: 'alto', msg });
      await zapiSend(PAULO_PHONE, msg);
    }

    // 3. Diamantes parados >4h
    const diamParados = active.filter(d => {
      return d.Tier_Lead === 'Diamante' && (nowMs - new Date(d.Last_Activity_Time || d.Created_Time || '2020-01-01').getTime()) > 4 * 3600000;
    });
    if (diamParados.length >= 3) {
      const msg = `💎 ${diamParados.length} DIAMANTES PARADOS >4H!\n${diamParados.slice(0,5).map(d => `• ${d.Deal_Name} (sc:${d.Score_Lead || '?'}) → ${d.Owner?.name || '?'}`).join('\n')}`;
      alerts.push({ tipo: 'alto', msg });
      await zapiSend(PAULO_PHONE, msg);
    }

    // 4. Closers >2h sem atividade (horário comercial)
    if (now.getHours() >= 8 && now.getHours() <= 18) {
      const closerActivity = {};
      for (const d of active) {
        const o = d.Owner?.name || '?';
        const h = (nowMs - new Date(d.Last_Activity_Time || '2020-01-01').getTime()) / 3600000;
        if (!closerActivity[o] || h < closerActivity[o]) closerActivity[o] = h;
      }
      const inativos = Object.entries(closerActivity).filter(([_, h]) => h > 2).map(([name, h]) => `• ${name}: ${Math.round(h)}h sem atividade`);
      if (inativos.length >= 2) {
        const msg = `😴 ${inativos.length} CLOSER(S) SEM ATIVIDADE >2H!\n${inativos.slice(0,5).join('\n')}`;
        alerts.push({ tipo: 'medio', msg });
        await zapiSend(PAULO_PHONE, msg);
      }
    }

    // 5. Alert closers individually via Z-API
    for (const d of googleSemContato.slice(0, 5)) {
      const phone = CLOSER_PHONES[d.Owner?.name];
      if (phone) {
        const firstName = (d.Owner?.name || '').split(' ')[0];
        await zapiSend(phone, `${firstName}, lead Google "${d.Deal_Name}" sem contato! Lead Google esfria em minutos. Ligar AGORA.`);
        await new Promise(r => setTimeout(r, 2000));
      }
    }

    res.json({ alerts, total: alerts.length, timestamp: now.toISOString() });
  } catch (err) { res.json({ error: err.message }); }
});

// --- Checklist por Etapa do Funil ---
const CHECKLIST_FUNIL = {
  'Primeiro Contato': [
    { id: 'pc_contato', label: 'Contato realizado (ligacao/WhatsApp)', field: 'Last_Activity_Time', check: (d,nowMs) => d.Last_Activity_Time && d.Last_Activity_Time !== d.Created_Time },
    { id: 'pc_cidade', label: 'Cidade preenchida', field: 'Cidade', check: d => !!d.Cidade },
    { id: 'pc_agua', label: 'Tipo de agua identificado', field: 'Tipo_de_Agua', check: d => !!d.Tipo_de_Agua },
    { id: 'pc_prazo', label: 'Prazo de compra', field: 'Prazo_para_a_Compra', check: d => !!d.Prazo_para_a_Compra },
  ],
  'Em Qualificação': [
    { id: 'eq_contato', label: 'Contato realizado', check: (d) => d.Last_Activity_Time && d.Last_Activity_Time !== d.Created_Time },
    { id: 'eq_cidade', label: 'Cidade preenchida', check: d => !!d.Cidade },
    { id: 'eq_agua', label: 'Tipo de agua', check: d => !!d.Tipo_de_Agua },
    { id: 'eq_prazo', label: 'Prazo de compra', check: d => !!d.Prazo_para_a_Compra },
    { id: 'eq_produto', label: 'Produto de interesse', check: d => !!d.Produto_Vendido },
    { id: 'eq_tier', label: 'Tier/Score atribuido', check: d => !!d.Tier_Lead && d.Tier_Lead !== '-' },
  ],
  'Proposta': [
    { id: 'pr_valor', label: 'Valor preenchido', check: d => parseFloat(d.Amount) > 0 },
    { id: 'pr_data', label: 'Data fechamento prevista', check: d => !!d.Closing_Date },
    { id: 'pr_followup', label: 'Follow-up recente (<24h)', check: (d,nowMs) => d.Last_Activity_Time && (nowMs - new Date(d.Last_Activity_Time).getTime()) < 24*3600000 },
  ],
  'Qualificado': [
    { id: 'qu_contato', label: 'Contato recente (<48h)', check: (d,nowMs) => d.Last_Activity_Time && (nowMs - new Date(d.Last_Activity_Time).getTime()) < 48*3600000 },
    { id: 'qu_tier', label: 'Tier atribuido', check: d => !!d.Tier_Lead && d.Tier_Lead !== '-' },
    { id: 'qu_prazo', label: 'Prazo definido', check: d => !!d.Prazo_para_a_Compra },
  ],
};

app.get('/cockpit/checklist-funil', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  const isAdmin = loggedUser?.role === 'admin';
  let targetUser = loggedUser;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) targetUser = USERS[req.query.closer];
  if (!targetUser?.crmOwner) return res.json({ error: 'user not mapped' });

  try {
    const ownerName = targetUser.crmOwner;
    const nowMs = Date.now();

    const active = await zohoSearch(
      `((Owner:equals:${ownerName})and(Stage:in:Primeiro Contato,Em Qualificação,Etapa IA,Analise ou vazão,Qualificado,Proposta Quente,Proposta Fria,Em Atendimento,Proposta))`,
      'Deal_Name,Stage,Pipeline,Tier_Lead,Score_Lead,Amount,Telefone_contato,Last_Activity_Time,Created_Time,Cidade,Tipo_de_Agua,Prazo_para_a_Compra,Produto_Vendido,Closing_Date',
      200
    );

    // Map stages to checklist stages
    const stageMap = {
      'Primeiro Contato': 'Primeiro Contato',
      'Etapa IA': 'Primeiro Contato',
      'Em Qualificação': 'Em Qualificação',
      'Analise ou vazão': 'Em Qualificação',
      'Qualificado': 'Qualificado',
      'Proposta Quente': 'Proposta',
      'Proposta Fria': 'Proposta',
      'Proposta': 'Proposta',
      'Em Atendimento': 'Qualificado',
    };

    // Analyze each deal
    const dealChecklists = active.map(d => {
      const stage = stageMap[d.Stage] || 'Primeiro Contato';
      const checks = CHECKLIST_FUNIL[stage] || [];
      const items = checks.map(c => ({
        id: c.id,
        label: c.label,
        done: c.check(d, nowMs),
      }));
      const total = items.length;
      const done = items.filter(i => i.done).length;
      const pct = total > 0 ? Math.round(done / total * 100) : 0;
      const completo = done === total;

      return {
        id: d.id,
        name: d.Deal_Name || '?',
        stage: d.Stage,
        checklistStage: stage,
        tier: d.Tier_Lead || '-',
        score: d.Score_Lead || 0,
        phone: d.Telefone_contato || '',
        items, total, done, pct, completo,
        crmLink: d.id ? `https://crmplus.zoho.com/tudodefiltro3711/index.do/cxapp/crm/org856385701/tab/Potentials/${d.id}` : '',
      };
    });

    // Summary by stage
    const stageSummary = {};
    for (const d of dealChecklists) {
      const s = d.checklistStage;
      if (!stageSummary[s]) stageSummary[s] = { total: 0, completos: 0, incompletos: 0, deals: [] };
      stageSummary[s].total++;
      if (d.completo) stageSummary[s].completos++;
      else { stageSummary[s].incompletos++; stageSummary[s].deals.push(d); }
    }

    // Score impact
    const pontosGanhos = dealChecklists.filter(d => d.completo).length * 10;
    const pontosPerdidos = dealChecklists.filter(d => !d.completo && d.pct < 50).length * 10;

    // Top incompletos (deals mais urgentes)
    const urgentes = dealChecklists
      .filter(d => !d.completo)
      .sort((a, b) => a.pct - b.pct)
      .slice(0, 15);

    res.json({
      closer: targetUser.name,
      stageSummary,
      urgentes,
      stats: {
        totalDeals: dealChecklists.length,
        completos: dealChecklists.filter(d => d.completo).length,
        incompletos: dealChecklists.filter(d => !d.completo).length,
        pctCompleto: dealChecklists.length > 0 ? Math.round(dealChecklists.filter(d => d.completo).length / dealChecklists.length * 100) : 0,
        pontosGanhos, pontosPerdidos,
      },
    });
  } catch (err) { res.json({ error: err.message }); }
});

