app.get('/loja/data', requireAuth, async (req, res) => {
  try {
    const now = new Date();
    const today = todayBR();
    const yesterday = new Date(now - 86400000).toISOString().slice(0, 10);
    const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;

    const [lojaMonth, lojaToday, lojaYesterday, insideMonth] = await Promise.all([
      zohoSearch(`((Layout:equals:6311862000101582231)and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Amount,Owner,Closing_Date,Produto_Vendido', 200),
      zohoSearch(`((Layout:equals:6311862000101582231)and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${today},${today}))`,
        'Deal_Name,Amount,Owner,Produto_Vendido', 200),
      zohoSearch(`((Layout:equals:6311862000101582231)and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${yesterday},${yesterday}))`,
        'Deal_Name,Amount,Owner', 200),
      zohoSearch(`((Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Amount,Owner,Layout', 200),
    ]);

    const fatHoje = lojaToday.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    const fatOntem = lojaYesterday.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    const fatMes = lojaMonth.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    const vendasHoje = lojaToday.length;
    const vendasMes = lojaMonth.length;
    const ticketMedio = vendasMes > 0 ? Math.round(fatMes / vendasMes) : 0;

    // Comparação hoje vs ontem
    const diffOntem = fatOntem > 0 ? Math.round((fatHoje - fatOntem) / fatOntem * 100) : (fatHoje > 0 ? 100 : 0);

    // Por produto
    const porProduto = {};
    for (const d of lojaMonth) {
      const prod = d.Produto_Vendido || 'Sem produto';
      if (!porProduto[prod]) porProduto[prod] = { vendas: 0, fat: 0 };
      porProduto[prod].vendas++;
      porProduto[prod].fat += parseFloat(d.Amount) || 0;
    }

    // Ranking vendedores loja
    const porVendedor = {};
    for (const d of lojaMonth) {
      const o = d.Owner?.name || '?';
      if (!porVendedor[o]) porVendedor[o] = { vendas: 0, fat: 0 };
      porVendedor[o].vendas++;
      porVendedor[o].fat += parseFloat(d.Amount) || 0;
    }
    const rankingVendedor = Object.entries(porVendedor).sort((a, b) => b[1].fat - a[1].fat);

    // Inside Sales comparativo (excluir loja)
    const insideOnly = insideMonth.filter(d => {
      const layoutId = d.Layout?.id || d.Layout;
      return layoutId !== '6311862000101582231' && layoutId !== 6311862000101582231;
    });
    const fatInside = insideOnly.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);

    // Alertas
    const alertas = [];
    if (fatHoje === 0 && now.getHours() >= 10) alertas.push({ tipo: 'warning', msg: 'Nenhuma venda na loja hoje' });
    if (diffOntem < -30) alertas.push({ tipo: 'danger', msg: `Queda de ${Math.abs(diffOntem)}% vs ontem` });
    const vendedoresSemVenda = Object.entries(porVendedor).length === 0 ? ['Nenhum vendedor'] : [];

    res.json({
      hoje: { fat: fatHoje, vendas: vendasHoje, deals: lojaToday },
      ontem: { fat: fatOntem, vendas: lojaYesterday.length },
      mes: { fat: fatMes, vendas: vendasMes, ticketMedio },
      diffOntem,
      porProduto: Object.entries(porProduto).sort((a, b) => b[1].fat - a[1].fat),
      rankingVendedor,
      comparativo: { loja: fatMes, inside: fatInside, pctLoja: fatMes + fatInside > 0 ? Math.round(fatMes / (fatMes + fatInside) * 100) : 0 },
      alertas,
    });
  } catch (err) { res.json({ error: err.message }); }
});

