async function getGotoToken() {
  if (_gotoToken && Date.now() < _gotoTokenExp) return _gotoToken;
  // Tenta OAuth refresh primeiro
  if (GOTO_CID && GOTO_CSECRET && _gotoRefresh) {
    try {
      const res = await fetch('https://authentication.logmeininc.com/oauth/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded', Authorization: 'Basic ' + Buffer.from(GOTO_CID + ':' + GOTO_CSECRET).toString('base64') },
        body: `grant_type=refresh_token&refresh_token=${_gotoRefresh}`,
      });
      const data = await res.json();
      if (data.access_token) {
        _gotoToken = data.access_token;
        _gotoTokenExp = Date.now() + (data.expires_in || 3600) * 1000;
        if (data.refresh_token) _gotoRefresh = data.refresh_token;
        console.log('[goto] OAuth refresh OK');
        return _gotoToken;
      } else {
        console.warn('[goto] OAuth refresh falhou:', data.error || JSON.stringify(data).slice(0, 200));
      }
    } catch (e) { console.error('[goto] OAuth refresh erro:', e.message); }
  }
  // Fallback: App Token (Personal Access Token) — se setado, usa direto sem refresh
  if (GOTO_APP_TOKEN) {
    _gotoToken = GOTO_APP_TOKEN;
    _gotoTokenExp = Date.now() + 60*60*1000; // App Tokens duram bem mais; só re-checa em 1h
    console.log('[goto] usando GOTO_APP_TOKEN (Personal Access Token)');
    return _gotoToken;
  }
  return '';
}

