app.get('/admin/goto-oauth/callback', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).send('admin only');
  const { code } = req.query;
  if (!code) return res.status(400).send('code não recebido. Usa <a href="/admin/goto-oauth/start">iniciar OAuth</a>');
  if (!GOTO_CID || !GOTO_CSECRET) return res.send('GOTO_CLIENT_ID/SECRET não configurados');
  try {
    const r = await fetch('https://authentication.logmeininc.com/oauth/token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Authorization: 'Basic ' + Buffer.from(GOTO_CID + ':' + GOTO_CSECRET).toString('base64'),
      },
      body: `grant_type=authorization_code&code=${code}&redirect_uri=${encodeURIComponent(GOTO_REDIRECT)}`,
    });
    const j = await r.json();
    if (!j.refresh_token) return res.send(`<pre>Falhou:\n${JSON.stringify(j, null, 2)}</pre>`);
    _gotoRefresh = j.refresh_token;
    _gotoToken = j.access_token;
    _gotoTokenExp = Date.now() + (j.expires_in || 3600) * 1000;
    // Salva no kv pra persistir entre deploys (sobrescreve env var pelo runtime)
    await kvSet('goto_refresh_token', j.refresh_token).catch(() => {});
    res.send(`
      <html><body style="font-family:sans-serif;padding:30px;background:#0d1117;color:#fff">
      <h1 style="color:#22c55e">✅ GoTo re-autorizado com sucesso!</h1>
      <p>Refresh token salvo. As ligações já vão começar a aparecer no dossiê.</p>
      <pre style="background:#0a0a0a;padding:14px;border-radius:8px;color:#fbbf24;font-size:11px;border:1px solid #333">⚠️ IMPORTANTE: copia este refresh_token e seta no Railway env GOTO_REFRESH_TOKEN pra sobreviver deploys:\n\n${j.refresh_token}</pre>
      <p><a href="/admin/goto-debug" style="color:#7cb9f5">→ Verificar /admin/goto-debug</a></p>
      </body></html>
    `);
  } catch(e) { res.send('Erro: ' + e.message); }
});
