// === LOGS DE ACESSO — quem loga, o que vê, quando ===
// Storage circular (últimos 5000 eventos)
let _ACCESS_LOG = [];
const ACCESS_LOG_MAX = 5000;
function _accessLogAdd(ev) {
  _ACCESS_LOG.push({ ...ev, ts: Date.now() });
  while (_ACCESS_LOG.length > ACCESS_LOG_MAX) _ACCESS_LOG.shift();
  // Persiste a cada 50 eventos novos
  if (_ACCESS_LOG.length % 50 === 0) {
    kvSet('access-logs', _ACCESS_LOG.slice(-2000)).catch(() => {});
  }
}
// Carrega do kv ao boot
setTimeout(async () => {
  try {
    const saved = _kvCache['access-logs'];
    if (Array.isArray(saved) && saved.length) {
      _ACCESS_LOG = saved.slice(-ACCESS_LOG_MAX);
      console.log(`[access-log] ${_ACCESS_LOG.length} eventos restaurados`);
    }
  } catch(_){}
}, 9500);

// Middleware de log: registra páginas visitadas (não API JSON)
app.use((req, res, next) => {
  // Loga APENAS GETs em rotas HTML que não sejam estáticas
  if (req.method === 'GET' && req.session?.user?.username) {
    const p = req.path;
    // Pula assets, healthchecks, polling APIs
    const skip = /^(\/uploads|\/sfx|\/style\.css|\/cliente-drawer|\/_health|\/diag|\/favicon|\/logo|\/socket\.io|\/inbox\/(conversas|mensagens|kanban-etapas)|\/cockpit\/(meta-bar|raiox-dia|director-live|conversao-stages|score|score-detalhado|score-semana|nubia|patente|destaques|forecast|calls|anual|meus-deals)|\/manutencao\/(data|wati-inbox|cliente-info|operadoras)|\/tarefas\/minhas|\/closy\/|\/perfil\b)/.test(p);
    if (!skip && !p.startsWith('/api/') && !p.match(/\.(js|css|png|jpg|jpeg|svg|ico|webp|mp3|mp4)$/i)) {
      _accessLogAdd({
        type: 'pageview',
        username: req.session.user.username,
        name: req.session.user.name,
        role: req.session.user.role,
        path: p,
        query: Object.keys(req.query||{}).length ? Object.fromEntries(Object.entries(req.query).slice(0,5)) : null,
        ip: (req.headers['x-forwarded-for']||req.ip||'').split(',')[0].trim(),
      });
    }
  }
  next();
});

