app.get('/admin/acessos/data', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const dias = Math.max(1, Math.min(30, parseInt(req.query.dias, 10) || 7));
  const cutoff = Date.now() - dias * 86400000;
  const eventos = _ACCESS_LOG.filter(e => e.ts >= cutoff);

  // Por usuário: último login, total pageviews, paths visitados, treinamentos vistos
  const porUser = {};
  for (const ev of eventos) {
    if (!porUser[ev.username]) {
      porUser[ev.username] = {
        username: ev.username, name: ev.name, role: ev.role,
        primeiro_acesso: ev.ts, ultimo_acesso: ev.ts,
        total_pageviews: 0, total_logins: 0,
        paths: {}, treinamentos: new Set(), dias_ativos: new Set(),
      };
    }
    const u = porUser[ev.username];
    u.ultimo_acesso = Math.max(u.ultimo_acesso, ev.ts);
    u.primeiro_acesso = Math.min(u.primeiro_acesso, ev.ts);
    u.dias_ativos.add(new Date(ev.ts).toISOString().slice(0,10));
    if (ev.type === 'login') u.total_logins++;
    else if (ev.type === 'pageview') {
      u.total_pageviews++;
      u.paths[ev.path] = (u.paths[ev.path]||0) + 1;
      // Treinamentos: rotas que comecem com /treinamento
      if (/^\/treinamento(\/|$)/.test(ev.path)) {
        const mod = ev.path.replace(/^\/treinamento\/?/, '') || 'index';
        u.treinamentos.add(mod);
      }
    }
  }

  // Lista todos closers, marca quem NÃO acessou
  const todosClosers = Object.entries(USERS)
    .filter(([_, c]) => c.role === 'closer' || c.role === 'posvenda')
    .map(([username, c]) => ({ username, name: c.name, team: c.team, crmOwner: c.crmOwner }));
  const naoAcessaram = todosClosers.filter(c => !porUser[c.username]);

  // Top paths
  const pathsCount = {};
  for (const ev of eventos) {
    if (ev.type !== 'pageview') continue;
    pathsCount[ev.path] = (pathsCount[ev.path]||0) + 1;
  }
  const topPaths = Object.entries(pathsCount).sort((a,b) => b[1]-a[1]).slice(0, 20).map(([p, c]) => ({ path: p, count: c }));

  res.json({
    janela_dias: dias,
    total_eventos: eventos.length,
    total_users_unicos: Object.keys(porUser).length,
    total_closers: todosClosers.length,
    nao_acessaram: naoAcessaram,
    por_usuario: Object.values(porUser).map(u => ({
      username: u.username, name: u.name, role: u.role,
      primeiro_acesso: u.primeiro_acesso, ultimo_acesso: u.ultimo_acesso,
      total_pageviews: u.total_pageviews, total_logins: u.total_logins,
      dias_ativos: u.dias_ativos.size,
      treinamentos_vistos: Array.from(u.treinamentos),
      top_paths: Object.entries(u.paths).sort((a,b) => b[1]-a[1]).slice(0,5).map(([p,n]) => ({ path: p, count: n })),
    })).sort((a,b) => b.ultimo_acesso - a.ultimo_acesso),
    top_paths: topPaths,
  });
});

