function _maskValue(v) {
  if (!v) return '';
  const s = String(v);
  if (s.length < 6) return '••••';
  return '••••' + s.slice(-4);
}

// GET conectores config (mascarado)
app.get('/admin/conectores/config', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const local = loadConectoresConfig();
  const result = {};
  for (const def of CONECTORES_DEFS) {
    const cfg = {};
    for (const f of def.campos) {
      const valLocal = local[def.id]?.[f.key];
      const valEnv = process.env[f.key];
      cfg[f.key] = {
        valor: valLocal ? _maskValue(valLocal) : (valEnv ? _maskValue(valEnv)+' (env)' : ''),
        tem: !!(valLocal || valEnv),
        fonte: valLocal ? 'kv' : (valEnv ? 'env' : null),
      };
    }
    const status = (() => {
      try { return def.statusCheck(local[def.id] || {}); }
      catch(_) { return false; }
    })();
    result[def.id] = {
      nome: def.nome, icone: def.icone, cor: def.cor, descricao: def.descricao,
      campos: def.campos,
      cfg, status,
      extra_link: def.extra_link || null,
      actions: def.actions || [],
    };
  }
  res.json({ conectores: result });
});

// POST atualiza
app.post('/admin/conectores/config', requireAuth, (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin') return res.status(403).json({ error: 'admin only' });
  const { conector, campos } = req.body || {};
  const def = CONECTORES_DEFS.find(d => d.id === conector);
  if (!def) return res.status(400).json({ error: 'conector inválido' });
  const local = loadConectoresConfig();
  if (!local[conector]) local[conector] = {};
  for (const [k, v] of Object.entries(campos || {})) {
    if (typeof v !== 'string') continue;
    const trim = v.trim();
    // Não sobrescreve com valor mascarado (••••)
    if (trim && !trim.includes('•')) local[conector][k] = trim;
    else if (!trim) delete local[conector][k]; // limpa explicito
  }
  saveConectoresConfig(local);
  // Aplica no runtime (process.env)
  for (const f of def.campos) {
    const v = local[conector][f.key];
    if (v) process.env[f.key] = v;
  }
  res.json({ ok: true });
});

// POST testa um conector
app.post('/admin/conectores/test/:id', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const id = req.params.id;
  try {
    if (id === 'zoho') {
      const tk = await getZohoToken();
      return res.json({ ok: !!tk, msg: tk ? 'Token OK' : 'Falhou — verifique credentials' });
    }
    if (id === 'wati' && WATI_TOKEN) {
      const r = await fetch(`${WATI_BASE}/api/v1/getContacts?pageSize=1&pageNumber=0`, { headers: { Authorization: `Bearer ${WATI_TOKEN}` } });
      return res.json({ ok: r.ok, status: r.status, msg: r.ok ? 'Token WATI OK' : 'WATI rejeitou — token expirado?' });
    }
    if (id === 'zapi' && ZAPI_INSTANCE && ZAPI_TOKEN) {
      const r = await fetch(`https://api.z-api.io/instances/${ZAPI_INSTANCE}/token/${ZAPI_TOKEN}/status`, { headers: ZAPI_CLIENT_TOKEN ? { 'Client-Token': ZAPI_CLIENT_TOKEN } : {} });
      const j = await r.json().catch(() => ({}));
      return res.json({ ok: r.ok, status: r.status, msg: j.connected ? 'Z-API conectado' : 'Z-API desconectado/inválido' });
    }
    if (id === 'goto') {
      const tk = await getGotoToken();
      return res.json({ ok: !!tk, msg: tk ? 'Token GoTo OK' : 'Falhou — use /admin/goto pra reconectar' });
    }
    if (id === 'google_ads') {
      const tk = await googleAds.getToken();
      return res.json({ ok: !!tk, msg: tk ? 'Token Google Ads OK' : 'Falhou' });
    }
    if (id === 'meta_ads') {
      const camps = await metaAds.getCampaigns('today').catch(e => ({ error: e.message }));
      return res.json({ ok: !camps.error, msg: camps.error || `${(camps||[]).length} campanhas retornadas` });
    }
    if (id === 'anthropic' && process.env.ANTHROPIC_API_KEY) {
      const Anthropic = require('@anthropic-ai/sdk').default || require('@anthropic-ai/sdk');
      const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
      const r = await client.messages.create({ model: 'claude-sonnet-4-5-20250929', max_tokens: 20, messages: [{ role:'user', content:'ping' }] });
      return res.json({ ok: true, msg: 'Claude OK · ' + (r.usage?.input_tokens||0) + ' tokens in / ' + (r.usage?.output_tokens||0) + ' out' });
    }
    if (id === 'openai' && process.env.OPENAI_API_KEY) {
      const r = await fetch('https://api.openai.com/v1/models', { headers: { Authorization: 'Bearer '+process.env.OPENAI_API_KEY } });
      return res.json({ ok: r.ok, msg: r.ok ? 'OpenAI API key válida' : 'Inválida (HTTP '+r.status+')' });
    }
    if (id === 'gemini' && process.env.GEMINI_API_KEY) {
      const r = await fetch('https://generativelanguage.googleapis.com/v1beta/models?key='+encodeURIComponent(process.env.GEMINI_API_KEY));
      return res.json({ ok: r.ok, msg: r.ok ? 'Gemini API key válida' : 'Inválida (HTTP '+r.status+')' });
    }
    if (id === 'grok' && process.env.GROK_API_KEY) {
      const r = await fetch('https://api.x.ai/v1/models', { headers: { Authorization: 'Bearer '+process.env.GROK_API_KEY } });
      return res.json({ ok: r.ok, msg: r.ok ? 'Grok API key válida' : 'Inválida (HTTP '+r.status+')' });
    }
    if (id === 'smtp' && process.env.SMTP_PASS) {
      const t = _getSmtpTransporter();
      if (!t) return res.json({ ok: false, msg: 'Nodemailer não inicializou' });
      try { await t.verify(); return res.json({ ok: true, msg: 'SMTP autenticou' }); }
      catch(e) { return res.json({ ok: false, msg: e.message }); }
    }
    if (id === 'auvo' && process.env.AUVO_API_KEY) {
      try { await getAuvoToken(); return res.json({ ok: true, msg: 'Auvo OK' }); }
      catch(e) { return res.json({ ok: false, msg: e.message }); }
    }
    return res.json({ ok: false, msg: 'Conector não configurado ou teste não implementado' });
  } catch(e) {
    res.json({ ok: false, msg: e.message });
  }
});

