// Diagnóstico GoTo (admin only)
app.get('/admin/goto-debug', requireAuth, async (req, res) => {
  const u = USERS[req.session.user.username];
  if (u?.role !== 'admin' && !isGestor(u)) return res.status(403).json({ error: 'admin/gestor only' });
  const date = req.query.date && /^\d{4}-\d{2}-\d{2}$/.test(req.query.date) ? req.query.date : todayBR();
  const debug = {
    date,
    has_creds: !!(GOTO_CID && GOTO_CSECRET && _gotoRefresh),
    has_account_key: !!GOTO_ACCT,
    token_status: 'unknown',
    http_status: null,
    total_calls: 0,
    calls_associadas: 0,
    calls_sem_vendedor: 0,
    sample_orphan_calls: [],
    stats: {},
    vendedores_mapeados: GOTO_VENDEDORES.map(v => ({ nome: v.nome, crmOwner: v.crmOwner, ramal: v.ramal, hasUserKey: !!v.userKey })),
  };
  try {
    const token = await getGotoToken();
    debug.token_status = token ? 'OK' : 'FAILED (sem refresh válido?)';
    if (!token) return res.json(debug);
    const url = `https://api.goto.com/call-events-report/v1/report-summaries?accountKey=${GOTO_ACCT}&startTime=${date}T00:00:00Z&endTime=${date}T23:59:59Z&pageSize=100`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
    debug.http_status = r.status;
    if (!r.ok) {
      debug.http_body = (await r.text()).slice(0, 500);
      return res.json(debug);
    }
    const data = await r.json();
    const calls = data.items || [];
    debug.total_calls = calls.length;
    const orphans = [];
    for (const call of calls) {
      const callerKey = call.caller?.userKey || call.caller?.type?.userKey;
      const callerRamal = call.caller?.number;
      let vend = GOTO_VENDEDORES.find(v => (callerKey && v.userKey === callerKey) || v.ramal === callerRamal);
      if (!vend && call.participants) {
        for (const p of call.participants) {
          const pKey = p.userKey || p.type?.userKey;
          const pRamal = p.number;
          vend = GOTO_VENDEDORES.find(v => (pKey && v.userKey === pKey) || v.ramal === pRamal);
          if (vend) break;
        }
      }
      if (vend) debug.calls_associadas++;
      else {
        debug.calls_sem_vendedor++;
        if (orphans.length < 5) orphans.push({
          direction: call.direction,
          caller: { userKey: callerKey || null, number: callerRamal || null, name: call.caller?.name || '' },
          participants: (call.participants||[]).slice(0,3).map(p => ({ userKey: p.userKey || p.type?.userKey || null, number: p.number || null, name: p.name || '' })),
          startTime: call.startTime,
        });
      }
    }
    debug.sample_orphan_calls = orphans;
    debug.stats = await getGotoCallStatsForDate(date).catch(() => ({}));
    res.json(debug);
  } catch(e) {
    debug.error = e.message;
    res.json(debug);
  }
});

async function getGotoCallStatsForDate(dateStr) {
  // dateStr: YYYY-MM-DD. Cache por hora pra dia atual, indefinido pra dias passados.
  const today = todayBR();
  const isToday = dateStr === today;
  const cacheKey = isToday
    ? `goto-stats:${new Date().toISOString().slice(0,13)}`
    : `goto-stats:date:${dateStr}`;
  const cached = cacheGet(cacheKey);
  if (cached) return cached;

  const token = await getGotoToken();
  if (!token) { console.warn('[goto] sem token — refresh pode ter expirado'); return {}; }

  try {
    const dayStart = dateStr + 'T00:00:00Z';
    const dayEnd = dateStr + 'T23:59:59Z';
    const url = `https://api.goto.com/call-events-report/v1/report-summaries?accountKey=${GOTO_ACCT}&startTime=${dayStart}&endTime=${dayEnd}&pageSize=100`;
    const gotoRes = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
    if (!gotoRes.ok) {
      console.warn(`[goto] HTTP ${gotoRes.status} pra ${dateStr}: ${(await gotoRes.text()).slice(0,200)}`);
      return {};
    }
    const data = await gotoRes.json();
    const calls = data.items || [];

    const stats = {};
    for (const v of GOTO_VENDEDORES) {
      stats[v.crmOwner] = { nome: v.nome, total: 0, outbound: 0, inbound: 0, answered: 0, missed: 0, totalDurSec: 0 };
    }
    for (const call of calls) {
      const callerKey = call.caller?.userKey || call.caller?.type?.userKey;
      const callerRamal = call.caller?.number;
      let vend = GOTO_VENDEDORES.find(v => (callerKey && v.userKey === callerKey) || v.ramal === callerRamal);
      if (!vend && call.participants) {
        for (const p of call.participants) {
          const pKey = p.userKey || p.type?.userKey;
          const pRamal = p.number;
          vend = GOTO_VENDEDORES.find(v => (pKey && v.userKey === pKey) || v.ramal === pRamal);
          if (vend) break;
        }
      }
      if (!vend) continue;
      const s = stats[vend.crmOwner];
      s.total++;
      if (call.direction === 'OUTBOUND') s.outbound++; else s.inbound++;
      const isAnswered = !!call.callAnswered;
      let durSec = 0;
      if (isAnswered && call.callAnswered && call.callEnded) {
        durSec = Math.max(0, Math.round((new Date(call.callEnded) - new Date(call.callAnswered)) / 1000));
      }
      if (isAnswered) { s.answered++; s.totalDurSec += durSec; }
      else s.missed++;
    }
    // Add avgDurMin
    Object.values(stats).forEach(s => {
      s.avgDurMin = s.answered > 0 ? Math.round(s.totalDurSec / s.answered / 60 * 10) / 10 : 0;
    });
    // Cache: 5min pra dia atual, 24h pra histórico (dado já fechado)
    cacheSet(cacheKey, stats, isToday ? 300000 : 86400000);
    return stats;
  } catch (e) {
    console.error('GoTo stats error:', e.message);
    return {};
  }
}
// Compat: nome antigo
async function getGotoCallStatsToday() {
  return getGotoCallStatsForDate(todayBR());
}

app.get('/cockpit/calls', requireAuth, async (req, res) => {
  try {
    const stats = await getGotoCallStatsToday();
    if (!Object.keys(stats).length) return res.json({ error: 'GoTo not configured', calls: [] });

    const loggedUser = USERS[req.session.user.username];
    const isAdmin = loggedUser?.role === 'admin';
    let targetOwner = loggedUser?.crmOwner;
    if (isAdmin && req.query.closer && USERS[req.query.closer]) {
      targetOwner = USERS[req.query.closer].crmOwner;
    }

    const now = new Date();
    const totalCalls = Object.values(stats).reduce((s, x) => s + x.total, 0);
    const result = isAdmin && !req.query.closer
      ? Object.entries(stats).filter(([_, s]) => s.total > 0).map(([owner, s]) => ({ owner, ...s }))
      : [{ owner: targetOwner, ...(stats[targetOwner] || {}) }];

    res.json({ date: todayBR(), totalCalls, stats: result });
  } catch (err) {
    res.json({ error: err.message, calls: [] });
  }
});

// --- Fase 10: Relatório Diário Automático ---
app.get('/gestao/relatorio-diario', requireAuth, async (req, res) => {
  const isAdmin = USERS[req.session.user.username]?.role === 'admin';
  if (!isAdmin) return res.status(403).json({ error: 'admin only' });

  try {
    const now = new Date();
    const today = todayBR();
    const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
    const hour = now.getHours();
    const tipo = hour < 12 ? 'manha' : 'fim_dia';

    // Fetch data
    const [won, active] = await Promise.all([
      zohoSearch(`((Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`, 'Deal_Name,Amount,Owner,Closing_Date', 200),
      zohoSearch('(Stage:in:Primeiro Contato,Em Qualificação,Etapa IA,Analise ou vazão,Qualificado,Proposta Quente,Proposta Fria,Em Atendimento,Proposta)', 'Deal_Name,Stage,Tier_Lead,Amount,Owner,Last_Activity_Time', 200),
    ]);

    const fatMes = won.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    const metaGlobal = Object.values(METAS_ABRIL).reduce((s, m) => s + m.faturamento, 0);
    const gap = Math.max(0, metaGlobal - fatMes);
    const diasRestantes = Math.max(1, 30 - now.getDate());
    const nowMs = Date.now();

    const propostas = active.filter(d => /Proposta/i.test(d.Stage));
    const valorProp = propostas.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    const semFollowup = propostas.filter(d => (nowMs - new Date(d.Last_Activity_Time || '2020-01-01').getTime()) / 3600000 > 24);
    const diamParados = active.filter(d => d.Tier_Lead === 'Diamante' && (nowMs - new Date(d.Last_Activity_Time || '2020-01-01').getTime()) / 3600000 > 4);

    // Per closer summary
    const closerLines = CLOSERS_LIST.map(c => {
      const myWon = won.filter(d => d.Owner?.name === c.crmOwner);
      const myActive = active.filter(d => d.Owner?.name === c.crmOwner);
      const meta = METAS_ABRIL[c.crmOwner] || { faturamento: 90000 };
      const fat = myWon.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
      const pct = Math.round(fat / meta.faturamento * 100);
      const myDiam = myActive.filter(d => d.Tier_Lead === 'Diamante' && (nowMs - new Date(d.Last_Activity_Time || '2020-01-01').getTime()) / 3600000 > 4).length;
      return `${c.name}: ${myWon.length} vendas R$${(fat/1000).toFixed(0)}k (${pct}%) ${myDiam > 0 ? '| ' + myDiam + ' Diam parados' : ''}`;
    }).join('\n');

    const msg = tipo === 'manha'
      ? `📊 RELATÓRIO DA MANHÃ — ${today}\n\n` +
        `Meta: R$ ${(metaGlobal/1000).toFixed(0)}k | Vendido: R$ ${(fatMes/1000).toFixed(0)}k | Gap: R$ ${(gap/1000).toFixed(0)}k\n` +
        `Dias restantes: ${diasRestantes} | Necessário/dia: R$ ${(gap/diasRestantes/1000).toFixed(0)}k\n\n` +
        `Propostas: ${propostas.length} (R$ ${(valorProp/1000).toFixed(0)}k) | ${semFollowup.length} sem follow-up\n` +
        `Diamantes parados: ${diamParados.length}\n\n` +
        `POR CLOSER:\n${closerLines}\n\n` +
        `Plano: Zerar leads sem contato até 10h. Atacar propostas >R$5k. Meta 25 ligações por closer.`
      : `📊 RELATÓRIO FIM DO DIA — ${today}\n\n` +
        `Vendido mês: R$ ${(fatMes/1000).toFixed(0)}k (${Math.round(fatMes/metaGlobal*100)}% da meta)\n` +
        `Propostas: ${propostas.length} (R$ ${(valorProp/1000).toFixed(0)}k)\n` +
        `Diamantes parados: ${diamParados.length}\n\n` +
        `POR CLOSER:\n${closerLines}\n\n` +
        `Amanhã: foco em fechamento. ${semFollowup.length} propostas precisam de follow-up.`;

    // Send via Z-API to Paulo
    if (req.query.send === 'true') {
      await zapiSend(PAULO_PHONE, msg);
      return res.json({ sent: true, tipo, message: msg });
    }

    res.json({ tipo, message: msg });
  } catch (err) {
    res.json({ error: err.message });
  }
});

// --- Fase 7: Motor de Correção Automática ---
// Endpoint que executa correções: redistribui leads parados, envia alertas, reativa leads frios
app.post('/gestao/correcao', requireAuth, async (req, res) => {
  const isAdmin = USERS[req.session.user.username]?.role === 'admin';
  if (!isAdmin) return res.status(403).json({ error: 'admin only' });

  const { action } = req.body;
  const results = { action, alerts: [], redistributed: 0, reactivated: 0 };

  try {
    const now = new Date();
    const today = todayBR();
    const nowMs = Date.now();

    if (action === 'alertar_todos' || action === 'full_scan') {
      // Scan all closers and alert those with problems
      const active = await zohoSearch(
        '(Stage:in:Primeiro Contato,Em Qualificação,Etapa IA,Analise ou vazão,Qualificado,Proposta Quente,Proposta Fria,Em Atendimento,Proposta)',
        'Deal_Name,Stage,Tier_Lead,Amount,Last_Activity_Time,Created_Time,Owner,Lead_Source,Telefone_contato', 200
      );

      // Group by owner
      const byOwner = {};
      for (const d of active) {
        const o = d.Owner?.name || '?';
        if (!byOwner[o]) byOwner[o] = { leads: [], diamantes: 0, propostas: 0, semContato: 0, valorProposta: 0 };
        const h = (nowMs - new Date(d.Last_Activity_Time || d.Created_Time || '2020-01-01').getTime()) / 3600000;
        if (d.Tier_Lead === 'Diamante' && h > 4) byOwner[o].diamantes++;
        if (/Proposta/i.test(d.Stage) && h > 24) { byOwner[o].propostas++; byOwner[o].valorProposta += parseFloat(d.Amount) || 0; }
        if (h > 24 && /Primeiro Contato/i.test(d.Stage)) byOwner[o].semContato++;
        byOwner[o].leads.push(d);
      }

      // Send Z-API alerts to closers with problems
      for (const [owner, data] of Object.entries(byOwner)) {
        const phone = CLOSER_PHONES[owner];
        if (!phone) continue;
        const firstName = owner.split(' ')[0];
        const msgs = [];

        if (data.diamantes >= 2) {
          msgs.push(`${firstName}, voce tem ${data.diamantes} Diamante(s) parado(s) ha mais de 4h. Esses sao clientes com maior potencial. Ligar AGORA.`);
        }
        if (data.propostas >= 2) {
          msgs.push(`${firstName}, voce tem ${data.propostas} propostas sem follow-up ha mais de 24h (R$ ${(data.valorProposta/1000).toFixed(0)}k parado). Proposta sem follow-up vira decoracao no CRM.`);
        }
        if (data.semContato >= 3) {
          msgs.push(`${firstName}, voce tem ${data.semContato} leads em Primeiro Contato ha mais de 24h sem acao. Lead novo esfria rapido. Aja agora.`);
        }

        for (const msg of msgs) {
          await zapiSend(phone, msg);
          results.alerts.push({ closer: owner, message: msg });
          await new Promise(r => setTimeout(r, 2000)); // rate limit
        }
      }
    }

    if (action === 'reativar_frios' || action === 'full_scan') {
      // Find cold leads (>5 days in Primeiro Contato) and trigger Nubia outreach
      const frios = await zohoSearch(
        '(Stage:in:Primeiro Contato,Etapa IA)',
        'Deal_Name,Telefone_contato,Pipeline,Tier_Lead,Owner', 200
      );

      const candidates = frios.filter(d => d.Telefone_contato).slice(0, 30);

      if (candidates.length > 0) {
        try {
          const outreachPayload = candidates.map(d => ({
            phone: d.Telefone_contato,
            name: d.Deal_Name || '?',
            deal_id: d.id || '',
            product_type: /bebedouro/i.test(d.Pipeline) ? 'bebedouro' : /po[cç]o/i.test(d.Pipeline) ? 'poco' : 'filtro_entrada',
          }));

          const nubiaRes = await fetch('https://generous-upliftment-production-271e.up.railway.app/outreach', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ leads: outreachPayload }),
          });
          const nubiaText = await nubiaRes.text();
          try {
            const nubiaData = JSON.parse(nubiaText);
            results.reactivated = nubiaData.total || candidates.length;
          } catch (parseErr) {
            results.reactivated = candidates.length;
            results.nubiaResponse = nubiaText.slice(0, 200);
          }
        } catch (e) {
          results.reactivated = 0;
          results.nubiaError = e.message;
        }
      }
    }

    // Notify Paulo
    const summary = `[Correcao Automatica] ${results.alerts.length} alertas enviados, ${results.reactivated} leads reativados via Nubia.`;
    await zapiSend(PAULO_PHONE, summary);
    results.summary = summary;

    res.json(results);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- Fase 8: Comparativos + Gamificação ---
app.get('/cockpit/gamificacao', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  const isAdmin = loggedUser?.role === 'admin';
  let targetUser = loggedUser;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) {
    targetUser = USERS[req.query.closer];
  }
  if (!targetUser?.crmOwner) return res.json({ error: 'user not mapped' });

  try {
    const ownerName = targetUser.crmOwner;
    const now = new Date();
    const today = todayBR();
    const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;

    // Won deals this month (all closers for ranking)
    const allWon = await zohoSearch(
      `((Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`,
      'Deal_Name,Amount,Owner,Closing_Date', 200
    );

    // Build ranking
    const ranking = {};
    for (const d of allWon) {
      const o = d.Owner?.name || '?';
      if (!ranking[o]) ranking[o] = { vendas: 0, faturamento: 0, melhorDia: '', melhorDiaValor: 0, diasComVenda: new Set(), ultimaVenda: '' };
      ranking[o].vendas++;
      ranking[o].faturamento += parseFloat(d.Amount) || 0;
      ranking[o].diasComVenda.add(d.Closing_Date);
      if (!ranking[o].ultimaVenda || d.Closing_Date > ranking[o].ultimaVenda) ranking[o].ultimaVenda = d.Closing_Date;
    }

    // Best day per closer
    const byDay = {};
    for (const d of allWon) {
      const o = d.Owner?.name || '?';
      const key = `${o}:${d.Closing_Date}`;
      byDay[key] = (byDay[key] || 0) + (parseFloat(d.Amount) || 0);
    }
    for (const [key, val] of Object.entries(byDay)) {
      const [o, dia] = key.split(':');
      if (ranking[o] && val > ranking[o].melhorDiaValor) {
        ranking[o].melhorDiaValor = val;
        ranking[o].melhorDia = dia;
      }
    }

    // Finalize
    for (const o of Object.keys(ranking)) {
      ranking[o].diasComVenda = ranking[o].diasComVenda.size;
      ranking[o].ticketMedio = ranking[o].vendas > 0 ? Math.round(ranking[o].faturamento / ranking[o].vendas) : 0;
    }

    // Sort by faturamento
    const sorted = Object.entries(ranking).sort((a,b) => b[1].faturamento - a[1].faturamento);
    const myPos = sorted.findIndex(([o]) => o === ownerName) + 1;
    const myData = ranking[ownerName] || { vendas: 0, faturamento: 0, ticketMedio: 0, diasComVenda: 0, melhorDia: '', melhorDiaValor: 0 };

    // Dias sem venda
    const todayStr3 = todayBR();
    const diasSemVenda = myData.ultimaVenda ? (myData.ultimaVenda === todayStr3 ? 0 : Math.max(0, Math.round((new Date(todayStr3+'T12:00:00Z') - new Date(myData.ultimaVenda+'T12:00:00Z')) / 86400000))) : now.getDate();

    // Medals
    const medals = [];
    if (sorted.length > 0 && sorted[0][0] === ownerName) medals.push({ emoji: '&#128081;', label: 'Lider de Faturamento' });
    const bestTicket = sorted.sort((a,b) => b[1].ticketMedio - a[1].ticketMedio);
    if (bestTicket.length > 0 && bestTicket[0][0] === ownerName) medals.push({ emoji: '&#128176;', label: 'Maior Ticket Medio' });
    const bestConsist = sorted.sort((a,b) => b[1].diasComVenda - a[1].diasComVenda);
    if (bestConsist.length > 0 && bestConsist[0][0] === ownerName) medals.push({ emoji: '&#127941;', label: 'Mais Consistente' });
    if (myData.vendas >= 20) medals.push({ emoji: '&#128293;', label: 'Maquina de Vendas (20+)' });
    if (diasSemVenda === 0) medals.push({ emoji: '&#9889;', label: 'Vendeu Hoje!' });

    // Re-sort by faturamento
    const finalRanking = Object.entries(ranking).sort((a,b) => b[1].faturamento - a[1].faturamento)
      .map(([name, d], i) => ({ name, ...d, pos: i + 1 }));

    res.json({
      posicao: myPos,
      totalClosers: sorted.length,
      meusDados: myData,
      diasSemVenda,
      medals,
      ranking: finalRanking.slice(0, 15),
      diffParaPrimeiro: myPos > 1 ? sorted.sort((a,b)=>b[1].faturamento-a[1].faturamento)[0][1].faturamento - myData.faturamento : 0,
      diffParaAcima: myPos > 1 ? finalRanking[myPos-2].faturamento - myData.faturamento : 0,
    });
  } catch (err) {
    res.json({ error: err.message });
  }
});

// --- Gestao Coach IA (visao estrategica pro dono) ---
app.get('/gestao/coach', requireAuth, async (req, res) => {
  const isAdmin = USERS[req.session.user.username]?.role === 'admin';
  if (!isAdmin) return res.status(403).json({ error: 'admin only' });

  try {
    const now = new Date();
    const today = todayBR();
    const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;

    const [parados, won, lost, novos] = await Promise.all([
      zohoSearch('((Tier_Lead:in:Diamante,Ouro)and(Stage:in:Primeiro Contato,Em Qualificação,Etapa IA,Analise ou vazão,Qualificado))',
        'Deal_Name,Tier_Lead,Score_Lead,Owner,Last_Activity_Time,Stage', 200),
      zohoSearch(`((Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Amount,Owner', 200),
      zohoSearch(`((Stage:equals:Fechado perdido)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Owner', 200),
      zohoSearch(`(Created_Time:between:${today}T00:00:00-03:00,${today}T23:59:59-03:00)`,
        'Deal_Name,Owner,Stage,Lead_Source', 200),
    ]);

    const nowMs = Date.now();
    const totalVendas = won.length;
    const totalFat = won.reduce((s,d) => s + (parseFloat(d.Amount)||0), 0);
    const paradosGrave = parados.filter(d => {
      const h = (nowMs - new Date(d.Last_Activity_Time || '2026-01-01').getTime()) / 3600000;
      return h > 12;
    });

    // Per closer summary
    const closerSummary = CLOSERS_LIST.map(c => {
      const o = c.crmOwner;
      const m = METAS_ABRIL[o] || {vendas:15,faturamento:60000};
      const v = won.filter(d => d.Owner?.name === o).length;
      const p = lost.filter(d => d.Owner?.name === o).length;
      const dp = parados.filter(d => d.Owner?.name === o && d.Tier_Lead === 'Diamante').length;
      return `${c.name} (${c.team}): ${v}/${m.vendas} vendas (${Math.round(v/m.vendas*100)}%), ${p} perdidos, ${dp} Diamantes parados`;
    }).join('\n');

    const prompt = `Voce e o Diretor Comercial IA da Tudo de Filtro analisando a OPERACAO INTEIRA para o dono Paulo.

DADOS GLOBAIS ABRIL (dia ${now.getDate()}/30):
- Vendas: ${totalVendas}
- Faturamento: R$${totalFat.toFixed(0)}
- Perdidos: ${lost.length}
- Leads parados tier alto: ${parados.length} (${paradosGrave.length} grave >12h)
- Novos hoje: ${novos.length}

POR CLOSER:
${closerSummary}

GERE:
## Diagnostico da Operacao
Analise fria em 3-4 frases. O que esta funcionando e o que esta quebrando.

## O Que Voce Precisa Agir AGORA
Lista de 3-5 acoes urgentes com nome do closer e motivo.

## Plano da Semana
3-4 recomendacoes estrategicas (treinamento, redistribuicao, meta, processo).

## Conselho Pro Dono
1-2 frases de visao estrategica honesta.

REGRAS: Seja DIRETO. Use NUMEROS. Aponte NOMES. Maximo 500 palavras.`;

    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) return res.json({ error: 'ANTHROPIC_API_KEY not configured' });
    const anthropic = new Anthropic({ apiKey });
    const response = await anthropic.messages.create({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1000,
      messages: [{ role: 'user', content: prompt }],
    });
    res.json({ coach: response.content[0].text });
  } catch (err) {
    res.json({ error: err.message });
  }
});

