app.get('/cockpit/coach', requireAuth, async (req, res) => {
  const loggedUser = USERS[req.session.user.username];
  const isAdmin = loggedUser?.role === 'admin';
  let targetUser = loggedUser;
  if (isAdmin && req.query.closer && USERS[req.query.closer]) {
    targetUser = USERS[req.query.closer];
  }
  if (!targetUser?.crmOwner) return res.json({ error: 'user not mapped' });

  try {
    const ownerName = targetUser.crmOwner;
    const now = new Date();
    const today = todayBR();
    const monthStart = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;
    const meta = METAS_ABRIL[ownerName] || { vendas: 15, faturamento: 60000 };

    // Fetch data
    // Comparativo: ontem + mês anterior
    const yesterday = new Date(now - 86400000).toISOString().slice(0, 10);
    const lastMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);
    const lastMonthStart = `${lastMonthEnd.getFullYear()}-${String(lastMonthEnd.getMonth()+1).padStart(2,'0')}-01`;
    const lastMonthSameDay = `${lastMonthEnd.getFullYear()}-${String(lastMonthEnd.getMonth()+1).padStart(2,'0')}-${String(Math.min(now.getDate(), lastMonthEnd.getDate())).padStart(2,'0')}`;

    const [active, won, lost] = await Promise.all([
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:in:Primeiro Contato,Em Qualificação,Etapa IA,Analise ou vazão,Qualificado,Proposta Quente,Proposta Fria,Em Atendimento,Leads Novos,IA sem Contato,Proposta))`,
        'Deal_Name,Stage,Tier_Lead,Score_Lead,Amount,Last_Activity_Time,Created_Time,Pipeline,Produto_Vendido', 200),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:equals:Fechado Ganho)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Amount,Closing_Date', 200),
      zohoSearch(`((Owner:equals:${ownerName})and(Stage:equals:Fechado perdido)and(Closing_Date:between:${monthStart},${today}))`,
        'Deal_Name,Amount', 200),
    ]);

    const vendas = won.length;
    const faturamento = won.reduce((s, d) => s + (parseFloat(d.Amount) || 0), 0);
    const nowMs = Date.now();

    // Build context for Claude
    const diamantes = active.filter(d => d.Tier_Lead === 'Diamante');
    const ouros = active.filter(d => d.Tier_Lead === 'Ouro');
    const propostas = active.filter(d => (d.Stage || '').includes('Proposta'));
    const semContato = active.filter(d => {
      const h = (nowMs - new Date(d.Last_Activity_Time || d.Created_Time).getTime()) / 3600000;
      return h > 24;
    });
    const quentes = active.filter(d => {
      const h = (nowMs - new Date(d.Last_Activity_Time || d.Created_Time).getTime()) / 3600000;
      return (d.Tier_Lead === 'Diamante' || d.Tier_Lead === 'Ouro') && h > 4;
    });

    const stageBreakdown = {};
    active.forEach(d => { stageBreakdown[d.Stage] = (stageBreakdown[d.Stage] || 0) + 1; });

    const topDeals = quentes.slice(0, 10).map(d => {
      const h = Math.round((nowMs - new Date(d.Last_Activity_Time || d.Created_Time).getTime()) / 3600000);
      return `- ${d.Deal_Name} | ${d.Tier_Lead} sc:${d.Score_Lead} | ${d.Stage} | ${h}h parado | ${d.Pipeline || ''} | R$${d.Amount || '?'}`;
    }).join('\n');

    const propostasDeals = propostas.slice(0, 8).map(d => {
      const h = Math.round((nowMs - new Date(d.Last_Activity_Time || d.Created_Time).getTime()) / 3600000);
      return `- ${d.Deal_Name} | R$${d.Amount || '?'} | ${h}h sem follow-up`;
    }).join('\n');

    const diasRestantes = 30 - now.getDate();
    const faltaVendas = Math.max(0, meta.vendas - vendas);
    const faltaFaturamento = Math.max(0, meta.faturamento - faturamento);
    const metaDiaria = diasRestantes > 0 ? Math.ceil(faltaFaturamento / diasRestantes) : faltaFaturamento;

    const prompt = `Voce e o Diretor Comercial IA da Tudo de Filtro. Analise os dados do closer ${targetUser.name} e gere:

1. FRASE DO DIA — motivacional mas conectada ao momento real (1 linha)
2. DIAGNOSTICO — analise fria do cenario atual em 3-4 frases. Elogie se merece, cobre se esta falhando. Sempre com dados.
3. PLANO DE ATAQUE HOJE — lista numerada de 4-6 acoes concretas com prioridade
4. ALERTAS — red flags que precisam de atencao imediata (se houver)

DADOS DO CLOSER ${targetUser.name.toUpperCase()} (${targetUser.team}):
- Vendas abril: ${vendas} de ${meta.vendas} (${Math.round(vendas/meta.vendas*100)}%)
- Faturamento: R$${faturamento.toFixed(0)} de R$${meta.faturamento} (${Math.round(faturamento/meta.faturamento*100)}%)
- Falta pra meta: ${faltaVendas} vendas, R$${faltaFaturamento.toFixed(0)}
- Meta diaria sugerida: R$${metaDiaria}
- Dias restantes no mes: ${diasRestantes}
- Perdidos abril: ${lost.length}
- Pipeline ativo: ${active.length} deals
- Diamantes: ${diamantes.length} (${quentes.filter(d=>d.Tier_Lead==='Diamante').length} parados >4h)
- Ouros: ${ouros.length} (${quentes.filter(d=>d.Tier_Lead==='Ouro').length} parados >4h)
- Propostas abertas: ${propostas.length} (R$${propostas.reduce((s,d)=>s+(parseFloat(d.Amount)||0),0).toFixed(0)})
- Sem atividade >24h: ${semContato.length} deals
- Stages: ${JSON.stringify(stageBreakdown)}
- Ticket medio: R$${vendas > 0 ? Math.round(faturamento/vendas) : 0}

LEADS QUENTES PARADOS (top 10):
${topDeals || '(nenhum)'}

PROPOSTAS ABERTAS:
${propostasDeals || '(nenhuma)'}

REGRAS:
- Seja DIRETO e FIRME. Nao suavize problemas.
- Use NUMEROS e DADOS em cada frase. Nada generico.
- Se vendas=0 e dia>15: cobre DURO.
- Se tem Diamante >12h parado: alerte como urgente.
- Se propostas >48h sem follow-up: cobre.
- Formato: use ## pra cada secao. Maximo 400 palavras total.`;

    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (!apiKey) return res.json({ error: 'ANTHROPIC_API_KEY not configured' });

    const anthropic = new Anthropic({ apiKey });
    const response = await anthropic.messages.create({
      model: 'claude-sonnet-4-20250514',
      max_tokens: 800,
      messages: [{ role: 'user', content: prompt }],
    });

    const coachText = response.content[0].text;
    res.json({
      closer: targetUser.name,
      team: targetUser.team,
      coach: coachText,
      kpis: { vendas, faturamento, meta, perdidos: lost.length, pipeline: active.length,
              diamantes: diamantes.length, ouros: ouros.length, propostas: propostas.length,
              semContato: semContato.length, faltaVendas, faltaFaturamento, metaDiaria, diasRestantes },
    });
  } catch (err) {
    console.error('Coach error:', err.message);
    res.json({ error: err.message });
  }
});

