const _leadScore = require('./lib/lead-score');
// Injeta tabela USERS pra owner-validator validar permissões por produto
require('./lib/lead-score/owner-validator').setUsersTable(USERS);
_leadScore.mount(app, {
  pool: _pgPool,
  handoff: {
    // SDR/both → dispara Núbia via API outreach existente
    async fireSdr({ deal, tier, product_type, motivo, reason }) {
      try {
        const phone = deal?.Telefone_contato || deal?.phone;
        if (!phone) return { ok: false, error: 'sem_telefone' };
        const r = await nubiaOutreach([{
          Telefone_contato: phone,
          Deal_Name: deal.Deal_Name || '?',
          id: deal.id || deal.deal_id,
          Pipeline: product_type || '',
        }], motivo || `cadence_${tier}`);
        return r;
      } catch (e) { return { ok: false, error: e.message }; }
    },
    // PIVOT 2026-05-12: lead-score NÃO escolhe mais closer.
    // Owner é definido pelo workflow Zoho ("Distribuição de contato" + assignment rules).
    // Aqui só lemos o Owner atual do deal e mapeamos pra username do portal.
    async assignCloser({ deal_id, product_type, current_owner_name, assignee_pool }) {
      try {
        let ownerName = current_owner_name || null;
        try {
          const deal = await zoho.getDeal(deal_id, 'Owner');
          if (deal?.Owner?.name) ownerName = deal.Owner.name;
        } catch (_) { /* zoho offline: usa current_owner_name */ }
        if (!ownerName) return null;
        const closer = _ownerToCloser(ownerName);
        if (!closer) return null;
        const meta = loadManutMeta();
        if (!meta[deal_id]) meta[deal_id] = {};
        if (meta[deal_id].operadora !== closer.username) {
          meta[deal_id].operadora = closer.username;
          meta[deal_id].operadoraUpdatedAt = new Date().toISOString();
          addTimelineEvent(meta, deal_id, {
            tipo: 'atribuicao',
            label: `Owner do deal=${ownerName} → mapeado pra ${closer.username} (workflow Zoho)`,
            by: 'lead-score-cadence',
          });
          saveManutMeta(meta);
        }
        return closer.username;
      } catch (e) {
        console.warn('[lead-score/assignCloser]', e.message);
        return null;
      }
    },
  },
  notifier: {
    async zapiSend({ ownerName, message }) {
      try {
        const phone = CLOSER_PHONES[ownerName] || null;
        if (!phone) return { ok: false, error: 'sem telefone mapeado pra '+ownerName };
        await zapiSend(phone, message);
        return { ok: true };
      } catch (e) { return { ok: false, error: e.message }; }
    },
    async cliqAlert({ message }) {
      try { await cliqAlert('operacional', message); return { ok: true }; }
      catch (e) { return { ok: false, error: e.message }; }
    },
    async createNote({ dealId, title, content }) {
      try { return await zoho.createNote({ parentId: dealId, parentModule: 'Deals', title, content }); }
      catch (e) { return { ok: false, error: e.message }; }
    },
  },
});

