// Z-API send genérico (F-MAPA-DRAWER) — usado pra mandar mensagem manual pra técnico/cliente
app.post('/operacional/api/zapi/send', requireAuth, async (req, res) => {
  try {
    const { phone, message, target } = req.body || {};
    if (!phone || !message) return res.status(400).json({ error: 'phone e message obrigatórios' });
    const r = await zapiSend(phone, message);
    if (!r.ok) return res.status(502).json({ ok: false, error: r.error || `Z-API status ${r.status}` });
    return res.json({ ok: true, target: target || null, phone, sent_at: new Date().toISOString() });
  } catch (e) { res.status(500).json({ error: String(e.message || e) }); }
});

